					val = FontManager.GetSubstituteFont(LocManager.Instance.Language, (FontType)0);
				}
			}
			catch (Exception)
			{
			}
			if (val == null)
			{
				try
				{
					val = ResourceLoader.Load<Font>("res://themes/fonts/zhs/noto_sans_mono_cjksc_regular_shared.tres", (string)null, (CacheMode)1);
				}
				catch (Exception)
				{
					val = null;
				}
			}
			DanmakuEmojiFont.AttachFallback(val);
			return val;
		}

