		public static void Shutdown()
		{
			Log("弹幕尖塔 Shutdown 开始（含轨迹收口）…");
			DanmakuFrontendUiGate.Reset();
			DanmakuSettingsHost.Shutdown();
			DanmakuChatComposer.Shutdown();
			SubmissionUiHost.Shutdown();
			CommunitySubmissionUiHost.Shutdown();
			DanmakuPauseButton.Shutdown();
			DanmakuModConfig.Shutdown();
			DanmakuLikeService.Shutdown();
			SceneCaptureService.Shutdown();
			_router?.Stop();
			_router = null;
			RunPersistenceCoordinator.Stop();
			RuleConsumerBootstrap.Shutdown();
			UgcAdvanceNode.Shutdown();
			_ugcAdvance = null;
			Interlocked.Increment(ref _ugcSyncGeneration);
			Interlocked.Exchange(ref _ugcSyncInProgress, 0);
			UgcConsumerBootstrap.Shutdown();
			_ugcRuntime?.Shutdown();
			_ugcRuntime = null;
			ModRunState.Shutdown();
			_emitter?.Shutdown();
			_emitter = null;
			DanmakuNetworkForwarder.Instance.Shutdown();
			DanmakuMultiplayerState.Reset();
			_hub?.Shutdown();
			_hub = null;
			DanmakuSourceIdentity.Reset();
			GameContextStore.Shutdown();
			RuntimeTraceRecorder.Stop();
			GameFactBus.Instance.Shutdown();
			if (_harmony != null)
			{
				_harmony.UnpatchAll(_harmony.Id);
			}
			_harmony = null;
			HarmonyPatchRuntimeState.Status = Array.Empty<HarmonyPatchInstallResult>();
			HarmonyPatchRuntimeState.ReportPath = "";
			DanmakuDiagnostics.MarkCleanShutdown();
		}

		public override void _ExitTree()
		{
