		private static List<IDanmakuRule> BuildRules()
		{
			return new List<IDanmakuRule>();
		}

		private static void LoadContentCatalogs()
		{
			CatalogStore.Instance.Reset();
			ManualCardSets.Reset();
			ManualRelicSets.Reset();
			PowerfulCombos.Reset();
			DanmakuLibrary.Reset();
			OriginalChineseNames.Reset();
			CatalogLoadResult catalogLoadResult = ContentCatalogLoader.Load(ModContentDir);
			CatalogLoadResult catalogLoadResult2 = ContentCatalogLoader.Load(ProjectSettings.GlobalizePath("user://DanmakuSpire/content/"));
			Log($"[Content] 内容目录加载：内置 {catalogLoadResult.Loaded}、覆盖 {catalogLoadResult2.Loaded}，跳过 {catalogLoadResult.Failed + catalogLoadResult2.Failed}。");
		}

		private static void LoadRuleContributions()
		{
			int loaded = 0;
			int failed = 0;
			TryLoadRuleContributions(Path.Combine(ActiveUgcCacheDir, "rules-contrib.json"), "远程缓存", ref loaded, ref failed);
			TryLoadRuleContributions(Path.Combine(ProjectSettings.GlobalizePath("user://DanmakuSpire/content/danmaku/"), "rules-contrib.json"), "用户覆盖", ref loaded, ref failed);
			Log($"[Content] 规则投稿加载：成功 {loaded} 层，隔离 {failed} 层。");
		}

		private static void TryLoadRuleContributions(string path, string layerName, ref int loaded, ref int failed)
		{
			if (!File.Exists(path))
			{
				return;
			}
			try
			{
				if (!RuleContributionValidator.TryParse(File.ReadAllText(path, Encoding.UTF8), out RuleLibrary library, out string error))
				{
					failed++;
					Log("[Content] 已隔离非法规则投稿层（" + layerName + "）：" + error);
				}
				else
				{
					DanmakuLibrary.ApplyContributions(library);
					loaded++;
				}
			}
			catch (Exception ex)
			{
				failed++;
				Log("[Content] 读取规则投稿层失败（" + layerName + "）：" + ex.Message);
			}
		}

		private static UgcSyncResult SyncUgcContentCore(string cacheDirectory)
		{
			UgcCacheStore cache = new UgcCacheStore(cacheDirectory);
			using HttpClient http = new HttpClient
			{
				Timeout = TimeSpan.FromSeconds(5L)
			};
			UgcHttpClient client = new UgcHttpClient(http);
			return new UgcSyncService(cache, (string url) => client.Fetch(url)).Sync("https://dl.danmakuspire.top/version.json", (ContentShardInfo shard) => UgcContentEndpoints.ShardUrl(shard.Name));
		}

		public static bool TryStartUgcSync(Action<UgcSyncResult>? completed = null)
		{
			Action<UgcSyncResult> completed2 = completed;
			if (_ugcRuntime == null)
			{
				completed2?.Invoke(new UgcSyncResult(Updated: false, Array.Empty<string>(), Array.Empty<string>(), null, UgcSyncStatus.Failed, "弹幕核心尚未初始化。"));
				return false;
			}
			if (Interlocked.CompareExchange(ref _ugcSyncInProgress, 1, 0) != 0)
			{
				return false;
			}
			int generation = Volatile.Read(ref _ugcSyncGeneration);
			string cacheDirectory = UgcCacheDir;
			Task.Run(async delegate
			{
				UgcSyncResult result;
				try
				{
					result = SyncUgcContentCore(cacheDirectory);
				}
				catch (Exception ex)
				{
					result = new UgcSyncResult(Updated: false, Array.Empty<string>(), Array.Empty<string>(), null, UgcSyncStatus.Failed, ex.Message);
				}
				try
				{
					await DanmakuLikeService.FlushPendingAsync().ConfigureAwait(continueOnCapturedContext: false);
				}
				catch (Exception ex2)
				{
					Log("[Like] 点赞批量上传失败：" + ex2.Message);
				}
				if (!UgcAdvanceNode.PostToMainThread(delegate
				{
					try
					{
						if (generation == Volatile.Read(ref _ugcSyncGeneration) && _ugcRuntime != null)
						{
							if (result.Status == UgcSyncStatus.Updated)
							{
								_ugcRuntime.ClearContent();
								LoadUgcShards(_ugcRuntime);
								LoadContentCatalogs();
								LoadRuleContributions();
							}
							Log($"[UGC] 内容同步：状态={result.Status}，下载 {result.DownloadedShards.Count} 片，失败 {result.FailedShards.Count}。");
							completed2?.Invoke(result);
						}
					}
					finally
					{
						Interlocked.Exchange(ref _ugcSyncInProgress, 0);
					}
				}))
				{
					Interlocked.Exchange(ref _ugcSyncInProgress, 0);
				}
			});
			return true;
		}

		private static void LoadUgcShards(UgcRuntime runtime)
		{
			UgcLoadResult ugcLoadResult = new UgcContentLoader(Path.Combine(ModContentDir, "danmaku", "ugc")).LoadAll(runtime, ContentLayer.Baseline);
			UgcLoadResult ugcLoadResult2 = new UgcContentLoader(ActiveUgcCacheDir).LoadAll(runtime, ContentLayer.Ugc);
			UgcLoadResult ugcLoadResult3 = new UgcContentLoader(ProjectSettings.GlobalizePath("user://DanmakuSpire/content/danmaku/ugc/")).LoadAll(runtime, ContentLayer.Overlay);
			Log($"[UGC] 共创分片加载完成：内置 {ugcLoadResult.Loaded}、缓存 {ugcLoadResult2.Loaded}、覆盖 {ugcLoadResult3.Loaded}，跳过 {ugcLoadResult.Failed + ugcLoadResult2.Failed + ugcLoadResult3.Failed}。");
		}

