namespace DanmakuSpire.DanmakuSpireCode.Telemetry
{
	public sealed class CoverageAccumulator
	{
		private sealed class MutableProof
		{
			public string RuleId { get; }

			public CoverageCategory Category { get; }

			public CoverageEvidenceStatus Status { get; set; }

			public int ObservationCount { get; set; }

			public DateTimeOffset FirstObservedAtUtc { get; }

			public DateTimeOffset LastObservedAtUtc { get; set; }

			public string LastRunSessionId { get; set; }

			public long LastTraceSequence { get; set; }

			public string LastReasonCode { get; set; }

			public string LastCorrelationId { get; set; }

			public string LastModVersion { get; set; }

			public MutableProof(string ruleId, CoverageCategory category, CoverageEvidenceStatus status, int observationCount, DateTimeOffset firstObservedAtUtc, DateTimeOffset lastObservedAtUtc, string lastRunSessionId, long lastTraceSequence, string lastReasonCode, string lastCorrelationId, string lastModVersion)
			{
				RuleId = ruleId;
				Category = category;
				Status = status;
				ObservationCount = observationCount;
				FirstObservedAtUtc = firstObservedAtUtc;
				LastObservedAtUtc = lastObservedAtUtc;
				LastRunSessionId = lastRunSessionId;
				LastTraceSequence = lastTraceSequence;
				LastReasonCode = lastReasonCode;
				LastCorrelationId = lastCorrelationId;
				LastModVersion = lastModVersion;
				base..ctor();
			}

			public static MutableProof From(CoverageProof proof)
			{
				return new MutableProof(proof.RuleId, proof.Category, proof.Status, proof.ObservationCount, proof.FirstObservedAtUtc, proof.LastObservedAtUtc, proof.LastRunSessionId, proof.LastTraceSequence, proof.LastReasonCode, proof.LastCorrelationId, proof.LastModVersion);
			}

			public CoverageProof Freeze()
			{
				return new CoverageProof(RuleId, Category, Status, ObservationCount, FirstObservedAtUtc, LastObservedAtUtc, LastRunSessionId, LastTraceSequence, LastReasonCode, LastCorrelationId, LastModVersion);
			}
		}

		private sealed class MutableRuleObservation
		{
			public string RuleId { get; }

			public int Evaluated { get; set; }

			public int Accepted { get; set; }

			public int NotMatched { get; set; }

			public int Suppressed { get; set; }

			public int Spawned { get; set; }

			public Dictionary<string, int> ReasonCounts { get; }

			public Dictionary<string, int> NotMatchedReasonCounts { get; }

			public Dictionary<string, int> VariantCounts { get; }

			public IReadOnlyDictionary<string, string> LastSnapshot { get; set; }

			public MutableRuleObservation(string ruleId)
			{
				RuleId = ruleId;
				ReasonCounts = new Dictionary<string, int>(StringComparer.Ordinal);
				NotMatchedReasonCounts = new Dictionary<string, int>(StringComparer.Ordinal);
				VariantCounts = new Dictionary<string, int>(StringComparer.Ordinal);
				LastSnapshot = new Dictionary<string, string>();
				base..ctor();
			}

			public static MutableRuleObservation From(RuleObservationSummary source)
			{
				MutableRuleObservation mutableRuleObservation = new MutableRuleObservation(source.RuleId)
				{
					Evaluated = source.Evaluated,
					Accepted = source.Accepted,
					NotMatched = source.NotMatched,
					Suppressed = source.Suppressed,
					Spawned = source.Spawned,
					LastSnapshot = new Dictionary<string, string>(source.LastSnapshot, StringComparer.Ordinal)
				};
				foreach (KeyValuePair<string, int> reasonCount in source.ReasonCounts)
				{
					mutableRuleObservation.ReasonCounts[reasonCount.Key] = reasonCount.Value;
				}
				if (source.NotMatchedReasonCounts != null)
				{
					foreach (KeyValuePair<string, int> notMatchedReasonCount in source.NotMatchedReasonCounts)
					{
						mutableRuleObservation.NotMatchedReasonCounts[notMatchedReasonCount.Key] = notMatchedReasonCount.Value;
					}
				}
				foreach (KeyValuePair<string, int> variantCount in source.VariantCounts)
				{
					mutableRuleObservation.VariantCounts[variantCount.Key] = variantCount.Value;
				}
				return mutableRuleObservation;
			}

			public RuleObservationSummary Freeze()
			{
				return new RuleObservationSummary(RuleId, Evaluated, Accepted, NotMatched, Suppressed, Spawned, new SortedDictionary<string, int>(ReasonCounts, StringComparer.Ordinal), new SortedDictionary<string, int>(NotMatchedReasonCounts, StringComparer.Ordinal), new SortedDictionary<string, int>(VariantCounts, StringComparer.Ordinal), new SortedDictionary<string, string>(LastSnapshot.ToDictionary<KeyValuePair<string, string>, string, string>((KeyValuePair<string, string> pair) => pair.Key, (KeyValuePair<string, string> pair) => pair.Value, StringComparer.Ordinal), StringComparer.Ordinal));
			}
		}

		private static readonly HashSet<string> LifecycleReasons = new HashSet<string> { "stale_lifecycle", "inactive_rule_phase", "not_local_player_fact", "context_store_unavailable" };

		private readonly Dictionary<string, MutableProof> _proofs = new Dictionary<string, MutableProof>(StringComparer.Ordinal);

		private readonly Dictionary<string, MutableRuleObservation> _rules = new Dictionary<string, MutableRuleObservation>(StringComparer.Ordinal);

		private readonly Dictionary<string, int> _runEvaluations = new Dictionary<string, int>(StringComparer.Ordinal);

		private bool _loadedRun;

		private int _newTargets;

		public int NewTargets => _newTargets;

		public int CoveredTargets => _proofs.Count;

		public CoverageAccumulator(CoverageProgressDocument? existing = null)
		{
			if ((object)existing == null || existing.SchemaVersion != 1 || existing.ContractVersion != CoverageContractCatalog.ContractVersion)
			{
				return;
			}
			foreach (CoverageProof proof in existing.Proofs)
			{
				_proofs[Key(proof.RuleId, proof.Category)] = MutableProof.From(proof);
			}
			foreach (RuleObservationSummary rule in existing.Rules)
			{
				_rules[rule.RuleId] = MutableRuleObservation.From(rule);
			}
		}

		public void BeginRun(bool isLoaded)
		{
			_loadedRun = isLoaded;
			_runEvaluations.Clear();
			_newTargets = 0;
		}

		public void ObserveRule(RuleAuditRecord record, string runSessionId, long traceSequence, string modVersion)
		{
			if (!CoverageContractCatalog.TryGet(record.RuleId, out RuleCoverageContract _))
			{
				return;
			}
			MutableRuleObservation rule = GetRule(record.RuleId);
			rule.Evaluated++;
			rule.ReasonCounts[record.ReasonCode] = rule.ReasonCounts.GetValueOrDefault(record.ReasonCode) + 1;
			if (!string.IsNullOrWhiteSpace(record.Variant))
			{
				rule.VariantCounts[record.Variant] = rule.VariantCounts.GetValueOrDefault(record.Variant) + 1;
			}
			rule.LastSnapshot = new Dictionary<string, string>(record.Snapshot, StringComparer.Ordinal);
			_runEvaluations[record.RuleId] = _runEvaluations.GetValueOrDefault(record.RuleId) + 1;
			switch (record.Decision)
			{
			case RuleDecision.Accepted:
				rule.Accepted++;
				Award(record.RuleId, CoverageCategory.POS, CoverageEvidenceStatus.Observed, runSessionId, traceSequence, record.ReasonCode, "", modVersion);
				if (!string.IsNullOrWhiteSpace(record.Variant))
				{
					AwardIfRequired(record.RuleId, CoverageCategory.VAR, CoverageEvidenceStatus.Observed, runSessionId, traceSequence, record.ReasonCode, "", modVersion);
				}
				break;
			case RuleDecision.NotMatched:
				rule.NotMatched++;
				rule.NotMatchedReasonCounts[record.ReasonCode] = rule.NotMatchedReasonCounts.GetValueOrDefault(record.ReasonCode) + 1;
				if (record.ReasonCode == "session_interrupted")
				{
					Award(record.RuleId, CoverageCategory.ABORT, CoverageEvidenceStatus.Verified, runSessionId, traceSequence, record.ReasonCode, "", modVersion);
				}
				else if (LifecycleReasons.Contains(record.ReasonCode))
				{
					Award(record.RuleId, CoverageCategory.LIFE, CoverageEvidenceStatus.Verified, runSessionId, traceSequence, record.ReasonCode, "", modVersion);
				}
				else
				{
					Award(record.RuleId, CoverageCategory.NEG, CoverageEvidenceStatus.Observed, runSessionId, traceSequence, record.ReasonCode, "", modVersion);
				}
				break;
			case RuleDecision.Suppressed:
				rule.Suppressed++;
				Award(record.RuleId, CoverageCategory.DEDUP, CoverageEvidenceStatus.Verified, runSessionId, traceSequence, record.SuppressionReason, "", modVersion);
				break;
			}
			if (_runEvaluations[record.RuleId] >= 2)
			{
				AwardIfRequired(record.RuleId, CoverageCategory.SEQ, CoverageEvidenceStatus.Observed, runSessionId, traceSequence, "multiple_real_evaluations", "", modVersion);
			}
			if (_loadedRun)
			{
				AwardIfRequired(record.RuleId, CoverageCategory.SAVE, CoverageEvidenceStatus.Observed, runSessionId, traceSequence, "evaluated_after_run_load", "", modVersion);
			}
		}

		public void ObserveEmission(EmissionTraceRecord record, string runSessionId, long traceSequence, string modVersion)
		{
			if (string.IsNullOrWhiteSpace(record.RuleId) || !CoverageContractCatalog.TryGet(record.RuleId, out RuleCoverageContract _))
			{
				return;
			}
			MutableRuleObservation rule = GetRule(record.RuleId);
			if (record.Stage == EmissionTraceStage.Spawned)
			{
				rule.Spawned++;
				Award(record.RuleId, CoverageCategory.POS, CoverageEvidenceStatus.Verified, runSessionId, traceSequence, "bubble_spawned", record.CorrelationId, modVersion);
				if (!record.ResolvedText.Contains('{', StringComparison.Ordinal))
				{
					Award(record.RuleId, CoverageCategory.CTX, CoverageEvidenceStatus.Verified, runSessionId, traceSequence, "resolved_text_spawned", record.CorrelationId, modVersion);
				}
				if (!string.IsNullOrWhiteSpace(record.Variant))
				{
					AwardIfRequired(record.RuleId, CoverageCategory.VAR, CoverageEvidenceStatus.Verified, runSessionId, traceSequence, "variant_bubble_spawned", record.CorrelationId, modVersion);
				}
			}
		}

		public CoverageProgressDocument Snapshot()
		{
			return new CoverageProgressDocument(1, CoverageContractCatalog.ContractVersion, DateTimeOffset.UtcNow, _proofs.Values.Select((MutableProof proof) => proof.Freeze()).OrderBy<CoverageProof, string>((CoverageProof proof) => proof.RuleId, StringComparer.Ordinal).ThenBy((CoverageProof proof) => proof.Category)
				.ToArray(), _rules.Values.Select((MutableRuleObservation rule) => rule.Freeze()).OrderBy<RuleObservationSummary, string>((RuleObservationSummary rule) => rule.RuleId, StringComparer.Ordinal).ToArray());
		}

		private void AwardIfRequired(string ruleId, CoverageCategory category, CoverageEvidenceStatus status, string runSessionId, long traceSequence, string reasonCode, string correlationId, string modVersion)
		{
			if (CoverageContractCatalog.Get(ruleId).Categories.Contains(category))
			{
				Award(ruleId, category, status, runSessionId, traceSequence, reasonCode, correlationId, modVersion);
			}
		}

		private void Award(string ruleId, CoverageCategory category, CoverageEvidenceStatus status, string runSessionId, long traceSequence, string reasonCode, string correlationId, string modVersion)
		{
			string key = Key(ruleId, category);
			DateTimeOffset utcNow = DateTimeOffset.UtcNow;
			if (!_proofs.TryGetValue(key, out MutableProof value))
			{
				value = new MutableProof(ruleId, category, status, 0, utcNow, utcNow, "", 0L, "", "", "");
				_proofs[key] = value;
				_newTargets++;
			}
			value.Status = (CoverageEvidenceStatus)Math.Max((int)value.Status, (int)status);
			value.ObservationCount++;
			value.LastObservedAtUtc = utcNow;
			value.LastRunSessionId = runSessionId;
			value.LastTraceSequence = traceSequence;
			value.LastReasonCode = reasonCode;
			value.LastCorrelationId = correlationId;
			value.LastModVersion = modVersion;
		}

		private MutableRuleObservation GetRule(string ruleId)
		{
			if (!_rules.TryGetValue(ruleId, out MutableRuleObservation value))
			{
				value = new MutableRuleObservation(ruleId);
				_rules[ruleId] = value;
			}
			return value;
		}

		private static string Key(string ruleId, CoverageCategory category)
		{
			return $"{ruleId}:{category}";
		}
	}
	public enum CoverageCategory
	{
		POS,
		NEG,
		BND,
		LIFE,
		DEDUP,
		ABORT,
		CTX,
		SEQ,
		SAVE,
		VAR
	}
	public sealed record RuleCoverageContract(DanmakuTrigger Trigger, string RuleId, IReadOnlyList<CoverageCategory> Categories, string RealGameCaseId);
	public static class CoverageContractCatalog
	{
		private static readonly IReadOnlyDictionary<string, RuleCoverageContract> ByRuleId;

		private static readonly CoverageCategory[] Common;

		private static readonly HashSet<DanmakuTrigger> StatefulRules;

		public static IReadOnlyList<RuleCoverageContract> All { get; }

		public static int TotalTargets => All.Sum((RuleCoverageContract contract) => contract.Categories.Count);

		public static string ContractVersion { get; }

		static CoverageContractCatalog()
		{
			Common = new CoverageCategory[7]
			{
				CoverageCategory.POS,
				CoverageCategory.NEG,
				CoverageCategory.BND,
				CoverageCategory.LIFE,
				CoverageCategory.DEDUP,
				CoverageCategory.ABORT,
				CoverageCategory.CTX
			};
			StatefulRules = new HashSet<DanmakuTrigger>
			{
				DanmakuTrigger.StrongMonster,
				DanmakuTrigger.StrongMonsterKill,
				DanmakuTrigger.EncounteredBefore,
				DanmakuTrigger.Reconviction,
				DanmakuTrigger.EliteStreak,
				DanmakuTrigger.StreakBreak,
				DanmakuTrigger.NoDamageStreak,
				DanmakuTrigger.BigDeck,
				DanmakuTrigger.CardThreeVisits,
				DanmakuTrigger.CollectiblePair,
				DanmakuTrigger.CloneEnchantment,
				DanmakuTrigger.UpgradeStreak,
				DanmakuTrigger.SaveLoad
			};
			All = (from trigger in Enum.GetValues<DanmakuTrigger>()
				where trigger != DanmakuTrigger.CombatStart
				select trigger).Select(Build).OrderBy<RuleCoverageContract, string>((RuleCoverageContract contract) => contract.RuleId, StringComparer.Ordinal).ToArray();
			ContractVersion = CreateContractVersion();
			ByRuleId = All.ToDictionary<RuleCoverageContract, string>((RuleCoverageContract contract) => contract.RuleId, StringComparer.Ordinal);
		}

		public static RuleCoverageContract Get(string ruleId)
		{
			if (!ByRuleId.TryGetValue(ruleId, out RuleCoverageContract value))
			{
				throw new KeyNotFoundException("未知业务规则 ID：" + ruleId);
			}
			return value;
		}

		public static bool TryGet(string ruleId, out RuleCoverageContract contract)
		{
			return ByRuleId.TryGetValue(ruleId, out contract);
		}

		private static RuleCoverageContract Build(DanmakuTrigger trigger)
		{
			List<CoverageCategory> list = new List<CoverageCategory>(Common);
			if (StatefulRules.Contains(trigger))
			{
				list.Add(CoverageCategory.SEQ);
				list.Add(CoverageCategory.SAVE);
			}
			DanmakuGroup? danmakuGroup = DanmakuLibrary.Get(trigger);
			if ((object)danmakuGroup != null && danmakuGroup.Entries.Any((DanmakuEntry entry) => !string.IsNullOrWhiteSpace(entry.Variant)))
			{
				list.Add(CoverageCategory.VAR);
			}
			string text = DanmakuRuleIds.Get(trigger);
			return new RuleCoverageContract(trigger, text, list, "RG-" + text);
		}

		private static string CreateContractVersion()
		{
			string s = string.Join('|', All.Select((RuleCoverageContract contract) => contract.RuleId + ":" + string.Join(',', contract.Categories)));
			return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s))).Substring(0, 16);
		}
	}
	public static class DanmakuDiagnostics
	{
		private const string LogsDirectoryName = "logs";

		private const string LatestLogFileName = "latest.log";

		private const string LastExitMarkerFileName = "last-exit.json";

		private const string CrashMarkerFileName = "crash-last.log";

		private static readonly object Sync = new object();

		private static bool _initialized;

		private static bool _crashed;

		private static string? _logsRoot;

		private static string? _latestLogPath;

		private static StreamWriter? _writer;

		private static string _lastException = "";

		public static string LogsRoot
		{
			get
			{
				if (_logsRoot != null)
				{
					return _logsRoot;
				}
				try
				{
					_logsRoot = Path.GetFullPath(ProjectSettings.GlobalizePath("user://DanmakuSpire/logs"));
				}
				catch
				{
					_logsRoot = Path.Combine(Path.GetTempPath(), "DanmakuSpire", "logs");
				}
				return _logsRoot;
			}
		}

		public static string LatestLogPath => _latestLogPath ?? (_latestLogPath = Path.Combine(LogsRoot, "latest.log"));

		public static string LastExitMarkerPath => Path.Combine(LogsRoot, "last-exit.json");

		public static string CrashMarkerPath => Path.Combine(LogsRoot, "crash-last.log");

		public static string ModVersion
		{
			get
			{
				try
				{
					return typeof(DanmakuDiagnostics).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion ?? typeof(DanmakuDiagnostics).Assembly.GetName().Version?.ToString() ?? "unknown";
				}
				catch
				{
					return "unknown";
				}
			}
		}

		public static string GameVersion
		{
			get
			{
				try
				{
					return Type.GetType("MegaCrit.Sts2.Core.Runs.RunManager, sts2", throwOnError: false)?.Assembly.GetName().Version?.ToString() ?? "unknown";
				}
				catch
				{
					return "unknown";
				}
			}
		}

		public static string Platform
		{
			get
			{
				string text = Environment.OSVersion.Platform.ToString();
				string versionString = Environment.OSVersion.VersionString;
				try
				{
					string name = OS.GetName();
					if (!string.IsNullOrWhiteSpace(name))
					{
						text = name;
					}
					if (OS.HasFeature("mobile"))
					{
						text += " (mobile)";
					}
					if (OS.HasFeature("android"))
					{
						text += "/Android";
					}
					if (OS.HasFeature("ios") || OS.HasFeature("iOS"))
					{
						text += "/iOS";
					}
				}
				catch
				{
				}
				return text + " | " + versionString;
			}
		}

		public static void Initialize()
		{
			lock (Sync)
			{
				if (_initialized)
				{
					return;
				}
				_initialized = true;
				try
				{
					Directory.CreateDirectory(LogsRoot);
				}
				catch
				{
				}
				try
				{
					if (File.Exists(LatestLogPath))
					{
						string destFileName = Path.Combine(LogsRoot, $"session-{DateTime.Now:yyyyMMdd-HHmmss}.log");
						File.Copy(LatestLogPath, destFileName, overwrite: true);
					}
				}
				catch
				{
				}
				try
				{
					_writer = new StreamWriter(new FileStream(LatestLogPath, FileMode.Create, FileAccess.Write, FileShare.ReadWrite), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false))
					{
						AutoFlush = true
					};
				}
				catch
				{
					_writer = null;
				}
				try
				{
					AppDomain.CurrentDomain.UnhandledException += OnUnhandledException;
				}
				catch
				{
				}
				WriteLine("==== 弹幕尖塔诊断会话开始 ====");
				WriteLine($"时间={DateTimeOffset.Now:O}");
				WriteLine("平台=" + Platform);
				WriteLine("模组版本=" + ModVersion);
				WriteLine("游戏版本=" + GameVersion);
				WriteLine("日志目录=" + LogsRoot);
				WriteLine("上次退出=" + ReadLastExitSummary());
			}
		}

		public static void Log(string message)
		{
			lock (Sync)
			{
				if (!_initialized)
				{
					Initialize();
				}
				WriteLine($"{DateTime.Now:HH:mm:ss.fff} {message}");
			}
		}

		public static void LogException(string context, Exception exception)
		{
			string text = ((exception == null) ? (context + ": <null exception>") : $"{context}: {exception.GetType().FullName}: {exception.Message}{Environment.NewLine}{exception.StackTrace}");
			Log("[Exception] " + text);
		}

		public static void MarkUnexpectedCrash(string detail)
		{
			lock (Sync)
			{
				_crashed = true;
				_lastException = detail ?? "";
				try
				{
					File.WriteAllText(CrashMarkerPath, $"{DateTimeOffset.Now:O}{Environment.NewLine}{detail}", new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				}
				catch
				{
				}
				try
				{
					File.WriteAllText(LastExitMarkerPath, $"{{\"clean\":false,\"at\":\"{DateTimeOffset.Now:O}\",\"error\":\"{SanitizeJson(detail ?? "")}\"}}", new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				}
				catch
				{
				}
				WriteLine("[Crash] " + detail);
			}
		}

		public static void MarkCleanShutdown()
		{
			lock (Sync)
			{
				if (!_crashed)
				{
					try
					{
						File.WriteAllText(LastExitMarkerPath, $"{{\"clean\":true,\"at\":\"{DateTimeOffset.Now:O}\"}}", new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
					}
					catch
					{
					}
					WriteLine("==== 弹幕尖塔正常退出 ====");
					FlushWriter();
				}
			}
		}

		public static string CaptureSnapshot()
		{
			Initialize();
			List<string> list = new List<string>
			{
				"===== 弹幕尖塔诊断信息 =====",
				"模组版本: " + ModVersion,
				"游戏版本: " + GameVersion,
				"平台: " + Platform,
				"Godot: " + TryGetGodotVersion(),
				"日志目录: " + LogsRoot,
				"日志文件: " + LatestLogPath,
				"上次退出: " + ReadLastExitSummary(),
				"最近异常: " + ((_lastException.Length == 0) ? "无" : _lastException),
				"",
				"--- Harmony 补丁 ---"
			};
			try
			{
				IReadOnlyList<HarmonyPatchInstallResult> harmonyPatchStatus = MainFile.HarmonyPatchStatus;
				int value = harmonyPatchStatus.Count((HarmonyPatchInstallResult item) => item.Success);
				list.Add($"成功 {value}/{harmonyPatchStatus.Count}");
				foreach (HarmonyPatchInstallResult item in harmonyPatchStatus.Where((HarmonyPatchInstallResult item) => !item.Success))
				{
					list.Add("失败 " + item.PatchType + ": " + item.Error);
				}
			}
			catch (Exception ex)
			{
				list.Add("无法读取 Harmony 状态: " + ex.Message);
			}
			list.Add("");
			list.Add("--- 已加载模组 ---");
			list.AddRange(GetLoadedMods());
			list.Add("");
			list.Add("--- mods 目录顶层 JSON（疑似残留/非模组清单） ---");
			IReadOnlyList<string> modsDirectoryJsonFiles = GetModsDirectoryJsonFiles();
			list.Add((modsDirectoryJsonFiles.Count == 0) ? "（无）" : string.Join(", ", modsDirectoryJsonFiles));
			list.Add("");
			list.Add("--- 最近日志 ---");
			list.AddRange(ReadRecentLogLines(80));
			return string.Join(Environment.NewLine, list);
		}

		public static bool TryCopyToClipboard(string text)
		{
			if (string.IsNullOrEmpty(text))
			{
				return false;
			}
			try
			{
				DisplayServer.ClipboardSet(text);
				return true;
			}
			catch
			{
				return false;
			}
		}

		public static string ExportLogsTo(string targetRoot)
		{
			try
			{
				Initialize();
				Directory.CreateDirectory(targetRoot);
				string text = Path.Combine(targetRoot, $"DanmakuSpire-logs-{DateTime.Now:yyyyMMdd-HHmmss}");
				Directory.CreateDirectory(text);
				string[] files = Directory.GetFiles(LogsRoot, "*.log", SearchOption.TopDirectoryOnly);
				foreach (string obj in files)
				{
					string fileName = Path.GetFileName(obj);
					File.Copy(obj, Path.Combine(text, fileName), overwrite: true);
				}
				string text2 = Path.Combine(LogsRoot, "last-exit.json");
				if (File.Exists(text2))
				{
					File.Copy(text2, Path.Combine(text, "last-exit.json"), overwrite: true);
				}
				File.WriteAllText(Path.Combine(text, "diagnostics.txt"), CaptureSnapshot(), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				return text;
			}
			catch (Exception exception)
			{
				LogException("导出诊断日志失败", exception);
				return "";
			}
		}

		private static void OnUnhandledException(object sender, UnhandledExceptionEventArgs e)
		{
			string text = e.ExceptionObject?.ToString() ?? "unknown unhandled exception";
			MarkUnexpectedCrash("未处理异常: " + text);
		}

		private static void WriteLine(string line)
		{
			if (_writer != null)
			{
				try
				{
					_writer.WriteLine(line);
					return;
				}
				catch
				{
					_writer = null;
				}
			}
			try
			{
				File.AppendAllText(LatestLogPath, line + Environment.NewLine, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
			}
			catch
			{
			}
		}

		private static void FlushWriter()
		{
			try
			{
				_writer?.Flush();
			}
			catch
			{
			}
		}

		private static string ReadLastExitSummary()
		{
			try
			{
				if (!File.Exists(LastExitMarkerPath))
				{
					return "无记录（首次启动）";
				}
				return File.ReadAllText(LastExitMarkerPath, Encoding.UTF8).Contains("\"clean\":true", StringComparison.Ordinal) ? "上次正常退出" : "上次异常退出";
			}
			catch
			{
				return "无法读取上次退出标记";
			}
		}

		private static string TryGetGodotVersion()
		{
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			//IL_0036: Unknown result type (might be due to invalid IL or missing references)
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Unknown result type (might be due to invalid IL or missing references)
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				Dictionary versionInfo = Engine.GetVersionInfo();
				if (versionInfo != null)
				{
					string value = Convert.ToString(versionInfo[Variant.op_Implicit("major")]) ?? "";
					string value2 = Convert.ToString(versionInfo[Variant.op_Implicit("minor")]) ?? "";
					string value3 = Convert.ToString(versionInfo[Variant.op_Implicit("patch")]) ?? "";
					return $"{value}.{value2}.{value3}";
				}
			}
			catch
			{
			}
			return "unknown";
		}

		private static IReadOnlyList<string> GetLoadedMods()
		{
			List<string> list = new List<string>();
			try
			{
				if ((Type.GetType("MegaCrit.Sts2.Core.Modding.ModManager, sts2", throwOnError: false)?.GetProperty("Mods", BindingFlags.Static | BindingFlags.Public))?.GetValue(null) is IEnumerable enumerable)
				{
					foreach (object item in enumerable)
					{
						if (item != null)
						{
							object? target = item.GetType().GetField("manifest")?.GetValue(item);
							string fieldString = GetFieldString(target, "id");
							string fieldString2 = GetFieldString(target, "name");
							string fieldString3 = GetFieldString(target, "version");
							string value = item.GetType().GetField("state")?.GetValue(item)?.ToString() ?? "";
							string modLoadErrors = GetModLoadErrors(item);
							string text = (string.IsNullOrWhiteSpace(fieldString2) ? $"{fieldString} {fieldString3} [{value}]" : $"{fieldString2} ({fieldString}) {fieldString3} [{value}]");
							list.Add(string.IsNullOrWhiteSpace(modLoadErrors) ? text : (text + " errors=" + modLoadErrors));
						}
					}
				}
			}
			catch (Exception ex)
			{
				list.Add("读取模组列表失败: " + ex.Message);
			}
			if (list.Count != 0)
			{
				return list;
			}
			return new List<string> { "（未读取到已加载模组）" };
		}

		private static string GetModLoadErrors(object mod)
		{
			try
			{
				if (!(mod.GetType().GetField("errors")?.GetValue(mod) is IEnumerable enumerable))
				{
					return "";
				}
				List<string> list = new List<string>();
				foreach (object item in enumerable)
				{
					if (item != null)
					{
						try
						{
							string text = item.GetType().GetMethod("GetFormattedText")?.Invoke(item, null) as string;
							list.Add(string.IsNullOrWhiteSpace(text) ? (item.ToString() ?? "") : text);
						}
						catch
						{
							list.Add(item.ToString() ?? "");
						}
					}
				}
				return string.Join(" | ", list.Where((string part) => !string.IsNullOrWhiteSpace(part)));
			}
			catch
			{
				return "";
			}
		}

		private static IReadOnlyList<string> GetModsDirectoryJsonFiles()
		{
			List<string> list = new List<string>();
			try
			{
				string text = ProjectSettings.GlobalizePath("user://mods");
				if (string.IsNullOrWhiteSpace(text) || !Directory.Exists(text))
				{
					return list;
				}
				list.AddRange((from name in Directory.GetFiles(text, "*.json", SearchOption.TopDirectoryOnly).Select(Path.GetFileName)
					where !string.IsNullOrWhiteSpace(name)
					select (name)).OrderBy<string, string>((string name) => name, StringComparer.Ordinal));
			}
			catch
			{
			}
			return list;
		}

		private static string GetFieldString(object? target, string fieldName)
		{
			try
			{
				return target?.GetType().GetField(fieldName)?.GetValue(target)?.ToString() ?? "";
			}
			catch
			{
				return "";
			}
		}

		private static IReadOnlyList<string> ReadRecentLogLines(int count)
		{
			List<string> list = new List<string>();
			try
			{
				if (!File.Exists(LatestLogPath))
				{
					return list;
				}
				string[] array = File.ReadAllLines(LatestLogPath, Encoding.UTF8);
				list.AddRange(array.Skip(Math.Max(0, array.Length - count)));
			}
			catch (Exception ex)
			{
				list.Add("读取日志失败: " + ex.Message);
			}
			return list;
		}

		private static string SanitizeJson(string value)
		{
			try
			{
				return (value ?? "").Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\r", " ")
					.Replace("\n", " ");
			}
			catch
			{
				return "?";
			}
		}
	}
	public sealed record HarmonyCompatibilityReport(int SchemaVersion, DateTimeOffset CapturedAtUtc, string GameAssemblyVersion, int PatchCount, int SuccessfulPatches, int FailedPatches, IReadOnlyList<string> AffectedRuleIds, IReadOnlyList<HarmonyPatchInstallResult> Patches)
	{
		public bool Compatible => FailedPatches == 0;

		public const int CurrentSchemaVersion = 1;

		[CompilerGenerated]
		private HarmonyCompatibilityReport(HarmonyCompatibilityReport original)
		{
			SchemaVersion = original.SchemaVersion;
			CapturedAtUtc = original.CapturedAtUtc;
			GameAssemblyVersion = original.GameAssemblyVersion;
			PatchCount = original.PatchCount;
			SuccessfulPatches = original.SuccessfulPatches;
			FailedPatches = original.FailedPatches;
			AffectedRuleIds = original.AffectedRuleIds;
			Patches = original.Patches;
		}
	}
	public static class HarmonyCompatibilityReporter
	{
		public static HarmonyCompatibilityReport Create(string gameAssemblyVersion, IReadOnlyList<HarmonyPatchInstallResult> patches)
		{
			HarmonyPatchInstallResult[] array = patches.OrderBy<HarmonyPatchInstallResult, string>((HarmonyPatchInstallResult item) => item.PatchType, StringComparer.Ordinal).ToArray();
			return new HarmonyCompatibilityReport(1, DateTimeOffset.UtcNow, gameAssemblyVersion, array.Length, array.Count((HarmonyPatchInstallResult item) => item.Success), array.Count((HarmonyPatchInstallResult item) => !item.Success), array.Where((HarmonyPatchInstallResult item) => !item.Success).SelectMany((HarmonyPatchInstallResult item) => item.AffectedRuleIds).Distinct<string>(StringComparer.Ordinal)
				.Order<string>(StringComparer.Ordinal)
				.ToArray(), array);
		}

		public static string Write(string outputRoot, string gameAssemblyVersion, IReadOnlyList<HarmonyPatchInstallResult> patches)
		{
			Directory.CreateDirectory(outputRoot);
			HarmonyCompatibilityReport harmonyCompatibilityReport = Create(gameAssemblyVersion, patches);
			string text = Path.Combine(outputRoot, "harmony-compatibility.json");
			WriteAtomically(text, JsonSerializer.Serialize(harmonyCompatibilityReport, TelemetryJson.Indented));
			WriteAtomically(Path.Combine(outputRoot, "harmony-compatibility.md"), RenderMarkdown(harmonyCompatibilityReport));
			return text;
		}

		private static string RenderMarkdown(HarmonyCompatibilityReport report)
		{
			List<string> list = new List<string>
			{
				"# 弹幕尖塔 Harmony 兼容性",
				"",
				"- 游戏程序集：`" + report.GameAssemblyVersion + "`",
				$"- 补丁：{report.SuccessfulPatches}/{report.PatchCount} 成功",
				"- 结论：" + (report.Compatible ? "可进入实机规则测试" : "存在失效监听，先修复再测试受影响规则"),
				""
			};
			if (report.Compatible)
			{
				list.Add("当前没有检测到失效补丁。");
				return string.Join(Environment.NewLine, list);
			}
			list.Add("## 失效补丁");
			list.Add("");
			foreach (HarmonyPatchInstallResult item in report.Patches.Where((HarmonyPatchInstallResult item) => !item.Success))
			{
				list.Add("- `" + item.PatchType + "`：" + item.Error);
				list.Add("  - 受影响规则：" + string.Join(", ", item.AffectedRuleIds.Select((string id) => "`" + id + "`")));
			}
			return string.Join(Environment.NewLine, list);
		}

		private static void WriteAtomically(string path, string content)
		{
			string text = path + $".{Guid.NewGuid():N}.tmp";
			File.WriteAllText(text, content, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
			File.Move(text, path, overwrite: true);
		}
	}
