		{
			SchemaVersion = original.SchemaVersion;
			ContractVersion = original.ContractVersion;
			UpdatedAtUtc = original.UpdatedAtUtc;
			Proofs = original.Proofs;
			Rules = original.Rules;
		}
	}
	public sealed record RunTraceSummary(string RunSessionId, string RunIdentity, string EndReason, int FactRecords, int RuleEvaluations, int AcceptedRules, int SpawnedBubbles, int NewCoverageTargets, int CoveredTargets, int TotalTargets, int CoveredPositiveRules, int TotalRules, int DroppedTraceRecords, string TracePath, string ProgressPath);
	public static class RuntimeTraceIds
	{
		private readonly record struct EntryIdCacheKey(DanmakuTrigger Trigger, string Variant, string Template);

		private static long _sequence;

		private static readonly ConcurrentDictionary<EntryIdCacheKey, string> EntryIdCache = new ConcurrentDictionary<EntryIdCacheKey, string>();

		public static string NewCorrelation(EventId? eventId, string ruleId)
		{
			return $"{ruleId}-{eventId?.RunEpoch ?? 0}-{eventId?.SourceSequence ?? 0}-{Interlocked.Increment(ref _sequence)}";
		}

		public static string EntryId(DanmakuTrigger trigger, string variant, string template)
		{
			return EntryIdCache.GetOrAdd(new EntryIdCacheKey(trigger, variant ?? string.Empty, template ?? string.Empty), (EntryIdCacheKey key) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes($"{key.Trigger}|{key.Variant}|{key.Template}"))).Substring(0, 16));
		}
	}
	public sealed class RuntimeTraceRecorder : IDisposable
	{
		private sealed record FactTracePendingPayload(FactAuditRecord Audit, IGameFact Fact);

		private sealed record TraceWriteItem(string Path, string RunSessionId, long Sequence, DateTimeOffset RecordedAtUtc, string Kind, string EventId, string RuleId, string CorrelationId, object Payload, Type PayloadType, bool Flush);

		private sealed class MutableRun
		{
			public string SessionId { get; }

			public string RunIdentity { get; }

			public long RunEpoch { get; }

			public bool IsLoaded { get; }

			public string TracePath { get; }

			public int FactRecords { get; set; }

			public int RuleEvaluations { get; set; }

			public int AcceptedRules { get; set; }

			public int SpawnedBubbles { get; set; }

			public string? ScheduledEndReason { get; set; }

			public MutableRun(string sessionId, string runIdentity, long runEpoch, bool isLoaded, string tracePath)
			{
				SessionId = sessionId;
				RunIdentity = runIdentity;
				RunEpoch = runEpoch;
				IsLoaded = isLoaded;
				TracePath = tracePath;
				base..ctor();
			}
		}

		private const int QueueCapacity = 8192;

		private readonly object _gate = new object();

		private readonly string _outputRoot;

		private readonly string _progressPath;

		private readonly string _latestSummaryPath;

		private readonly TraceRuntimeMetadata _runtime;

		private readonly GameFactBus _bus;

		private readonly RuleDiagnostics _diagnostics;

		private readonly Action<string> _logger;

		private readonly CoverageAccumulator _coverage;

		private readonly BlockingCollection<TraceWriteItem> _writes = new BlockingCollection<TraceWriteItem>(8192);

		private readonly Task _writerTask;

		private readonly List<RuntimeHealthPayload> _startupHealth = new List<RuntimeHealthPayload>();

		private MutableRun? _run;

		private long _traceSequence;

		private int _droppedRecords;

		private bool _disposed;

		private string _writerError = "";

		public static RuntimeTraceRecorder? Instance { get; private set; }

		public string OutputRoot => _outputRoot;

		public string ProgressPath => _progressPath;

		public string LatestSummaryPath => _latestSummaryPath;

		public string CurrentTracePath => _run?.TracePath ?? "";

		public RuntimeTraceRecorder(string outputRoot, TraceRuntimeMetadata runtime, GameFactBus? bus = null, RuleDiagnostics? diagnostics = null, Action<string>? logger = null)
		{
			if (string.IsNullOrWhiteSpace(outputRoot))
			{
				throw new ArgumentException("轨迹目录不能为空", "outputRoot");
			}
			_outputRoot = Path.GetFullPath(outputRoot);
			Directory.CreateDirectory(_outputRoot);
			_progressPath = Path.Combine(_outputRoot, "coverage-progress.json");
			_latestSummaryPath = Path.Combine(_outputRoot, "latest-run-summary.json");
			_runtime = runtime;
			_bus = bus ?? GameFactBus.Instance;
			_diagnostics = diagnostics ?? RuleDiagnostics.Instance;
			_logger = logger ?? new Action<string>(MainFile.Log);
			_coverage = new CoverageAccumulator(LoadProgress(_progressPath, _logger));
			_bus.AuditRecorded += RecordFact;
			_diagnostics.AuditRecorded += RecordRule;
			_writerTask = Task.Run((Action)WriterLoop);
		}

		public static RuntimeTraceRecorder Start(string outputRoot, string gameAssemblyVersion)
		{
			Stop("recorder_restarted");
			TraceRuntimeMetadata runtime = new TraceRuntimeMetadata(typeof(RuntimeTraceRecorder).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion ?? typeof(RuntimeTraceRecorder).Assembly.GetName().Version?.ToString() ?? "unknown", gameAssemblyVersion, CoverageContractCatalog.ContractVersion, Environment.OSVersion.ToString());
			Instance = new RuntimeTraceRecorder(outputRoot, runtime);
			return Instance;
		}

		public static void Stop(string reason = "mod_shutdown")
		{
			RuntimeTraceRecorder instance = Instance;
			Instance = null;
			if (instance != null)
			{
				instance.EndRun(reason);
				instance.Dispose();
			}
		}

		public void BeginRun(string runIdentity, long runEpoch, bool isLoaded)
		{
			lock (_gate)
			{
				ThrowIfDisposed();
				if (_run != null)
				{
					EndRunLocked(_run.ScheduledEndReason ?? "run_replaced");
				}
				string text = $"{DateTime.UtcNow:yyyyMMddTHHmmssfffZ}-r{runEpoch}-{Guid.NewGuid():N}";
				text = text.Substring(0, Math.Min(text.Length, 48));
				string tracePath = Path.Combine(_outputRoot, "trace-" + text + ".jsonl");
				_run = new MutableRun(text, runIdentity, runEpoch, isLoaded, tracePath);
				_coverage.BeginRun(isLoaded);
				RunTracePayload payload = new RunTracePayload(runIdentity, runEpoch, isLoaded, "", _runtime);
				Enqueue("run.started", payload, "", "", "", flush: true);
				foreach (RuntimeHealthPayload item in _startupHealth)
				{
					Enqueue("runtime.health", item, "", string.Join(',', item.AffectedRuleIds));
				}
			}
		}

		public void SetPatchHealth(IReadOnlyList<HarmonyPatchInstallResult> patches)
		{
			lock (_gate)
			{
				if (_disposed)
				{
					return;
				}
				_startupHealth.RemoveAll((RuntimeHealthPayload item) => item.Component == "Harmony");
				int num = patches.Count((HarmonyPatchInstallResult item) => !item.Success);
				_startupHealth.Add(new RuntimeHealthPayload("Harmony", (num == 0) ? "Healthy" : "Degraded", (num == 0) ? "PATCH_INSTALL_OK" : "PATCH_INSTALL_FAILED", $"成功 {patches.Count - num}/{patches.Count}，失败 {num}", patches.Where((HarmonyPatchInstallResult item) => !item.Success).SelectMany((HarmonyPatchInstallResult item) => item.AffectedRuleIds).Distinct<string>(StringComparer.Ordinal)
					.Order<string>(StringComparer.Ordinal)
					.ToArray()));
				foreach (HarmonyPatchInstallResult item in patches.Where((HarmonyPatchInstallResult item) => !item.Success))
				{
					_startupHealth.Add(new RuntimeHealthPayload("Harmony", "Failed", "PATCH_INSTALL_FAILED", item.PatchType + ": " + item.Error, item.AffectedRuleIds));
				}
			}
		}

		public RunTraceSummary? EndRun(string reason)
		{
			lock (_gate)
			{
				if (_disposed || _run == null)
				{
					return null;
				}
				return EndRunLocked(_run.ScheduledEndReason ?? reason);
			}
		}

		public void ScheduleEndRun(string reason, TimeSpan drainTime)
		{
			string reason2 = reason;
			string sessionId;
			lock (_gate)
			{
				if (_disposed || _run == null)
				{
					return;
				}
				sessionId = _run.SessionId;
				_run.ScheduledEndReason = reason2;
			}
			Task.Delay(drainTime).ContinueWith(delegate
			{
				lock (_gate)
				{
					if (!_disposed && !(_run?.SessionId != sessionId))
					{
						EndRunLocked(_run.ScheduledEndReason ?? reason2);
					}
				}
			}, CancellationToken.None, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
		}

		public void RecordDispatch(DanmakuSignal signal, RuleEvidence evidence)
		{
			lock (_gate)
			{
				if (!_disposed && _run != null)
				{
					string ruleId = DanmakuRuleIds.Get(signal.Trigger);
					DispatchTracePayload payload = new DispatchTracePayload(evidence.EventId, signal.Trigger, ruleId, signal.Variant, evidence.Phase, signal.Scope, signal.Context, evidence.ReasonCode, signal.SourceCharacterId);
					Enqueue("dispatch", payload, evidence.EventId.ToString(), ruleId, signal.CorrelationId);
				}
			}
		}

		public void RecordEmission(EmissionTraceRecord record)
		{
			lock (_gate)
			{
				if (!_disposed && _run != null)
				{
					long traceSequence = Enqueue("emission", record, record.EventId?.ToString() ?? "", record.RuleId, record.CorrelationId);
					_coverage.ObserveEmission(record, _run.SessionId, traceSequence, _runtime.ModVersion);
					if (record.Stage == EmissionTraceStage.Spawned)
					{
						_run.SpawnedBubbles++;
					}
				}
			}
		}

		public bool RecordFixture(RealGameFixtureMarker marker)
		{
			lock (_gate)
			{
				if (_disposed || _run == null)
				{
					return false;
				}
				Enqueue("fixture", marker, "", marker.RuleId, "", flush: true);
				return true;
			}
		}

		private void RecordFact(FactAuditRecord audit, IGameFact fact)
		{
			lock (_gate)
			{
				if (!_disposed && _run != null)
				{
					Enqueue("fact", new FactTracePendingPayload(audit, fact), audit.EventId.ToString());
					_run.FactRecords++;
				}
			}
		}

		private void RecordRule(RuleAuditRecord audit)
		{
			lock (_gate)
			{
				if (!_disposed && _run != null)
				{
					long traceSequence = Enqueue("rule", new RuleTracePayload(audit), audit.EventId.ToString(), audit.RuleId);
					_coverage.ObserveRule(audit, _run.SessionId, traceSequence, _runtime.ModVersion);
					_run.RuleEvaluations++;
					if (audit.Decision == RuleDecision.Accepted)
					{
						_run.AcceptedRules++;
					}
				}
			}
		}

		private RunTraceSummary EndRunLocked(string reason)
		{
			MutableRun run = _run;
			Enqueue("run.ended", new RunTracePayload(run.RunIdentity, run.RunEpoch, run.IsLoaded, reason, _runtime), "", "", "", flush: true);
			CoverageProgressDocument coverageProgressDocument = _coverage.Snapshot();
			int coveredPositiveRules = coverageProgressDocument.Proofs.Count((CoverageProof proof) => proof.Category == CoverageCategory.POS);
			RunTraceSummary runTraceSummary = new RunTraceSummary(run.SessionId, run.RunIdentity, reason, run.FactRecords, run.RuleEvaluations, run.AcceptedRules, run.SpawnedBubbles, _coverage.NewTargets, coverageProgressDocument.Proofs.Count, CoverageContractCatalog.TotalTargets, coveredPositiveRules, CoverageContractCatalog.All.Count, _droppedRecords, run.TracePath, _progressPath);
			Enqueue("run.summary", runTraceSummary, "", "", "", flush: true);
			PersistJsonAtomically(_progressPath, coverageProgressDocument);
			PersistJsonAtomically(_latestSummaryPath, runTraceSummary);
			PersistTextAtomically(Path.Combine(_outputRoot, "latest-run-summary.md"), RenderSummary(runTraceSummary, coverageProgressDocument));
			_logger($"[Coverage] 本局新增 {runTraceSummary.NewCoverageTargets} 个覆盖目标；累计 {runTraceSummary.CoveredTargets}/{runTraceSummary.TotalTargets}，正例规则 {runTraceSummary.CoveredPositiveRules}/{runTraceSummary.TotalRules}。报告：{_latestSummaryPath}");
			if (_droppedRecords > 0)
			{
				_logger($"[Coverage] 轨迹队列曾满，丢弃 {_droppedRecords} 条记录；本局证据不应作为完整证明。");
			}
			if (!string.IsNullOrWhiteSpace(_writerError))
			{
				_logger("[Coverage] 后台写入曾失败：" + _writerError);
			}
			_run = null;
			_droppedRecords = 0;
			return runTraceSummary;
		}

		private long Enqueue<T>(string kind, T payload, string eventId = "", string ruleId = "", string correlationId = "", bool flush = false)
		{
			if (_run == null)
			{
				return 0L;
			}
			long num = ++_traceSequence;
			TraceWriteItem item = new TraceWriteItem(_run.TracePath, _run.SessionId, num, DateTimeOffset.UtcNow, kind, eventId, ruleId, correlationId, payload, typeof(T), flush);
			if (!_writes.TryAdd(item))
			{
				_droppedRecords++;
			}
			return num;
		}

		private void WriterLoop()
		{
			StreamWriter streamWriter = null;
			string a = "";
			try
			{
				foreach (TraceWriteItem item in _writes.GetConsumingEnumerable())
				{
					try
					{
						if (!string.Equals(a, item.Path, StringComparison.Ordinal))
						{
							streamWriter?.Dispose();
							Directory.CreateDirectory(Path.GetDirectoryName(item.Path));
							streamWriter = new StreamWriter(new FileStream(item.Path, FileMode.Append, FileAccess.Write, FileShare.ReadWrite), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false))
							{
								AutoFlush = true
							};
							a = item.Path;
						}
						JsonElement payload;
						if (item.Payload is FactTracePendingPayload factTracePendingPayload)
						{
							JsonElement fact;
							try
							{
								fact = JsonSerializer.SerializeToElement(factTracePendingPayload.Fact, factTracePendingPayload.Fact.GetType(), TelemetryJson.Compact);
							}
							catch (Exception ex)
							{
								fact = JsonSerializer.SerializeToElement(new
								{
									serializationError = ex.Message
								}, TelemetryJson.Compact);
							}
							payload = JsonSerializer.SerializeToElement(new FactTracePayload(factTracePendingPayload.Audit, factTracePendingPayload.Fact.GetType().Name, fact), typeof(FactTracePayload), TelemetryJson.Compact);
						}
						else
						{
							payload = JsonSerializer.SerializeToElement(item.Payload, item.PayloadType, TelemetryJson.Compact);
						}
						RuntimeTraceEvent value = new RuntimeTraceEvent(1, item.RunSessionId, item.Sequence, item.RecordedAtUtc, item.Kind, item.EventId, item.RuleId, item.CorrelationId, payload);
						streamWriter.WriteLine(JsonSerializer.Serialize(value, TelemetryJson.Compact));
						if (item.Flush)
						{
							streamWriter.Flush();
						}
					}
					catch (Exception ex2)
					{
						_writerError = ex2.Message;
					}
				}
			}
			finally
			{
				try
				{
					streamWriter?.Dispose();
				}
				catch
				{
				}
			}
		}

		private static CoverageProgressDocument? LoadProgress(string path, Action<string> logger)
		{
			try
			{
				return File.Exists(path) ? JsonSerializer.Deserialize<CoverageProgressDocument>(File.ReadAllText(path), TelemetryJson.Compact) : null;
			}
			catch (Exception ex)
			{
				logger("[Coverage] 旧进度无法读取，将按当前契约重新累计：" + ex.Message);
				return null;
			}
		}

		private void PersistJsonAtomically<T>(string path, T value)
		{
			PersistTextAtomically(path, JsonSerializer.Serialize(value, TelemetryJson.Indented));
		}

		private void PersistTextAtomically(string path, string content)
		{
			string text = path + $".{Guid.NewGuid():N}.tmp";
			try
			{
				Directory.CreateDirectory(Path.GetDirectoryName(path));
				File.WriteAllText(text, content, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				File.Move(text, path, overwrite: true);
			}
			catch (Exception ex)
			{
				_logger("[Coverage] 写入报告失败 " + path + ": " + ex.Message);
				try
				{
					if (File.Exists(text))
					{
						File.Delete(text);
					}
				}
				catch
				{
				}
			}
		}

		private static string RenderSummary(RunTraceSummary summary, CoverageProgressDocument progress)
		{
			List<string> list = new List<string>
			{
				"# 弹幕尖塔实机覆盖摘要",
				"",
				$"- Run：`{summary.RunIdentity}`（`{summary.RunSessionId}`）",
				"- 结束原因：`" + summary.EndReason + "`",
				$"- 本局事实/规则评估/接受/实际气泡：{summary.FactRecords}/{summary.RuleEvaluations}/{summary.AcceptedRules}/{summary.SpawnedBubbles}",
				$"- 本局新增覆盖：{summary.NewCoverageTargets}",
				$"- 累计覆盖：{summary.CoveredTargets}/{summary.TotalTargets}",
				$"- 已观察正例规则：{summary.CoveredPositiveRules}/{summary.TotalRules}",
				$"- 丢弃轨迹记录：{summary.DroppedTraceRecords}",
				"",
				"## 尚缺类别",
				""
			};
			HashSet<string> proofKeys = progress.Proofs.Select((CoverageProof proof) => $"{proof.RuleId}:{proof.Category}").ToHashSet<string>(StringComparer.Ordinal);
			foreach (IGrouping<CoverageCategory, (string, CoverageCategory)> item in from target in CoverageContractCatalog.All.SelectMany((RuleCoverageContract contract) => contract.Categories.Select((CoverageCategory category) => (RuleId: contract.RuleId, Category: category)))
				where !proofKeys.Contains($"{target.RuleId}:{target.Category}")
				group target by target.Category into @group
				orderby @group.Key
				select @group)
			{
				list.Add($"- `{item.Key}`：{item.Count()} 条规则");
			}
			list.Add("");
			list.Add("轨迹：`" + summary.TracePath + "`");
			list.Add("累计进度：`" + summary.ProgressPath + "`");
			return string.Join(Environment.NewLine, list);
		}

		private void ThrowIfDisposed()
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
		}

		public void Dispose()
		{
			lock (_gate)
			{
				if (_disposed)
				{
					return;
				}
				if (_run != null)
				{
					EndRunLocked("recorder_disposed");
				}
				_disposed = true;
				_bus.AuditRecorded -= RecordFact;
				_diagnostics.AuditRecorded -= RecordRule;
				_writes.CompleteAdding();
			}
			try
			{
				_writerTask.Wait(TimeSpan.FromSeconds(5L));
			}
			catch (Exception ex)
			{
				_logger("[Coverage] 等待后台写入结束失败：" + ex.Message);
			}
			_writes.Dispose();
		}
	}
}
namespace DanmakuSpire.DanmakuSpireCode.Emitter
{
	public sealed class DanmakuEmitter : IDanmakuEmitter
	{
		private readonly RollingDanmakuEmitter _rolling;

		private bool _shutdown;

		public TimeSpan RunEndTraceDrainTime => TimeSpan.FromSeconds(18.0);

		public DanmakuEmitter()
		{
			_rolling = new RollingDanmakuEmitter();
		}

		public void BeginRunSession()
		{
			_rolling.BeginRunSession();
		}

		public void BeginRoomSession()
		{
			_rolling.BeginRoomSession();
		}

		public void BeginCombatSession()
		{
			_rolling.BeginCombatSession();
		}

		public void CancelRunSession()
		{
			_rolling.CancelRunSession();
		}

		public void CancelRoomSession()
		{
			_rolling.CancelRoomSession();
		}

		public void CancelCombatSession()
		{
			_rolling.CancelCombatSession();
		}

		public void Emit(DanmakuSignal signal)
		{
			if (_shutdown)
			{
				return;
			}
			if (signal.Channel == DanmakuChannel.Multiplayer)
			{
				if (DanmakuModConfig.ShouldEmitMultiplayer() && (!signal.IsRemote || DanmakuModConfig.ShouldReceiveMultiplayer()))
				{
					_rolling.EmitMultiplayer(signal);
				}
			}
			else if (DanmakuModConfig.ShouldEmitSinglePlayer())
			{
				_rolling.Emit(signal);
			}
		}

		public DanmakuSignal? PrepareMultiplayer(DanmakuSignal signal)
		{
			if (_shutdown)
			{
				return null;
			}
			return _rolling.PrepareMultiplayer(signal);
		}

		public void EmitChat(string body, string sourceCharacterId, string sourcePlayerName, string correlationId, EmissionScope scope, string color = "", bool rainbow = false)
		{
			if (!_shutdown)
			{
				_rolling.EmitChat(body, sourceCharacterId, sourcePlayerName, correlationId, scope, color, rainbow);
			}
		}

		public void Shutdown()
		{
			if (!_shutdown)
			{
				_shutdown = true;
				_rolling.Shutdown();
			}
		}
	}
	public static class DanmakuEmojiFont
	{
		public const string EmbeddedResourceName = "DanmakuSpire.Assets.NotoColorEmoji.ttf";

		private const float EmojiScale = 1.5f;

		private static Font? _font;

		private static bool _loadAttempted;

		private static bool _loadFailed;

		public static Font? Load()
		{
			//IL_0054: Unknown result type (might be due to invalid IL or missing references)
			//IL_0059: Unknown result type (might be due to invalid IL or missing references)
			//IL_0065: Expected O, but got Unknown
			if (_loadAttempted)
			{
				return _font;
			}
			_loadAttempted = true;
			try
			{
				using Stream stream = typeof(DanmakuEmojiFont).Assembly.GetManifestResourceStream("DanmakuSpire.Assets.NotoColorEmoji.ttf");
				if (stream == null)
				{
					throw new InvalidOperationException("程序集资源不存在：DanmakuSpire.Assets.NotoColorEmoji.ttf");
				}
				byte[] array = new byte[stream.Length];
				stream.ReadExactly(array);
				_font = WrapWithScale(new FontFile
				{
					Data = array
				});
				MainFile.Log($"[EmojiFont] 彩色 emoji 字体已加载（FontVariation 缩放 {1.5f}x）。");
			}
			catch (Exception ex)
			{
				_loadFailed = true;
				MainFile.Log("[EmojiFont] 彩色 emoji 字体载入失败，emoji 将回退为普通字形：" + ex.Message);
			}
			return _font;
		}

		private static Font WrapWithScale(FontFile fontFile)
		{
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0031: Unknown result type (might be due to invalid IL or missing references)
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Expected O, but got Unknown
			try
			{
				Transform2D variationTransform = default(Transform2D);
				((Transform2D)(ref variationTransform))..ctor(0f, new Vector2(1.5f, 1.5f), 0f, Vector2.Zero);
				return (Font)new FontVariation
				{
					BaseFont = (Font)(object)fontFile,
					VariationTransform = variationTransform
				};
			}
			catch
			{
				return (Font)(object)fontFile;
			}
		}

		public static void AttachFallback(Font? primary)
		{
			if (primary == null)
			{
				return;
			}
			Font val = Load();
			if (val == null || _loadFailed)
			{
				return;
			}
			try
			{
				Array<Font> obj = new Array<Font>();
				obj.Add(val);
				primary.Fallbacks = obj;
			}
			catch (Exception ex)
			{
				MainFile.Log("[EmojiFont] 设置 emoji 字体回退失败：" + ex.Message);
			}
		}

