			{
				DanmakuChatComposer.CloseComposer();
			}
			ApplyFrontendAvailability();
		}

		private void CaptureScene()
		{
			SceneCapture sceneCapture = SceneCaptureService.Capture();
			if (sceneCapture == null)
			{
				ShowToast("捕获失败：当前没有可用的游戏场景。", error: true);
				return;
			}
			SceneCaptureService.Store?.Add(sceneCapture);
			SubmissionUiHost.RefreshInspirations();
			ShowToast("已捕获当前游戏状态并存储于“我的灵感”。可用于共创弹幕投稿", error: false);
		}

		private void ShowToast(string text, bool error)
		{
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			if (_captureToastLabel != null)
			{
				_captureToastLabel.Text = text;
				((CanvasItem)_captureToastLabel).Modulate = (error ? new Color(1f, 0.55f, 0.5f, 1f) : new Color(0.92f, 0.88f, 0.72f, 1f));
				((CanvasItem)_captureToastLabel).Visible = true;
				_captureToastRemaining = 4.0;
			}
		}

		public override void _Process(double delta)
		{
			if (_captureToastRemaining > 0.0)
			{
				_captureToastRemaining -= delta;
				if (_captureToastRemaining <= 0.0 && _captureToastLabel != null)
				{
					((CanvasItem)_captureToastLabel).Visible = false;
				}
			}
		}

