				Trace(signal, EmissionTraceStage.Rejected, "renderer=rolling;rule_disabled:" + text2);
				return;
			}
			IReadOnlyList<DanmakuEntry> entries = DanmakuLibrary.GetEntries(signal.Trigger, signal.Variant);
			entries = MultiplayerCharacterSubstitute.FilterSinglePlayerCandidates(entries, signal.Trigger, signal.Variant);
			if (entries.Count == 0)
			{
				MainFile.Log($"[RollingEmitter] 未找到触发 {signal.Trigger}/{signal.Variant} 的弹幕组，跳过。");
				Trace(signal, EmissionTraceStage.Rejected, "renderer=rolling;empty_danmaku_group");
