				MainFile.Log($"[RollingEmitter] 触发 {signal.Trigger}/{signal.Variant} 缺少模板上下文 {text3}，跳过。");
				Trace(signal, EmissionTraceStage.Rejected, "renderer=rolling;missing_context:" + text3);
				return;
			}
			if (array.Length != entries.Count)
			{
				string value = string.Join(",", entries.SelectMany((DanmakuEntry entry) => entry.GetMissingContextKeys(signal.Context)).Distinct());
				MainFile.Log($"[RollingEmitter] 触发 {signal.Trigger}/{signal.Variant} 缺少部分模板上下文 {value}，仅抽取可解析词条。");
			}
			DanmakuIntensity danmakuIntensity = DanmakuIntensityCatalog.Get(signal.Trigger);
			int num = ((signal.FixedCount > 0) ? signal.FixedCount : RollingDanmakuCountProfile.PickCount(signal.Trigger, _rng));
			IReadOnlyList<PlannedRollingDanmaku> readOnlyList = RollingDanmakuPlanner.Plan(array, num, _rng, danmakuIntensity, signal.ForceTop);
			string text4 = (string.IsNullOrWhiteSpace(signal.CorrelationId) ? RuntimeTraceIds.NewCorrelation(signal.SourceEventId, DanmakuRuleIds.Get(signal.Trigger)) : signal.CorrelationId);
			Color? val = RollingCharacterColors.Resolve(signal.SourceCharacterId);
			List<PendingRollingDanmaku> list = new List<PendingRollingDanmaku>(readOnlyList.Count);
			for (int i = 0; i < readOnlyList.Count; i++)
			{
				DanmakuEntry entry2 = readOnlyList[i].Entry;
				string entryId = RuntimeTraceIds.EntryId(signal.Trigger, signal.Variant, entry2.Text);
				bool flag = !string.IsNullOrWhiteSpace(entry2.LikeTargetId) && !string.IsNullOrWhiteSpace(entry2.Author) && !string.Equals(entry2.Author, "预设", StringComparison.Ordinal);
				string text5 = (flag ? entry2.LikeTargetId : "");
				Color? val2 = ParseColor(entry2.Color);
				RollingPlacement placement = (entry2.TopPinned ? RollingPlacement.Top : readOnlyList[i].Placement);
				(string, string)[] array2 = (from item in entry2.ResolveAll(signal.Context).Select((string text, int index) => (Text: text, Template: entry2.AllTexts[index]))
					where !string.IsNullOrWhiteSpace(item.Text)
					select item).ToArray();
				double num2 = DanmakuSequence.IntervalSeconds(entry2.SequenceSpeed);
				for (int j = 0; j < array2.Length; j++)
				{
					string item2 = array2[j].Item1;
					string itemId = $"{text4}:r{i + 1}:s{j + 1}";
					string item3 = array2[j].Item2;
					DanmakuTextStyle style = entry2.Style;
					DanmakuTrigger trigger = signal.Trigger;
					EmissionScope scope = signal.Scope;
					double delaySeconds = readOnlyList[i].DelaySeconds;
					string variant = signal.Variant;
					EventId? sourceEventId = signal.SourceEventId;
					Color? characterColor = ((entry2.Style == DanmakuTextStyle.Character) ? val : null);
					string sourceCharacterId = signal.SourceCharacterId;
					Color? textColor = val2;
					bool rainbow = entry2.Rainbow;
					string sequenceGroupId = ((array2.Length > 1) ? $"{text4}:r{i + 1}" : "");
					int sequenceIndex = j;
					int sequenceCount = array2.Length;
					double sequenceIntervalSeconds = num2;
					string author = (string.IsNullOrWhiteSpace(entry2.Author) ? "预设" : entry2.Author);
					bool forceTop = signal.ForceTop;
					string likeTargetId = text5;
					bool likeable = flag;
					PendingRollingDanmaku item4 = new PendingRollingDanmaku(item2, style, placement, trigger, scope, delaySeconds, text4, itemId, entryId, variant, item3, sourceEventId, characterColor, sourceCharacterId, null, textColor, rainbow, sequenceGroupId, sequenceIndex, sequenceCount, sequenceIntervalSeconds, author, forceTop, likeTargetId, likeable);
					list.Add(item4);
					Trace(item4, EmissionTraceStage.Selected, $"renderer=rolling;intensity={danmakuIntensity};target_count={num};placement={item4.Placement.ToString().ToLowerInvariant()};delay_seconds={item4.DelaySeconds:F3};sequence={j + 1}/{array2.Length};rainbow={entry2.Rainbow.ToString().ToLowerInvariant()}");
