		public DanmakuSignal? PrepareMultiplayer(DanmakuSignal signal)
		{
			if (signal.Scope == EmissionScope.Unknown)
			{
				Trace(signal, EmissionTraceStage.Rejected, "renderer=rolling;multiplayer;unknown_scope");
				return null;
			}
			IReadOnlyList<DanmakuEntry> candidates = DanmakuLibrary.GetMultiplayerEntries(signal.Trigger, signal.Variant);
			if (candidates.Count == 0)
			{
				Trace(signal, EmissionTraceStage.Rejected, "renderer=rolling;multiplayer;empty_multiplayer_group");
				return null;
			}
			IReadOnlyDictionary<string, string> context = ResolveMultiplayerContext(signal);
			DanmakuEntry? danmakuEntry = null;
			long num = -1L;
			if (signal.EntryIndex >= 0 && signal.EntryIndex < candidates.Count)
			{
				danmakuEntry = candidates[(int)signal.EntryIndex];
				num = signal.EntryIndex;
			}
			else
			{
				int[] array = (from index in Enumerable.Range(0, candidates.Count)
					where candidates[index].GetMissingContextKeys(context).Count == 0
					select index).ToArray();
				if (array.Length != 0)
				{
					num = array[_rng.Next(array.Length)];
					danmakuEntry = candidates[(int)num];
				}
			}
			if (!danmakuEntry.HasValue || danmakuEntry.Value.GetMissingContextKeys(context).Count > 0)
			{
				string value = ((!danmakuEntry.HasValue) ? "" : string.Join(",", danmakuEntry.Value.GetMissingContextKeys(context)));
				Trace(signal, EmissionTraceStage.Rejected, $"renderer=rolling;multiplayer;unresolvable_entry;index={signal.EntryIndex};missing={value}");
				return null;
			}
			return signal with
			{
				EntryIndex = num
			};
		}

		public void EmitMultiplayer(DanmakuSignal signal)
		{
			if (signal.Scope == EmissionScope.Unknown)
			{
				Trace(signal, EmissionTraceStage.Rejected, "renderer=rolling;multiplayer;unknown_scope");
