			if (!DanmakuModConfig.IsRuleEnabled(text2))
			{
				Trace(signal, EmissionTraceStage.Rejected, "renderer=rolling;multiplayer;rule_disabled:" + text2);
				return;
			}
			IReadOnlyList<DanmakuEntry> multiplayerEntries = DanmakuLibrary.GetMultiplayerEntries(signal.Trigger, signal.Variant);
			if (signal.EntryIndex < 0 || signal.EntryIndex >= multiplayerEntries.Count)
			{
				Trace(signal, EmissionTraceStage.Rejected, $"renderer=rolling;multiplayer;invalid_entry_index={signal.EntryIndex}");
				return;
			}
			IReadOnlyDictionary<string, string> context = ResolveMultiplayerContext(signal);
			DanmakuEntry entry = multiplayerEntries[(int)signal.EntryIndex];
			if (entry.GetMissingContextKeys(context).Count > 0)
			{
				string text3 = string.Join(",", entry.GetMissingContextKeys(context));
				Trace(signal, EmissionTraceStage.Rejected, "renderer=rolling;multiplayer;missing_context:" + text3);
				return;
			}
			bool flag = !string.IsNullOrWhiteSpace(entry.LikeTargetId) && !string.IsNullOrWhiteSpace(entry.Author) && !string.Equals(entry.Author, "预设", StringComparison.Ordinal);
			string text4 = (flag ? entry.LikeTargetId : "");
			string text5 = (string.IsNullOrWhiteSpace(signal.CorrelationId) ? RuntimeTraceIds.NewCorrelation(signal.SourceEventId, DanmakuRuleIds.Get(signal.Trigger)) : signal.CorrelationId);
			Color? characterColor = RollingCharacterColors.Resolve(signal.SourceCharacterId);
			(string, string)[] array = (from item in entry.ResolveAll(context).Select((string text, int index) => (Text: text, Template: entry.AllTexts[index]))
				where !string.IsNullOrWhiteSpace(item.Text)
				select item).ToArray();
			double delaySeconds = _rng.NextDouble() * 0.45000000000000007 + 0.1;
			double num = DanmakuSequence.IntervalSeconds(entry.SequenceSpeed);
			List<PendingRollingDanmaku> list = new List<PendingRollingDanmaku>(array.Length);
			for (int i = 0; i < array.Length; i++)
			{
				string item2 = array[i].Item1;
				string text6 = (string.IsNullOrWhiteSpace(signal.SourcePlayerName) ? item2 : (signal.SourcePlayerName + "：" + item2));
				DanmakuTrigger trigger = signal.Trigger;
				EmissionScope scope = signal.Scope;
				string itemId = $"{text5}:mp:s{i + 1}";
				string entryId = RuntimeTraceIds.EntryId(signal.Trigger, signal.Variant, entry.Text);
				string variant = signal.Variant;
				string item3 = array[i].Item2;
				EventId? sourceEventId = signal.SourceEventId;
				string sourceCharacterId = signal.SourceCharacterId;
				bool rainbow = entry.Rainbow;
				string sequenceGroupId = ((array.Length > 1) ? (text5 + ":mp") : "");
				int sequenceIndex = i;
				int sequenceCount = array.Length;
				double sequenceIntervalSeconds = num;
				string author = (string.IsNullOrWhiteSpace(entry.Author) ? "预设" : entry.Author);
				string likeTargetId = text4;
				bool likeable = flag;
				PendingRollingDanmaku item4 = new PendingRollingDanmaku(text6, DanmakuTextStyle.Character, RollingPlacement.Scrolling, trigger, scope, delaySeconds, text5, itemId, entryId, variant, item3, sourceEventId, characterColor, sourceCharacterId, null, null, rainbow, sequenceGroupId, sequenceIndex, sequenceCount, sequenceIntervalSeconds, author, TopCanFallback: false, likeTargetId, likeable);
				list.Add(item4);
				Trace(item4, EmissionTraceStage.Selected, $"renderer=rolling;multiplayer;fixed_entry;top=never;sequence={i + 1}/{array.Length};" + "player_name=" + (string.IsNullOrWhiteSpace(signal.SourcePlayerName) ? "none" : "set"));
			}
			_scheduler.EnqueueBatch(list);
		}

