	public static class RollingDanmakuCountProfile
	{
		public static DanmakuCountRange GetRange(DanmakuIntensity intensity)
		{
			return GetRange(intensity, DanmakuModConfig.弹幕密度);
		}

		public static DanmakuCountRange GetRange(DanmakuIntensity intensity, DanmakuModConfig.弹幕密度档位 density)
		{
			(int, int) tuple;
			switch (intensity)
			{
			case DanmakuIntensity.Light:
				switch (density)
				{
				case DanmakuModConfig.弹幕密度档位.稀疏:
					break;
				case DanmakuModConfig.弹幕密度档位.标准:
					goto IL_0062;
				case DanmakuModConfig.弹幕密度档位.密集:
					goto IL_006c;
				default:
					goto IL_00b6;
				}
				tuple = (1, 2);
				break;
			case DanmakuIntensity.Medium:
				switch (density)
				{
				case DanmakuModConfig.弹幕密度档位.稀疏:
					break;
				case DanmakuModConfig.弹幕密度档位.标准:
					goto IL_0080;
				case DanmakuModConfig.弹幕密度档位.密集:
					goto IL_008a;
				default:
					goto IL_00b6;
				}
				tuple = (2, 3);
				break;
			case DanmakuIntensity.Strong:
				switch (density)
				{
				case DanmakuModConfig.弹幕密度档位.稀疏:
					break;
				case DanmakuModConfig.弹幕密度档位.标准:
					goto IL_009e;
				case DanmakuModConfig.弹幕密度档位.密集:
					goto IL_00aa;
				default:
					goto IL_00b6;
				}
				tuple = (6, 8);
				break;
			default:
				goto IL_00b6;
				IL_00aa:
				tuple = (12, 14);
				break;
				IL_009e:
				tuple = (10, 12);
				break;
				IL_006c:
				tuple = (3, 4);
				break;
				IL_008a:
				tuple = (6, 8);
				break;
				IL_0080:
				tuple = (4, 6);
				break;
				IL_0062:
				tuple = (2, 3);
				break;
				IL_00b6:
				tuple = (2, 4);
				break;
			}
			var (min, max) = tuple;
			return new DanmakuCountRange(min, max);
		}

		public static int PickCount(DanmakuTrigger trigger, Random random)
		{
			return GetRange(DanmakuIntensityCatalog.Get(trigger)).Pick(random);
		}
	}
