			if (candidates.Count == 0 || targetCount <= 0)
			{
				return Array.Empty<PlannedRollingDanmaku>();
			}
			DanmakuEntry[] array = candidates.Where((DanmakuEntry item) => item.Style == DanmakuTextStyle.Character).ToArray();
			DanmakuEntry[] array2 = candidates.Where((DanmakuEntry item) => item.Style == DanmakuTextStyle.Narration).ToArray();
			List<DanmakuEntry> list = new List<DanmakuEntry>(targetCount);
			if (array.Length != 0)
			{
				list.Add(array[random.Next(array.Length)]);
			}
			while (list.Count < targetCount && array2.Length != 0)
			{
				list.Add(array2[random.Next(array2.Length)]);
			}
			double[] array3 = CreateDelays(list.Count, random);
			int num = PickTopIndex(list, random, intensity);
			PlannedRollingDanmaku[] array4 = new PlannedRollingDanmaku[list.Count];
			for (int i = 0; i < list.Count; i++)
			{
				bool flag = forceTop || num == -2 || i == num;
				array4[i] = new PlannedRollingDanmaku(list[i], array3[i], flag ? RollingPlacement.Top : RollingPlacement.Scrolling);
			}
			return array4;
		}

		public static double[] CreateDelays(int count, Random random)
		{
			if (count <= 0)
			{
				return Array.Empty<double>();
			}
			switch (count)
			{
			case 1:
				return new double[1] { Uniform(random, 0.1, 0.55) };
			case 2:
			{
				double[] obj = new double[2]
				{
					Uniform(random, 0.1, 0.4),
					Uniform(random, 1.6, 2.6)
				};
				Shuffle(obj, random);
				return obj;
			}
			default:
			{
				double[] array = new double[count];
				array[0] = Uniform(random, 0.1, 0.4);
				for (int i = 1; i < count - 1; i++)
				{
					array[i] = TruncatedNormal(random, 1.6, 0.5, 0.55, 2.75);
				}
				array[^1] = ((count >= 6) ? Uniform(random, 4.0, 5.6) : Uniform(random, 3.3, 4.5));
				Shuffle(array, random);
				return array;
			}
			}
		}

		private static int PickTopIndex(IReadOnlyList<DanmakuEntry> selected, Random random, DanmakuIntensity intensity)
		{
			if (DanmakuModConfig.顶部弹幕 == DanmakuModConfig.顶部弹幕档位.无)
			{
				return -1;
			}
			if (DanmakuModConfig.顶部弹幕 == DanmakuModConfig.顶部弹幕档位.全部)
			{
				return -2;
			}
			int[] array = (from pair in selected.Select((DanmakuEntry entry, int index) => (entry: entry, index: index))
				where pair.entry.Style == DanmakuTextStyle.Narration
				select pair.index).ToArray();
			if (array.Length == 0)
			{
				return -1;
			}
			double num = BaseTopProbability(intensity);
			if (!(random.NextDouble() < num))
			{
				return -1;
			}
			return array[random.Next(array.Length)];
		}

		public static double BaseTopProbability(DanmakuIntensity intensity)
		{
			return intensity switch
			{
				DanmakuIntensity.Light => 0.0, 
				DanmakuIntensity.Strong => 0.3, 
				_ => 0.15, 
			};
		}

		private static double TruncatedNormal(Random random, double mean, double deviation, double minimum, double maximum)
		{
			for (int i = 0; i < 12; i++)
			{
				double d = Math.Max(double.Epsilon, random.NextDouble());
				double num = random.NextDouble();
				double num2 = Math.Sqrt(-2.0 * Math.Log(d)) * Math.Cos(Math.PI * 2.0 * num);
				double num3 = mean + num2 * deviation;
				if (num3 >= minimum && num3 <= maximum)
				{
					return num3;
				}
			}
			return Math.Clamp(mean, minimum, maximum);
		}

		private static double Uniform(Random random, double minimum, double maximum)
		{
			return minimum + random.NextDouble() * (maximum - minimum);
		}

		private static void Shuffle(double[] values, Random random)
		{
			for (int num = values.Length - 1; num > 0; num--)
			{
				int num2 = random.Next(num + 1);
				ref double reference = ref values[num];
				ref double reference2 = ref values[num2];
				double num3 = values[num2];
				double num4 = values[num];
				reference = num3;
				reference2 = num4;
			}
		}
	}
