		private bool TrySelectAvailableLane(int requestedLaneLimit, double now, bool topPlacement, out LaneState selected)
		{
			int num = Math.Min(requestedLaneLimit, _lanes.Length);
			for (int i = 0; i < num; i++)
			{
				LaneState laneState = _lanes[i];
				if (!((topPlacement ? laneState.TopNextFreeAt : laneState.NextSafeAt) > now))
				{
					selected = laneState;
					return true;
				}
			}
			selected = null;
			return false;
		}

		private static float CalculateLaneY(float viewportHeight, int laneIndex, int laneLimit)
		{
			float num = Math.Max(100f, viewportHeight * 0.105f);
			float num2 = CalculateLaneStep(viewportHeight, laneLimit);
			return num + (float)laneIndex * num2;
		}

		public static float CalculateLaneStep(float viewportHeight)
		{
			return CalculateLaneStep(viewportHeight, 16);
		}

		public static float CalculateLaneStep(float viewportHeight, int laneLimit)
		{
			float num = Math.Max(100f, viewportHeight * 0.105f);
			return Math.Clamp(Math.Max(1f, viewportHeight - num - 48f * RollingDanmakuSpawner.VisualScale) / (float)Math.Max(1, laneLimit - 1), RollingDanmakuSpawner.CurrentLaneMinimumStep, 68f * RollingDanmakuSpawner.VisualScale);
		}

		public static double SpeedToSeconds(DanmakuModConfig.弹幕速度档位 speed)
		{
			return speed switch
			{
				DanmakuModConfig.弹幕速度档位.慢 => 14.0, 
				DanmakuModConfig.弹幕速度档位.较慢 => 12.0, 
				DanmakuModConfig.弹幕速度档位.较快 => 8.0, 
				DanmakuModConfig.弹幕速度档位.快 => 6.0, 
				_ => 10.0, 
			};
		}

		private void CompleteScroll(long id, string detail)
