			foreach (ActiveScroll value2 in _scrolling.Values)
			{
				Trace(value2.Item, EmissionTraceStage.Cancelled, "renderer=rolling;all_cancelled");
				RollingDanmakuSpawner.Remove(value2.Node);
			}
			_scrolling.Clear();
			_hoverPausedSince.Clear();
			_hoverRefCounts.Clear();
			_authorShownIds.Clear();
			GlobalPaused = false;
			_globalPauseSince = 0.0;
			LaneState[] lanes = _lanes;
			foreach (LaneState obj in lanes)
			{
