			if (num >= 0 && num + 1 < text.Length)
			{
				string text2 = text;
				int num2 = num + 1;
				text = text2.Substring(num2, text2.Length - num2);
			}
			if (text.EndsWith("Model", StringComparison.OrdinalIgnoreCase))
			{
				string text2 = text;
				int num2 = "Model".Length;
				text = text2.Substring(0, text2.Length - num2);
			}
			return text.Replace('-', '_').ToUpperInvariant();
		}

