	public readonly record struct RollingLaneSnapshot(int Index, double NextSafeAt, double LastExitAt);
	public readonly record struct RollingLaneDecision(int LaneIndex, double ReadyAt, bool ImmediatelyAvailable);
	public static class RollingLaneAllocator
	{
		public static RollingLaneDecision Select(IReadOnlyList<RollingLaneSnapshot> lanes, double now)
		{
			if (lanes.Count == 0)
			{
				throw new ArgumentException("至少需要一条滚动轨道。", "lanes");
			}
			foreach (RollingLaneSnapshot item in lanes.OrderBy((RollingLaneSnapshot item) => item.Index))
			{
				if (item.NextSafeAt <= now)
				{
					return new RollingLaneDecision(item.Index, now, ImmediatelyAvailable: true);
				}
			}
			RollingLaneSnapshot rollingLaneSnapshot = (from item in lanes
				orderby item.NextSafeAt, item.LastExitAt, item.Index
				select item).First();
			return new RollingLaneDecision(rollingLaneSnapshot.Index, rollingLaneSnapshot.NextSafeAt, ImmediatelyAvailable: false);
		}
	}
