		public override void _Process(double delta)
		{
			Action result;
			while (_mainThreadActions.TryDequeue(out result))
			{
				try
				{
					result();
				}
				catch (Exception value)
				{
					MainFile.Log($"[UGC] 主线程更新失败：{value}");
				}
			}
			if (RollingDanmakuScheduler.GlobalPaused)
			{
				return;
			}
			double now = _runtime.AdvanceClock(delta);
			if (!DanmakuModConfig.ShouldEmitUgc())
			{
				_runtime.Engine.ClearHotspots();
				return;
			}
			foreach (HotspotEmission item in _runtime.Advance(now))
			{
				_emitter.Emit(item);
			}
		}

