	public sealed class UgcEmitter
	{
		private readonly RollingDanmakuScheduler _scheduler;

		private readonly ContentStore _store;

		private readonly INetworkForwarder _forwarder;

		public UgcEmitter(ContentStore store, INetworkForwarder? forwarder = null)
		{
			_scheduler = RollingDanmakuScheduler.EnsureCreated();
			_store = store;
			_forwarder = forwarder ?? NoopNetworkForwarder.Instance;
		}

		public void Emit(HotspotEmission emission, IReadOnlyDictionary<string, string>? context = null)
		{
			string sourceCharacterId = DanmakuSourceIdentity.ResolveCurrentCharacterId();
			EmitEntry(emission.EntryId, context, sourceCharacterId);
			_forwarder.ForwardUgc(emission.EntryId, Array.Empty<KeyValuePair<string, string>>(), sourceCharacterId, $"ugc:{emission.EntryId}:{Guid.NewGuid():N}");
		}

		public void EmitRemote(string entryId, string sourceCharacterId)
		{
			EmitEntry(entryId, null, sourceCharacterId);
		}

		private void EmitEntry(string entryId, IReadOnlyDictionary<string, string>? context, string sourceCharacterId)
		{
			IReadOnlyDictionary<string, string> context2 = context;
			ContentEntry? entry = _store.GetById(entryId);
			if (!entry.HasValue)
			{
				return;
			}
			if (context2 == null)
			{
				context2 = ResolveTriggerContext(entry.Value.Trigger);
			}
			IReadOnlyList<string> readOnlyList = entry.Value.AllTexts.SelectMany((string text) => UgcEmissionPlanner.GetMissingKeys(text, context2)).Distinct<string>(StringComparer.Ordinal).ToArray();
			if (readOnlyList.Count > 0)
			{
				MainFile.Log($"[UGC] 词条 {entryId} 缺少模板上下文 {string.Join(',', readOnlyList)}，跳过。");
				return;
			}
			UgcEmissionPlan ugcEmissionPlan = UgcEmissionPlanner.Plan(entry.Value, context2);
			(string, string)[] array = (from item in ugcEmissionPlan.AllTexts.Select((string text, int index) => (Text: text, Template: entry.Value.AllTexts[index]))
				where !string.IsNullOrWhiteSpace(item.Text)
				select item).ToArray();
			if (array.Length == 0)
			{
				return;
			}
			Color? val = ((ugcEmissionPlan.ColorHex != null) ? ParseHexColor(ugcEmissionPlan.ColorHex) : null);
			bool flag = ugcEmissionPlan.Style == ContentStyle.Character;
			string text2 = "";
			if (flag)
			{
				text2 = ((!string.IsNullOrWhiteSpace(ugcEmissionPlan.Avatar)) ? ugcEmissionPlan.Avatar : sourceCharacterId);
				if (string.IsNullOrWhiteSpace(text2) && entry.Value.Trigger.Kind == ContentObjectKind.Character && entry.Value.Trigger.Id != "*")
				{
					text2 = entry.Value.Trigger.Id;
				}
			}
			Color? characterColor = (flag ? RollingCharacterColors.Resolve(text2) : null);
			string text3 = $"ugc:{entryId}:{Guid.NewGuid():N}";
			double num = DanmakuSequence.IntervalSeconds(ugcEmissionPlan.SequenceSpeed);
			bool flag2 = !string.IsNullOrWhiteSpace(entry.Value.Author) && !string.Equals(entry.Value.Author, "预设", StringComparison.Ordinal);
			List<PendingRollingDanmaku> list = new List<PendingRollingDanmaku>(array.Length);
			for (int i = 0; i < array.Length; i++)
			{
				string item2 = array[i].Item1;
				bool style = !flag;
				int placement = (ugcEmissionPlan.TopPinned ? 1 : 0);
				string itemId = $"{text3}:s{i + 1}";
				string item3 = array[i].Item2;
				string sourceCharacterId2 = text2;
				Color? textColor = val;
				bool rainbow = ugcEmissionPlan.Rainbow;
				string sequenceGroupId = ((array.Length > 1) ? text3 : "");
				int sequenceIndex = i;
				int sequenceCount = array.Length;
				double sequenceIntervalSeconds = num;
				string author = entry.Value.Author;
				bool likeable = flag2;
				list.Add(new PendingRollingDanmaku(item2, style ? DanmakuTextStyle.Narration : DanmakuTextStyle.Character, (RollingPlacement)placement, DanmakuTrigger.CombatStart, EmissionScope.Run, 0.0, text3, itemId, entryId, "", item3, null, characterColor, sourceCharacterId2, null, textColor, rainbow, sequenceGroupId, sequenceIndex, sequenceCount, sequenceIntervalSeconds, author, TopCanFallback: false, entryId, likeable));
			}
			_scheduler.EnqueueBatch(list);
		}

		private static IReadOnlyDictionary<string, string> ResolveTriggerContext(ContentTrigger trigger)
		{
			string text = ResolveObjectDisplayName(trigger);
			switch (trigger.Kind)
			{
			case ContentObjectKind.Character:
				return new Dictionary<string, string>(StringComparer.Ordinal) { ["char"] = CharacterNames.DisplayName(trigger.Id) };
			case ContentObjectKind.Card:
				return new Dictionary<string, string>(StringComparer.Ordinal)
				{
					["card"] = CardAlias.DisplayName(text),
					["item"] = CardAlias.DisplayName(text)
				};
			case ContentObjectKind.Relic:
				return new Dictionary<string, string>(StringComparer.Ordinal) { ["item"] = RelicAlias.DisplayName(text) };
			case ContentObjectKind.Monster:
			case ContentObjectKind.Event:
				return new Dictionary<string, string>(StringComparer.Ordinal) { ["item"] = text };
			default:
				return new Dictionary<string, string>(0);
			}
		}

		private static string ResolveObjectDisplayName(ContentTrigger trigger)
		{
			try
			{
				ContentObjectCatalog contentObjectCatalog = ObjectCatalogProvider.Instance.TryGetAvailableCatalog();
				if (contentObjectCatalog == null)
				{
					return trigger.Id;
				}
				ContentObjectEntry? contentObjectEntry = contentObjectCatalog.Objects.FirstOrDefault((ContentObjectEntry item) => item.Kind == trigger.Kind && string.Equals(item.Id, trigger.Id, StringComparison.Ordinal));
				if (contentObjectEntry.HasValue)
				{
					ContentObjectEntry valueOrDefault = contentObjectEntry.GetValueOrDefault();
					if (!string.IsNullOrWhiteSpace(valueOrDefault.DisplayName))
					{
						return valueOrDefault.DisplayName;
					}
				}
				if (trigger.Kind == ContentObjectKind.Event)
				{
					int num = trigger.Id.IndexOf(':');
					if (num > 0 && num + 1 < trigger.Id.Length)
					{
						string eventId = trigger.Id.Substring(0, num);
						string id = trigger.Id;
						int num2 = num + 1;
						string optionId = id.Substring(num2, id.Length - num2);
						EventOptionEntry? eventOptionEntry = contentObjectCatalog.EventOptions.FirstOrDefault((EventOptionEntry item) => string.Equals(item.EventId, eventId, StringComparison.Ordinal) && string.Equals(item.OptionKey, optionId, StringComparison.Ordinal));
						if (eventOptionEntry.HasValue)
						{
							EventOptionEntry valueOrDefault2 = eventOptionEntry.GetValueOrDefault();
							if (!string.IsNullOrWhiteSpace(valueOrDefault2.DisplayName))
							{
								return valueOrDefault2.DisplayName;
							}
						}
					}
				}
			}
			catch (Exception ex)
			{
				MainFile.Log("[UGC] 对象目录解析失败，回退稳定 ID：" + ex.Message);
			}
			return trigger.Id;
		}

		private static Color? ParseHexColor(string hex)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				return new Color(hex);
			}
			catch
			{
				return null;
			}
		}
	}
