		public static void Apply(CardCategoryScan scan)
		{
			if (!(scan == null))
			{
				Attack.Clear();
				Attack.UnionWith(scan.Attack);
				Block.Clear();
				Block.UnionWith(scan.Block);
				Draw.Clear();
				Draw.UnionWith(scan.Draw);
				Aoe.Clear();
				Aoe.UnionWith(scan.Aoe);
				MultiHit.Clear();
				MultiHit.UnionWith(scan.MultiHit);
				XCost.Clear();
				XCost.UnionWith(scan.XCost);
			}
		}
