	public static class CardScanner
	{
		private sealed record CardCategoryCache(string Fingerprint, IReadOnlyList<string> Attack, IReadOnlyList<string> Block, IReadOnlyList<string> Draw, IReadOnlyList<string> Aoe, IReadOnlyList<string> MultiHit, IReadOnlyList<string> XCost);

		private static string? _cachePath;

		private static bool _loaded;

		public static readonly IReadOnlySet<string> KnownScanDiffs = new HashSet<string>(StringComparer.Ordinal) { "MAD_SCIENCE", "SOVEREIGN_BLADE", "SHIV", "MIRAGE", "CONSTELLATION", "MIDNIGHT", "OUTRAGE", "THE_BALL" };

		public static void Initialize(string? cachePath)
		{
			_cachePath = cachePath;
		}

		public static void EnsureLoaded()
		{
			if (_loaded)
			{
				return;
			}
			_loaded = true;
			string text = ObjectScanner.ComputeFingerprint();
			string cachePath = _cachePath;
			if (!string.IsNullOrWhiteSpace(cachePath) && File.Exists(cachePath))
			{
				try
				{
					CardCategoryCache cardCategoryCache = JsonSerializer.Deserialize<CardCategoryCache>(File.ReadAllText(cachePath, Encoding.UTF8));
					if (cardCategoryCache != null && cardCategoryCache.Fingerprint == text && cardCategoryCache.Attack.Count > 0 && cardCategoryCache.Block.Count > 0)
					{
						CardCategories.Apply(new CardCategoryScan(ToSet(cardCategoryCache.Attack), ToSet(cardCategoryCache.Block), ToSet(cardCategoryCache.Draw), ToSet(cardCategoryCache.Aoe), ToSet(cardCategoryCache.MultiHit), ToSet(cardCategoryCache.XCost), Array.Empty<CardScanResult>(), Array.Empty<string>()));
						return;
					}
				}
				catch (Exception ex)
				{
					MainFile.Log("[CardScanner] 分类缓存读取失败，重新扫描：" + ex.Message);
				}
			}
			CardCategoryScan cardCategoryScan = ScanAll();
			if (cardCategoryScan.Attack.Count > 0 || cardCategoryScan.Block.Count > 0 || cardCategoryScan.Aoe.Count > 0 || cardCategoryScan.XCost.Count > 0)
			{
				CardCategories.Apply(cardCategoryScan);
				TrySaveCache(cachePath, text, cardCategoryScan);
			}
		}

		private static void TrySaveCache(string? path, string fingerprint, CardCategoryScan scan)
		{
			if (string.IsNullOrWhiteSpace(path))
			{
				return;
			}
			try
			{
				string directoryName = Path.GetDirectoryName(path);
				if (!string.IsNullOrWhiteSpace(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				CardCategoryCache value = new CardCategoryCache(fingerprint, scan.Attack.OrderBy<string, string>((string x) => x, StringComparer.Ordinal).ToArray(), scan.Block.OrderBy<string, string>((string x) => x, StringComparer.Ordinal).ToArray(), scan.Draw.OrderBy<string, string>((string x) => x, StringComparer.Ordinal).ToArray(), scan.Aoe.OrderBy<string, string>((string x) => x, StringComparer.Ordinal).ToArray(), scan.MultiHit.OrderBy<string, string>((string x) => x, StringComparer.Ordinal).ToArray(), scan.XCost.OrderBy<string, string>((string x) => x, StringComparer.Ordinal).ToArray());
				string text = path + ".new";
				File.WriteAllText(text, JsonSerializer.Serialize(value), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				File.Move(text, path, overwrite: true);
			}
			catch (Exception ex)
			{
				MainFile.Log("[CardScanner] 分类缓存写入失败，忽略：" + ex.Message);
			}
		}

		private static HashSet<string> ToSet(IReadOnlyList<string> values)
		{
			return new HashSet<string>(values ?? Array.Empty<string>(), StringComparer.Ordinal);
		}

		public static IReadOnlyList<Type> EnumerateCardTypes()
		{
			return (from type in typeof(CardModel).Assembly.GetTypes()
				where type.IsSubclassOf(typeof(CardModel)) && !type.IsAbstract && (type.Namespace == null || !type.Namespace.Contains(".Mocks"))
				select type).ToList();
		}

		public static CardScanResult? Scan(Type type)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Expected O, but got Unknown
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0023: Invalid comparison between Unknown and I4
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Invalid comparison between Unknown and I4
			try
			{
				CardModel card = (CardModel)Activator.CreateInstance(type);
				bool flag = (int)card.Type == 1;
				bool gainsBlock = ReadBool(() => card.GainsBlock);
				bool isAoe = flag && (int)card.TargetType == 3;
				bool isXCost = ReadBool(() => card.EnergyCost.CostsX) || ReadBool(() => card.HasStarCostX);
				int baseReplayCount = ReadInt(() => card.BaseReplayCount);
				bool drawsCards = ReadBool(() => card.DynamicVars.Cards != null && ((DynamicVar)card.DynamicVars.Cards).BaseValue > 0m);
				return new CardScanResult(((AbstractModel)card).Id.Entry, flag, gainsBlock, isAoe, isXCost, baseReplayCount, drawsCards);
			}
			catch (Exception)
			{
				return null;
			}
		}

		public static CardCategoryScan ScanAll(IReadOnlyList<Type>? types = null)
		{
			if (types == null)
			{
				types = EnumerateCardTypes();
			}
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			HashSet<string> hashSet2 = new HashSet<string>(StringComparer.Ordinal);
			HashSet<string> hashSet3 = new HashSet<string>(StringComparer.Ordinal);
			HashSet<string> hashSet4 = new HashSet<string>(StringComparer.Ordinal);
			HashSet<string> hashSet5 = new HashSet<string>(StringComparer.Ordinal);
			HashSet<string> hashSet6 = new HashSet<string>(StringComparer.Ordinal);
			List<CardScanResult> list = new List<CardScanResult>();
			List<string> list2 = new List<string>();
			foreach (Type type in types)
			{
				CardScanResult? cardScanResult = Scan(type);
				if (!cardScanResult.HasValue)
				{
					list2.Add(type.Name);
					continue;
				}
				list.Add(cardScanResult.Value);
				if (cardScanResult.Value.IsAttack)
				{
					hashSet.Add(cardScanResult.Value.Entry);
				}
				if (cardScanResult.Value.GainsBlock)
				{
					hashSet2.Add(cardScanResult.Value.Entry);
				}
				if (cardScanResult.Value.DrawsCards)
				{
					hashSet3.Add(cardScanResult.Value.Entry);
				}
				if (cardScanResult.Value.IsAoe)
				{
					hashSet4.Add(cardScanResult.Value.Entry);
				}
				if (cardScanResult.Value.BaseReplayCount + 1 >= 3)
				{
					hashSet5.Add(cardScanResult.Value.Entry);
				}
				if (cardScanResult.Value.IsXCost)
				{
					hashSet6.Add(cardScanResult.Value.Entry);
				}
			}
			return new CardCategoryScan(hashSet, hashSet2, hashSet3, hashSet4, hashSet5, hashSet6, list, list2);
		}

		public static IReadOnlyList<string> ComputeDrift(IReadOnlySet<string> scanned, IReadOnlySet<string> expected)
		{
			List<string> list = new List<string>();
			foreach (string item in scanned.Except(expected))
			{
				if (!KnownScanDiffs.Contains(item))
				{
					list.Add("+" + item);
				}
			}
			foreach (string item2 in expected.Except(scanned))
			{
				if (!KnownScanDiffs.Contains(item2))
				{
					list.Add("-" + item2);
				}
			}
			return list;
		}

		private static bool ReadBool(Func<bool> read)
		{
			try
			{
				return read();
			}
			catch
			{
				return false;
			}
		}

		private static int ReadInt(Func<int> read)
		{
			try
			{
				return read();
			}
			catch
			{
				return 0;
			}
		}
	}
