	public static class CollectibleSetsExporter
	{
		public static CollectibleSets ExportFromHardcoded()
		{
			return new CollectibleSets(ManualCardSets.KeyCardsByCharacter.ToDictionary<KeyValuePair<string, HashSet<string>>, string, IReadOnlySet<string>>((KeyValuePair<string, HashSet<string>> pair) => pair.Key, (KeyValuePair<string, HashSet<string>> pair) => new HashSet<string>(pair.Value, StringComparer.Ordinal), StringComparer.Ordinal), new HashSet<string>(ManualCardSets.Overpowered, StringComparer.Ordinal), new HashSet<string>(ManualCardSets.Startup, StringComparer.Ordinal), new HashSet<string>(ManualCardSets.Future, StringComparer.Ordinal), new HashSet<string>(ManualRelicSets.OverpoweredRelics, StringComparer.Ordinal), PowerfulCombos.All.Select(ToCombo).ToList());
		}

		private static ComboDefinition ToCombo(CollectiblePairDefinition pair)
		{
			return new ComboDefinition(pair.PairId, ToSource(pair.Source), ToItem(pair.Target));
		}

		private static ComboSource ToSource(CollectibleSourceSelector source)
		{
			switch (source.Kind)
			{
			case CollectibleSourceKind.XCostCard:
				return new ComboSource(ComboSourceKind.XCost, null);
			case CollectibleSourceKind.EnchantedAttackCard:
				return new ComboSource(ComboSourceKind.EnchantedAttack, null);
			default:
			{
				CollectibleRef? exactItem = source.ExactItem;
				ComboItem? item;
				if (exactItem.HasValue)
				{
					CollectibleRef valueOrDefault = exactItem.GetValueOrDefault();
					item = ToItem(valueOrDefault);
				}
				else
				{
					item = null;
				}
				return new ComboSource(ComboSourceKind.Exact, item);
			}
			}
		}

		private static ComboItem ToItem(CollectibleRef item)
		{
			return new ComboItem((item.Kind == CollectibleKind.Card) ? "card" : "relic", item.ModelId, item.OfficialChineseName, item.SourceTypeName);
		}
	}
	public enum DanmakuTextStyle
	{
		Character,
		Narration
	}
	public readonly record struct DanmakuEntry(string Text, DanmakuTextStyle Style, string Variant = "", string Author = "", string Color = "", bool TopPinned = false, bool Rainbow = false, IReadOnlyList<string>? ContinuationTexts = null, DanmakuSequenceSpeed SequenceSpeed = DanmakuSequenceSpeed.Medium, string LikeTargetId = "")
	{
		public IReadOnlyList<string> StableContinuationTexts => ContinuationTexts ?? Array.Empty<string>();

		public IReadOnlyList<string> AllTexts => new string[1] { Text }.Concat(StableContinuationTexts).ToArray();

		public static DanmakuEntry Character(string text)
		{
			return new DanmakuEntry(text, DanmakuTextStyle.Character);
		}

		public static DanmakuEntry Narration(string text)
		{
			return new DanmakuEntry(text, DanmakuTextStyle.Narration);
		}

		public IReadOnlyList<string> GetMissingContextKeys(IReadOnlyDictionary<string, string> context)
		{
			if (AllTexts.All(string.IsNullOrEmpty))
			{
				return Array.Empty<string>();
			}
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			foreach (string allText in AllTexts)
			{
				int num = 0;
				while (num < allText.Length)
				{
					int num2 = allText.IndexOf('{', num);
					if (num2 < 0)
					{
						break;
					}
					int num3 = allText.IndexOf('}', num2 + 1);
					if (num3 < 0)
					{
						break;
					}
					int num4 = num2 + 1;
					string text = allText.Substring(num4, num3 - num4);
					if (text.Length > 0 && !context.ContainsKey(text))
					{
						hashSet.Add(text);
					}
					num = num3 + 1;
				}
			}
			return hashSet.OrderBy<string, string>((string key) => key, StringComparer.Ordinal).ToArray();
		}

		public string Resolve(IReadOnlyDictionary<string, string> context)
		{
			return ResolveTemplate(Text, context);
		}

		public IReadOnlyList<string> ResolveAll(IReadOnlyDictionary<string, string> context)
		{
			IReadOnlyDictionary<string, string> context2 = context;
			return AllTexts.Select((string text) => ResolveTemplate(text, context2)).ToArray();
		}

		private static string ResolveTemplate(string text, IReadOnlyDictionary<string, string> context)
		{
			if (string.IsNullOrEmpty(text) || context.Count == 0)
			{
				return text;
			}
			string text2 = text;
			foreach (KeyValuePair<string, string> item in context)
			{
				string newValue = item.Key switch
				{
					"card" => CardAlias.DisplayName(item.Value), 
					"item" => CollectibleAlias.DisplayName(item.Value), 
					"char" => CharacterNames.DisplayName(item.Value), 
					_ => item.Value, 
				};
				text2 = text2.Replace("{" + item.Key + "}", newValue);
			}
			return text2;
		}
	}
