		{
			return intensity switch
			{
				DanmakuIntensity.Light => new DanmakuCountRange(2, 3), 
				DanmakuIntensity.Medium => new DanmakuCountRange(4, 6), 
				DanmakuIntensity.Strong => new DanmakuCountRange(10, 12), 
				_ => throw new ArgumentOutOfRangeException("intensity", intensity, "未知弹幕强度。"), 
			};
		}

		public static int PickCount(DanmakuTrigger trigger, Random random)
		{
			return GetRange(Get(trigger)).Pick(random);
		}
