		private static void ApplyMultiplayerCharacterCopies(Dictionary<DanmakuTrigger, DanmakuGroup> groups)
		{
			foreach (DanmakuTrigger multiplayerCharacterSubstituteRule in MultiplayerCharacterSubstituteRules)
			{
				if (groups.TryGetValue(multiplayerCharacterSubstituteRule, out DanmakuGroup value))
				{
					DanmakuEntry[] multiplayerEntries = (from entry in value.Entries
						where entry.Style == DanmakuTextStyle.Character
						group entry by (Text: entry.Text, Variant: entry.Variant) into entries
						select entries.First()).ToArray();
					groups[multiplayerCharacterSubstituteRule] = value with
					{
						MultiplayerEntries = multiplayerEntries
					};
				}
			}
		}

		public static DanmakuGroup? Get(DanmakuTrigger trigger)
		{
			if (!Groups.TryGetValue(trigger, out DanmakuGroup value))
			{
				return null;
			}
			return value;
		}

		public static void Apply(RuleLibrary library)
		{
			Dictionary<DanmakuTrigger, DanmakuGroup> dictionary = new Dictionary<DanmakuTrigger, DanmakuGroup>(_groups);
			foreach (KeyValuePair<DanmakuTrigger, DanmakuGroup> item in Convert(library))
			{
				item.Deconstruct(out var key, out var value);
				DanmakuTrigger key2 = key;
				DanmakuGroup value2 = value;
				dictionary[key2] = value2;
			}
			_groups = dictionary;
		}

		public static void ApplyContributions(RuleLibrary library)
		{
			Dictionary<string, DanmakuTrigger> dictionary = new Dictionary<string, DanmakuTrigger>(StringComparer.Ordinal);
			DanmakuTrigger[] values = Enum.GetValues<DanmakuTrigger>();
			foreach (DanmakuTrigger danmakuTrigger in values)
			{
				dictionary[DanmakuRuleIds.Get(danmakuTrigger).ToLowerInvariant()] = danmakuTrigger;
			}
			Dictionary<DanmakuTrigger, DanmakuGroup> dictionary2 = new Dictionary<DanmakuTrigger, DanmakuGroup>(_groups);
			foreach (RuleGroup group in library.Groups)
			{
				if (!dictionary.TryGetValue(group.RuleId.Trim().ToLowerInvariant(), out var value))
				{
					continue;
				}
				DanmakuEntry[] array = group.Entries.Select((RuleEntry entry) => new DanmakuEntry(entry.Text, ToTextStyle(entry.Style), entry.Variant, entry.Author, entry.Color, entry.TopPinned, entry.Rainbow, entry.StableContinuationTexts, entry.SequenceSpeed, entry.Id)).ToArray();
				if (array.Length != 0)
				{
					if (dictionary2.TryGetValue(value, out var value2))
					{
						dictionary2[value] = value2 with
						{
							Entries = value2.Entries.Concat(array).ToArray()
						};
					}
					else
					{
						dictionary2[value] = new DanmakuGroup(value, array, Array.Empty<DanmakuEntry>());
					}
				}
			}
			_groups = dictionary2;
		}

		public static void Reset()
		{
			_groups = _hardcoded ?? Groups;
		}

		private static IReadOnlyDictionary<DanmakuTrigger, DanmakuGroup> Convert(RuleLibrary library)
		{
			Dictionary<string, DanmakuTrigger> dictionary = new Dictionary<string, DanmakuTrigger>(StringComparer.Ordinal);
			DanmakuTrigger[] values = Enum.GetValues<DanmakuTrigger>();
			foreach (DanmakuTrigger danmakuTrigger in values)
			{
				dictionary[DanmakuRuleIds.Get(danmakuTrigger).ToLowerInvariant()] = danmakuTrigger;
			}
			Dictionary<DanmakuTrigger, DanmakuGroup> dictionary2 = new Dictionary<DanmakuTrigger, DanmakuGroup>();
			foreach (RuleGroup group in library.Groups)
			{
				if (dictionary.TryGetValue(group.RuleId, out var value))
				{
					DanmakuEntry[] entries = group.Entries.Select((RuleEntry entry) => new DanmakuEntry(entry.Text, ToTextStyle(entry.Style), entry.Variant, entry.Author, entry.Color, entry.TopPinned, entry.Rainbow, entry.StableContinuationTexts, entry.SequenceSpeed, entry.Id)).ToArray();
					DanmakuEntry[] multiplayerEntries = group.MultiplayerEntries.Select((RuleEntry entry) => new DanmakuEntry(entry.Text, ToTextStyle(entry.Style), entry.Variant, entry.Author, entry.Color, entry.TopPinned, entry.Rainbow, entry.StableContinuationTexts, entry.SequenceSpeed, entry.Id)).ToArray();
					dictionary2[value] = new DanmakuGroup(value, entries, multiplayerEntries);
				}
			}
			return dictionary2;
		}

		private static DanmakuTextStyle ToTextStyle(ContentStyle style)
		{
			if (style != 0)
			{
				return DanmakuTextStyle.Narration;
			}
			return DanmakuTextStyle.Character;
		}

		public static IReadOnlyList<DanmakuEntry> GetEntries(DanmakuTrigger trigger, string variant)
		{
			string variant2 = variant;
			DanmakuGroup danmakuGroup = Get(trigger);
			if ((object)danmakuGroup == null)
			{
				return Array.Empty<DanmakuEntry>();
			}
			if (string.IsNullOrEmpty(variant2))
			{
				return danmakuGroup.Entries;
			}
			DanmakuEntry[] array = danmakuGroup.Entries.Where((DanmakuEntry entry) => entry.Variant == variant2).ToArray();
			if (array.Length == 0)
			{
				return danmakuGroup.Entries.Where((DanmakuEntry entry) => entry.Variant.Length == 0).ToArray();
			}
			return array;
		}

		public static IReadOnlyList<DanmakuEntry> GetMultiplayerEntries(DanmakuTrigger trigger, string variant)
		{
			string variant2 = variant;
			DanmakuGroup danmakuGroup = Get(trigger);
			if ((object)danmakuGroup == null)
			{
				return Array.Empty<DanmakuEntry>();
			}
			if (string.IsNullOrEmpty(variant2))
			{
				return danmakuGroup.MultiplayerEntries;
			}
			DanmakuEntry[] array = danmakuGroup.MultiplayerEntries.Where((DanmakuEntry entry) => entry.Variant == variant2).ToArray();
			if (array.Length == 0)
			{
				return danmakuGroup.MultiplayerEntries.Where((DanmakuEntry entry) => entry.Variant.Length == 0).ToArray();
			}
			return array;
		}

