			AddEntries(groups, DanmakuTrigger.HardChoice, Narration("我说忠孝两难全"), Narration("抉择，抉择了"));
			AddEntries(groups, DanmakuTrigger.BigDeck, Narration("终于看到正常卡组了"), Narration("卡组还是太小了"), Narration("{count}张，小卡组"));
			AddEntries(groups, DanmakuTrigger.CardThreeVisits, Narration("{card}真的很想加入这个家"), Narration("{card}追着来"), Narration("{card}又来了"), Narration("{card}：考虑一下我"));
			AddEntries(groups, DanmakuTrigger.BuyPremiumRelic, Character("上等好货"));
			AddEntries(groups, DanmakuTrigger.ShopCardRemoval, Narration("删牌大于一切啊"), Narration("再见了，{card}"));
			AddEntries(groups, DanmakuTrigger.ArchitectWithPotion, Narration("给建筑师带小饮料"), Narration("给建筑师带小甜水算你赢了"), Narration("我说给建筑师带饮料算你赢了"), Narration("给建筑师带果汁"));
			AddEntries(groups, DanmakuTrigger.BridgeEvent, Character("我爱桥！", "weak"), Narration("桥有木了", "weak"), Character("这桥有用", "weak"), Narration("免费删牌了", "weak"), Narration("好桥兄弟好桥", "weak"), Narration("桥游牧了", "strong"), Narration("可惜兄弟，可惜", "strong"));
			AddEntries(groups, DanmakuTrigger.CloneEnchantment, Narration("翻倍是危险的设计"), Narration("翻倍是个危险的设计"), Narration("指数是危险的设计"), Character("我说指数是个危险的设计"), Character("我说翻倍是个危险的设计"));
			AddEntries(groups, DanmakuTrigger.RestSiteSleep, Character("我说好好睡"), Character("火堆起防"), Character("养精蓄锐了"));
			AddEntries(groups, DanmakuTrigger.FullHpRestSiteSleep, Narration("依旧美容觉"), Narration("睡美容觉算你赢了"), Narration("我说睡美容觉算你赢了"));
			AddEntries(groups, DanmakuTrigger.LowHpSkippedRest, Narration("{hp}血还不睡？！"), Narration("不睡觉？"), Narration("！？不睡觉？！"), Narration("伏笔了"));
		}

		private static void AddEntries(Dictionary<DanmakuTrigger, DanmakuGroup> groups, DanmakuTrigger trigger, params DanmakuEntry[] entries)
		{
			DanmakuGroup group = groups[trigger];
			DanmakuEntry[] second = entries.Where((DanmakuEntry candidate) => !group.Entries.Any((DanmakuEntry existing) => existing.Text == candidate.Text && existing.Variant == candidate.Variant)).ToArray();
			groups[trigger] = group with
			{
				Entries = group.Entries.Concat(second).ToArray()
			};
		}

		private static DanmakuGroup Group(DanmakuTrigger t, params DanmakuEntry[] entries)
		{
			return new DanmakuGroup(t, entries);
		}

		private static DanmakuEntry Character(string text, string variant = "")
		{
			return new DanmakuEntry(text, DanmakuTextStyle.Character, variant);
		}

		private static DanmakuEntry Narration(string text, string variant = "")
		{
			return new DanmakuEntry(text, DanmakuTextStyle.Narration, variant);
		}
	}
