		}

		public static IReadOnlyList<RuleSpec> SpecsFor(TimingPhase phase)
		{
			if (!ByPhase.TryGetValue(phase, out IReadOnlyList<RuleSpec> value))
			{
				return Array.Empty<RuleSpec>();
			}
			return value;
		}

