	public readonly record struct CollectibleObservation(CollectibleObservationKind Kind, CollectibleRef Item);
	public enum CollectibleSourceKind
	{
		Exact,
		XCostCard,
		EnchantedAttackCard
	}
	public sealed record CollectibleSourceSelector(CollectibleSourceKind Kind, CollectibleRef? ExactItem, string DisplayName)
	{
		public string Identity
		{
			get
			{
				if (Kind == CollectibleSourceKind.Exact)
				{
					CollectibleRef? exactItem = ExactItem;
					if (exactItem.HasValue)
					{
						return exactItem.GetValueOrDefault().Identity;
					}
				}
				return $"Selector:{Kind}";
			}
		}

		public static CollectibleSourceSelector XCostCard { get; } = new CollectibleSourceSelector(CollectibleSourceKind.XCostCard, null, "X费牌");


		public static CollectibleSourceSelector EnchantedAttackCard { get; } = new CollectibleSourceSelector(CollectibleSourceKind.EnchantedAttackCard, null, "带有附魔的攻击牌");


		public static CollectibleSourceSelector Exact(CollectibleRef item)
		{
			return new CollectibleSourceSelector(CollectibleSourceKind.Exact, item, item.OfficialChineseName);
		}

		public bool Matches(CollectibleObservation observation)
		{
			int result;
			switch (Kind)
			{
			case CollectibleSourceKind.Exact:
				if (observation.Kind == CollectibleObservationKind.Obtained)
				{
					CollectibleRef? exactItem = ExactItem;
					if (exactItem.HasValue)
					{
						result = ((exactItem.GetValueOrDefault().Identity == observation.Item.Identity) ? 1 : 0);
						goto IL_005e;
					}
				}
				result = 0;
				goto IL_005e;
			case CollectibleSourceKind.XCostCard:
				return observation.Kind == CollectibleObservationKind.Obtained && observation.Item.Kind == CollectibleKind.Card && CardCategories.XCost.Contains(observation.Item.ModelId);
			case CollectibleSourceKind.EnchantedAttackCard:
				return observation.Kind == CollectibleObservationKind.AttackEnchanted && observation.Item.Kind == CollectibleKind.Card && CardCategories.Attack.Contains(observation.Item.ModelId);
			default:
				{
					return false;
				}
				IL_005e:
				return (byte)result != 0;
			}
		}

		[CompilerGenerated]
		private CollectibleSourceSelector(CollectibleSourceSelector original)
		{
			Kind = original.Kind;
			ExactItem = original.ExactItem;
			DisplayName = original.DisplayName;
		}
	}
