		private static CollectiblePairDefinition ToPair(ComboDefinition combo)
		{
			return new CollectiblePairDefinition(combo.Id, ToSelector(combo.Source), ToRef(combo.Target));
		}

		private static CollectibleSourceSelector ToSelector(ComboSource source)
		{
			return source.Kind switch
			{
				ComboSourceKind.XCost => CollectibleSourceSelector.XCostCard, 
				ComboSourceKind.EnchantedAttack => CollectibleSourceSelector.EnchantedAttackCard, 
				_ => CollectibleSourceSelector.Exact(ToRef(source.Item.Value)), 
			};
		}

		private static CollectibleRef ToRef(ComboItem item)
		{
			return new CollectibleRef((!(item.ItemKind == "card")) ? CollectibleKind.Relic : CollectibleKind.Card, item.ModelId, item.Name, item.TypeName);
		}
