	public sealed record RealGameTestCase(string CaseId, string RuleId, DanmakuTrigger Trigger, RealGameTestBatch Batch, string Condition, string HookBoundary, IReadOnlyList<string> RequiredEvidence);
	public static class RealGameTestCatalog
	{
		private static readonly IReadOnlyDictionary<string, RealGameTestCase> Cases = Build();

		public static IReadOnlyList<RealGameTestCase> All => Cases.Values.OrderBy<RealGameTestCase, string>((RealGameTestCase item) => item.RuleId, StringComparer.Ordinal).ToArray();

		public static bool TryGet(string caseId, out RealGameTestCase testCase)
		{
			return Cases.TryGetValue(caseId.Trim().ToUpperInvariant(), out testCase);
		}

		public static string WriteJson(string outputRoot)
		{
			Directory.CreateDirectory(outputRoot);
			string text = Path.Combine(outputRoot, "real-game-cases.json");
			string text2 = text + $".{Guid.NewGuid():N}.tmp";
			var value = new
			{
				schemaVersion = 1,
				generatedAtUtc = DateTimeOffset.UtcNow,
				totalCases = All.Count,
				requiredEvidence = new string[5] { "fact", "reasonCode", "decision", "emission", "visual" },
				cases = All
			};
			File.WriteAllText(text2, JsonSerializer.Serialize(value, TelemetryJson.Indented), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
			File.Move(text2, text, overwrite: true);
			return text;
		}

		private static IReadOnlyDictionary<string, RealGameTestCase> Build()
		{
			Dictionary<string, RealGameTestCase> dictionary = new Dictionary<string, RealGameTestCase>(StringComparer.OrdinalIgnoreCase);
			foreach (IGrouping<DanmakuTrigger, RuleSpec> item in from item in DanmakuRuleCatalog.All
				where item.Trigger != DanmakuTrigger.CombatStart
				group item by item.Trigger)
			{
				DanmakuTrigger key = item.Key;
				string text = DanmakuRuleIds.Get(key);
				string text2 = "RG-" + text;
				dictionary.Add(text2, new RealGameTestCase(text2, text, key, BatchOf(text), string.Join("；", item.Select((RuleSpec item) => item.Condition).Distinct<string>(StringComparer.Ordinal)), string.Join("；", item.Select((RuleSpec item) => item.HookHint).Distinct<string>(StringComparer.Ordinal)), new global::<>z__ReadOnlyArray<string>(new string[4] { "事实或直接适配器边界", "reasonCode 与决策", "派发与气泡生成", "人工视觉结论" })));
			}
			return dictionary;
		}

		private static RealGameTestBatch BatchOf(string ruleId)
		{
			return ruleId[0] switch
			{
				'A' => RealGameTestBatch.CombatHistory, 
				'B' => RealGameTestBatch.HandAndTurn, 
				'C' => RealGameTestBatch.DamageAndDeath, 
				'D' => RealGameTestBatch.MonsterSpecific, 
				'E' => RealGameTestBatch.RewardAndDeck, 
				'F' => RealGameTestBatch.Shop, 
				'G' => RealGameTestBatch.EventAndRestSite, 
				'H' => RealGameTestBatch.RunLifecycle, 
				'I' => RealGameTestBatch.Multiplayer, 
				_ => throw new InvalidOperationException("未知实机规则分组：" + ruleId), 
			};
		}
	}
