	public static class RuleLibraryExporter
	{
		public static RuleLibrary ExportFromHardcoded()
		{
			List<RuleGroup> list = new List<RuleGroup>();
			foreach (DanmakuTrigger item in DanmakuLibrary.Groups.Keys.OrderBy((DanmakuTrigger trigger) => (int)trigger))
			{
				DanmakuGroup danmakuGroup = DanmakuLibrary.Groups[item];
				string text = DanmakuRuleIds.Get(item).ToLowerInvariant();
				List<RuleEntry> list2 = new List<RuleEntry>();
				int num = 0;
				foreach (DanmakuEntry entry in danmakuGroup.Entries)
				{
					num++;
					list2.Add(new RuleEntry($"{text}-{num:D5}", entry.Text, ToContentStyle(entry.Style), entry.Variant));
				}
				List<RuleEntry> list3 = new List<RuleEntry>();
				int num2 = 0;
				foreach (DanmakuEntry multiplayerEntry in danmakuGroup.MultiplayerEntries)
				{
					num2++;
					list3.Add(new RuleEntry($"{text}-m{num2:D3}", multiplayerEntry.Text, ToContentStyle(multiplayerEntry.Style), multiplayerEntry.Variant));
				}
				list.Add(new RuleGroup(text, list2, list3));
			}
			return new RuleLibrary(list);
		}

		private static ContentStyle ToContentStyle(DanmakuTextStyle style)
		{
			if (style != 0)
			{
				return ContentStyle.Narration;
			}
			return ContentStyle.Character;
		}
	}
