	public sealed class DanmakuPool
	{
		public TimingPhase Phase { get; }

		public IReadOnlyList<IDanmakuRule> Rules { get; }

		public bool IsActive { get; private set; }

		public DanmakuPool(TimingPhase phase, IReadOnlyList<IDanmakuRule> rules)
		{
			Phase = phase;
			Rules = rules;
		}

		public void Activate()
		{
			if (IsActive)
			{
				return;
			}
			IsActive = true;
			foreach (IDanmakuRule rule in Rules)
			{
				try
				{
					rule.Activate();
				}
				catch (Exception ex)
				{
					MainFile.Log($"[Pool:{Phase}] 启用规则 {rule.Trigger} 失败: {ex.Message}");
				}
			}
		}

		public void Deactivate()
		{
			if (!IsActive)
			{
				return;
			}
			IsActive = false;
			foreach (IDanmakuRule rule in Rules)
			{
				try
				{
					rule.Deactivate();
				}
				catch (Exception ex)
				{
					MainFile.Log($"[Pool:{Phase}] 停用规则 {rule.Trigger} 失败: {ex.Message}");
				}
			}
		}
	}
	public enum GameFlowState
	{
		Inactive,
		Run,
		Map,
		Reward,
		Shop,
		Event,
		RestSite,
		CombatPending,
		CombatOpening,
		PlayerTurn,
		EnemyTurn
	}
	public static class FlowPoolPolicy
	{
		public static IReadOnlySet<TimingPhase> GetActivePhases(GameFlowState state)
		{
			switch (state)
			{
			case GameFlowState.Inactive:
				return Set();
			case GameFlowState.Run:
			case GameFlowState.CombatPending:
				return Set(default(TimingPhase));
			case GameFlowState.Map:
				return Set(TimingPhase.Run, TimingPhase.Map);
			case GameFlowState.Reward:
				return Set(TimingPhase.Run, TimingPhase.Reward);
			case GameFlowState.Shop:
				return Set(TimingPhase.Run, TimingPhase.Shop);
			case GameFlowState.Event:
				return Set(TimingPhase.Run, TimingPhase.Event);
			case GameFlowState.RestSite:
				return Set(TimingPhase.Run, TimingPhase.RestSite);
			case GameFlowState.CombatOpening:
				return Set(TimingPhase.Run, TimingPhase.CombatStart, TimingPhase.Combat);
			case GameFlowState.PlayerTurn:
				return Set(TimingPhase.Run, TimingPhase.Combat);
			case GameFlowState.EnemyTurn:
				return Set(TimingPhase.Run, TimingPhase.Combat, TimingPhase.TurnEnd);
			default:
				throw new ArgumentOutOfRangeException("state", state, "未定义的游戏流程状态");
			}
		}

		private static IReadOnlySet<TimingPhase> Set(params TimingPhase[] phases)
		{
			return new HashSet<TimingPhase>(phases);
		}
	}
	public interface IDanmakuRule
	{
		DanmakuTrigger Trigger { get; }

		TimingPhase Phase { get; }

		string Description { get; }

		void Activate();

		void Deactivate();
	}
	public abstract class DanmakuRule : IDanmakuRule
	{
		public DanmakuTrigger Trigger { get; }

		public TimingPhase Phase { get; }

		public string Description { get; }

		protected DanmakuRule(DanmakuTrigger trigger, TimingPhase phase, string description)
		{
			Trigger = trigger;
			Phase = phase;
			Description = description;
		}

		protected virtual void OnActivate()
		{
		}

		protected virtual void OnDeactivate()
		{
		}

		void IDanmakuRule.Activate()
		{
			OnActivate();
		}

		void IDanmakuRule.Deactivate()
		{
			OnDeactivate();
		}
	}
