				_onRunStarted = BeginRun;
				RunManager.Instance.RunStarted += _onRunStarted;
			}
		}

		public static void Shutdown()
		{
			if (_initialized)
			{
				if (_onRunStarted != null)
				{
					RunManager.Instance.RunStarted -= _onRunStarted;
				}
				_onRunStarted = null;
				_initialized = false;
				ClearCombatReferences();
			}
		}

		public static void BeginRun(RunState _)
		{
			RunEpoch++;
			RoomSequence = 0L;
			CombatSequence = 0L;
			TurnSequence = 0L;
			_sourceSequence = 0L;
		}

		public static void BeginRoom()
		{
			RoomSequence++;
			TurnSequence = 0L;
		}

		public static void BeginCombat(CombatState state)
		{
			CombatSequence++;
			TurnSequence = 0L;
			IsStreakRun = NoDamageStreak >= 4;
			CombatDamagedByEnemy = false;
			StreakBreakFired = false;
			StartupPlayCount = 0;
			PotionUseCount = 0;
			CombatBingeFired = false;
			DrawOverflowFired = false;
			QueenPresent = false;
			BowlbugRockPresent = false;
			ScrollOfBitingPresent = false;
			ScrollMaxHpLost = false;
			EnemyTurnHpLost = 0;
			EnemyTurnBlockedDamage = 0;
			EndTurnEnergy = 0;
			MinimumFlushedBlockCardCost = null;
			BigTurnFired = false;
			CombatStartProcessed = false;
			CurrentStrongMonsterTypes.Clear();
			CurrentCombatMonsterTypes.Clear();
			PriorEncounteredMonsterTypes.Clear();
			PriorKilledMonsterTypes.Clear();
			CurrentCombatKilledMonsterTypes.Clear();
			DefenseOffenseChecked = false;
			ProcessedDeaths.Clear();
			PendingExactLethalOverkill.Clear();
			ExperimentHitCounts.Clear();
			ExperimentThresholdFired.Clear();
			SculptorsChanted.Clear();
			HighDamageCardsThisTurn.Clear();
			QueenVariantsThisTurn.Clear();
			ClearTurnEvidence();
			RuleDiagnostics.Instance.BeginCombat();
		}

		public static void BeginTurn(CombatState state)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Invalid comparison between Unknown and I4
			if ((int)state.CurrentSide == 1)
			{
				TurnSequence++;
				DefenseOffenseChecked = false;
				BigTurnFired = false;
				HighDamageCardsThisTurn.Clear();
				QueenVariantsThisTurn.Clear();
				ClearTurnEvidence();
				RuleDiagnostics.Instance.BeginTurn();
			}
		}

		public static EventId NextEvent(EventSourceKind source)
		{
