		}

		public static FactPublishDecision Publish<TFact>(TFact fact) where TFact : IGameFact
		{
			return GameFactBus.Instance.Publish(fact, CurrentLifecycle);
		}

		public static void MarkDamagedByEnemy(int hpLost)
		{
			CombatDamagedByEnemy = CombatRuleEvaluators.MarkDamagedByEnemy(new CombatDamageState(CombatDamagedByEnemy, EnemyTurnHpLost), hpLost).DamagedByEnemy;
		}

		public static bool TryBreakStreak()
		{
			if (!IsStreakRun || StreakBreakFired)
			{
				return false;
			}
			StreakBreakFired = true;
			IsStreakRun = false;
			return true;
		}

		public static bool TryFireBigTurn()
		{
			if (BigTurnFired)
			{
				return false;
			}
			BigTurnFired = true;
			return true;
		}

		public static bool TryFireHighDamage(CardModel card)
		{
			return HighDamageCardsThisTurn.Add(CardInstanceKey(card));
		}

		public static bool TryFireQueenVariant(string variant)
		{
			return QueenVariantsThisTurn.Add(variant);
		}

		public static string CardInstanceKey(CardModel card)
		{
			return $"{((AbstractModel)card).Id.Entry}#{RuntimeHelpers.GetHashCode(card)}";
		}

		public static bool TryFireHasBlockNoPlay()
		{
			if (!EndTurnBlockSnapshotFinalized || FlushedUnplayedBlockCards.Count == 0 || HasBlockNoPlayFired)
			{
				return false;
			}
			HasBlockNoPlayFired = true;
			return true;
		}

		public static void RecordEnemyDamage(int hpLost, int blockedDamage, uint dealerCombatId)
		{
			bool flag = FrozenEnemyMoves.ContainsKey(dealerCombatId);
			EnemyTurnHpLost = CombatRuleEvaluators.RecordEnemyTurnHpLost(new CombatDamageState(CombatDamagedByEnemy, EnemyTurnHpLost), hpLost, flag).EnemyTurnHpLost;
			if (flag && blockedDamage > 0)
			{
				EnemyTurnBlockedDamage += blockedDamage;
			}
		}

		public static void ClearTurnEvidence()
		{
			EndTurnBlockCandidates.Clear();
			FlushedUnplayedBlockCards.Clear();
			EndTurnBlockSnapshotFinalized = false;
			HasBlockNoPlayFired = false;
			FrozenEnemyMoves.Clear();
			CompletedAttackMoves.Clear();
			ExecutedAttacksAgainstPlayer.Clear();
			EnemyTurnDamageRedirectedToPlayerPet = false;
			EnemyTurnPlayerHadBuffer = false;
			EnemyTurnEvaluationFinalized = false;
			EnemyTurnHpLost = 0;
			EnemyTurnBlockedDamage = 0;
			EndTurnEnergy = 0;
			MinimumFlushedBlockCardCost = null;
		}

		public static void ClearCombatReferences()
		{
			ClearTurnEvidence();
			PendingExactLethalOverkill.Clear();
			CurrentStrongMonsterTypes.Clear();
			CurrentCombatMonsterTypes.Clear();
			PriorEncounteredMonsterTypes.Clear();
			PriorKilledMonsterTypes.Clear();
			BowlbugRockPresent = false;
			QueenPresent = false;
			ScrollOfBitingPresent = false;
			ScrollMaxHpLost = false;
		}

		public static void FinishCombat(bool won)
		{
			if (won)
			{
				foreach (string currentCombatMonsterType in CurrentCombatMonsterTypes)
				{
					EncounteredMonsterTypes.Add(currentCombatMonsterType);
					KilledMonsterTypes.Add(currentCombatMonsterType);
				}
			}
			CurrentStrongMonsterTypes.Clear();
			CurrentCombatMonsterTypes.Clear();
			PriorEncounteredMonsterTypes.Clear();
			PriorKilledMonsterTypes.Clear();
			CurrentCombatKilledMonsterTypes.Clear();
			IsStreakRun = false;
			StreakBreakFired = false;
		}
	}
