			}
			if (_onCombatEnded != null)
			{
				instance.CombatEnded -= _onCombatEnded;
			}
			if (_onRunStarted != null)
			{
				RunManager.Instance.RunStarted -= _onRunStarted;
			}
			if (_onRoomEntered != null)
			{
				RunManager.Instance.RoomEntered -= _onRoomEntered;
