				ModRunState.Publish(new CombatStartedFact(ModRunState.CreateFactHeader(EventSourceKind.CombatBegan, CurrentState, EmissionScope.Combat), state.Enemies.Count, node, (me != null) ? me.Creature.CurrentHp : 0, (me != null) ? me.Creature.MaxHp : 0, state.Enemies.Select((Creature enemy) => enemy.ModelId.Entry).ToArray()));
