		private void BindCombatBegan(CombatManager cm)
		{
			EventInfo eventInfo = typeof(CombatManager).GetEvent("CombatBegan") ?? typeof(CombatManager).GetEvent("CombatSetUp");
			if (eventInfo == null)
			{
				throw new InvalidOperationException("未找到战斗开始事件（CombatBegan/CombatSetUp）");
			}
			if (_onBegan == null)
			{
				_onBegan = OnCombatBegan;
			}
			_combatBeganEvent = eventInfo;
			_combatBeganDelegate = Delegate.CreateDelegate(eventInfo.EventHandlerType, this, "OnCombatBegan");
			eventInfo.AddEventHandler(cm, _combatBeganDelegate);
		}

		private void UnbindCombatBegan(CombatManager cm)
		{
			if (_combatBeganEvent != null && (object)_combatBeganDelegate != null)
			{
				_combatBeganEvent.RemoveEventHandler(cm, _combatBeganDelegate);
			}
			_combatBeganEvent = null;
			_combatBeganDelegate = null;
		}

		private static void EvaluateCombatStartRules(CombatState state, EventId eventId)
		{
			//IL_023f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0245: Invalid comparison between Unknown and I4
			if (ModRunState.CombatStartProcessed)
			{
				return;
			}
			ModRunState.CombatStartProcessed = true;
			Player me = LocalContext.GetMe((ICombatState)(object)state);
			Creature val = ((me != null) ? me.Creature : null);
			string[] array = state.Enemies.Select((Creature e) => e.ModelId.Entry).Distinct().ToArray();
			ModRunState.CurrentCombatMonsterTypes.UnionWith(array);
			ModRunState.PriorEncounteredMonsterTypes.UnionWith(ModRunState.EncounteredMonsterTypes);
			ModRunState.PriorKilledMonsterTypes.UnionWith(ModRunState.KilledMonsterTypes);
			int num;
			if (val == null)
			{
				num = 0;
			}
			else
			{
				Player player = val.Player;
				num = (((player != null) ? new bool?(player.Deck.Cards.Any((CardModel c) => CardCategories.Aoe.Contains(((AbstractModel)c).Id.Entry))) : null).GetValueOrDefault() ? 1 : 0);
			}
			bool flag = (byte)num != 0;
			StrongMonsterEvaluation strongMonsterEvaluation = RuleBusinessEvaluators.EvaluateStrongMonster(state.RunState.ActFloor, flag, array);
			if (strongMonsterEvaluation.Result.Matched)
			{
				ModRunState.StrongMonsterTriggered = true;
				foreach (string matchedMonsterId in strongMonsterEvaluation.MatchedMonsterIds)
				{
					ModRunState.CurrentStrongMonsterTypes.Add(matchedMonsterId);
				}
				Dispatch(DanmakuTrigger.StrongMonster, eventId, strongMonsterEvaluation.Result.ReasonCode, new Dictionary<string, string>
				{
					["actFloor"] = state.RunState.ActFloor.ToString(),
					["noAoe"] = (!flag).ToString(),
					["aMatch"] = strongMonsterEvaluation.AClassMatched.ToString(),
					["bMatch"] = strongMonsterEvaluation.BClassMatched.ToString()
				});
			}
			if (RuleBusinessEvaluators.EvaluateEncounteredBefore(array, ModRunState.PriorEncounteredMonsterTypes).Matched)
			{
				Dispatch(DanmakuTrigger.EncounteredBefore, eventId, "monster_seen_in_previous_won_combat", new Dictionary<string, string> { ["matched"] = string.Join(",", array.Where(ModRunState.PriorEncounteredMonsterTypes.Contains)) });
			}
			IRunState runState = state.RunState;
			IRunState obj = ((runState is RunState) ? runState : null);
			MapPoint obj2 = ((obj != null) ? ((RunState)obj).CurrentMapPoint : null);
			if (RuleBusinessEvaluators.EvaluateLowHpElite(obj2 != null && (int)obj2.PointType == 6, (val != null) ? val.CurrentHp : 0, (val != null) ? val.MaxHp : 0).Matched && val != null)
			{
				Dispatch(DanmakuTrigger.LowHpElite, eventId, "low_hp_elite", new Dictionary<string, string>
				{
					["hp"] = val.CurrentHp.ToString(),
					["maxHp"] = val.MaxHp.ToString(),
					["room"] = "Elite"
				}, new Dictionary<string, string> { ["hp"] = val.CurrentHp.ToString() });
			}
			ModRunState.QueenPresent = array.Contains("QUEEN");
			ModRunState.BowlbugRockPresent = array.Contains("BOWLBUG_ROCK");
			ModRunState.ScrollOfBitingPresent = array.Contains("SCROLL_OF_BITING");
		}

