		private void OnTurnStarted(CombatState state)
		{
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			//IL_000e: Invalid comparison between Unknown and I4
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0031: Invalid comparison between Unknown and I4
			ModRunState.BeginTurn(state);
			TransitionTo(((int)state.CurrentSide == 1) ? GameFlowState.PlayerTurn : GameFlowState.EnemyTurn);
			ModRunState.Publish(new TurnStartedFact(ModRunState.CreateFactHeader(EventSourceKind.TurnStarted, CurrentState, EmissionScope.Combat), (int)state.CurrentSide == 1));
		}

		private void OnTurnEnded(CombatState state)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Invalid comparison between Unknown and I4
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			//IL_001f: Invalid comparison between Unknown and I4
			if ((int)state.CurrentSide == 2)
			{
				FinalizePlayerHandFlush(state);
				TransitionTo(GameFlowState.EnemyTurn);
			}
			else if ((int)state.CurrentSide == 1)
			{
				EvaluateCompletedEnemyTurn(state);
				ModRunState.Publish(new EnemyTurnCompletedFact(ModRunState.CreateFactHeader(EventSourceKind.EnemyTurnCompleted, CurrentState, EmissionScope.Combat)));
				TransitionTo(GameFlowState.PlayerTurn);
			}
		}

		private static void OnAboutToSwitchToEnemyTurn(CombatState state)
		{
			ModRunState.Publish(new PlayerEndTurnRequestedFact(ModRunState.CreateFactHeader(EventSourceKind.PlayerEndTurnRequested, GameFlowState.PlayerTurn, EmissionScope.Combat, FactBoundary.LocalPlayer)));
			ModRunState.EndTurnBlockCandidates.Clear();
			ModRunState.FlushedUnplayedBlockCards.Clear();
			ModRunState.EndTurnBlockSnapshotFinalized = false;
			ModRunState.HasBlockNoPlayFired = false;
			ModRunState.FrozenEnemyMoves.Clear();
			ModRunState.CompletedAttackMoves.Clear();
			ModRunState.ExecutedAttacksAgainstPlayer.Clear();
			ModRunState.EnemyTurnDamageRedirectedToPlayerPet = false;
			ModRunState.EnemyTurnEvaluationFinalized = false;
			ModRunState.EnemyTurnHpLost = 0;
			ModRunState.EnemyTurnBlockedDamage = 0;
			Player me = LocalContext.GetMe((ICombatState)(object)state);
			PlayerCombatState val = ((me != null) ? me.PlayerCombatState : null);
			ModRunState.EndTurnEnergy = ((val != null) ? val.Energy : 0);
			ModRunState.MinimumFlushedBlockCardCost = null;
			ModRunState.EnemyTurnPlayerHadBuffer = me != null && me.Creature.GetPowerAmount<BufferPower>() > 0;
			if (me != null && val != null)
			{
				foreach (CardModel card in CardPile.GetCards(me, (PileType[])(object)new PileType[1] { (PileType)2 }))
				{
					if (CombatRuleEvaluators.IsPlayableBlockCandidate(card.GainsBlock, card.CanPlay()))
					{
						ModRunState.EndTurnBlockCandidates.Add(card);
					}
				}
			}
			foreach (Creature item in state.Enemies.Where((Creature e) => e.IsAlive && e.Monster != null))
			{
				uint valueOrDefault = item.CombatId.GetValueOrDefault();
				MoveState nextMove = item.Monster.NextMove;
				ModRunState.FrozenEnemyMoves[valueOrDefault] = new ModRunState.FrozenEnemyMove(valueOrDefault, item.ModelId.Entry, ((MonsterState)nextMove).Id, item.Monster.IntendsToAttack);
			}
		}

		private static void FinalizePlayerHandFlush(CombatState state)
		{
			ModRunState.FlushedUnplayedBlockCards.Clear();
			Player me = LocalContext.GetMe((ICombatState)(object)state);
			if (me != null)
			{
				HashSet<CardModel> hashSet = new HashSet<CardModel>(CardPile.GetCards(me, (PileType[])(object)new PileType[1] { (PileType)3 }), ReferenceEqualityComparer.Instance);
				foreach (CardModel endTurnBlockCandidate in ModRunState.EndTurnBlockCandidates)
				{
					if (hashSet.Contains(endTurnBlockCandidate))
					{
						ModRunState.FlushedUnplayedBlockCards.Add(endTurnBlockCandidate);
					}
				}
				if (ModRunState.FlushedUnplayedBlockCards.Count > 0)
				{
					ModRunState.MinimumFlushedBlockCardCost = ModRunState.FlushedUnplayedBlockCards.Min((CardModel card) => Math.Max(0, card.EnergyCost.GetWithModifiers((CostModifiers)(-1))));
				}
			}
			ModRunState.EndTurnBlockSnapshotFinalized = true;
		}

		private static void EvaluateCompletedEnemyTurn(CombatState state)
		{
			if (ModRunState.EnemyTurnEvaluationFinalized)
			{
				return;
			}
			ModRunState.EnemyTurnEvaluationFinalized = true;
			Player me = LocalContext.GetMe((ICombatState)(object)state);
			Creature val = ((me != null) ? me.Creature : null);
			if (val != null)
			{
				RuleEvaluation ruleEvaluation = CombatRuleEvaluators.EvaluateNumberExtreme(new NumberExtremeInput(ModRunState.FrozenEnemyMoves.Values.Count((ModRunState.FrozenEnemyMove m) => m.HadAttackIntent), ModRunState.CompletedAttackMoves.Count, ModRunState.ExecutedAttacksAgainstPlayer.Count, ModRunState.EnemyTurnHpLost, ModRunState.EnemyTurnBlockedDamage, val.Block, AlreadyEvaluated: false, ModRunState.EnemyTurnDamageRedirectedToPlayerPet, ModRunState.EnemyTurnPlayerHadBuffer));
				string reasonCode = ruleEvaluation.ReasonCode;
				EventId eventId = ModRunState.NextEvent(EventSourceKind.TurnEnded);
				Dictionary<string, string> snapshot = new Dictionary<string, string>
				{
					["frozenAttackIntents"] = ModRunState.FrozenEnemyMoves.Values.Count((ModRunState.FrozenEnemyMove m) => m.HadAttackIntent).ToString(),
					["completedAttackMoves"] = ModRunState.CompletedAttackMoves.Count.ToString(),
					["executedAttacks"] = ModRunState.ExecutedAttacksAgainstPlayer.Count.ToString(),
					["hpLost"] = ModRunState.EnemyTurnHpLost.ToString(),
					["blockedDamage"] = ModRunState.EnemyTurnBlockedDamage.ToString(),
					["block"] = val.Block.ToString(),
					["damageRedirectedToPlayerPet"] = ModRunState.EnemyTurnDamageRedirectedToPlayerPet.ToString()
				};
				RuleEvidence evidence = new RuleEvidence(eventId, reasonCode, snapshot, TimingPhase.TurnEnd);
				if (ruleEvaluation.Matched)
				{
					DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(DanmakuTrigger.NumberExtreme), evidence);
				}
				else
				{
					RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.NumberExtreme, evidence);
				}
			}
		}

		private void OnRunStarted(RunState _)
		{
			GameFactBus.Instance.BeginRun();
			_emitter.BeginRunSession();
			_currentRoomKind = null;
			_currentNodeSequence = 0L;
			_runEndedPublished = false;
			TransitionTo(GameFlowState.Run);
			RunLaunchState runLaunchState = RunPersistenceCoordinator.ConsumeLaunch(_);
			PlayerStateSnapshot initialState = PlayerSnapshotFactory.CaptureLocal();
			RuntimeTraceRecorder.Instance?.BeginRun(runLaunchState.Identity, ModRunState.RunEpoch, runLaunchState.IsLoaded);
			if (runLaunchState.IsLoaded)
			{
				ModRunState.Publish(new RunLoadedFact(ModRunState.CreateFactHeader(EventSourceKind.RunLoaded, CurrentState, EmissionScope.Run), runLaunchState.Identity, runLaunchState.PersistentState, initialState));
			}
			else
			{
				ModRunState.Publish(new RunStartedFact(ModRunState.CreateFactHeader(EventSourceKind.RunStarted, CurrentState, EmissionScope.Run), runLaunchState.Identity, initialState));
			}
		}

		private void OnMapOpened()
		{
			if (_started)
			{
				GameContextStore? instance = GameContextStore.Instance;
				if (instance != null && instance.Run.IsActive)
				{
					TransitionTo(GameFlowState.Map);
					ModRunState.Publish(new MapEnteredFact(ModRunState.CreateFactHeader(EventSourceKind.MapEntered, CurrentState, EmissionScope.Room)));
				}
			}
		}

		private void OnMapClosed()
		{
			if (CurrentState == GameFlowState.Map)
			{
				TransitionTo(GameFlowState.Run);
			}
		}

