				GameContextStore? instance2 = GameContextStore.Instance;
				if (instance2 != null && instance2.Event.IsActive)
				{
					ModRunState.Publish(new EventClosedFact(ModRunState.CreateFactHeader(EventSourceKind.EventClosed, CurrentState, EmissionScope.Room), "next_room_entered", after));
				}
				GameContextStore? instance3 = GameContextStore.Instance;
				if (instance3 != null && instance3.RestSite.IsActive)
				{
					ModRunState.Publish(new RestSiteClosedFact(ModRunState.CreateFactHeader(EventSourceKind.RestSiteClosed, CurrentState, EmissionScope.Room), "next_room_entered", after));
				}
				ModRunState.Publish(new RoomLeavingFact(ModRunState.CreateFactHeader(EventSourceKind.RoomLeaving, CurrentState, EmissionScope.Room), _currentRoomKind, "next_room_entered", after, _currentNodeSequence));
			}
			ModRunState.BeginRoom();
			GameContextStore instance4 = GameContextStore.Instance;
			if (instance4 != null && instance4.Run.PairCollections.CurrentNode == 0L)
			{
				instance4.Run.PairCollections.RestoreOwned(PlayerSnapshotFactory.CaptureLocal(), 0L);
			}
			_currentNodeSequence = GameContextStore.Instance?.Run.PairCollections.BeginNode() ?? (_currentNodeSequence + 1);
			_emitter.BeginRoomSession();
			if (instance.CombatRoom != null)
			{
				_currentRoomKind = "Combat";
				NonCombatFactPatches.DiscardPendingEventOpened();
				TransitionTo(GameFlowState.CombatPending);
			}
			else if (instance.MerchantRoom != null)
			{
				_currentRoomKind = "Shop";
				NonCombatFactPatches.DiscardPendingEventOpened();
				TransitionTo(GameFlowState.Shop);
			}
			else if (instance.EventRoom != null)
			{
				_currentRoomKind = "Event";
				TransitionTo(GameFlowState.Event);
				_flushPendingEventOpened = true;
			}
			else if (instance.RestSiteRoom != null)
			{
				_currentRoomKind = "RestSite";
				NonCombatFactPatches.DiscardPendingEventOpened();
				TransitionTo(GameFlowState.RestSite);
			}
			else
			{
				_currentRoomKind = "Run";
				NonCombatFactPatches.DiscardPendingEventOpened();
				TransitionTo(GameFlowState.Run);
			}
			ModRunState.Publish(new RoomEnteredFact(ModRunState.CreateFactHeader(EventSourceKind.RoomEntered, CurrentState, EmissionScope.Room), _currentRoomKind, _currentNodeSequence));
			if (_flushPendingEventOpened)
			{
				_flushPendingEventOpened = false;
				NonCombatFactPatches.FlushPendingEventOpened();
			}
		}

		private void OnCombatWon(CombatRoom _)
		{
			_combatWon = true;
		}

		private void OnCombatEnded(CombatRoom _)
		{
			if (_combatActive)
			{
				CombatEndedFact fact = new CombatEndedFact(ModRunState.CreateFactHeader(EventSourceKind.CombatEnded, CurrentState, EmissionScope.Combat), _combatWon, ModRunState.CombatDamagedByEnemy);
				ModRunState.Publish(fact);
				EvaluateScrollProtection(fact);
				EvaluateReconviction(fact);
				ModRunState.FinishCombat(_combatWon);
			}
			OnCombatExited();
		}

		private static void EvaluateScrollProtection(CombatEndedFact fact)
		{
			ConditionResult conditionResult = ScrollOfBitingRuleEvaluators.EvaluateProtected(ModRunState.ScrollOfBitingPresent, ModRunState.ScrollMaxHpLost, fact.Won);
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["scrollPresent"] = ModRunState.ScrollOfBitingPresent.ToString(),
				["maxHpLost"] = ModRunState.ScrollMaxHpLost.ToString(),
				["won"] = fact.Won.ToString()
			};
			RuleEvidence evidence = new RuleEvidence(fact.Header.EventId, conditionResult.ReasonCode, snapshot, TimingPhase.Combat);
			if (conditionResult.Matched)
			{
				DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(DanmakuTrigger.ScrollMaxHpProtected), evidence);
			}
			else
			{
				RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.ScrollMaxHpProtected, evidence);
			}
		}

		private static void EvaluateReconviction(CombatEndedFact fact)
		{
			string[] array = ModRunState.CurrentCombatKilledMonsterTypes.Where(ModRunState.PriorKilledMonsterTypes.Contains).Order<string>(StringComparer.Ordinal).ToArray();
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["killedThisCombat"] = string.Join(",", ModRunState.CurrentCombatKilledMonsterTypes.Order<string>(StringComparer.Ordinal)),
				["priorKilled"] = string.Join(",", ModRunState.PriorKilledMonsterTypes.Order<string>(StringComparer.Ordinal)),
				["matched"] = string.Join(",", array)
			};
			RuleEvidence evidence = new RuleEvidence(fact.Header.EventId, "monster_type_defeated_in_previous_won_combat", snapshot, TimingPhase.Combat);
			if (array.Length != 0)
			{
				DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(DanmakuTrigger.Reconviction), evidence);
			}
			else
			{
				RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.Reconviction, evidence);
			}
		}

		public void OnCombatExited()
		{
			if (_combatActive)
			{
				_combatActive = false;
				_combatWon = false;
				_activeCombatSequence = 0L;
				DanmakuMonitorNode instance = DanmakuMonitorNode.Instance;
				if (instance != null && GodotObject.IsInstanceValid((GodotObject)(object)instance))
				{
					DanmakuMonitorNode.ReleaseInstance(instance);
					((Node)instance).QueueFree();
				}
				ModRunState.ClearCombatReferences();
				if (_started)
				{
					TransitionTo(GameFlowState.Run);
				}
			}
		}

		public void OnRewardOpened()
		{
			if (_started)
			{
				TransitionTo(GameFlowState.Reward);
			}
		}

		public void OnRewardClosed()
		{
			if (_started && CurrentState == GameFlowState.Reward)
			{
				TransitionTo(GameFlowState.Run);
			}
		}

		public void OnRunEnded(string reason, bool deletePersistentState)
		{
			if (_runEndedPublished)
			{
				return;
			}
			GameContextStore? instance = GameContextStore.Instance;
			if (instance != null && instance.Run.IsActive)
			{
				_runEndedPublished = true;
				if (deletePersistentState)
				{
					RunPersistenceCoordinator.DeleteStoredState();
				}
				else
				{
					RunPersistenceCoordinator.PersistActive();
				}
				ModRunState.Publish(new RunEndedFact(ModRunState.CreateFactHeader(EventSourceKind.RunEnded, GameFlowState.Inactive, EmissionScope.Run), reason));
				OnCombatExited();
				if (reason == "cleanup")
				{
					_emitter.CancelCombatSession();
					_emitter.CancelRoomSession();
					_emitter.CancelRunSession();
				}
				_currentRoomKind = null;
				_currentNodeSequence = 0L;
				TransitionTo(GameFlowState.Inactive);
				if (reason == "cleanup")
				{
					RuntimeTraceRecorder.Instance?.EndRun(reason);
				}
				else
				{
					RuntimeTraceRecorder.Instance?.ScheduleEndRun(reason, _emitter.RunEndTraceDrainTime);
				}
			}
		}

		private void TransitionTo(GameFlowState next)
		{
			CurrentState = next;
			_pools.SetActivePhases(FlowPoolPolicy.GetActivePhases(next));
		}
	}
	public sealed class PoolManager
	{
		private readonly Dictionary<TimingPhase, DanmakuPool> _pools = new Dictionary<TimingPhase, DanmakuPool>();

		private readonly HashSet<TimingPhase> _active = new HashSet<TimingPhase>();

		public static PoolManager Instance { get; private set; }

		public IReadOnlySet<TimingPhase> ActivePhases => new HashSet<TimingPhase>(_active);

		public static PoolManager Create(IEnumerable<IDanmakuRule> rules)
		{
			PoolManager poolManager = new PoolManager();
			TimingPhase[] values = Enum.GetValues<TimingPhase>();
			foreach (TimingPhase timingPhase in values)
			{
				poolManager._pools[timingPhase] = new DanmakuPool(timingPhase, new List<IDanmakuRule>());
			}
			foreach (IGrouping<TimingPhase, IDanmakuRule> item in from r in rules
				group r by r.Phase)
			{
				poolManager._pools[item.Key] = new DanmakuPool(item.Key, item.ToList());
			}
			Instance = poolManager;
			return poolManager;
		}

		public static bool IsPhaseActive(TimingPhase phase)
		{
			return Instance?._active.Contains(phase) ?? false;
		}

		public void SetActivePhases(IEnumerable<TimingPhase> phases)
		{
			HashSet<TimingPhase> target = new HashSet<TimingPhase>(phases);
			foreach (TimingPhase item in target)
			{
				if (!_pools.ContainsKey(item))
				{
					throw new ArgumentOutOfRangeException("phases", item, "未定义的判定池阶段");
				}
			}
			TimingPhase[] array = _active.Where((TimingPhase p) => !target.Contains(p)).ToArray();
			TimingPhase[] array2 = target.Where((TimingPhase p) => !_active.Contains(p)).ToArray();
			TimingPhase[] array3 = array;
			foreach (TimingPhase timingPhase in array3)
			{
				_active.Remove(timingPhase);
				_pools[timingPhase].Deactivate();
			}
			array3 = array2;
			foreach (TimingPhase timingPhase2 in array3)
			{
				_active.Add(timingPhase2);
				_pools[timingPhase2].Activate();
			}
		}

		public void Shutdown()
		{
			SetActivePhases(Array.Empty<TimingPhase>());
			if (Instance == this)
			{
				Instance = null;
			}
		}
	}
}
namespace DanmakuSpire.DanmakuSpireCode.Monitor.Rules
