	public static class ShopRuleEvaluators
	{
		public static ConditionResult EvaluateHighValuePurchase(ShopItemSnapshot purchased, IReadOnlyList<ShopItemSnapshot> openedItems)
		{
			if (purchased.Kind == "MerchantCardEntry")
			{
				int num = (from i in openedItems.Where(IsCard)
					select i.Price).DefaultIfEmpty(-1).Max();
				if (purchased.Price < num)
				{
					return ConditionResult.Miss("purchased_card_not_most_expensive");
				}
				return ConditionResult.Match("purchased_most_expensive_shop_card");
			}
			if (purchased.Kind == "MerchantRelicEntry")
			{
				if (purchased.IsPremiumSlot)
				{
					return ConditionResult.Match("purchased_special_shop_relic");
				}
				int num2 = (from i in openedItems.Where(IsRelic)
					select i.Price).DefaultIfEmpty(-1).Max();
				if (purchased.Price < num2)
				{
					return ConditionResult.Miss("purchased_relic_not_most_expensive");
				}
				return ConditionResult.Match("purchased_most_expensive_shop_relic");
			}
			return ConditionResult.Miss("purchase_not_card_or_relic");
		}

		private static bool IsCard(ShopItemSnapshot item)
		{
			return item.Kind == "MerchantCardEntry";
		}

		private static bool IsRelic(ShopItemSnapshot item)
		{
			return item.Kind == "MerchantRelicEntry";
		}

		public static IReadOnlyList<ShopItemSnapshot> SelectShopUmbrellaItems(IReadOnlyList<ShopItemSnapshot> items)
		{
			return items.Where((ShopItemSnapshot item) => !item.Purchased && !string.IsNullOrWhiteSpace(item.DisplayName)).ToArray();
		}

		public static string ShopUmbrellaVariant(ShopItemSnapshot item)
		{
			return $"{item.Kind}:{item.SlotIndex}:{item.ItemId}";
		}
	}
