	internal static class CombatHistoryPatches
	{
		[HarmonyPatch(typeof(CombatHistory), "CardPlayStarted", new Type[]
		{
			typeof(ICombatState),
			typeof(CardPlay)
		})]
		private static class CardPlayStartedPatch
		{
			private static void Postfix(ICombatState combatState, CardPlay cardPlay)
			{
				//IL_022e: Unknown result type (might be due to invalid IL or missing references)
				//IL_0234: Invalid comparison between Unknown and I4
				if (!PoolManager.IsPhaseActive(TimingPhase.Combat) || ((cardPlay != null) ? cardPlay.Card : null) == null || !cardPlay.IsFirstInSeries || cardPlay.Card.Owner == null || !LocalContext.IsMe(cardPlay.Card.Owner))
				{
					return;
				}
				CardModel card = cardPlay.Card;
				string entry = ((AbstractModel)card).Id.Entry;
				ModRunState.Publish(new CardPlayedFact(new GameFactHeader(ModRunState.NextEvent(EventSourceKind.CardPlayStarted), PhaseRouter.Instance?.CurrentState ?? GameFlowState.PlayerTurn, EmissionScope.Combat, ModRunState.RoomSequence, FactBoundary.LocalPlayer), entry, cardPlay.PlayCount));
				ConditionResult conditionResult = RuleBusinessEvaluators.EvaluateStartupCard(entry);
				if (conditionResult.Matched)
				{
					ModRunState.StartupPlayCount++;
					Dictionary<string, string> context = new Dictionary<string, string> { ["x"] = ModRunState.StartupPlayCount.ToString() };
					EventId eventId = ModRunState.NextEvent(EventSourceKind.CardPlayStarted);
					DanmakuHub.Instance?.Dispatch(new DanmakuSignal(DanmakuTrigger.StartupCard, context), new RuleEvidence(eventId, conditionResult.ReasonCode, new Dictionary<string, string>
					{
						["card"] = entry,
						["startupCount"] = ModRunState.StartupPlayCount.ToString()
					}, TimingPhase.Combat));
				}
				int baseReplayCount = card.BaseReplayCount;
				int enemyCount = combatState.Enemies.Count((Creature enemy) => enemy.IsAlive);
				Creature target = cardPlay.Target;
				VariantEvaluation variantEvaluation = RuleBusinessEvaluators.EvaluateCounterMatch(entry, baseReplayCount, enemyCount, (target != null) ? target.ModelId.Entry : null);
				if (variantEvaluation.Result.Matched)
				{
					EventId eventId2 = ModRunState.NextEvent(EventSourceKind.CardPlayStarted);
					DanmakuHub? instance = DanmakuHub.Instance;
					if (instance != null)
					{
						DanmakuSignal signal = DanmakuSignal.Of(DanmakuTrigger.CounterMatch);
						string reasonCode = variantEvaluation.Result.ReasonCode;
						Dictionary<string, string> obj = new Dictionary<string, string>
						{
							["card"] = entry,
							["enemyCount"] = combatState.Enemies.Count.ToString()
						};
						Creature target2 = cardPlay.Target;
						obj["target"] = ((target2 != null) ? target2.ModelId.Entry : null) ?? "";
						instance.Dispatch(signal, new RuleEvidence(eventId2, reasonCode, obj, TimingPhase.Combat, variantEvaluation.Variant));
					}
				}
				RuleEvaluation ruleEvaluation = CombatRuleEvaluators.EvaluateBigTurn(new BigTurnInput(cardPlay.PlayCount, (int)card.Type == 1, HasQueuedCard: false, 0f));
				if (ruleEvaluation.Matched && ModRunState.TryFireBigTurn())
				{
					EventId eventId3 = ModRunState.NextEvent(EventSourceKind.CardPlayStarted);
					DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(DanmakuTrigger.BigTurn), new RuleEvidence(eventId3, ruleEvaluation.ReasonCode, new Dictionary<string, string>
					{
						["card"] = entry,
						["playCount"] = cardPlay.PlayCount.ToString()
					}, TimingPhase.Combat));
				}
				DanmakuMonitorNode.Instance?.OnPlayerAction();
			}
		}

