		[HarmonyPatch(typeof(PaperCutsPower), "AfterDamageGiven")]
		private static class ScrollMaxHpLossPatch
		{
			private readonly record struct State(bool Candidate, int OldMaxHp);

			private static void Prefix(PaperCutsPower __instance, Creature target, DamageResult result, out State __state)
			{
				bool candidate = ModRunState.ScrollOfBitingPresent && ((PowerModel)__instance).Owner.ModelId.Entry == "SCROLL_OF_BITING" && target != null && LocalContext.IsMe(target) && result.UnblockedDamage > 0;
				__state = new State(candidate, (target != null) ? target.MaxHp : 0);
			}

			private static void Postfix(Creature target, State __state)
			{
				if (__state.Candidate && target != null && PoolManager.IsPhaseActive(TimingPhase.Combat))
				{
					int maxHp = target.MaxHp;
					MaxHpChangedFact maxHpChangedFact = new MaxHpChangedFact(ModRunState.CreateFactHeader(EventSourceKind.DamageReceived, PhaseRouter.Instance?.CurrentState ?? GameFlowState.PlayerTurn, EmissionScope.Combat, FactBoundary.LocalPlayer), __state.OldMaxHp, maxHp);
					ModRunState.Publish(maxHpChangedFact);
					ConditionResult conditionResult = ScrollOfBitingRuleEvaluators.EvaluateMaxHpLoss(ModRunState.ScrollOfBitingPresent, __state.OldMaxHp, maxHp);
					RuleEvidence evidence = new RuleEvidence(Snapshot: new Dictionary<string, string>
					{
						["source"] = "SCROLL_OF_BITING",
						["oldMaxHp"] = __state.OldMaxHp.ToString(),
						["newMaxHp"] = maxHp.ToString()
					}, EventId: maxHpChangedFact.Header.EventId, ReasonCode: conditionResult.ReasonCode, Phase: TimingPhase.Combat);
					if (conditionResult.Matched && !ModRunState.ScrollMaxHpLost)
					{
						ModRunState.ScrollMaxHpLost = true;
						DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(DanmakuTrigger.ScrollMaxHpLost), evidence);
					}
					else
					{
						RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.ScrollMaxHpLost, evidence);
					}
				}
			}
		}

