	internal static class DeathRulesPatch
	{
		private readonly record struct DeathSnapshot(long CombatSequence, ICombatState CombatState, Creature Creature, uint CombatId, string ModelEntry, bool IsMonster, bool IsLocalPlayer, int AliveEnemyCountBeforeDeath, bool IsFirstPlayerTurn, bool MonsterTypeKilledEarlierInRun, bool StrongMonsterTriggeredEarlierInRun, bool IsDevotedSculptor, bool SculptorChanted, bool QueenPresent, string LocalCharacterId);

		[HarmonyPatch(typeof(Creature), "InvokeDiedEvent", new Type[] { })]
		private static class InvokeDiedEventPatch
		{
			private static void Prefix(Creature __instance)
			{
				Creature __instance2 = __instance;
				if (!PoolManager.IsPhaseActive(TimingPhase.Combat))
				{
					return;
				}
				ICombatState combatState = __instance2.CombatState;
				if (combatState == null || CombatManager.Instance.DebugOnlyGetState() != combatState)
				{
					return;
				}
				bool isMonster = __instance2.IsMonster;
				bool flag = __instance2.IsPlayer && LocalContext.IsMe(__instance2);
				if (isMonster || flag)
				{
					uint num = (uint)(((int?)__instance2.CombatId) ?? RuntimeHelpers.GetHashCode(__instance2));
					string entry = __instance2.ModelId.Entry;
					int aliveEnemiesExcludingCreature = combatState.Enemies.Count((Creature e) => e.IsAlive && e != __instance2);
					long combatSequence = ModRunState.CombatSequence;
					Creature creature = __instance2;
					int aliveEnemyCountBeforeDeath = CombatRuleEvaluators.CountAliveEnemiesBeforeDeath(aliveEnemiesExcludingCreature, isMonster);
					bool isFirstPlayerTurn = ModRunState.TurnSequence == 1;
					bool monsterTypeKilledEarlierInRun = isMonster && ModRunState.PriorKilledMonsterTypes.Contains(entry);
					bool strongMonsterTriggeredEarlierInRun = isMonster && ModRunState.CurrentStrongMonsterTypes.Contains(entry);
					bool isDevotedSculptor = entry == "DEVOTED_SCULPTOR";
					bool sculptorChanted = ModRunState.SculptorsChanted.Contains(num);
					bool queenPresent = ModRunState.QueenPresent;
					Player me = LocalContext.GetMe(combatState);
					ProcessConfirmedDeath(new DeathSnapshot(combatSequence, combatState, creature, num, entry, isMonster, flag, aliveEnemyCountBeforeDeath, isFirstPlayerTurn, monsterTypeKilledEarlierInRun, strongMonsterTriggeredEarlierInRun, isDevotedSculptor, sculptorChanted, queenPresent, ((me != null) ? ((AbstractModel)me.Character).Id.Entry : null) ?? string.Empty));
				}
			}

			private static void ProcessConfirmedDeath(DeathSnapshot death)
			{
				if (!CombatRuleEvaluators.IsSameCombatLifecycle(death.CombatSequence, death.CombatState, ModRunState.CombatSequence, CombatManager.Instance.DebugOnlyGetState()) || !PoolManager.IsPhaseActive(TimingPhase.Combat) || death.Creature.CombatState != death.CombatState || !ModRunState.ProcessedDeaths.Add(death.CombatId))
				{
					return;
				}
				if (death.IsMonster)
				{
					ModRunState.CurrentCombatKilledMonsterTypes.Add(death.ModelEntry);
				}
				DeathRuleEvaluation deathRuleEvaluation = CombatRuleEvaluators.EvaluateDeath(new DeathRuleInput(death.IsMonster, death.IsLocalPlayer, death.IsFirstPlayerTurn, death.AliveEnemyCountBeforeDeath, death.MonsterTypeKilledEarlierInRun, death.StrongMonsterTriggeredEarlierInRun, death.IsDevotedSculptor, death.SculptorChanted, AlreadyProcessed: false));
				EventId eventId = ModRunState.NextEvent(EventSourceKind.MonsterDied);
				ModRunState.Publish(new CreatureDeathConfirmedFact(new GameFactHeader(eventId, PhaseRouter.Instance?.CurrentState ?? GameFlowState.PlayerTurn, EmissionScope.Combat, ModRunState.RoomSequence, death.IsLocalPlayer ? FactBoundary.LocalPlayer : FactBoundary.System), death.ModelEntry, death.IsLocalPlayer));
				Dictionary<string, string> dictionary = new Dictionary<string, string>
				{
					["combatId"] = death.CombatId.ToString(),
					["modelId"] = death.ModelEntry,
					["aliveEnemyCountBeforeDeath"] = death.AliveEnemyCountBeforeDeath.ToString(),
					["turn"] = ModRunState.TurnSequence.ToString()
				};
				if (deathRuleEvaluation.PlayerDeath)
				{
					Dispatch(DanmakuTrigger.PlayerDeath, eventId, deathRuleEvaluation.ReasonCode, dictionary);
				}
				else
				{
					if (!death.IsMonster)
					{
						return;
					}
					if (death.ModelEntry == "QUEEN")
					{
						ModRunState.QueenPresent = false;
					}
					if (ModRunState.PendingExactLethalOverkill.Remove(death.CombatId, out var value))
					{
						RuleEvaluation ruleEvaluation = CombatRuleEvaluators.EvaluateExactLethal(targetDied: true, value);
						if (ruleEvaluation.Matched)
						{
							Dispatch(DanmakuTrigger.NumberExtreme, eventId, ruleEvaluation.ReasonCode, new Dictionary<string, string>(dictionary) { ["overkill"] = value.ToString() });
						}
					}
					if (deathRuleEvaluation.OneTurnKill)
					{
						Dispatch(DanmakuTrigger.OneTurnKill, eventId, "monster_killed_in_first_player_turn", dictionary, "", new Dictionary<string, string> { ["char"] = death.LocalCharacterId });
					}
					if (deathRuleEvaluation.StrongMonsterKill)
					{
						Dispatch(DanmakuTrigger.StrongMonsterKill, eventId, "current_strong_monster_killed", dictionary);
					}
					if (deathRuleEvaluation.SculptorPreChant)
					{
						Dispatch(DanmakuTrigger.SculptorPreChant, eventId, "devoted_sculptor_killed_before_forbidden_incantation", dictionary);
					}
					ConditionResult conditionResult = RuleBusinessEvaluators.EvaluateQueenTorchheadKill(death.QueenPresent, death.ModelEntry, ModRunState.QueenVariantsThisTurn.Contains("kill_torch"));
					if (conditionResult.Matched && ModRunState.TryFireQueenVariant("kill_torch"))
					{
						Dispatch(DanmakuTrigger.QueenTorchhead, eventId, conditionResult.ReasonCode, dictionary);
					}
				}
			}
		}

		private static void Dispatch(DanmakuTrigger trigger, EventId id, string reason, Dictionary<string, string> snapshot, string variant = "", IReadOnlyDictionary<string, string>? context = null)
		{
			DanmakuHub.Instance?.Dispatch(new DanmakuSignal(trigger, context, variant), new RuleEvidence(id, reason, snapshot, TimingPhase.Combat, variant));
		}
	}
	internal static class HandQualityRulesPatch
	{
		[HarmonyPatch(typeof(Hook), "AfterAutoPrePlayPhaseEntered", new Type[]
		{
			typeof(HookPlayerChoiceContext),
			typeof(ICombatState),
			typeof(Player)
		})]
		private static class AfterAutoPrePlayPhasePatch
		{
			private static void Postfix(ICombatState combatState, Player player, ref Task __result)
			{
				long combatSequence = ModRunState.CombatSequence;
				__result = AwaitAndEvaluateAsync(__result, combatState, player, combatSequence);
			}

			private static async Task AwaitAndEvaluateAsync(Task originalTask, ICombatState combatState, Player player, long combatSequence)
			{
				await originalTask;
				if (!CombatRuleEvaluators.IsSameCombatLifecycle(combatSequence, combatState, ModRunState.CombatSequence, CombatManager.Instance.DebugOnlyGetState()) || !PoolManager.IsPhaseActive(TimingPhase.Combat) || (int)combatState.CurrentSide != 1)
				{
					return;
				}
				PlayerCombatState playerCombatState = player.PlayerCombatState;
				if (playerCombatState != null && CombatRuleEvaluators.IsExpectedAutoPrePlayBoundary((int)playerCombatState.Phase) && LocalContext.IsMe(player) && !ModRunState.DefenseOffenseChecked)
				{
					ModRunState.DefenseOffenseChecked = true;
					EventId id = ModRunState.NextEvent(EventSourceKind.TurnStarted);
					bool enemyIntendsToAttack = combatState.Enemies.Any(delegate(Creature e)
					{
						MonsterModel monster = e.Monster;
						return monster != null && monster.IntendsToAttack;
					});
					CardModel[] array = CardPile.GetCards(player, (PileType[])(object)new PileType[1] { (PileType)2 }).ToArray();
					bool hasBlock = array.Any((CardModel c) => c.GainsBlock);
					bool hasAttack = array.Any((CardModel c) => CardCategories.Attack.Contains(((AbstractModel)c).Id.Entry));
					bool hasDraw = array.Any((CardModel c) => CardCategories.Draw.Contains(((AbstractModel)c).Id.Entry));
					int currentActIndex = combatState.RunState.CurrentActIndex;
					ModRunState.Publish(new HandDrawCompletedFact(ModRunState.CreateFactHeader(EventSourceKind.HandDrawCompleted, PhaseRouter.Instance?.CurrentState ?? GameFlowState.PlayerTurn, EmissionScope.Combat, FactBoundary.LocalPlayer), array.Select((CardModel c) => ((AbstractModel)c).Id.Entry).ToArray(), enemyIntendsToAttack, currentActIndex));
					Dictionary<string, string> snapshot = new Dictionary<string, string>
					{
						["enemyAttacks"] = enemyIntendsToAttack.ToString(),
						["handCount"] = array.Length.ToString(),
						["actIndex"] = currentActIndex.ToString(),
						["hasBlock"] = hasBlock.ToString(),
						["hasAttack"] = hasAttack.ToString(),
						["hasDraw"] = hasDraw.ToString()
					};
					OpeningHandQualityInput input = new OpeningHandQualityInput(currentActIndex, enemyIntendsToAttack, hasBlock, hasAttack, hasDraw);
					RuleEvaluation ruleEvaluation = CombatRuleEvaluators.EvaluateDefenseLack(input);
					RuleEvaluation ruleEvaluation2 = CombatRuleEvaluators.EvaluateOffenseLack(input);
					if (ruleEvaluation.Matched)
					{
						Dispatch(DanmakuTrigger.DefenseLack, id, ruleEvaluation.ReasonCode, snapshot);
					}
					else if (ruleEvaluation2.Matched)
					{
						Dispatch(DanmakuTrigger.OffenseLack, id, ruleEvaluation2.ReasonCode, snapshot);
					}
				}
			}
		}

