		{
			DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(trigger), new RuleEvidence(id, reason, snapshot, TimingPhase.Combat));
		}
	}
	public sealed record HarmonyPatchImpact(string PatchType, IReadOnlyList<string> ProducedFacts, IReadOnlyList<string> AffectedRuleIds);
	public static class HarmonyPatchImpactCatalog
	{
		private sealed record Definition(Type[] Facts, DanmakuTrigger[] DirectRules, bool AffectsAllRules = false, bool InfrastructureOnly = false);

		private static readonly IReadOnlyDictionary<string, Definition> Definitions = Build();

		public static IReadOnlyList<string> RegisteredPatchKeys => Definitions.Keys.OrderBy<string, string>((string key) => key, StringComparer.Ordinal).ToArray();

		public static HarmonyPatchImpact Get(Type patchType)
		{
			string text = KeyOf(patchType);
			if (!Definitions.TryGetValue(text, out Definition definition))
			{
				throw new InvalidOperationException("Harmony 补丁 " + text + " 尚未登记影响范围");
			}
			HashSet<DanmakuTrigger> hashSet = definition.DirectRules.ToHashSet();
			foreach (RuleFactRegistration item in RuleFactRegistry.All)
			{
				if (item.Bindings.Any((RuleFactBinding binding) => definition.Facts.Contains(binding.FactType)))
				{
					hashSet.Add(item.Trigger);
				}
			}
			if (definition.AffectsAllRules)
			{
				foreach (RuleFactRegistration item2 in RuleFactRegistry.All.Where((RuleFactRegistration item) => item.Status != RuleImplementationStatus.Meta))
				{
					hashSet.Add(item2.Trigger);
				}
			}
			return new HarmonyPatchImpact(patchType.FullName ?? patchType.Name, definition.Facts.Select((Type type) => type.Name).Order<string>(StringComparer.Ordinal).ToArray(), hashSet.Where((DanmakuTrigger trigger) => trigger != DanmakuTrigger.CombatStart).Select(DanmakuRuleIds.Get).Order<string>(StringComparer.Ordinal)
				.ToArray());
		}

		public static string KeyOf(Type patchType)
		{
			if (!(patchType.DeclaringType == null))
			{
				return patchType.DeclaringType.Name + "+" + patchType.Name;
			}
			return patchType.Name;
		}

		public static bool IsInfrastructure(Type patchType)
		{
			if (Definitions.TryGetValue(KeyOf(patchType), out Definition value))
			{
				return value.InfrastructureOnly;
			}
			return false;
		}

