	public sealed record HarmonyPatchInstallResult(string PatchType, bool Success, string Error, IReadOnlyList<string> TargetMethods, IReadOnlyList<string> ProducedFacts, IReadOnlyList<string> AffectedRuleIds);
	public static class HarmonyPatchRuntimeState
	{
		public static IReadOnlyList<HarmonyPatchInstallResult> Status { get; set; } = Array.Empty<HarmonyPatchInstallResult>();


		public static string ReportPath { get; set; } = "";

	}
	public static class HarmonyPatchInstaller
	{
		public static IReadOnlyList<Type> Discover(Assembly assembly)
		{
			IEnumerable<Type> source;
			try
			{
				source = assembly.GetTypes();
			}
			catch (ReflectionTypeLoadException ex)
			{
				source = ex.Types.OfType<Type>();
				string text = string.Join(" | ", (from item in ex.LoaderExceptions
					where item != null
					select item.Message).Distinct<string>(StringComparer.Ordinal));
				MainFile.Log("[Harmony] 当前游戏版本无法加载部分监听类型，已跳过并继续发现其余补丁：" + text);
			}
			return source.Where((Type type) => type.GetCustomAttributes(typeof(HarmonyPatch), inherit: false).Length != 0).OrderBy<Type, string>((Type type) => type.FullName, StringComparer.Ordinal).ToArray();
		}

		public static IReadOnlyList<HarmonyPatchInstallResult> Install(Harmony harmony, Assembly assembly)
		{
			List<HarmonyPatchInstallResult> list = new List<HarmonyPatchInstallResult>();
			foreach (Type item in Discover(assembly))
			{
				HarmonyPatchImpact harmonyPatchImpact;
				try
				{
					harmonyPatchImpact = HarmonyPatchImpactCatalog.Get(item);
				}
				catch (Exception ex)
				{
					string text = item.FullName ?? item.Name;
					list.Add(new HarmonyPatchInstallResult(text, Success: false, ex.Message, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<string>()));
					MainFile.Log($"[Harmony] 补丁缺少影响登记，其他补丁继续：{text} | {ex}");
					continue;
				}
				IReadOnlyList<string> readOnlyList = Array.Empty<string>();
				try
				{
					readOnlyList = ResolveTargets(item);
					if (readOnlyList.Count == 0)
					{
						throw new MissingMethodException("Harmony 未解析到原始目标方法");
					}
					harmony.CreateClassProcessor(item).Patch();
					list.Add(Result(item, success: true, "", readOnlyList, harmonyPatchImpact));
				}
				catch (Exception ex2)
				{
					string value = item.FullName ?? item.Name;
					list.Add(Result(item, success: false, ex2.Message, readOnlyList, harmonyPatchImpact));
					MainFile.Log($"[Harmony] 补丁安装失败，其他补丁继续：{value} | 受影响规则 {string.Join(",", harmonyPatchImpact.AffectedRuleIds)} | {ex2}");
				}
			}
			return list;
		}

		public static IReadOnlyList<HarmonyPatchInstallResult> Inspect(Assembly assembly)
		{
			List<HarmonyPatchInstallResult> list = new List<HarmonyPatchInstallResult>();
			foreach (Type item in Discover(assembly))
			{
				HarmonyPatchImpact impact;
				try
				{
					impact = HarmonyPatchImpactCatalog.Get(item);
				}
				catch (Exception ex)
				{
					list.Add(new HarmonyPatchInstallResult(item.FullName ?? item.Name, Success: false, ex.Message, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<string>()));
					continue;
				}
				try
				{
					IReadOnlyList<string> readOnlyList = ResolveTargets(item);
					if (readOnlyList.Count == 0)
					{
						throw new MissingMethodException("Harmony 未解析到原始目标方法");
					}
					list.Add(Result(item, success: true, "", readOnlyList, impact));
				}
				catch (Exception ex2)
				{
					list.Add(Result(item, success: false, ex2.Message, Array.Empty<string>(), impact));
				}
			}
			return list;
		}

		private static IReadOnlyList<string> ResolveTargets(Type patchType)
		{
			//IL_00b3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ba: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d1: Expected I4, but got Unknown
			MethodInfo method = patchType.GetMethod("TargetMethods", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, null, Type.EmptyTypes, null);
			if (method != null)
			{
				return ((method.Invoke(null, null) as IEnumerable<MethodBase>) ?? throw new InvalidOperationException("TargetMethods 未返回方法集合")).Select(FormatTarget).ToArray();
			}
			MethodInfo method2 = patchType.GetMethod("TargetMethod", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, null, Type.EmptyTypes, null);
			if (method2 != null)
			{
				return new <>z__ReadOnlySingleElementList<string>(FormatTarget((method2.Invoke(null, null) as MethodBase) ?? throw new InvalidOperationException("TargetMethod 未返回目标方法")));
			}
			HarmonyMethod mergedFromType = HarmonyMethodExtensions.GetMergedFromType(patchType);
			MethodType valueOrDefault = mergedFromType.methodType.GetValueOrDefault((MethodType)0);
			MethodBase methodBase = (int)valueOrDefault switch
			{
				0 => string.IsNullOrWhiteSpace(mergedFromType.methodName) ? null : AccessTools.DeclaredMethod(mergedFromType.declaringType, mergedFromType.methodName, mergedFromType.argumentTypes, (Type[])null), 
				3 => AccessTools.DeclaredConstructor(mergedFromType.declaringType, mergedFromType.argumentTypes, false), 
				1 => AccessTools.DeclaredPropertyGetter(mergedFromType.declaringType, mergedFromType.methodName), 
				2 => AccessTools.DeclaredPropertySetter(mergedFromType.declaringType, mergedFromType.methodName), 
				_ => throw new NotSupportedException($"静态预检暂不支持 Harmony MethodType {mergedFromType.methodType}"), 
			};
			if (methodBase == null)
			{
				return Array.Empty<string>();
			}
			return new <>z__ReadOnlySingleElementList<string>(FormatTarget(methodBase));
		}

		private static string FormatTarget(MethodBase method)
		{
			return $"{method.DeclaringType?.FullName}.{method.Name}({string.Join(",", from p in method.GetParameters()
				select p.ParameterType.FullName ?? p.ParameterType.Name)})";
		}

		private static HarmonyPatchInstallResult Result(Type patchType, bool success, string error, IReadOnlyList<string> targets, HarmonyPatchImpact impact)
		{
			return new HarmonyPatchInstallResult(patchType.FullName ?? patchType.Name, success, error, targets, impact.ProducedFacts, impact.AffectedRuleIds);
		}
	}
	internal static class MultiplayerRuleConsumers
	{
		public static void Register(RuleConsumerGroup group, GameFactBus bus)
		{
			group.Add(new RuleFactConsumer<RewardSelectedFact>(bus, DanmakuTrigger.MultiplayerRewardSelect, TimingPhase.Reward, OnRewardSelected, requireLocalPlayer: true));
			group.Add(new RuleFactConsumer<ShopPurchasedFact>(bus, DanmakuTrigger.MultiplayerShopPurchase, TimingPhase.Shop, OnShopPurchased, requireLocalPlayer: true));
			group.Add(new RuleFactConsumer<ShopCardRemovalUsedFact>(bus, DanmakuTrigger.MultiplayerShopPurchase, TimingPhase.Shop, OnShopCardRemoval, requireLocalPlayer: true));
			group.Add(new RuleFactConsumer<RestSiteOptionCompletedFact>(bus, DanmakuTrigger.MultiplayerRestSite, TimingPhase.RestSite, OnRestSiteOption, requireLocalPlayer: true));
		}

		private static void OnRewardSelected(RuleConsumptionContext<RewardSelectedFact> input)
		{
			DispatchMultiplayer(DanmakuTrigger.MultiplayerRewardSelect, TimingPhase.Reward, input, new Dictionary<string, string>
			{
				["rewardId"] = input.Fact.RewardId,
				["rewardName"] = input.Fact.RewardName ?? ""
			}, new RuleContextBuilder().CardReference(input.Fact.RewardName ?? "", input.Fact.RewardId).Build());
		}

		private static void OnShopPurchased(RuleConsumptionContext<ShopPurchasedFact> input)
		{
			if (string.Equals(input.Fact.Item.Kind, "MerchantCardRemovalEntry", StringComparison.Ordinal))
			{
				RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.MultiplayerShopPurchase, new RuleEvidence(input.Fact.Header.EventId, "card_removal_uses_removal_variant", new Dictionary<string, string>
				{
					["itemId"] = input.Fact.Item.ItemId,
					["itemKind"] = input.Fact.Item.Kind
				}, TimingPhase.Shop));
			}
			else
			{
				DispatchMultiplayer(DanmakuTrigger.MultiplayerShopPurchase, TimingPhase.Shop, input, new Dictionary<string, string>
				{
					["itemId"] = input.Fact.Item.ItemId,
					["itemKind"] = input.Fact.Item.Kind,
					["itemName"] = input.Fact.Item.DisplayName
				}, new RuleContextBuilder().ItemReference(input.Fact.Item.DisplayName, input.Fact.Item.ItemId, input.Fact.Item.Kind.Contains("Card", StringComparison.Ordinal) ? "card" : (input.Fact.Item.Kind.Contains("Relic", StringComparison.Ordinal) ? "relic" : "item")).Build());
			}
		}

		private static void OnShopCardRemoval(RuleConsumptionContext<ShopCardRemovalUsedFact> input)
		{
			DispatchMultiplayer(DanmakuTrigger.MultiplayerShopPurchase, TimingPhase.Shop, input, new Dictionary<string, string>
			{
				["removedCardId"] = input.Fact.RemovedCardId,
				["removedCardName"] = input.Fact.RemovedCardName
			}, string.IsNullOrWhiteSpace(input.Fact.RemovedCardName) ? null : new RuleContextBuilder().CardReference(input.Fact.RemovedCardName, input.Fact.RemovedCardId).Build(), "removal");
		}

		private static void OnRestSiteOption(RuleConsumptionContext<RestSiteOptionCompletedFact> input)
		{
			if (input.Fact.Succeeded)
			{
				CardStateSnapshot cardStateSnapshot = RulePlayerDiff.Between(new RulePlayerSnapshot(input.Fact.Before, input.Fact.Before.StableCardStates), new RulePlayerSnapshot(input.Fact.After, input.Fact.After.StableCardStates)).Upgrades.FirstOrDefault((CardStateChange change) => change.After.UpgradeLevel > change.Before.UpgradeLevel)?.After;
				string text = cardStateSnapshot?.DisplayName ?? "";
				DispatchMultiplayer(DanmakuTrigger.MultiplayerRestSite, TimingPhase.RestSite, input, new Dictionary<string, string>
				{
					["optionId"] = input.Fact.OptionId,
					["upgradedCardName"] = text
				}, string.IsNullOrWhiteSpace(text) ? null : new RuleContextBuilder().CardReference(text, cardStateSnapshot?.CardId ?? "").Build());
			}
		}

		private static void DispatchMultiplayer<TFact>(DanmakuTrigger trigger, TimingPhase phase, RuleConsumptionContext<TFact> input, IReadOnlyDictionary<string, string> snapshot, RuleContext? context = null, string variant = "") where TFact : IGameFact
		{
			ConditionResult conditionResult = MultiplayerRuleEvaluators.EvaluateMultiplayerSession(DanmakuMultiplayerState.IsMultiplayerSession);
			RuleEvidence evidence = new RuleEvidence(input.Fact.Header.EventId, conditionResult.ReasonCode, snapshot, phase);
			if (!conditionResult.Matched)
			{
				RuleDiagnostics.Instance.RecordNotMatched(trigger, evidence);
				return;
			}
			DanmakuSignal signal = new DanmakuSignal(trigger, context, variant, DanmakuChannel.Multiplayer, context?.Refs);
			DanmakuHub.Instance?.Dispatch(signal, evidence);
		}
	}
	internal static class NonCombatFactPatches
	{
		private sealed record RewardCandidate(string Id, string Name, string Rarity);

		private sealed record ShopPurchaseAttempt(ShopItemSnapshot Item, PlayerStateSnapshot Before);

		private sealed record RestSelectionAttempt(RestSiteOption Option, PlayerStateSnapshot Before, long RoomSequence);

		[HarmonyPatch(typeof(NCardRewardSelectionScreen), "AfterOverlayOpened")]
		private static class RewardOpenedPatch
		{
			private static void Postfix(NCardRewardSelectionScreen __instance)
			{
				PhaseRouter.Instance?.OnRewardOpened();
				if (PoolManager.IsPhaseActive(TimingPhase.Reward))
				{
					IReadOnlyList<RewardCandidate> source = RewardCandidates(__instance);
					ModRunState.Publish(new RewardOpenedFact(Header(EventSourceKind.RewardOpened, GameFlowState.Reward), source.Select((RewardCandidate c) => c.Id).ToArray(), CapturePlayer(), (from c in source
						group c by c.Id).ToDictionary((IGrouping<string, RewardCandidate> g) => g.Key, (IGrouping<string, RewardCandidate> g) => g.First().Name), source.Select((RewardCandidate c) => c.Rarity).ToArray()));
				}
			}
		}

		[HarmonyPatch(typeof(NCardRewardSelectionScreen), "OptionSelected")]
		private static class RewardSelectedPatch
		{
			private static void Postfix(NCardRewardSelectionScreen __instance, ref Task<int?> __result)
			{
				long roomSequence = ModRunState.RoomSequence;
				__result = AwaitSelection(__result, __instance, roomSequence);
			}

			private static async Task<int?> AwaitSelection(Task<int?> original, NCardRewardSelectionScreen screen, long room)
			{
				int? result = await original;
				if (room != ModRunState.RoomSequence || !result.HasValue)
				{
					return result;
				}
				IReadOnlyList<RewardCandidate> readOnlyList = RewardCandidates(screen);
				if (result.Value >= 0 && result.Value < readOnlyList.Count)
				{
					ModRunState.Publish(new RewardSelectedFact(Header(EventSourceKind.RewardSelected, GameFlowState.Reward), readOnlyList[result.Value].Id, readOnlyList[result.Value].Name));
					return result;
				}
				if (!(typeof(NCardRewardSelectionScreen).GetField("_extraOptions", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(screen) is IReadOnlyList<CardRewardAlternative> readOnlyList2))
				{
					return result;
				}
				int num = result.Value - readOnlyList.Count;
				if (num < 0 || num >= readOnlyList2.Count)
				{
					return result;
				}
				string optionId = readOnlyList2[num].OptionId;
				if (string.Equals(optionId, "Skip", StringComparison.OrdinalIgnoreCase))
				{
					ModRunState.Publish(new RewardSkippedFact(Header(EventSourceKind.RewardSkipped, GameFlowState.Reward)));
					return result;
				}
				if (string.Equals(optionId, "REROLL", StringComparison.OrdinalIgnoreCase))
				{
					IReadOnlyList<RewardCandidate> source = RewardCandidates(screen);
					GameContextStore.Instance?.Reward.RefreshCandidates(source.Select((RewardCandidate c) => c.Id).ToArray(), (from c in source
						group c by c.Id).ToDictionary((IGrouping<string, RewardCandidate> g) => g.Key, (IGrouping<string, RewardCandidate> g) => g.First().Name));
					ModRunState.Publish(new RewardOpenedFact(Header(EventSourceKind.RewardOpened, GameFlowState.Reward), source.Select((RewardCandidate c) => c.Id).ToArray(), CapturePlayer(), (from c in source
						group c by c.Id).ToDictionary((IGrouping<string, RewardCandidate> g) => g.Key, (IGrouping<string, RewardCandidate> g) => g.First().Name), source.Select((RewardCandidate c) => c.Rarity).ToArray()));
				}
				return result;
			}
		}

		[HarmonyPatch(typeof(NCardRewardSelectionScreen), "AfterOverlayClosed")]
		private static class RewardClosedPatch
		{
			private static void Prefix()
			{
				GameContextStore? instance = GameContextStore.Instance;
				if (instance != null && instance.Reward.IsActive)
				{
					ModRunState.Publish(new RewardClosedFact(Header(EventSourceKind.RewardClosed, GameFlowState.Reward), "overlay_closed", CapturePlayer()));
					PhaseRouter.Instance?.OnRewardClosed();
				}
			}
		}

