		[HarmonyPatch(typeof(NEventRoom), "SetupLayout")]
		private static class EventOpenedPatch
		{
			private static void Postfix(NEventRoom __instance, ref Task __result)
			{
				long roomSequence = ModRunState.RoomSequence;
				__result = AwaitSetup(__result, __instance, roomSequence);
			}

			private static async Task AwaitSetup(Task original, NEventRoom node, long room)
			{
				await original;
				if (GameContextStore.Instance?.Event.IsActive ?? false)
				{
					return;
				}
				object? obj = typeof(NEventRoom).GetField("_event", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(node);
				EventModel val = (EventModel)((obj is EventModel) ? obj : null);
				if (val != null)
				{
					MainFile.Log($"[EventPatches] 事件房已打开：{((AbstractModel)val).Id.Entry}（捕获房间序列 {room}，当前 {ModRunState.RoomSequence}）");
					EventOpenedFact eventOpenedFact = new EventOpenedFact(Header(EventSourceKind.EventOpened, GameFlowState.Event), ((AbstractModel)val).Id.Entry, val.CurrentOptions.Select((EventOption o) => o.TextKey).ToArray(), CapturePlayer());
					if (PoolManager.IsPhaseActive(TimingPhase.Event))
					{
						ModRunState.Publish(eventOpenedFact);
					}
					else
					{
						_pendingEventOpened = eventOpenedFact;
					}
				}
			}
		}

		[HarmonyPatch(typeof(EventOption), "Chosen")]
		private static class EventChoicePatch
		{
			private static void Postfix(EventOption __instance, ref Task __result)
			{
