				EventSession eventSession = GameContextStore.Instance?.Event;
				if (eventSession != null && eventSession.IsActive && !option.IsProceed)
				{
					MainFile.Log($"[EventPatches] 事件选项已选择：{eventSession.ModelId}/{option.TextKey}（捕获房间序列 {room}）");
					ModRunState.Publish(new EventChoiceCompletedFact(Header(EventSourceKind.EventChoiceCompleted, GameFlowState.Event), eventSession.ModelId, option.TextKey, CapturePlayer()));
				}
			}
		}

		[HarmonyPatch(typeof(RestSiteSynchronizer), "ChooseLocalOption")]
		private static class RestSiteOpenedPatch
		{
			private static void Prefix(RestSiteSynchronizer __instance)
			{
				EnsureRestSiteOpened(__instance);
			}
		}

		[HarmonyPatch(typeof(RestSiteSynchronizer), "ChooseLocalOption")]
		private static class RestSiteSelectedPatch
		{
			private static void Prefix(RestSiteSynchronizer __instance, int index, out RestSelectionAttempt? __state)
			{
				EnsureRestSiteOpened(__instance);
				IReadOnlyList<RestSiteOption> localOptions = __instance.GetLocalOptions();
				if ((uint)index >= (uint)localOptions.Count)
				{
					__state = null;
					return;
				}
				PlayerStateSnapshot before = GameContextStore.Instance?.RestSite.Before.Copy() ?? CapturePlayer();
				__state = new RestSelectionAttempt(localOptions[index], before, ModRunState.RoomSequence);
			}

			private static void Postfix(ref Task<bool> __result, RestSelectionAttempt? __state)
			{
				if (__state != null)
				{
					__result = AwaitSelection(__result, __state);
				}
			}

			private static async Task<bool> AwaitSelection(Task<bool> original, RestSelectionAttempt attempt)
			{
				bool flag = await original;
				if (attempt.RoomSequence == ModRunState.RoomSequence && (GameContextStore.Instance?.RestSite.IsActive ?? false))
				{
					ModRunState.Publish(new RestSiteOptionCompletedFact(Header(EventSourceKind.RestSiteOptionCompleted, GameFlowState.RestSite), attempt.Option.OptionId, attempt.Before, CapturePlayer(), flag));
				}
				return flag;
			}
		}

		private static EventOpenedFact? _pendingEventOpened;

		public static void FlushPendingEventOpened()
		{
			EventOpenedFact pendingEventOpened = _pendingEventOpened;
			_pendingEventOpened = null;
			if (!(pendingEventOpened == null))
			{
				GameContextStore? instance = GameContextStore.Instance;
				if (instance == null || !instance.Event.IsActive)
				{
					ModRunState.Publish(pendingEventOpened);
				}
			}
		}

		public static void DiscardPendingEventOpened()
		{
			_pendingEventOpened = null;
		}

		private static PlayerStateSnapshot CapturePlayer()
		{
			return PlayerSnapshotFactory.CaptureLocal();
