		private static GameFactHeader Header(EventSourceKind source, GameFlowState fallback)
		{
			return ModRunState.CreateFactHeader(source, PhaseRouter.Instance?.CurrentState ?? fallback, (source == EventSourceKind.RunEnded) ? EmissionScope.Run : EmissionScope.Room, FactBoundary.LocalPlayer);
		}

		private static void EnsureRestSiteOpened(RestSiteSynchronizer synchronizer)
		{
			GameContextStore? instance = GameContextStore.Instance;
			if ((instance == null || !instance.RestSite.IsActive) && PoolManager.IsPhaseActive(TimingPhase.RestSite))
			{
				IReadOnlyList<RestSiteOption> localOptions = synchronizer.GetLocalOptions();
				ModRunState.Publish(new RestSiteOpenedFact(Header(EventSourceKind.RestSiteOpened, GameFlowState.RestSite), localOptions.Select((RestSiteOption option) => option.OptionId).ToArray(), CapturePlayer()));
			}
		}

		private static string CurrentShopVisitKey()
		{
			//IL_00ca: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f5: Unknown result type (might be due to invalid IL or missing references)
			//IL_0128: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				RunState val = RunManager.Instance.DebugOnlyGetState();
				if (val == null)
				{
					return $"run:{ModRunState.RunEpoch}/room:{ModRunState.RoomSequence}";
				}
				MapCoord? currentMapCoord = val.CurrentMapCoord;
				DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(30, 6);
				defaultInterpolatedStringHandler.AppendLiteral("run:");
				defaultInterpolatedStringHandler.AppendFormatted(ModRunState.RunEpoch);
				defaultInterpolatedStringHandler.AppendLiteral("/act:");
				defaultInterpolatedStringHandler.AppendFormatted(val.CurrentActIndex);
				defaultInterpolatedStringHandler.AppendLiteral("/floor:");
				defaultInterpolatedStringHandler.AppendFormatted(val.ActFloor);
				defaultInterpolatedStringHandler.AppendLiteral("/coord:");
				defaultInterpolatedStringHandler.AppendFormatted(currentMapCoord?.col ?? (-1));
				defaultInterpolatedStringHandler.AppendLiteral(",");
				defaultInterpolatedStringHandler.AppendFormatted(currentMapCoord?.row ?? (-1));
				defaultInterpolatedStringHandler.AppendLiteral("/type:");
				MapPoint currentMapPoint = val.CurrentMapPoint;
				defaultInterpolatedStringHandler.AppendFormatted((currentMapPoint != null) ? new MapPointType?(currentMapPoint.PointType) : null);
				return defaultInterpolatedStringHandler.ToStringAndClear();
			}
			catch
			{
				return $"run:{ModRunState.RunEpoch}/room:{ModRunState.RoomSequence}";
			}
		}

		private static IReadOnlyList<RewardCandidate> RewardCandidates(NCardRewardSelectionScreen screen)
