			{
				return Array.Empty<RewardCandidate>();
			}
			return source.Select(delegate(CardCreationResult o)
			{
				//IL_0021: Unknown result type (might be due to invalid IL or missing references)
				//IL_0026: Unknown result type (might be due to invalid IL or missing references)
				string entry = ((AbstractModel)o.Card).Id.Entry;
				string title = o.Card.Title;
				CardRarity rarity = o.Card.Rarity;
				return new RewardCandidate(entry, title, ((object)(CardRarity)(ref rarity)).ToString());
			}).ToArray();
		}

		private static string MerchantItemId(MerchantEntry entry)
		{
			MerchantCardEntry val = (MerchantCardEntry)(object)((entry is MerchantCardEntry) ? entry : null);
			if (val == null)
			{
				MerchantRelicEntry val2 = (MerchantRelicEntry)(object)((entry is MerchantRelicEntry) ? entry : null);
				if (val2 == null)
				{
					MerchantPotionEntry val3 = (MerchantPotionEntry)(object)((entry is MerchantPotionEntry) ? entry : null);
					if (val3 == null)
					{
						if (entry is MerchantCardRemovalEntry)
						{
							return "card_removal";
						}
						return ((object)entry).GetType().Name;
					}
					PotionModel model = val3.Model;
					return ((model != null) ? ((AbstractModel)model).Id.Entry : null) ?? "potion:empty";
				}
				RelicModel model2 = val2.Model;
				return ((model2 != null) ? ((AbstractModel)model2).Id.Entry : null) ?? "relic:empty";
			}
			CardCreationResult creationResult = val.CreationResult;
			return ((creationResult != null) ? ((AbstractModel)creationResult.Card).Id.Entry : null) ?? "card:empty";
		}

		private static string MerchantItemName(MerchantEntry entry)
		{
			MerchantCardEntry val = (MerchantCardEntry)(object)((entry is MerchantCardEntry) ? entry : null);
			if (val == null)
			{
				MerchantRelicEntry val2 = (MerchantRelicEntry)(object)((entry is MerchantRelicEntry) ? entry : null);
				if (val2 == null)
				{
					MerchantPotionEntry val3 = (MerchantPotionEntry)(object)((entry is MerchantPotionEntry) ? entry : null);
					if (val3 == null)
					{
						if (entry is MerchantCardRemovalEntry)
						{
							return "删牌服务";
						}
						return "";
					}
					PotionModel model = val3.Model;
					return ((model != null) ? model.Title.GetFormattedText() : null) ?? "";
				}
				RelicModel model2 = val2.Model;
				return ((model2 != null) ? model2.Title.GetFormattedText() : null) ?? "";
			}
			CardCreationResult creationResult = val.CreationResult;
			return ((creationResult != null) ? creationResult.Card.Title : null) ?? "";
		}

		private static IReadOnlyList<ShopItemSnapshot> ShopItems(NMerchantRoom room)
		{
			NMerchantInventory inventory = room.Inventory;
			MerchantInventory val = ((inventory != null) ? inventory.Inventory : null);
			if (val == null)
			{
				return Array.Empty<ShopItemSnapshot>();
			}
			MerchantEntry[] source = val.AllEntries.ToArray();
			MerchantRelicEntry premiumRelic = val.RelicEntries.LastOrDefault();
			return source.Select((MerchantEntry entry, int index) => new ShopItemSnapshot(MerchantItemId(entry), ((object)entry).GetType().Name, index, entry.Cost, !entry.IsStocked, MerchantItemName(entry), entry == premiumRelic, MerchantItemRarity(entry))).ToArray();
		}

		private static string MerchantItemRarity(MerchantEntry entry)
		{
			//IL_001c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			MerchantCardEntry val = (MerchantCardEntry)(object)((entry is MerchantCardEntry) ? entry : null);
			if (val != null)
			{
				CardCreationResult creationResult = val.CreationResult;
				object obj;
				if (creationResult == null)
				{
					obj = null;
				}
				else
				{
					CardRarity rarity = creationResult.Card.Rarity;
					obj = ((object)(CardRarity)(ref rarity)).ToString();
				}
				if (obj == null)
				{
					obj = "";
				}
				return (string)obj;
			}
			return "";
		}

		private static ShopPurchaseAttempt? CapturePurchaseAttempt(MerchantEntry entry)
		{
			MerchantEntry entry2 = entry;
			ShopSession shopSession = GameContextStore.Instance?.Shop;
			if (shopSession == null || !shopSession.IsActive)
			{
				return null;
			}
			string itemId = MerchantItemId(entry2);
			string kind = ((object)entry2).GetType().Name;
			NMerchantRoom instance = NMerchantRoom.Instance;
			object obj;
			if (instance == null)
			{
				obj = null;
			}
			else
			{
				NMerchantInventory inventory = instance.Inventory;
				obj = ((inventory != null) ? inventory.Inventory : null);
			}
			MerchantInventory val = (MerchantInventory)obj;
			MerchantEntry[] array = ((val != null) ? val.AllEntries.ToArray() : null) ?? Array.Empty<MerchantEntry>();
			int slotIndex = Array.FindIndex(array, (MerchantEntry candidate) => candidate == entry2);
			ShopItemSnapshot shopItemSnapshot = shopSession.Items.FirstOrDefault((ShopItemSnapshot candidate) => candidate.SlotIndex == slotIndex && candidate.ItemId == itemId && candidate.Kind == kind && !candidate.Purchased);
			if ((object)shopItemSnapshot == null)
			{
				shopItemSnapshot = shopSession.Items.FirstOrDefault((ShopItemSnapshot candidate) => candidate.ItemId == itemId && candidate.Kind == kind && !candidate.Purchased);
			}
			if (shopItemSnapshot == null)
			{
				MerchantEntry val2 = (MerchantEntry)(object)((val != null) ? val.RelicEntries.LastOrDefault() : null);
				shopItemSnapshot = new ShopItemSnapshot(itemId, kind, slotIndex, entry2.Cost, Purchased: false, MerchantItemName(entry2), entry2 == val2, MerchantItemRarity(entry2));
			}
			return new ShopPurchaseAttempt(shopItemSnapshot, CapturePlayer());
		}

		private static Task<bool> WrapPurchase(Task<bool> original, ShopPurchaseAttempt attempt, long room, bool isCardRemoval)
		{
			return AwaitPurchase(original, attempt, room, isCardRemoval);
		}

		private static async Task<bool> AwaitPurchase(Task<bool> original, ShopPurchaseAttempt attempt, long room, bool isCardRemoval)
		{
			bool flag = await original;
			if (flag && room == ModRunState.RoomSequence)
			{
				GameContextStore? instance = GameContextStore.Instance;
				if (instance != null && instance.Shop.IsActive)
				{
					ShopItemSnapshot item = attempt.Item;
					ModRunState.Publish(new ShopPurchasedFact(Header(EventSourceKind.ShopPurchased, GameFlowState.Shop), item with
					{
						Purchased = true
					}));
					if (isCardRemoval)
					{
						PlayerStateSnapshot playerStateSnapshot = CapturePlayer();
						CardStateSnapshot cardStateSnapshot = RulePlayerDiff.Between(new RulePlayerSnapshot(attempt.Before, attempt.Before.StableCardStates), new RulePlayerSnapshot(playerStateSnapshot, playerStateSnapshot.StableCardStates)).RemovedCardStates.FirstOrDefault();
						ModRunState.Publish(new ShopCardRemovalUsedFact(Header(EventSourceKind.ShopPurchased, GameFlowState.Shop), cardStateSnapshot?.CardId ?? "", cardStateSnapshot?.DisplayName ?? ""));
					}
					return flag;
				}
			}
			return flag;
		}
	}
	internal static class NonCombatRuleConsumers
	{
		public static void Register(RuleConsumerGroup group, GameFactBus bus)
		{
			group.Add(new RuleFactConsumer<RoomLeavingFact>(bus, DanmakuTrigger.MissedKeyCard, TimingPhase.Shop, OnShopLeaving, requireLocalPlayer: true, (RoomLeavingFact _) => GameContextStore.Instance?.Shop.CloseKind ?? SessionCloseKind.Aborted));
			group.Add(new RuleFactConsumer<ShopCardRemovalUsedFact>(bus, DanmakuTrigger.ShopCardRemoval, TimingPhase.Shop, OnCardRemoval, requireLocalPlayer: true));
			group.Add(new RuleFactConsumer<ShopOpenedFact>(bus, DanmakuTrigger.ShopUmbrella, TimingPhase.Shop, OnShopUmbrella, requireLocalPlayer: true));
			group.Add(new RuleFactConsumer<EventOpenedFact>(bus, DanmakuTrigger.ArchitectWithPotion, TimingPhase.Event, OnEventOpened, requireLocalPlayer: true));
			group.Add(new RuleFactConsumer<EventChoiceCompletedFact>(bus, DanmakuTrigger.BridgeEvent, TimingPhase.Event, OnEventChoice, requireLocalPlayer: true));
			group.Add(new RuleFactConsumer<CardEnchantmentChangedFact>(bus, DanmakuTrigger.CloneEnchantment, TimingPhase.Run, OnEnchantmentChanged, requireLocalPlayer: true));
			group.Add(new RuleFactConsumer<RestSiteOptionCompletedFact>(bus, DanmakuTrigger.CloneEnchantment, TimingPhase.RestSite, OnCloneRestSite, requireLocalPlayer: true));
		}

		private static void OnShopLeaving(RuleConsumptionContext<RoomLeavingFact> input)
		{
			ShopSession shop = input.Contexts.Shop;
			CardRuleEvaluation cardRuleEvaluation = AdditionalShopRuleEvaluators.EvaluateMissedDesirableCard(new ShopMissedCardInput(shop.Items, shop.Purchases, input.Fact.After.Gold, shop.Before.CharacterId));
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["remainingGold"] = input.Fact.After.Gold.ToString(),
				["cardId"] = cardRuleEvaluation.CardId,
				["purchaseCount"] = shop.Purchases.Count.ToString(),
				["characterId"] = shop.Before.CharacterId
			};
			IReadOnlyDictionary<string, string> context = (cardRuleEvaluation.Result.Matched ? new RuleContextBuilder().Card(cardRuleEvaluation.CardName).Character(shop.Before.CharacterId).Build() : null);
			Dispatch(DanmakuTrigger.MissedKeyCard, input.Fact.Header.EventId, TimingPhase.Shop, cardRuleEvaluation.Result, snapshot, context);
		}

		private static void OnCardRemoval(RuleConsumptionContext<ShopCardRemovalUsedFact> input)
		{
			CardRuleEvaluation cardRuleEvaluation = AdditionalShopRuleEvaluators.EvaluateCardRemoval(input.Fact.RemovedCardId, input.Fact.RemovedCardName);
			Dispatch(DanmakuTrigger.ShopCardRemoval, input.Fact.Header.EventId, TimingPhase.Shop, cardRuleEvaluation.Result, new Dictionary<string, string> { ["cardId"] = cardRuleEvaluation.CardId }, new RuleContextBuilder().Card(cardRuleEvaluation.CardName).Build());
		}

		private static void OnShopUmbrella(RuleConsumptionContext<ShopOpenedFact> input)
		{
			if (!input.Fact.IsFirstOpenForVisit)
			{
				RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.ShopUmbrella, new RuleEvidence(input.Fact.Header.EventId, "shop_inventory_already_emitted", new Dictionary<string, string> { ["visitKey"] = input.Fact.VisitKey }, TimingPhase.Shop));
				return;
			}
			IReadOnlyList<ShopItemSnapshot> readOnlyList = ShopRuleEvaluators.SelectShopUmbrellaItems(input.Fact.Items);
			Dictionary<string, string> dictionary = new Dictionary<string, string> { ["itemCount"] = readOnlyList.Count.ToString() };
			foreach (ShopItemSnapshot item in readOnlyList)
			{
				RuleContext context = (string.IsNullOrWhiteSpace(item.DisplayName) ? null : new RuleContextBuilder().Text("item", item.DisplayName).Build());
				Dictionary<string, string> snapshot = new Dictionary<string, string>(dictionary)
				{
					["itemId"] = item.ItemId,
					["itemKind"] = item.Kind,
					["itemName"] = item.DisplayName,
					["slotIndex"] = item.SlotIndex.ToString()
				};
				string variant = ShopRuleEvaluators.ShopUmbrellaVariant(item);
				RuleEvidence evidence = new RuleEvidence(input.Fact.Header.EventId, "shop_umbrella_item", snapshot, TimingPhase.Shop, variant);
				DanmakuSignal danmakuSignal = new DanmakuSignal(DanmakuTrigger.ShopUmbrella, context, variant);
				danmakuSignal.FixedCount = 1;
				danmakuSignal.ForceTop = true;
				DanmakuSignal signal = danmakuSignal;
				DanmakuHub.Instance?.Dispatch(signal, evidence);
			}
		}

		private static void OnEventOpened(RuleConsumptionContext<EventOpenedFact> input)
		{
			ConditionResult result = EventRuleEvaluators.EvaluateArchitect(input.Fact.ModelId, input.Fact.Before.PotionIds);
			Dispatch(DanmakuTrigger.ArchitectWithPotion, input.Fact.Header.EventId, TimingPhase.Event, result, new Dictionary<string, string>
			{
				["eventId"] = input.Fact.ModelId,
				["potionCount"] = input.Fact.Before.PotionIds.Count.ToString()
			});
		}

		private static void OnEventChoice(RuleConsumptionContext<EventChoiceCompletedFact> input)
		{
			EventSession @event = input.Contexts.Event;
			PlayerStateSnapshot? obj = @event.LastChoiceAfter ?? @event.Before;
			RulePlayerDiff rulePlayerDiff = RulePlayerDiff.Between(new RulePlayerSnapshot(obj, obj.StableCardStates), new RulePlayerSnapshot(input.Fact.After, input.Fact.After.StableCardStates));
			@event.RecordChoiceAfter(input.Fact.After);
			BridgeRuleEvaluation bridgeRuleEvaluation = EventRuleEvaluators.EvaluateBridge(input.Fact.EventId, rulePlayerDiff.RemovedCardStates, @event.Before.CharacterId);
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["eventId"] = input.Fact.EventId,
				["choiceId"] = input.Fact.ChoiceId,
				["removedCardCount"] = rulePlayerDiff.RemovedCardStates.Count.ToString(),
				["cardId"] = bridgeRuleEvaluation.Card?.CardId ?? "",
				["cardType"] = bridgeRuleEvaluation.Card?.CardType ?? "",
				["rarity"] = bridgeRuleEvaluation.Card?.Rarity ?? ""
			};
			Dispatch(DanmakuTrigger.BridgeEvent, input.Fact.Header.EventId, TimingPhase.Event, bridgeRuleEvaluation.Result, snapshot, null, bridgeRuleEvaluation.Variant);
		}

		private static void OnEnchantmentChanged(RuleConsumptionContext<CardEnchantmentChangedFact> input)
		{
			CloneEnchantmentEvaluation cloneEnchantmentEvaluation = CloneEnchantmentRuleEvaluator.EvaluateFirstAcquisition(input.Contexts.Run.CloneEnchantmentSeen, input.Fact.PreviousEnchantmentId, input.Fact.CurrentEnchantmentId);
			input.Contexts.Run.CloneEnchantmentSeen = cloneEnchantmentEvaluation.SeenAfter;
			Dispatch(DanmakuTrigger.CloneEnchantment, input.Fact.Header.EventId, TimingPhase.Run, cloneEnchantmentEvaluation.Result, new Dictionary<string, string>
			{
				["cardId"] = input.Fact.CardId,
				["previousEnchantmentId"] = input.Fact.PreviousEnchantmentId,
				["currentEnchantmentId"] = input.Fact.CurrentEnchantmentId,
				["sourceType"] = input.Fact.SourceTypeName,
				["seenAfter"] = cloneEnchantmentEvaluation.SeenAfter.ToString()
			});
		}

		private static void OnCloneRestSite(RuleConsumptionContext<RestSiteOptionCompletedFact> input)
		{
			if (input.Fact.Succeeded)
			{
				ConditionResult result = CloneEnchantmentRuleEvaluator.EvaluateRestSiteUse(input.Fact.OptionId);
				Dispatch(DanmakuTrigger.CloneEnchantment, input.Fact.Header.EventId, TimingPhase.RestSite, result, new Dictionary<string, string> { ["optionId"] = input.Fact.OptionId });
			}
		}

		private static void Dispatch(DanmakuTrigger trigger, EventId eventId, TimingPhase phase, ConditionResult result, IReadOnlyDictionary<string, string> snapshot, IReadOnlyDictionary<string, string>? context = null, string variant = "")
		{
			(DanmakuSignal, RuleEvidence) tuple = RuleDispatchFactory.Create(trigger, eventId, phase, result, snapshot, context, variant);
			if (result.Matched)
			{
				DanmakuHub.Instance?.Dispatch(tuple.Item1, tuple.Item2);
			}
			else
			{
				RuleDiagnostics.Instance.RecordNotMatched(trigger, tuple.Item2);
			}
		}
	}
	internal static class RewardRuleConsumers
	{
		private static readonly DanmakuTrigger[] ClosedRules = new DanmakuTrigger[5]
		{
			DanmakuTrigger.DraftFutureCard,
			DanmakuTrigger.MissedKeyCard,
			DanmakuTrigger.RejectFutureCard,
			DanmakuTrigger.FullApotheosis,
			DanmakuTrigger.SkipCardReward
		};

		public static void Register(RuleConsumerGroup group, GameFactBus bus)
		{
			DanmakuTrigger[] closedRules = ClosedRules;
			foreach (DanmakuTrigger trigger in closedRules)
			{
				group.Add(new RuleFactConsumer<RewardClosedFact>(bus, trigger, TimingPhase.Reward, delegate(RuleConsumptionContext<RewardClosedFact> input)
				{
					OnRewardClosed(input, trigger);
				}, requireLocalPlayer: true, (RewardClosedFact _) => GameContextStore.Instance?.Reward.CloseKind ?? SessionCloseKind.Aborted));
			}
			group.Add(new RuleFactConsumer<RewardOpenedFact>(bus, DanmakuTrigger.HardChoice, TimingPhase.Reward, OnRewardOpened, requireLocalPlayer: true));
			group.Add(new RuleFactConsumer<RewardOpenedFact>(bus, DanmakuTrigger.CardThreeVisits, TimingPhase.Reward, OnRewardAppearances, requireLocalPlayer: true));
			group.Add(new RuleFactConsumer<ShopOpenedFact>(bus, DanmakuTrigger.CardThreeVisits, TimingPhase.Shop, OnShopAppearances, requireLocalPlayer: true));
		}

		private static void OnRewardClosed(RuleConsumptionContext<RewardClosedFact> input, DanmakuTrigger trigger)
		{
			RewardSession reward = input.Contexts.Reward;
			RewardRuleInput rewardRuleInput = new RewardRuleInput(reward.CandidateIds, reward.CandidateNames, reward.SelectedId, reward.SelectedName, reward.Skipped, reward.Before, input.Fact.After);
			CardRuleEvaluation result;
			ConditionResult result2;
			switch (trigger)
			{
			case DanmakuTrigger.DraftFutureCard:
				result = RewardRuleEvaluators.EvaluateDraftFutureCard(rewardRuleInput);
				result2 = result.Result;
				break;
			case DanmakuTrigger.MissedKeyCard:
				result = RewardRuleEvaluators.EvaluateMissedKeyCard(rewardRuleInput);
				result2 = result.Result;
				break;
			case DanmakuTrigger.RejectFutureCard:
				result = RewardRuleEvaluators.EvaluateRejectFutureCard(rewardRuleInput);
				result2 = result.Result;
				break;
			case DanmakuTrigger.FullApotheosis:
				result = RewardRuleEvaluators.EvaluateFullApotheosis(rewardRuleInput);
				result2 = result.Result;
				break;
			case DanmakuTrigger.SkipCardReward:
				OnSkipCardReward(rewardRuleInput, input.Contexts.Run, input.Fact.Header.EventId);
				return;
			default:
				throw new ArgumentOutOfRangeException("trigger", trigger, "未知奖励规则");
			}
			Dictionary<string, string> dictionary = BaseSnapshot(rewardRuleInput);
			dictionary["cardId"] = result.CardId;
			Dispatch(trigger, input.Fact.Header.EventId, result2, dictionary, BuildContext(trigger, rewardRuleInput, result));
		}

		private static void OnSkipCardReward(RewardRuleInput ruleInput, RunContext run, EventId eventId)
		{
			int skipRewardProbability = run.SkipRewardProbability;
			(bool Matched, string Reason, int NextProbability) tuple = RewardRuleEvaluators.SkipRewardRuleEvaluators.Evaluate(ruleInput.Skipped, skipRewardProbability, Random.Shared.NextDouble());
			var (flag, reasonCode, _) = tuple;
			int num = (run.SkipRewardProbability = tuple.NextProbability);
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["skipped"] = ruleInput.Skipped.ToString(),
				["probabilityBefore"] = skipRewardProbability.ToString(),
				["probabilityAfter"] = num.ToString(),
				["candidateCount"] = ruleInput.CandidateIds.Count.ToString(),
				["characterId"] = ruleInput.Before.CharacterId,
				["actIndex"] = ruleInput.Before.CurrentActIndex.ToString()
			};
			RuleEvidence evidence = new RuleEvidence(eventId, reasonCode, snapshot, TimingPhase.Reward);
			if (flag)
			{
				DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(DanmakuTrigger.SkipCardReward), evidence);
			}
			else
			{
				RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.SkipCardReward, evidence);
			}
		}

		private static void OnRewardOpened(RuleConsumptionContext<RewardOpenedFact> input)
		{
			RuleConsumptionContext<RewardOpenedFact> input2 = input;
			ConditionResult result = RewardRuleEvaluators.EvaluateHardChoice(input2.Fact.CandidateIds, input2.Fact.Before.CharacterId);
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["candidateCount"] = input2.Fact.CandidateIds.Count.ToString(),
				["desirableCount"] = input2.Fact.CandidateIds.Count((string cardId) => RewardRuleEvaluators.IsDesirable(cardId, input2.Fact.Before.CharacterId)).ToString(),
				["characterId"] = input2.Fact.Before.CharacterId
			};
			Dispatch(DanmakuTrigger.HardChoice, input2.Fact.Header.EventId, result, snapshot);
		}

		private static void OnRewardAppearances(RuleConsumptionContext<RewardOpenedFact> input)
		{
			IReadOnlyDictionary<string, string> names = input.Fact.CandidateNames ?? new Dictionary<string, string>();
			IReadOnlyList<string> rarities = input.Fact.CandidateRarities;
			RecordAppearances(input.Fact.Header.EventId, input.Contexts.Run, input.Fact.CandidateIds.Select((string cardId, int index) => (cardId: cardId, names.GetValueOrDefault(cardId, cardId), (rarities != null && index < rarities.Count) ? rarities[index] : "")), input.Fact.Before.DeckCardIds, TimingPhase.Reward);
		}

		private static void OnShopAppearances(RuleConsumptionContext<ShopOpenedFact> input)
		{
			string text = (string.IsNullOrWhiteSpace(input.Fact.VisitKey) ? $"run:{input.Fact.Header.EventId.RunEpoch}/room:{input.Fact.Header.RoomSequence}" : input.Fact.VisitKey);
			if (!input.Contexts.Run.ObservedShopVisitKeys.Add(text))
			{
				RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.CardThreeVisits, new RuleEvidence(input.Fact.Header.EventId, "shop_inventory_already_counted", new Dictionary<string, string> { ["visitKey"] = text }, TimingPhase.Shop));
				return;
			}
			RecordAppearances(input.Fact.Header.EventId, input.Contexts.Run, from item in input.Fact.Items
				where item.Kind == "MerchantCardEntry" && !item.Purchased
				select (ItemId: item.ItemId, DisplayName: item.DisplayName, Rarity: item.Rarity), input.Fact.Before.DeckCardIds, TimingPhase.Shop);
		}

		private static void RecordAppearances(EventId eventId, RunContext run, IEnumerable<(string CardId, string CardName, string Rarity)> appearances, IReadOnlyList<string> ownedCardIds, TimingPhase phase)
		{
			IReadOnlySet<string> ownedCardIds2 = new HashSet<string>(ownedCardIds, StringComparer.Ordinal);
			IReadOnlyList<CardAppearanceThreshold> readOnlyList = CardAppearanceRuleEvaluator.Record(run.CardAppearanceCount, appearances, ownedCardIds2);
			if (readOnlyList.Count == 0)
			{
				RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.CardThreeVisits, new RuleEvidence(eventId, "card_appearance_threshold_not_crossed", new Dictionary<string, string>(), phase));
				return;
			}
			foreach (CardAppearanceThreshold item in readOnlyList)
			{
				Dictionary<string, string> snapshot = new Dictionary<string, string>
				{
					["cardId"] = item.CardId,
					["previousCount"] = item.PreviousCount.ToString(),
					["currentCount"] = item.CurrentCount.ToString()
				};
				(DanmakuSignal, RuleEvidence) tuple = RuleDispatchFactory.Create(DanmakuTrigger.CardThreeVisits, eventId, phase, ConditionResult.Match("card_appearance_threshold_crossed"), snapshot, new RuleContextBuilder().Card(item.CardName).Build(), item.CardId);
				DanmakuHub.Instance?.Dispatch(tuple.Item1, tuple.Item2);
			}
		}

		private static Dictionary<string, string> BaseSnapshot(RewardRuleInput input)
		{
			return new Dictionary<string, string>
			{
				["candidateCount"] = input.CandidateIds.Count.ToString(),
				["selectedId"] = input.SelectedId ?? "",
				["skipped"] = input.Skipped.ToString(),
				["characterId"] = input.Before.CharacterId,
				["actIndex"] = input.Before.CurrentActIndex.ToString()
			};
		}

		private static IReadOnlyDictionary<string, string>? BuildContext(DanmakuTrigger trigger, RewardRuleInput input, CardRuleEvaluation result)
		{
			RuleContextBuilder ruleContextBuilder = new RuleContextBuilder();
			if (!string.IsNullOrWhiteSpace(result.CardName))
			{
				ruleContextBuilder.Card(result.CardName);
			}
			if (trigger == DanmakuTrigger.MissedKeyCard)
			{
				ruleContextBuilder.Character(input.Before.CharacterId);
			}
			IReadOnlyDictionary<string, string> readOnlyDictionary = ruleContextBuilder.Build();
			if (readOnlyDictionary.Count != 0)
			{
				return readOnlyDictionary;
			}
			return null;
		}

		private static void Dispatch(DanmakuTrigger trigger, EventId eventId, ConditionResult result, Dictionary<string, string> snapshot, IReadOnlyDictionary<string, string>? context = null, TimingPhase phase = TimingPhase.Reward, string variant = "")
		{
			RuleEvidence evidence = new RuleEvidence(eventId, result.ReasonCode, snapshot, phase, variant);
			if (result.Matched)
			{
				DanmakuHub.Instance?.Dispatch(new DanmakuSignal(trigger, context, variant), evidence);
			}
			else
			{
				RuleDiagnostics.Instance.RecordNotMatched(trigger, evidence);
			}
		}
	}
	public static class RuleConsumerBootstrap
	{
		private static RuleConsumerGroup? _group;

		public static void Start(GameFactBus bus)
		{
			Shutdown();
			_group = new RuleConsumerGroup();
			RewardRuleConsumers.Register(_group, bus);
			NonCombatRuleConsumers.Register(_group, bus);
			MultiplayerRuleConsumers.Register(_group, bus);
			_group.Add(bus.Subscribe<RunStartedFact>(delegate
			{
				DanmakuNetworkForwarder instance = DanmakuNetworkForwarder.Instance;
				RunManager instance2 = RunManager.Instance;
				instance.EnsureAttached((instance2 != null) ? instance2.NetService : null);
			}));
			_group.Add(bus.Subscribe<RunEndedFact>(delegate
			{
				DanmakuNetworkForwarder.Instance.Shutdown();
				DanmakuMultiplayerState.ResetPeers();
			}));
			_group.Add(new RuleFactConsumer<ShopPurchasedFact>(bus, DanmakuTrigger.BuyPremiumRelic, TimingPhase.Shop, OnShopPurchased, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<DeckChangedFact>(bus, DanmakuTrigger.BigDeck, TimingPhase.Run, OnDeckChanged, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<DeckChangedFact>(bus, DanmakuTrigger.SmallDeck, TimingPhase.Run, OnSmallDeckChanged, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<RestSiteOptionCompletedFact>(bus, DanmakuTrigger.RestSiteSleep, TimingPhase.RestSite, delegate(RuleConsumptionContext<RestSiteOptionCompletedFact> input)
			{
				OnRestSiteOption(input, DanmakuTrigger.RestSiteSleep);
			}, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<RestSiteOptionCompletedFact>(bus, DanmakuTrigger.FullHpRestSiteSleep, TimingPhase.RestSite, delegate(RuleConsumptionContext<RestSiteOptionCompletedFact> input)
			{
				OnRestSiteOption(input, DanmakuTrigger.FullHpRestSiteSleep);
			}, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<RestSiteOptionCompletedFact>(bus, DanmakuTrigger.LowHpSkippedRest, TimingPhase.RestSite, delegate(RuleConsumptionContext<RestSiteOptionCompletedFact> input)
			{
				OnRestSiteOption(input, DanmakuTrigger.LowHpSkippedRest);
			}, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<CombatStartedFact>(bus, DanmakuTrigger.EliteStreak, TimingPhase.CombatStart, OnCombatStarted));
			_group.Add(new RuleFactConsumer<CombatEndedFact>(bus, DanmakuTrigger.NoDamageStreak, TimingPhase.Combat, OnCombatEnded));
			_group.Add(new RuleFactConsumer<RestSiteOptionCompletedFact>(bus, DanmakuTrigger.UpgradeStreak, TimingPhase.RestSite, OnUpgradeStreak, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<RestSiteOptionCompletedFact>(bus, DanmakuTrigger.FullApotheosis, TimingPhase.RestSite, OnRestSiteFullApotheosis, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<RunLoadedFact>(bus, DanmakuTrigger.SaveLoad, TimingPhase.Run, OnRunLoaded));
			_group.Add(new RuleFactConsumer<CollectibleObtainedFact>(bus, DanmakuTrigger.CollectiblePair, TimingPhase.Run, OnCollectibleObtained, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<CollectibleObtainedFact>(bus, DanmakuTrigger.GotOverpoweredCard, TimingPhase.Run, OnOverpoweredRelicObtained, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<CollectibleObtainedFact>(bus, DanmakuTrigger.FullApotheosis, TimingPhase.Run, OnApotheosisObtained, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<CollectibleObtainedFact>(bus, DanmakuTrigger.DuplicateCard, TimingPhase.Run, delegate(RuleConsumptionContext<CollectibleObtainedFact> input)
			{
				OnCardObtained(input, DanmakuTrigger.DuplicateCard);
			}, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<CollectibleObtainedFact>(bus, DanmakuTrigger.GotKeyCard, TimingPhase.Run, delegate(RuleConsumptionContext<CollectibleObtainedFact> input)
			{
				OnCardObtained(input, DanmakuTrigger.GotKeyCard);
			}, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<CollectibleObtainedFact>(bus, DanmakuTrigger.GotOverpoweredCard, TimingPhase.Run, delegate(RuleConsumptionContext<CollectibleObtainedFact> input)
			{
				OnCardObtained(input, DanmakuTrigger.GotOverpoweredCard);
			}, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<CollectibleObtainedFact>(bus, DanmakuTrigger.AttackDefenseCard, TimingPhase.Run, delegate(RuleConsumptionContext<CollectibleObtainedFact> input)
			{
				OnCardObtained(input, DanmakuTrigger.AttackDefenseCard);
			}, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<CardEnchantmentChangedFact>(bus, DanmakuTrigger.CollectiblePair, TimingPhase.Run, OnAttackEnchanted, requireLocalPlayer: true));
			_group.Add(new RuleFactConsumer<RoomLeavingFact>(bus, DanmakuTrigger.CollectiblePair, TimingPhase.Run, OnPairNodeEnded));
		}

		public static void Shutdown()
		{
			_group?.Dispose();
			_group = null;
		}

		private static void OnCollectibleObtained(RuleConsumptionContext<CollectibleObtainedFact> input)
		{
			foreach (var (pair, result) in input.Contexts.Run.PairCollections.Obtain(input.Fact.Item))
			{
				DispatchPairResult(input.Fact.Header.EventId, pair, result);
			}
		}

		private static void OnCardObtained(RuleConsumptionContext<CollectibleObtainedFact> input, DanmakuTrigger trigger)
		{
			if (input.Fact.Kind == CollectibleKind.Card)
			{
				string cardId = input.Fact.ModelId;
				string characterId = input.Fact.CharacterId;
				string officialChineseName = input.Fact.OfficialChineseName;
				ConditionResult conditionResult = trigger switch
				{
					DanmakuTrigger.DuplicateCard => RewardRuleEvaluators.CardObtainedRuleEvaluators.EvaluateDuplicate(PlayerSnapshotFactory.CaptureDeckCardIds().Count((string id) => id == cardId)), 
					DanmakuTrigger.GotKeyCard => RewardRuleEvaluators.CardObtainedRuleEvaluators.EvaluateKeyCard(cardId, characterId), 
					DanmakuTrigger.GotOverpoweredCard => RewardRuleEvaluators.CardObtainedRuleEvaluators.EvaluateOverpoweredCard(cardId), 
					DanmakuTrigger.AttackDefenseCard => RewardRuleEvaluators.CardObtainedRuleEvaluators.EvaluateAttackDefenseCard(cardId), 
					_ => ConditionResult.Miss("not_card_obtained_rule"), 
				};
				Dictionary<string, string> snapshot = new Dictionary<string, string>
				{
					["cardId"] = cardId,
					["cardName"] = officialChineseName,
					["characterId"] = characterId
				};
				RuleEvidence evidence = new RuleEvidence(input.Fact.Header.EventId, conditionResult.ReasonCode, snapshot, TimingPhase.Run);
				if (conditionResult.Matched)
				{
					DanmakuHub.Instance?.Dispatch(new DanmakuSignal(trigger, new RuleContextBuilder().Card(officialChineseName).Build()), evidence);
				}
				else
				{
					RuleDiagnostics.Instance.RecordNotMatched(trigger, evidence);
				}
			}
		}

		private static void OnApotheosisObtained(RuleConsumptionContext<CollectibleObtainedFact> input)
		{
			if (input.Fact.Kind == CollectibleKind.Card && !(input.Fact.ModelId != "APOTHEOSIS"))
			{
				Dictionary<string, string> snapshot = new Dictionary<string, string>
				{
					["cardId"] = input.Fact.ModelId,
					["cardName"] = input.Fact.OfficialChineseName
				};
				DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(DanmakuTrigger.FullApotheosis), new RuleEvidence(input.Fact.Header.EventId, "apotheosis_selected", snapshot, TimingPhase.Run));
			}
		}

		private static void OnOverpoweredRelicObtained(RuleConsumptionContext<CollectibleObtainedFact> input)
		{
			if (input.Fact.Kind == CollectibleKind.Relic)
			{
				ConditionResult conditionResult = RuleBusinessEvaluators.EvaluateOverpoweredRelic(input.Fact.ModelId);
				if (conditionResult.Matched)
				{
					RuleContext context = new RuleContextBuilder().Text("card", CollectibleAlias.DisplayName(input.Fact.OfficialChineseName)).Build();
					Dictionary<string, string> snapshot = new Dictionary<string, string>
					{
						["relicId"] = input.Fact.ModelId,
						["relicName"] = input.Fact.OfficialChineseName
					};
					DanmakuHub.Instance?.Dispatch(new DanmakuSignal(DanmakuTrigger.GotOverpoweredCard, context), new RuleEvidence(input.Fact.Header.EventId, conditionResult.ReasonCode, snapshot, TimingPhase.Run));
				}
			}
		}

		private static void OnAttackEnchanted(RuleConsumptionContext<CardEnchantmentChangedFact> input)
		{
			if (string.IsNullOrWhiteSpace(input.Fact.CurrentEnchantmentId))
			{
				return;
			}
			CollectibleRef card = new CollectibleRef(CollectibleKind.Card, input.Fact.CardId, input.Fact.CardName, input.Fact.SourceTypeName);
			foreach (var (pair, result) in input.Contexts.Run.PairCollections.ObserveEnchantedAttack(card))
			{
				DispatchPairResult(input.Fact.Header.EventId, pair, result);
			}
		}

		private static void OnPairNodeEnded(RuleConsumptionContext<RoomLeavingFact> input)
		{
			foreach (var (pair, result) in input.Contexts.Run.PairCollections.EndNode(input.Fact.NodeSequence))
			{
				DispatchPairResult(input.Fact.Header.EventId, pair, result);
			}
		}

		private static void DispatchPairResult(EventId eventId, CollectiblePairDefinition pair, PairCollectionResult result)
		{
			string text = result.Decision switch
			{
				PairCollectionDecision.Waiting => "waiting", 
				PairCollectionDecision.Completed => "completed", 
				PairCollectionDecision.TimedOut => "timeout", 
				_ => throw new ArgumentOutOfRangeException("result", result.Decision, "不应派发空成对判定"), 
			};
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["pairId"] = pair.PairId,
				["decision"] = result.Decision.ToString(),
				["startedAtNode"] = result.Progress?.StartedAtNode.ToString() ?? "",
				["currentNode"] = GameContextStore.Instance?.Run.PairCollections.CurrentNode.ToString() ?? ""
			};
			CollectibleRef? missingItem = result.MissingItem;
			object obj;
			if (missingItem.HasValue)
			{
				CollectibleRef valueOrDefault = missingItem.GetValueOrDefault();
				obj = new RuleContextBuilder().Text("item", valueOrDefault.OfficialChineseName).Build();
			}
			else
			{
				obj = null;
			}
			IReadOnlyDictionary<string, string> context = (IReadOnlyDictionary<string, string>)obj;
			string variant = text + ":" + pair.PairId;
			RuleEvidence evidence = new RuleEvidence(eventId, "collectible_pair_" + text, snapshot, TimingPhase.Run, variant);
			DanmakuHub.Instance?.Dispatch(new DanmakuSignal(DanmakuTrigger.CollectiblePair, context, text), evidence);
		}

		private static void OnRestSiteOption(RuleConsumptionContext<RestSiteOptionCompletedFact> input, DanmakuTrigger trigger)
		{
			if (input.Fact.Succeeded)
			{
				RestSiteRuleInput input2 = new RestSiteRuleInput(input.Fact.OptionId, input.Fact.Before.CurrentHp, input.Fact.Before.MaxHp, input.Fact.Before.StableRelicIds.Contains("MINIATURE_TENT"));
				ConditionResult conditionResult = trigger switch
				{
					DanmakuTrigger.RestSiteSleep => RestSiteRuleEvaluators.EvaluateSleep(input2), 
					DanmakuTrigger.FullHpRestSiteSleep => RestSiteRuleEvaluators.EvaluateFullHpSleep(input2), 
					DanmakuTrigger.LowHpSkippedRest => RestSiteRuleEvaluators.EvaluateLowHpSkippedRest(input2), 
					_ => throw new ArgumentOutOfRangeException("trigger", trigger, "未知火堆规则"), 
				};
				Dictionary<string, string> snapshot = new Dictionary<string, string>
				{
					["optionId"] = input.Fact.OptionId,
					["hpBefore"] = input.Fact.Before.CurrentHp.ToString(),
					["maxHpBefore"] = input.Fact.Before.MaxHp.ToString(),
					["hpAfter"] = input.Fact.After.CurrentHp.ToString(),
					["hasMiniatureTent"] = input2.HasMiniatureTent.ToString()
				};
				RuleEvidence evidence = new RuleEvidence(input.Fact.Header.EventId, conditionResult.ReasonCode, snapshot, TimingPhase.RestSite);
				if (!conditionResult.Matched)
				{
					RuleDiagnostics.Instance.RecordNotMatched(trigger, evidence);
					return;
				}
				IReadOnlyDictionary<string, string> context = ((trigger == DanmakuTrigger.LowHpSkippedRest) ? new RuleContextBuilder().Number("hp", input.Fact.Before.CurrentHp).Build() : null);
				DanmakuHub.Instance?.Dispatch(new DanmakuSignal(trigger, context), evidence);
			}
		}

		private static void OnDeckChanged(RuleConsumptionContext<DeckChangedFact> input)
		{
			int addedCount = ((input.Fact.ChangeKind == "added") ? 1 : 0);
			int count = input.Fact.DeckCardIds.Count;
			(BigDeckGateState, bool) tuple = new BigDeckGateState(ModRunState.BigDeckCountdown).RecordAddedCards(addedCount, count);
			ModRunState.BigDeckCountdown = tuple.Item1.Countdown;
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["addedCards"] = addedCount.ToString(),
				["deckCount"] = count.ToString(),
				["countdown"] = tuple.Item1.Countdown.ToString()
			};
			if (!tuple.Item2)
			{
				RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.BigDeck, new RuleEvidence(input.Fact.Header.EventId, "big_deck_countdown_not_ready", snapshot, TimingPhase.Run));
				return;
			}
			(DanmakuSignal, RuleEvidence) tuple2 = RuleDispatchFactory.Create(DanmakuTrigger.BigDeck, input.Fact.Header.EventId, TimingPhase.Run, ConditionResult.Match("big_deck_added_cards_countdown_reached"), snapshot, new RuleContextBuilder().Number("count", count).Build());
			DanmakuHub.Instance?.Dispatch(tuple2.Item1, tuple2.Item2);
		}

		private static void OnSmallDeckChanged(RuleConsumptionContext<DeckChangedFact> input)
		{
			ConditionResult result = RuleBusinessEvaluators.EvaluateSmallDeck(input.Fact.ChangeKind, input.Fact.DeckCardIds.Count);
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["changeKind"] = input.Fact.ChangeKind,
				["deckCount"] = input.Fact.DeckCardIds.Count.ToString()
			};
			if (!result.Matched)
			{
				RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.SmallDeck, new RuleEvidence(input.Fact.Header.EventId, result.ReasonCode, snapshot, TimingPhase.Run));
				return;
			}
			(DanmakuSignal, RuleEvidence) tuple = RuleDispatchFactory.Create(DanmakuTrigger.SmallDeck, input.Fact.Header.EventId, TimingPhase.Run, result, snapshot);
			DanmakuHub.Instance?.Dispatch(tuple.Item1, tuple.Item2);
		}

		private static void OnCombatStarted(RuleConsumptionContext<CombatStartedFact> input)
		{
			RunNodeSnapshot node = input.Fact.Node;
			int key = node?.ActIndex ?? (-1);
			if (!input.Contexts.Run.EliteNodeKeysByAct.TryGetValue(key, out HashSet<string> value))
			{
				value = new HashSet<string>(StringComparer.Ordinal);
			}
			EliteStreakEvaluation eliteStreakEvaluation = EliteStreakRuleEvaluator.Evaluate(node, value);
			if (eliteStreakEvaluation.Added && node != null)
			{
				value.Add(node.StableKey);
				input.Contexts.Run.EliteNodeKeysByAct[key] = value;
			}
			DispatchConsecutive(DanmakuTrigger.EliteStreak, input.Fact.Header.EventId, TimingPhase.CombatStart, eliteStreakEvaluation.Result, eliteStreakEvaluation.Count, new Dictionary<string, string>
			{
				["actIndex"] = key.ToString(),
				["nodeKey"] = node?.StableKey ?? "",
				["pointType"] = node?.PointType ?? ""
			});
		}

		private static void OnCombatEnded(RuleConsumptionContext<CombatEndedFact> input)
		{
			ConsecutiveRuleEvaluation consecutiveRuleEvaluation = NoDamageStreakRuleEvaluator.Evaluate(input.Contexts.Run.NoDamageStreak, input.Fact.Won, input.Fact.DamagedByEnemy);
			input.Contexts.Run.NoDamageStreak = consecutiveRuleEvaluation.Count;
			DispatchConsecutive(DanmakuTrigger.NoDamageStreak, input.Fact.Header.EventId, TimingPhase.Combat, consecutiveRuleEvaluation.Result, consecutiveRuleEvaluation.Count, new Dictionary<string, string>
			{
				["won"] = input.Fact.Won.ToString(),
				["damagedByEnemy"] = input.Fact.DamagedByEnemy.ToString()
			});
		}

		private static void OnUpgradeStreak(RuleConsumptionContext<RestSiteOptionCompletedFact> input)
		{
			RulePlayerDiff rulePlayerDiff = RulePlayerDiff.Between(new RulePlayerSnapshot(input.Fact.Before, input.Fact.Before.StableCardStates), new RulePlayerSnapshot(input.Fact.After, input.Fact.After.StableCardStates));
			bool upgradedCard = rulePlayerDiff.Upgrades.Any((CardStateChange change) => change.After.UpgradeLevel > change.Before.UpgradeLevel);
			bool hasMiniatureTent = input.Fact.Before.StableRelicIds.Contains("MINIATURE_TENT");
			ConsecutiveRuleEvaluation consecutiveRuleEvaluation = UpgradeStreakRuleEvaluator.Evaluate(input.Contexts.Run.UpgradeStreak, upgradedCard, hasMiniatureTent);
			input.Contexts.Run.UpgradeStreak = consecutiveRuleEvaluation.Count;
			DispatchConsecutive(DanmakuTrigger.UpgradeStreak, input.Fact.Header.EventId, TimingPhase.RestSite, consecutiveRuleEvaluation.Result, consecutiveRuleEvaluation.Count, new Dictionary<string, string>
			{
				["optionId"] = input.Fact.OptionId,
				["upgradedCards"] = rulePlayerDiff.Upgrades.Count.ToString(),
				["hasMiniatureTent"] = hasMiniatureTent.ToString(),
				["ignored"] = consecutiveRuleEvaluation.Ignored.ToString()
			});
		}

		private static void OnRestSiteFullApotheosis(RuleConsumptionContext<RestSiteOptionCompletedFact> input)
		{
			if (input.Fact.Succeeded)
			{
				RulePlayerDiff rulePlayerDiff = RulePlayerDiff.Between(new RulePlayerSnapshot(input.Fact.Before, input.Fact.Before.StableCardStates), new RulePlayerSnapshot(input.Fact.After, input.Fact.After.StableCardStates));
				bool num = rulePlayerDiff.Upgrades.Any((CardStateChange change) => change.After.UpgradeLevel > change.Before.UpgradeLevel);
				IReadOnlyList<CardStateSnapshot> stableCardStates = input.Fact.After.StableCardStates;
				bool flag = stableCardStates.Count > 0 && stableCardStates.All((CardStateSnapshot card) => !card.Upgradable);
				RuleEvidence evidence = new RuleEvidence(ReasonCode: (!num) ? "no_card_upgraded_at_rest_site" : (flag ? "all_deck_cards_upgraded_after_rest_site_smith" : "deck_not_fully_upgraded"), Snapshot: new Dictionary<string, string>
				{
					["optionId"] = input.Fact.OptionId,
					["upgradedCards"] = rulePlayerDiff.Upgrades.Count.ToString(),
					["deckCardCount"] = stableCardStates.Count.ToString(),
					["fullyUpgraded"] = flag.ToString()
				}, EventId: input.Fact.Header.EventId, Phase: TimingPhase.RestSite);
				if (num && flag)
				{
					DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(DanmakuTrigger.FullApotheosis), evidence);
				}
				else
				{
					RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.FullApotheosis, evidence);
				}
			}
		}

		private static void OnRunLoaded(RuleConsumptionContext<RunLoadedFact> input)
		{
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["loadIdentity"] = input.Fact.LoadIdentity,
				["stateRestored"] = (input.Fact.PersistentState != null).ToString()
			};
			DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(DanmakuTrigger.SaveLoad), new RuleEvidence(input.Fact.Header.EventId, "saved_run_loaded", snapshot, TimingPhase.Run));
		}

		private static void DispatchConsecutive(DanmakuTrigger trigger, EventId eventId, TimingPhase phase, ConditionResult result, int count, Dictionary<string, string> snapshot)
		{
			snapshot["count"] = count.ToString();
			RuleEvidence evidence = new RuleEvidence(eventId, result.ReasonCode, snapshot, phase);
			if (result.Matched)
			{
				DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(trigger), evidence);
			}
			else
			{
				RuleDiagnostics.Instance.RecordNotMatched(trigger, evidence);
			}
		}

		private static void OnShopPurchased(RuleConsumptionContext<ShopPurchasedFact> input)
		{
			ConditionResult result = ShopRuleEvaluators.EvaluateHighValuePurchase(input.Fact.Item, input.Contexts.Shop.Items);
			Dictionary<string, string> snapshot = new Dictionary<string, string>
			{
				["itemId"] = input.Fact.Item.ItemId,
				["kind"] = input.Fact.Item.Kind,
				["price"] = input.Fact.Item.Price.ToString(),
				["premiumSlot"] = input.Fact.Item.IsPremiumSlot.ToString()
			};
			if (!result.Matched)
			{
				RuleDiagnostics.Instance.RecordNotMatched(DanmakuTrigger.BuyPremiumRelic, new RuleEvidence(input.Fact.Header.EventId, result.ReasonCode, snapshot, TimingPhase.Shop));
				return;
			}
			(DanmakuSignal, RuleEvidence) tuple = RuleDispatchFactory.Create(DanmakuTrigger.BuyPremiumRelic, input.Fact.Header.EventId, TimingPhase.Shop, result, snapshot, new RuleContextBuilder().Text("item", input.Fact.Item.DisplayName).Build());
			DanmakuHub.Instance?.Dispatch(tuple.Item1, tuple.Item2);
		}
	}
	internal static class RunLifecyclePatches
	{
		[HarmonyPatch(typeof(RunManager), "InitializeSavedRun")]
		private static class SavedRunInitializedPatch
		{
			private static void Prefix(SerializableRun save)
			{
				//IL_0022: Unknown result type (might be due to invalid IL or missing references)
				//IL_0028: Invalid comparison between Unknown and I4
				if (!save.DailyTime.HasValue)
				{
					INetGameService netService = RunManager.Instance.NetService;
					if (netService == null || (int)netService.Type != 4)
					{
						RunPersistenceCoordinator.MarkLoaded(save);
					}
				}
			}
		}

		[HarmonyPatch(typeof(RunManager), "OnEnded")]
		private static class RunEndedPatch
		{
			private static void Prefix(bool isVictory)
			{
				PhaseRouter.Instance?.OnRunEnded(isVictory ? "victory" : "defeat", deletePersistentState: true);
			}
		}

		[HarmonyPatch(typeof(RunManager), "CleanUp")]
		private static class RunCleanupPatch
		{
			private static void Prefix()
			{
				PhaseRouter.Instance?.OnRunEnded("cleanup", deletePersistentState: false);
			}
		}
	}
	internal static class SculptorPatch
	{
		[HarmonyPatch(typeof(CombatHistory), "MonsterPerformedMove", new Type[]
		{
			typeof(ICombatState),
			typeof(MonsterModel),
			typeof(MoveState),
			typeof(IEnumerable<Creature>)
		})]
		private static class MonsterPerformedMovePatch
		{
			private static void Postfix(MonsterModel monster, MoveState move)
			{
				if (PoolManager.IsPhaseActive(TimingPhase.Combat) && monster != null && move != null)
				{
					Creature creature = monster.Creature;
					uint valueOrDefault = ((creature != null) ? creature.CombatId : null).GetValueOrDefault();
					ConditionResult conditionResult = RuleBusinessEvaluators.EvaluateSculptorChant(((AbstractModel)monster).Id.Entry, ((MonsterState)move).Id, ModRunState.SculptorsChanted.Contains(valueOrDefault));
					if (conditionResult.Matched && ModRunState.SculptorsChanted.Add(valueOrDefault))
					{
						EventId eventId = ModRunState.NextEvent(EventSourceKind.MonsterPerformedMove);
						DanmakuHub.Instance?.Dispatch(DanmakuSignal.Of(DanmakuTrigger.SculptorChant), new RuleEvidence(eventId, conditionResult.ReasonCode, new Dictionary<string, string>
						{
							["monsterCombatId"] = valueOrDefault.ToString(),
							["move"] = ((MonsterState)move).Id
						}, TimingPhase.Combat));
					}
				}
			}
		}
	}
	public sealed class UgcFactConsumer<TFact> : IDisposable where TFact : IGameFact
	{
		private readonly IDisposable _subscription;

		public UgcFactConsumer(GameFactBus bus, Action<TFact> consume)
		{
			Action<TFact> consume2 = consume;
			base..ctor();
			_subscription = bus.Subscribe(delegate(TFact fact)
			{
				if (!LocalPlayerFactKinds.IsLocalPlayerFact(typeof(TFact)) || fact.Header.Boundary == FactBoundary.LocalPlayer)
				{
					consume2(fact);
				}
			});
		}

		public void Dispose()
		{
			_subscription.Dispose();
		}
	}
	public static class UgcConsumerBootstrap
	{
		private static RuleConsumerGroup? _group;

		private static UgcFactBridge? _bridge;

		private static UgcRuntime? _runtime;

		private static double Now()
		{
			return _runtime?.LogicalNow ?? 0.0;
		}

		public static void Start(GameFactBus bus, UgcRuntime runtime)
		{
			Shutdown();
			_runtime = runtime;
			ApplyDensity();
			DanmakuModConfig.Changed += ApplyDensity;
			_bridge = new UgcFactBridge(runtime);
			_group = new RuleConsumerGroup();
			_group.Add(new UgcFactConsumer<RunStartedFact>(bus, delegate(RunStartedFact fact)
			{
				_bridge.OnRunStarted(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<RunLoadedFact>(bus, delegate(RunLoadedFact fact)
			{
				_bridge.OnRunLoaded(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<RunEndedFact>(bus, delegate(RunEndedFact fact)
			{
				_bridge.OnRunEnded(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<RoomEnteredFact>(bus, delegate(RoomEnteredFact fact)
			{
				_bridge.OnRoomEntered(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<RoomLeavingFact>(bus, delegate(RoomLeavingFact fact)
			{
				_bridge.OnRoomLeaving(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<CollectibleObtainedFact>(bus, delegate(CollectibleObtainedFact fact)
			{
				_bridge.OnCollectibleObtained(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<DeckChangedFact>(bus, delegate(DeckChangedFact fact)
			{
				_bridge.OnDeckChanged(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<CardPlayedFact>(bus, delegate(CardPlayedFact fact)
			{
				_bridge.OnCardPlayed(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<CardUpgradedFact>(bus, delegate(CardUpgradedFact fact)
			{
				_bridge.OnCardUpgraded(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<EventOpenedFact>(bus, delegate(EventOpenedFact fact)
			{
				_bridge.OnEventOpened(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<EventChoiceCompletedFact>(bus, delegate(EventChoiceCompletedFact fact)
			{
				_bridge.OnEventChoice(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<EventClosedFact>(bus, delegate(EventClosedFact fact)
			{
				_bridge.OnEventClosed(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<RewardOpenedFact>(bus, delegate(RewardOpenedFact fact)
			{
				_bridge.OnRewardOpened(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<RewardClosedFact>(bus, delegate(RewardClosedFact fact)
			{
				_bridge.OnRewardClosed(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<ShopOpenedFact>(bus, delegate(ShopOpenedFact fact)
			{
				_bridge.OnShopOpened(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<RestSiteOpenedFact>(bus, delegate(RestSiteOpenedFact fact)
			{
				_bridge.OnRestSiteOpened(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<RestSiteClosedFact>(bus, delegate(RestSiteClosedFact fact)
			{
				_bridge.OnRestSiteClosed(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<CombatStartedFact>(bus, delegate(CombatStartedFact fact)
			{
				_bridge.OnCombatStarted(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<CombatEndedFact>(bus, delegate(CombatEndedFact fact)
			{
				_bridge.OnCombatEnded(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<TurnStartedFact>(bus, delegate(TurnStartedFact fact)
			{
				_bridge.OnTurnStarted(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<CreatureDeathConfirmedFact>(bus, delegate(CreatureDeathConfirmedFact fact)
			{
				_bridge.OnCreatureDeath(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<CharacterPreselectedFact>(bus, delegate(CharacterPreselectedFact fact)
			{
				_bridge.OnCharacterPreselected(fact, Now());
			}));
			_group.Add(new UgcFactConsumer<CharacterConfirmedFact>(bus, delegate(CharacterConfirmedFact fact)
			{
				_bridge.OnCharacterConfirmed(fact, Now());
			}));
		}

		public static void Shutdown()
		{
			DanmakuModConfig.Changed -= ApplyDensity;
			_group?.Dispose();
			_group = null;
			_bridge = null;
			_runtime = null;
		}

		private static void ApplyDensity()
		{
			if (_runtime != null)
			{
				UgcEngine engine = _runtime.Engine;
				engine.Density = DanmakuModConfig.弹幕密度 switch
				{
					DanmakuModConfig.弹幕密度档位.稀疏 => DanmakuDensity.Sparse, 
					DanmakuModConfig.弹幕密度档位.密集 => DanmakuDensity.Dense, 
					_ => DanmakuDensity.Standard, 
				};
			}
		}
	}
	public sealed class UgcFactBridge
	{
		private readonly UgcRuntime _runtime;

		private int _currentAct = -1;

		private int _currentPlayerTurn;

		private bool _inCombat;

		public UgcFactBridge(UgcRuntime runtime)
		{
			_runtime = runtime;
		}

		public void OnRunStarted(RunStartedFact fact, double now)
		{
			_runtime.Clear();
			_currentAct = -1;
			_currentPlayerTurn = 0;
			_inCombat = false;
			ApplySnapshot(fact.InitialState, now, allowActEntered: true);
		}

		public void OnRunLoaded(RunLoadedFact fact, double now)
		{
			_runtime.Clear();
			_currentAct = -1;
			_currentPlayerTurn = 0;
			_inCombat = false;
			_runtime.RestoreShuffleBags(fact.PersistentState?.UgcShuffleBags);
			ApplySnapshot(fact.InitialState, now, allowActEntered: false);
		}

		public void OnRunEnded(RunEndedFact fact, double now)
		{
			_runtime.Clear();
			_currentAct = -1;
			_currentPlayerTurn = 0;
			_inCombat = false;
		}

		public void OnRoomEntered(RoomEnteredFact fact, double now)
		{
			_currentPlayerTurn = 0;
			_inCombat = false;
			_runtime.State.RemoveAll(ContentObjectKind.Event, ContentInterval.InEvent);
			_runtime.Engine.EndCombat();
			_runtime.Engine.RefreshPreconditions();
		}

		public void OnRoomLeaving(RoomLeavingFact fact, double now)
		{
			_currentPlayerTurn = 0;
			_inCombat = false;
			ApplySnapshot(fact.After, now, allowActEntered: true);
			_runtime.State.RemoveAll(ContentObjectKind.Event, ContentInterval.InEvent);
			_runtime.Engine.EndCombat();
			_runtime.Engine.RefreshPreconditions();
		}

		public void OnCollectibleObtained(CollectibleObtainedFact fact, double now)
		{
			ContentObjectKind kind = ((fact.Kind == CollectibleKind.Card) ? ContentObjectKind.Card : ContentObjectKind.Relic);
			ContentTrigger trigger = new ContentTrigger(kind, ContentInstant.Obtained, fact.ModelId);
			_runtime.State.Set(kind, ContentInterval.Own, fact.ModelId);
			_runtime.Engine.OnObjectEvent(trigger, now);
		}

		public void OnCharacterPreselected(CharacterPreselectedFact fact, double now)
		{
			_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Character, ContentInstant.Preselected, fact.CharacterId), now);
		}

		public void OnCharacterConfirmed(CharacterConfirmedFact fact, double now)
		{
			_runtime.State.RemoveAll(ContentObjectKind.Character, ContentInterval.Using);
			if (!string.IsNullOrWhiteSpace(fact.CharacterId))
			{
				_runtime.State.Set(ContentObjectKind.Character, ContentInterval.Using, fact.CharacterId);
			}
			_runtime.Engine.RefreshPreconditions();
			_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Character, ContentInstant.Confirmed, fact.CharacterId), now);
		}

		public void OnDeckChanged(DeckChangedFact fact, double now)
		{
			ReplaceOwned(ContentObjectKind.Card, fact.DeckCardIds);
			_runtime.Engine.RefreshPreconditions();
			if (string.Equals(fact.ChangeKind, "removed", StringComparison.OrdinalIgnoreCase))
			{
				ContentTrigger trigger = new ContentTrigger(ContentObjectKind.Card, ContentInstant.Removed, fact.CardId);
				_runtime.Engine.OnObjectEvent(trigger, now);
			}
		}

		public void OnCardPlayed(CardPlayedFact fact, double now)
		{
			_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Card, ContentInstant.Played, fact.CardId), now);
		}

		public void OnCardUpgraded(CardUpgradedFact fact, double now)
		{
			_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Card, ContentInstant.Upgraded, fact.CardId), now);
		}

		public void OnEventOpened(EventOpenedFact fact, double now)
		{
			ApplySnapshot(fact.Before, now, allowActEntered: true);
			_runtime.State.RemoveAll(ContentObjectKind.Event, ContentInterval.InEvent);
			_runtime.State.Set(ContentObjectKind.Event, ContentInterval.InEvent, fact.ModelId);
			_runtime.Engine.RefreshPreconditions();
			_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Event, ContentInstant.Entered, fact.ModelId), now);
		}

		public void OnEventChoice(EventChoiceCompletedFact fact, double now)
		{
			_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Event, ContentInstant.OptionSelected, fact.EventId), now);
			if (!string.IsNullOrWhiteSpace(fact.ChoiceId))
			{
				_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Event, ContentInstant.OptionSelected, fact.EventId + ":" + fact.ChoiceId), now);
			}
			ApplySnapshot(fact.After, now, allowActEntered: true);
		}

		public void OnEventClosed(EventClosedFact fact, double now)
		{
			_runtime.State.RemoveAll(ContentObjectKind.Event, ContentInterval.InEvent);
			ApplySnapshot(fact.After, now, allowActEntered: true);
		}

		public void OnRewardOpened(RewardOpenedFact fact, double now)
		{
			ApplySnapshot(fact.Before, now, allowActEntered: true);
		}

		public void OnRewardClosed(RewardClosedFact fact, double now)
		{
			ApplySnapshot(fact.After, now, allowActEntered: true);
		}

		public void OnShopOpened(ShopOpenedFact fact, double now)
		{
			ApplySnapshot(fact.Before, now, allowActEntered: true);
		}

		public void OnRestSiteOpened(RestSiteOpenedFact fact, double now)
		{
			ApplySnapshot(fact.Before, now, allowActEntered: true);
		}

		public void OnRestSiteClosed(RestSiteClosedFact fact, double now)
		{
			ApplySnapshot(fact.After, now, allowActEntered: true);
		}

		public void OnCombatStarted(CombatStartedFact fact, double now)
		{
			_currentPlayerTurn = 0;
			_inCombat = true;
			_runtime.Engine.EndCombat();
			foreach (string stableEnemyId in fact.StableEnemyIds)
			{
				_runtime.State.Set(ContentObjectKind.Monster, ContentInterval.InCombat, stableEnemyId);
				_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Monster, ContentInstant.Encountered, stableEnemyId), now);
			}
			_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Monster, ContentInstant.Combat, "*"), now);
		}

		public void OnCombatEnded(CombatEndedFact fact, double now)
		{
			_currentPlayerTurn = 0;
			_inCombat = false;
			_runtime.Engine.EndCombat();
		}

		public void OnTurnStarted(TurnStartedFact fact, double now)
		{
			if (fact.IsPlayerTurn)
			{
				int num = (int)fact.Header.EventId.TurnSequence;
				if (num > 0)
				{
					_currentPlayerTurn = num;
					string id = num.ToString();
					_runtime.State.RemoveAll(ContentObjectKind.Turn, ContentInterval.AtTurn);
					_runtime.State.Set(ContentObjectKind.Turn, ContentInterval.AtTurn, id);
					_runtime.Engine.RefreshPreconditions();
					RetriggerCombatIfNeeded(now);
					_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Turn, ContentInstant.TurnEntered, id), now);
				}
			}
		}

		private void RetriggerCombatIfNeeded(double now)
		{
			if (_inCombat)
			{
				_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Monster, ContentInstant.Combat, "*"), now);
			}
		}

		public void OnCreatureDeath(CreatureDeathConfirmedFact fact, double now)
		{
			if (!fact.IsPlayer)
			{
				_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Monster, ContentInstant.Defeated, fact.CreatureId), now, freezeCandidates: true);
				_runtime.State.Remove(ContentObjectKind.Monster, ContentInterval.InCombat, fact.CreatureId);
				_runtime.Engine.RefreshPreconditions();
			}
		}

		private void ApplySnapshot(PlayerStateSnapshot? snapshot, double now, bool allowActEntered)
		{
			if (!(snapshot == null))
			{
				_runtime.State.RemoveAll(ContentObjectKind.Character, ContentInterval.Using);
				if (!string.IsNullOrWhiteSpace(snapshot.CharacterId))
				{
					_runtime.State.Set(ContentObjectKind.Character, ContentInterval.Using, snapshot.CharacterId);
				}
				ReplaceOwned(ContentObjectKind.Card, snapshot.DeckCardIds);
				ReplaceOwned(ContentObjectKind.Relic, snapshot.StableRelicIds);
				ApplyActSnapshot(snapshot.CurrentActIndex, now, allowActEntered);
				_runtime.Engine.RefreshPreconditions();
			}
		}

		private void ApplyActSnapshot(int actIndex, double now, bool allowActEntered)
		{
			if (actIndex >= 0 && actIndex != _currentAct)
			{
				_currentAct = actIndex;
				string id = (actIndex + 1).ToString();
				_runtime.State.RemoveAll(ContentObjectKind.Act, ContentInterval.AtAct);
				_runtime.State.Set(ContentObjectKind.Act, ContentInterval.AtAct, id);
				_runtime.Engine.RefreshPreconditions();
				RetriggerCombatIfNeeded(now);
				if (allowActEntered)
				{
					_runtime.Engine.OnObjectEvent(new ContentTrigger(ContentObjectKind.Act, ContentInstant.ActEntered, id), now);
				}
			}
		}

		private void ReplaceOwned(ContentObjectKind kind, IEnumerable<string> ids)
		{
			_runtime.State.RemoveAll(kind, ContentInterval.Own);
			foreach (string item in ids.Where((string id) => !string.IsNullOrWhiteSpace(id)).Distinct<string>(StringComparer.Ordinal))
			{
				_runtime.State.Set(kind, ContentInterval.Own, item);
			}
		}
	}
}
namespace DanmakuSpire.DanmakuSpireCode.Core
{
	public readonly record struct RuleEvaluation(bool Matched, string ReasonCode);
	public readonly record struct HasBlockNoPlayInput(bool EnemyDealer, int UnblockedDamage, bool FlushFinalized, int FlushedPlayableBlockCount, bool AlreadyFired, int EndTurnEnergy = 0, int? MinimumBlockCardCost = null);
	public readonly record struct BigTurnInput(int CardPlayCount, bool IsAttack, bool HasQueuedCard, float QueueSeconds);
	public readonly record struct NumberExtremeInput(int FrozenAttackIntents, int CompletedAttackMoves, int ExecutedAttacksAgainstPlayer, int EnemyHpLost, int BlockedDamage, int BlockAfterEnemyActions, bool AlreadyEvaluated, bool DamageRedirectedToPlayerPet = false, bool HasBuffer = false);
	public readonly record struct OpeningHandQualityInput(int CurrentActIndex, bool EnemyIntendsToAttack, bool HasBlock, bool HasAttack, bool HasDraw);
	public readonly record struct CombatDamageState(bool DamagedByEnemy, int EnemyTurnHpLost);
	public static class CombatRuleEvaluators
	{
		public static bool IsPlayableBlockCandidate(bool gainsBlock, bool canPlay)
		{
			return gainsBlock && canPlay;
		}

		public static CombatDamageState MarkDamagedByEnemy(CombatDamageState state, int hpLost)
		{
			if (hpLost <= 0)
			{
				return state;
			}
			return state with
			{
				DamagedByEnemy = true
			};
		}

		public static CombatDamageState RecordEnemyTurnHpLost(CombatDamageState state, int hpLost, bool hasFrozenEnemyMove)
		{
			if (!hasFrozenEnemyMove || hpLost <= 0)
			{
				return state;
			}
			return state with
			{
				EnemyTurnHpLost = state.EnemyTurnHpLost + hpLost
			};
		}

		public static RuleEvaluation EvaluateNakedHit(int blockedDamage, int hpLost)
		{
			if (blockedDamage != 0)
			{
				return new RuleEvaluation(Matched: false, "damage_consumed_block");
			}
			if (hpLost < 5)
			{
				return new RuleEvaluation(Matched: false, "unblocked_damage_below_five");
			}
			return new RuleEvaluation(Matched: true, "enemy_unblocked_damage_at_least_five");
		}

		public static int DamageIncludingOverkill(int totalDamage, int overkillDamage)
		{
			long num = (long)Math.Max(0, totalDamage) + (long)Math.Max(0, overkillDamage);
			if (num <= int.MaxValue)
			{
				return (int)num;
			}
			return int.MaxValue;
		}

		public static bool IsSingleCardHighDamage(int totalDamage)
		{
			return totalDamage >= 40;
		}

		public static bool ShouldCountExperimentHit(int totalDamage, bool isIntangible)
		{
			return totalDamage > 0 && isIntangible;
		}

		public static RuleEvaluation EvaluateExactLethal(bool targetDied, int overkillDamage)
		{
			if (!targetDied)
			{
				return new RuleEvaluation(Matched: false, "target_survived_damage");
			}
			if (overkillDamage != 0)
			{
				return new RuleEvaluation(Matched: false, "lethal_damage_overkilled");
			}
			return new RuleEvaluation(Matched: true, "enemy_died_without_overkill");
		}

		public static RuleEvaluation EvaluateBowlbugRockOneDamage(string dealerId, int blockedDamage, int hpLost)
		{
			if (dealerId != "BOWLBUG_ROCK")
			{
				return new RuleEvaluation(Matched: false, "dealer_not_bowlbug_rock");
			}
			if (blockedDamage <= 0)
			{
				return new RuleEvaluation(Matched: false, "bowlbug_attack_consumed_no_block");
			}
			if (hpLost != 1)
			{
				return new RuleEvaluation(Matched: false, "bowlbug_hp_loss_not_one");
			}
			return new RuleEvaluation(Matched: true, "bowlbug_rock_attack_left_exactly_one_damage");
		}

		public static int CountAliveEnemiesBeforeDeath(int aliveEnemiesExcludingCreature, bool isMonster)
		{
			return aliveEnemiesExcludingCreature + (isMonster ? 1 : 0);
		}

		public static bool IsSameCombatLifecycle(long capturedSequence, object? capturedState, long currentSequence, object? currentState)
		{
			if (capturedSequence == currentSequence)
			{
				return capturedState == currentState;
			}
			return false;
		}

		public static bool IsExpectedAutoPrePlayBoundary(int phaseValue)
		{
			return phaseValue == 2;
		}

		public static RuleEvaluation EvaluateDefenseLack(OpeningHandQualityInput input)
		{
			if (input.CurrentActIndex != 0)
			{
				return new RuleEvaluation(Matched: false, "defense_lack_outside_act_one");
			}
			if (!input.EnemyIntendsToAttack)
			{
				return new RuleEvaluation(Matched: false, "enemy_has_no_attack_intent");
			}
			if (input.HasBlock)
			{
				return new RuleEvaluation(Matched: false, "hand_has_block");
			}
			if (input.HasDraw)
			{
				return new RuleEvaluation(Matched: false, "hand_has_draw_out");
			}
			return new RuleEvaluation(Matched: true, "act_one_enemy_attack_no_block_or_draw_after_hand_draw");
		}

		public static RuleEvaluation EvaluateOffenseLack(OpeningHandQualityInput input)
		{
			if (input.CurrentActIndex != 0)
			{
				return new RuleEvaluation(Matched: false, "offense_lack_outside_act_one");
			}
			if (input.EnemyIntendsToAttack)
			{
				return new RuleEvaluation(Matched: false, "enemy_attack_creates_defense_pressure");
			}
			if (input.HasAttack)
			{
				return new RuleEvaluation(Matched: false, "hand_has_attack");
			}
			if (input.HasDraw)
			{
				return new RuleEvaluation(Matched: false, "hand_has_draw_out");
			}
			return new RuleEvaluation(Matched: true, "act_one_no_enemy_attack_no_attack_or_draw_after_hand_draw");
		}

		public static RuleEvaluation EvaluateHasBlockNoPlay(HasBlockNoPlayInput input)
		{
			if (!input.EnemyDealer)
			{
				return new RuleEvaluation(Matched: false, "damage_not_from_enemy");
			}
			if (input.UnblockedDamage <= 0)
			{
				return new RuleEvaluation(Matched: false, "no_hp_damage");
			}
			if (!input.FlushFinalized)
			{
				return new RuleEvaluation(Matched: false, "end_turn_flush_not_finalized");
			}
			if (input.FlushedPlayableBlockCount <= 0)
			{
				return new RuleEvaluation(Matched: false, "no_flushed_playable_block_card");
			}
			int? minimumBlockCardCost = input.MinimumBlockCardCost;
			if (minimumBlockCardCost.HasValue)
			{
				int valueOrDefault = minimumBlockCardCost.GetValueOrDefault();
				if (input.EndTurnEnergy < valueOrDefault)
				{
					return new RuleEvaluation(Matched: false, "insufficient_energy_for_cheapest_block_card");
				}
				if (input.AlreadyFired)
				{
					return new RuleEvaluation(Matched: false, "already_fired_this_enemy_turn");
				}
				return new RuleEvaluation(Matched: true, "enemy_damage_after_flushing_unplayed_payable_block");
			}
			return new RuleEvaluation(Matched: false, "minimum_block_cost_unavailable");
		}

		public static RuleEvaluation EvaluateBigTurn(BigTurnInput input)
		{
			if (input.IsAttack && input.CardPlayCount >= 5)
			{
				return new RuleEvaluation(Matched: true, "attack_play_count_at_least_five");
			}
			if (input.HasQueuedCard && input.QueueSeconds >= 3f)
			{
				return new RuleEvaluation(Matched: true, "card_waited_in_play_queue_three_seconds");
			}
			if (!input.IsAttack && input.CardPlayCount >= 5)
			{
				return new RuleEvaluation(Matched: false, "high_play_count_card_not_attack");
			}
			return new RuleEvaluation(Matched: false, "big_turn_threshold_not_reached");
		}

		public static RuleEvaluation EvaluateNumberExtreme(NumberExtremeInput input)
		{
			if (input.AlreadyEvaluated)
			{
				return new RuleEvaluation(Matched: false, "already_evaluated_enemy_turn");
			}
			if (input.FrozenAttackIntents <= 0)
			{
				return new RuleEvaluation(Matched: false, "no_attack_intent_frozen");
			}
			if (input.CompletedAttackMoves <= 0)
			{
				return new RuleEvaluation(Matched: false, "attack_move_not_completed");
			}
			if (input.ExecutedAttacksAgainstPlayer <= 0)
			{
				return new RuleEvaluation(Matched: false, "no_attack_executed_against_player");
			}
			if (input.DamageRedirectedToPlayerPet)
			{
				return new RuleEvaluation(Matched: false, "enemy_damage_redirected_to_player_pet");
			}
			if (input.HasBuffer)
			{
				return new RuleEvaluation(Matched: false, "player_has_buffer_power");
			}
			if (input.EnemyHpLost != 0)
			{
				return new RuleEvaluation(Matched: false, "player_lost_hp_during_enemy_attacks");
			}
			if (input.BlockedDamage <= 0)
			{
				return new RuleEvaluation(Matched: false, "enemy_attacks_consumed_no_block");
			}
			if (input.BlockAfterEnemyActions != 0)
			{
				return new RuleEvaluation(Matched: false, "block_not_exactly_consumed");
			}
			return new RuleEvaluation(Matched: true, "enemy_attacks_exactly_consumed_all_block");
		}

		public static DeathRuleEvaluation EvaluateDeath(DeathRuleInput input)
		{
			if (input.AlreadyProcessed)
			{
				return new DeathRuleEvaluation(OneTurnKill: false, Reconviction: false, StrongMonsterKill: false, SculptorPreChant: false, PlayerDeath: false, "death_already_processed");
			}
			if (input.IsPlayer)
			{
				return new DeathRuleEvaluation(OneTurnKill: false, Reconviction: false, StrongMonsterKill: false, SculptorPreChant: false, PlayerDeath: true, "player_death_confirmed");
			}
			if (!input.IsMonster)
			{
				return new DeathRuleEvaluation(OneTurnKill: false, Reconviction: false, StrongMonsterKill: false, SculptorPreChant: false, PlayerDeath: false, "non_monster_non_player_death");
			}
			return new DeathRuleEvaluation(input.IsFirstPlayerTurn && input.AliveEnemyCountBeforeDeath == 1, input.MonsterTypeKilledEarlierInRun, input.StrongMonsterTriggeredEarlierInRun, input.IsDevotedSculptor && !input.SculptorChanted, PlayerDeath: false, "monster_death_confirmed");
		}
	}
