	public sealed class DanmakuHub
	{
		private readonly IDanmakuEmitter _localEmitter;

		private readonly RuleDiagnostics _diagnostics;

		private INetworkForwarder _network;

		public static DanmakuHub? Instance { get; private set; }

		public DanmakuHub(IDanmakuEmitter localEmitter, INetworkForwarder? network = null, RuleDiagnostics? diagnostics = null)
		{
			_localEmitter = localEmitter;
			_network = network ?? NoopNetworkForwarder.Instance;
			_diagnostics = diagnostics ?? RuleDiagnostics.Instance;
			Instance = this;
		}

		[Obsolete("生产规则必须调用 Dispatch(signal, evidence)", true)]
		public void Dispatch(DanmakuSignal signal)
		{
			throw new InvalidOperationException("缺少 RuleEvidence 的本地 Dispatch 已禁用。");
		}

		public void Dispatch(DanmakuSignal signal, RuleEvidence evidence)
		{
			if (!_diagnostics.TryAccept(signal.Trigger, evidence))
			{
				return;
			}
			string correlationId = RuntimeTraceIds.NewCorrelation(evidence.EventId, DanmakuRuleIds.Get(signal.Trigger));
			DanmakuSignal danmakuSignal = signal with
			{
				Scope = EmissionScopePolicy.FromPhase(evidence.Phase),
				SourceEventId = evidence.EventId,
				CorrelationId = correlationId,
				SourceCharacterId = DanmakuSourceIdentity.ResolveCurrentCharacterId(),
				SourcePlayerNetId = DanmakuMultiplayerState.LocalPlayerNetId,
				SourcePlayerName = DanmakuMultiplayerState.ResolvePlayerName(DanmakuMultiplayerState.LocalPlayerNetId)
			};
			RuntimeTraceRecorder.Instance?.RecordDispatch(danmakuSignal, evidence);
			if (danmakuSignal.Channel == DanmakuChannel.Multiplayer)
			{
				DanmakuSignal? danmakuSignal2 = _localEmitter.PrepareMultiplayer(danmakuSignal);
				if (danmakuSignal2.HasValue)
				{
					if (DanmakuModConfig.ShouldEmitMultiplayer())
					{
						_localEmitter.Emit(danmakuSignal2.Value);
					}
					_network.Forward(danmakuSignal2.Value);
				}
				return;
			}
			_localEmitter.Emit(danmakuSignal);
			_network.Forward(danmakuSignal);
			if (!MultiplayerCharacterSubstitute.IsActive(danmakuSignal.Trigger, danmakuSignal.Variant))
			{
				return;
			}
			DanmakuSignal signal2 = danmakuSignal with
			{
				Channel = DanmakuChannel.Multiplayer
			};
			DanmakuSignal? danmakuSignal3 = _localEmitter.PrepareMultiplayer(signal2);
			if (danmakuSignal3.HasValue)
			{
				if (DanmakuModConfig.ShouldEmitMultiplayer())
				{
					_localEmitter.Emit(danmakuSignal3.Value);
				}
				_network.Forward(danmakuSignal3.Value);
			}
		}

		public void DispatchRemote(DanmakuSignal signal)
		{
			if (DanmakuModConfig.ShouldEmitMultiplayer() && DanmakuModConfig.ShouldReceiveMultiplayer())
			{
				DanmakuSignal danmakuSignal = (string.IsNullOrWhiteSpace(signal.CorrelationId) ? signal with
				{
					CorrelationId = RuntimeTraceIds.NewCorrelation(signal.SourceEventId, DanmakuRuleIds.Get(signal.Trigger))
				} : signal);
				_localEmitter.Emit(danmakuSignal with
				{
					IsRemote = true
				});
			}
		}

		public void DispatchChat(string body, string sourceCharacterId, string sourcePlayerName, string color = "", bool rainbow = false)
		{
			if (DanmakuModConfig.ShouldEmitChat())
			{
				string correlationId = $"chat:{Guid.NewGuid():N}";
				_localEmitter.EmitChat(body, sourceCharacterId, sourcePlayerName, correlationId, EmissionScope.Run, color, rainbow);
				_network.ForwardChat(body, sourceCharacterId, correlationId, color, rainbow);
			}
		}

		public void DispatchRemoteChat(string body, string sourceCharacterId, string sourcePlayerName, string correlationId, string color = "", bool rainbow = false)
		{
			_localEmitter.EmitChat(body, sourceCharacterId, sourcePlayerName, correlationId, EmissionScope.Run, color, rainbow);
		}

		public void SetNetworkForwarder(INetworkForwarder network)
		{
			_network = network ?? NoopNetworkForwarder.Instance;
		}

		public void Shutdown()
		{
			_network = NoopNetworkForwarder.Instance;
			if (Instance == this)
			{
				Instance = null;
			}
		}
	}
