	public static class DanmakuMultiplayerState
	{
		private static readonly HashSet<ulong> _compatiblePeers = new HashSet<ulong>();

		public static string ModVersion { get; } = ResolveModVersion();


		public static Func<bool> IsMultiplayerSessionProvider { get; set; } = DefaultIsMultiplayerSession;


		public static Func<ulong, string> PlayerNameResolver { get; set; } = DefaultPlayerNameResolver;


		public static Func<ulong> LocalPlayerNetIdProvider { get; set; } = DefaultLocalPlayerNetId;


		public static bool IsMultiplayerSession
		{
			get
			{
				try
				{
					return IsMultiplayerSessionProvider();
				}
				catch
				{
					return false;
				}
			}
		}

		public static ulong LocalPlayerNetId
		{
			get
			{
				try
				{
					return LocalPlayerNetIdProvider();
				}
				catch
				{
					return 0uL;
				}
			}
		}

		public static bool HasCompatiblePeers => _compatiblePeers.Count > 0;

		public static IReadOnlyCollection<ulong> Peers => (IReadOnlyCollection<ulong>)(object)_compatiblePeers.ToArray();

		public static string ResolvePlayerName(ulong netId)
		{
			if (netId == 0L)
			{
				return "";
			}
			try
			{
				return PlayerNameResolver(netId) ?? "";
			}
			catch
			{
				return "";
			}
		}

		public static string ResolveLocalPlayerDisplayName()
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				PlatformType primaryPlatform = PlatformUtil.PrimaryPlatform;
				if ((int)primaryPlatform == 0)
				{
					return "";
				}
				return PlatformUtil.GetPlayerNameRaw(primaryPlatform, PlatformUtil.GetLocalPlayerId(primaryPlatform));
			}
			catch
			{
				return "";
			}
		}

		public static void RecordPeer(ulong netId, string modVersion)
		{
			if (netId != 0L && string.Equals(modVersion, ModVersion, StringComparison.Ordinal))
			{
				_compatiblePeers.Add(netId);
			}
		}

		public static bool IsCompatiblePeer(ulong netId)
		{
			if (netId != 0L && netId != LocalPlayerNetId)
			{
				return _compatiblePeers.Contains(netId);
			}
			return false;
		}

		public static void ResetPeers()
		{
			_compatiblePeers.Clear();
		}

		private static string ResolveModVersion()
		{
			return typeof(DanmakuMultiplayerState).Assembly.GetName().Version?.ToString(3) ?? "0.0.0";
		}

		public static void Reset()
		{
			IsMultiplayerSessionProvider = DefaultIsMultiplayerSession;
			PlayerNameResolver = DefaultPlayerNameResolver;
			LocalPlayerNetIdProvider = DefaultLocalPlayerNetId;
			ResetPeers();
		}

		private static bool DefaultIsMultiplayerSession()
		{
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0020: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Invalid comparison between Unknown and I4
			RunManager instance = RunManager.Instance;
			INetGameService val = ((instance != null) ? instance.NetService : null);
			if (val == null)
			{
				return false;
			}
			NetGameType type = val.Type;
			if (type - 2 <= 1)
			{
				return val.IsConnected;
			}
			return false;
		}

		private static string DefaultPlayerNameResolver(ulong netId)
		{
			//IL_001c: Unknown result type (might be due to invalid IL or missing references)
			RunManager instance = RunManager.Instance;
			INetGameService val = ((instance != null) ? instance.NetService : null);
			if (val == null)
			{
				return "";
			}
			return PlatformUtil.GetPlayerName(val.Platform, netId);
		}

		private static ulong DefaultLocalPlayerNetId()
		{
			RunManager instance = RunManager.Instance;
			ulong? obj;
			if (instance == null)
			{
				obj = null;
			}
			else
			{
				INetGameService netService = instance.NetService;
				obj = ((netService != null) ? new ulong?(netService.NetId) : null);
			}
			ulong? num = obj;
			return num.GetValueOrDefault();
		}
	}
