	public readonly record struct DanmakuSignal
	{
		public DanmakuTrigger Trigger { get; init; }

		public IReadOnlyDictionary<string, string> Context { get; init; }

		public EmissionScope Scope { get; init; }

		public string Variant { get; init; }

		public EventId? SourceEventId { get; init; }

		public string CorrelationId { get; init; }

		public string SourceCharacterId { get; init; }

		public DanmakuChannel Channel { get; init; }

		public long EntryIndex { get; init; }

		public ulong SourcePlayerNetId { get; init; }

		public string SourcePlayerName { get; init; }

		public IReadOnlyDictionary<string, string> ContextRefs { get; init; }

		public bool IsRemote { get; init; }

		public int FixedCount { get; init; }

		public bool ForceTop { get; init; }

		private static readonly IReadOnlyDictionary<string, string> EmptyContext = new Dictionary<string, string>(0);

		public DanmakuSignal(DanmakuTrigger trigger, IReadOnlyDictionary<string, string>? context = null, string variant = "", DanmakuChannel channel = DanmakuChannel.SinglePlayer, IReadOnlyDictionary<string, string>? contextRefs = null)
		{
			Trigger = trigger;
			Context = context ?? EmptyContext;
			Variant = variant;
			Channel = channel;
			EntryIndex = -1L;
			SourcePlayerNetId = 0uL;
			SourcePlayerName = "";
			ContextRefs = contextRefs ?? EmptyContext;
			IsRemote = false;
			FixedCount = -1;
			ForceTop = false;
			Scope = EmissionScope.Unknown;
			SourceEventId = null;
			CorrelationId = "";
			SourceCharacterId = "";
		}

		public static DanmakuSignal Of(DanmakuTrigger trigger)
		{
			return new DanmakuSignal(trigger);
		}
	}
