	public enum EmissionScope
	{
		Unknown,
		Combat,
		Room,
		Run
	}
	public static class EmissionScopePolicy
	{
		public static EmissionScope FromPhase(TimingPhase phase)
		{
			switch (phase)
			{
			case TimingPhase.CombatStart:
			case TimingPhase.Combat:
			case TimingPhase.TurnEnd:
				return EmissionScope.Combat;
			case TimingPhase.Reward:
			case TimingPhase.Shop:
			case TimingPhase.RestSite:
			case TimingPhase.Event:
			case TimingPhase.Map:
				return EmissionScope.Room;
			case TimingPhase.Run:
				return EmissionScope.Run;
			default:
				throw new ArgumentOutOfRangeException("phase", phase, "未定义的判定阶段");
			}
		}

		public static bool IsCanceledBy(EmissionScope itemScope, EmissionScope canceledScope)
		{
			return RequireValid(itemScope) == RequireValid(canceledScope);
		}

		public static EmissionScope RequireValid(EmissionScope scope)
		{
			if ((uint)(scope - 1) <= 2u)
			{
				return scope;
			}
			throw new ArgumentOutOfRangeException("scope", scope, "弹幕缺少有效生命周期归属");
		}
	}
	public sealed class EmissionGenerations
	{
		private readonly long[] _values = new long[4];

		public long Current(EmissionScope scope)
		{
			return _values[(int)EmissionScopePolicy.RequireValid(scope)];
		}

		public long Advance(EmissionScope scope)
		{
			scope = EmissionScopePolicy.RequireValid(scope);
			return ++_values[(int)scope];
		}

		public bool IsCurrent(EmissionScope scope, long generation)
		{
			return Current(scope) == generation;
		}
	}
