	public sealed class GameContextStore : IDisposable
	{
		private readonly List<IDisposable> _subscriptions = new List<IDisposable>();

		private bool _disposed;

		public static GameContextStore? Instance { get; private set; }

		public RunContext Run { get; } = new RunContext();


		public RoomContext Room { get; } = new RoomContext();


		public CombatContext Combat { get; } = new CombatContext();


		public TurnContext Turn { get; } = new TurnContext();


		public RewardSession Reward { get; } = new RewardSession();


		public ShopSession Shop { get; } = new ShopSession();


		public EventSession Event { get; } = new EventSession();


		public RestSiteSession RestSite { get; } = new RestSiteSession();


		public GameContextStore(GameFactBus bus)
		{
			ArgumentNullException.ThrowIfNull(bus, "bus");
			_subscriptions.Add(bus.Subscribe<RunStartedFact>(OnRunStarted));
			_subscriptions.Add(bus.Subscribe<RunLoadedFact>(OnRunLoaded));
			_subscriptions.Add(bus.Subscribe(delegate(RunEndedFact f)
			{
				EndRun(f.Reason);
			}));
			_subscriptions.Add(bus.Subscribe<RoomEnteredFact>(OnRoomEntered));
			_subscriptions.Add(bus.Subscribe<RoomLeavingFact>(OnRoomLeaving));
			_subscriptions.Add(bus.Subscribe<CombatStartedFact>(OnCombatStarted));
			_subscriptions.Add(bus.Subscribe<CombatEndedFact>(OnCombatEnded));
			_subscriptions.Add(bus.Subscribe<TurnStartedFact>(OnTurnStarted));
			_subscriptions.Add(bus.Subscribe<HandDrawCompletedFact>(Turn.Record));
			_subscriptions.Add(bus.Subscribe(delegate(PlayerEndTurnRequestedFact f)
			{
				Turn.RequestEnd(f.Header.EventId.TurnSequence);
			}));
			_subscriptions.Add(bus.Subscribe(delegate(EnemyTurnCompletedFact f)
			{
				Turn.CompleteEnemyTurn(f.Header.EventId.TurnSequence);
			}));
			_subscriptions.Add(bus.Subscribe<CardPlayedFact>(Combat.Record));
			_subscriptions.Add(bus.Subscribe<CardDrawnFact>(Combat.Record));
			_subscriptions.Add(bus.Subscribe<DamageResolvedFact>(Combat.Record));
			_subscriptions.Add(bus.Subscribe<CreatureDeathConfirmedFact>(Combat.Record));
			_subscriptions.Add(bus.Subscribe(delegate(RewardOpenedFact f)
			{
				Reward.Begin(f.Header.RoomSequence, f.CandidateIds, f.Before, f.CandidateNames);
			}));
			_subscriptions.Add(bus.Subscribe(delegate(RewardSelectedFact f)
			{
				Reward.Select(f.RewardId, f.RewardName);
			}));
			_subscriptions.Add(bus.Subscribe<RewardSkippedFact>(delegate
			{
				Reward.Skip();
			}));
			_subscriptions.Add(bus.Subscribe(delegate(RewardClosedFact f)
			{
				Reward.Close((!Reward.Skipped) ? SessionCloseKind.Completed : SessionCloseKind.Skipped, f.Reason, f.After);
			}));
			_subscriptions.Add(bus.Subscribe(delegate(ShopOpenedFact f)
			{
				Shop.Begin(f.Header.RoomSequence, f.Items, f.Before, f.VisitKey);
			}));
			_subscriptions.Add(bus.Subscribe(delegate(ShopPurchasedFact f)
			{
				Shop.Purchase(f.Item);
			}));
			_subscriptions.Add(bus.Subscribe<ShopCardRemovalUsedFact>(delegate
			{
				Shop.MarkCardRemovalUsed();
			}));
			_subscriptions.Add(bus.Subscribe(delegate(EventOpenedFact f)
			{
				Event.Begin(f.Header.RoomSequence, f.ModelId, f.OptionIds, f.Before);
			}));
			_subscriptions.Add(bus.Subscribe(delegate(EventChoiceCompletedFact f)
			{
				Event.Select(f.ChoiceId);
			}));
			_subscriptions.Add(bus.Subscribe(delegate(EventClosedFact f)
			{
				Event.Close(SessionCloseKind.Completed, f.Reason, f.After);
			}));
			_subscriptions.Add(bus.Subscribe(delegate(RestSiteOpenedFact f)
			{
				RestSite.Begin(f.Header.RoomSequence, f.OptionIds, f.Before);
			}));
			_subscriptions.Add(bus.Subscribe(delegate(RestSiteOptionCompletedFact f)
			{
				RestSite.Select(f.OptionId);
			}));
			_subscriptions.Add(bus.Subscribe(delegate(RestSiteClosedFact f)
			{
				RestSite.Close(SessionCloseKind.Completed, f.Reason, f.After);
			}));
		}

		public static GameContextStore Start(GameFactBus bus)
		{
			Instance?.Dispose();
			Instance = new GameContextStore(bus);
			return Instance;
		}

		public static void Shutdown()
		{
			Instance?.Dispose();
			Instance = null;
		}

		private void OnRunStarted(RunStartedFact fact)
		{
			BeginRun(fact.Header.EventId.RunEpoch, fact.RunIdentity);
		}

		private void OnRunLoaded(RunLoadedFact fact)
		{
			BeginRun(fact.Header.EventId.RunEpoch, fact.LoadIdentity);
			if (fact.PersistentState != null)
			{
				Run.Restore(fact.PersistentState);
			}
		}

		private void BeginRun(long sequence, string identity)
		{
			Run.Begin(sequence, identity);
			Room.Reset();
			Combat.Reset();
			Turn.Reset();
			ResetNonCombatSessions();
		}

		private void EndRun(string reason)
		{
			Run.End();
			Room.Reset();
			Combat.Reset();
			Turn.Reset();
			AbortNonCombatSessions(reason);
		}

		private void OnRoomEntered(RoomEnteredFact fact)
		{
			AbortNonCombatSessions("room_replaced");
			Room.Enter(fact.Header.RoomSequence, fact.RoomKind);
			Combat.Reset();
			Turn.Reset();
		}

		private void OnRoomLeaving(RoomLeavingFact fact)
		{
			CloseActiveSession(fact.Reason, fact.After);
			Room.Leave(fact.Header.RoomSequence, fact.Reason);
		}

		private void OnCombatStarted(CombatStartedFact fact)
		{
			Combat.Begin(fact.Header.EventId.CombatSequence, fact.EnemyCount);
			Turn.Reset();
		}

		private void OnCombatEnded(CombatEndedFact fact)
		{
			Combat.End(fact.Header.EventId.CombatSequence, fact.Won, fact.DamagedByEnemy);
			Turn.Reset();
		}

		private void OnTurnStarted(TurnStartedFact fact)
		{
			Turn.Begin(fact.Header.EventId.TurnSequence, fact.IsPlayerTurn);
		}

		private void CloseActiveSession(string reason, PlayerStateSnapshot after)
		{
			if (Reward.IsActive)
			{
				Reward.Close((!Reward.Skipped) ? SessionCloseKind.Completed : SessionCloseKind.Skipped, reason, after);
			}
			if (Shop.IsActive)
			{
				Shop.Close(SessionCloseKind.Completed, reason, after);
			}
			if (Event.IsActive)
			{
				Event.Close(SessionCloseKind.Completed, reason, after);
			}
			if (RestSite.IsActive)
			{
				RestSite.Close(SessionCloseKind.Completed, reason, after);
			}
		}

		private void AbortNonCombatSessions(string reason)
		{
			if (Reward.IsActive)
			{
				Reward.Abort(reason);
			}
			if (Shop.IsActive)
			{
				Shop.Abort(reason);
			}
			if (Event.IsActive)
			{
				Event.Abort(reason);
			}
			if (RestSite.IsActive)
			{
				RestSite.Abort(reason);
			}
		}

		private void ResetNonCombatSessions()
		{
			Reward.Reset();
			Shop.Reset();
			Event.Reset();
			RestSite.Reset();
		}

		public GameContextSnapshot Snapshot()
		{
			return new GameContextSnapshot(Run.Snapshot(), Room.Snapshot(), Combat.Snapshot(), Turn.Snapshot());
		}

		public void Dispose()
		{
			if (_disposed)
			{
				return;
			}
			_disposed = true;
			foreach (IDisposable subscription in _subscriptions)
			{
				subscription.Dispose();
			}
			_subscriptions.Clear();
			Run.End();
			Room.Reset();
			Combat.Reset();
			Turn.Reset();
			ResetNonCombatSessions();
			if (Instance == this)
			{
				Instance = null;
			}
		}
	}
	public sealed record GameContextSnapshot(RunContextSnapshot Run, RoomContextSnapshot Room, CombatContextSnapshot Combat, TurnContextSnapshot Turn);
	public enum FactPublishDecision
	{
		Accepted,
		Duplicate,
		StaleLifecycle
	}
	public sealed record FactAuditRecord(long Sequence, EventId EventId, string FactType, FactPublishDecision Decision, FlowLifecycle PublishedLifecycle, FlowLifecycle CurrentLifecycle);
	public sealed class GameFactBus
	{
		private readonly record struct FactDedupeKey(Type FactType, EventId EventId);

		private sealed class Subscription : IDisposable
		{
			private Action? _unsubscribe;

			public Subscription(Action unsubscribe)
			{
				_unsubscribe = unsubscribe;
				base..ctor();
			}

			public void Dispose()
			{
				Interlocked.Exchange(ref _unsubscribe, null)?.Invoke();
			}
		}

		private const int AuditCapacity = 2000;

		private readonly Dictionary<Type, List<Delegate>> _handlers = new Dictionary<Type, List<Delegate>>();

		private readonly HashSet<FactDedupeKey> _published = new HashSet<FactDedupeKey>();

		private readonly Queue<FactAuditRecord> _audit = new Queue<FactAuditRecord>();

		private readonly Action<Exception>? _handlerError;

		private long _sequence;

		public static GameFactBus Instance { get; } = new GameFactBus();


		public IReadOnlyList<FactAuditRecord> AuditSnapshot => _audit.ToArray();

		public event Action<FactAuditRecord, IGameFact>? AuditRecorded;

		public GameFactBus(Action<Exception>? handlerError = null)
		{
			_handlerError = handlerError;
		}

		public IReadOnlyList<FactAuditRecord> AuditSince(long sequence)
		{
			return _audit.Where((FactAuditRecord record) => record.Sequence > sequence).ToArray();
		}

		public IDisposable Subscribe<TFact>(Action<TFact> handler) where TFact : IGameFact
		{
			Action<TFact> handler2 = handler;
			ArgumentNullException.ThrowIfNull(handler2, "handler");
			Type type = typeof(TFact);
			if (!_handlers.TryGetValue(type, out List<Delegate> value))
			{
				value = new List<Delegate>();
				_handlers[type] = value;
			}
			value.Add(handler2);
			return new Subscription(delegate
			{
				Unsubscribe(type, handler2);
			});
		}

		public FactPublishDecision Publish<TFact>(TFact fact, FlowLifecycle currentLifecycle) where TFact : IGameFact
		{
			ArgumentNullException.ThrowIfNull(fact, "fact");
			if (!LifecyclePolicy.IsCurrent(fact.Header.Lifecycle, currentLifecycle, fact.Header.Scope))
			{
				return Record(fact, FactPublishDecision.StaleLifecycle, currentLifecycle);
			}
			if (!_published.Add(new FactDedupeKey(typeof(TFact), fact.Header.EventId)))
			{
				return Record(fact, FactPublishDecision.Duplicate, currentLifecycle);
			}
			FactPublishDecision result = Record(fact, FactPublishDecision.Accepted, currentLifecycle);
			if (!_handlers.TryGetValue(typeof(TFact), out List<Delegate> value))
			{
				return result;
			}
			Delegate[] array = value.ToArray();
			foreach (Delegate @delegate in array)
			{
				try
				{
					((Action<TFact>)@delegate)(fact);
				}
				catch (Exception ex)
				{
					if (_handlerError != null)
					{
						_handlerError(ex);
						continue;
					}
					MainFile.Log($"[FactBus] {typeof(TFact).Name} 消费者异常: {ex}");
				}
			}
			return result;
		}

		public void BeginRun()
		{
			_published.Clear();
			_audit.Clear();
		}

		public void Shutdown()
		{
			_handlers.Clear();
			_published.Clear();
			_audit.Clear();
		}

		private FactPublishDecision Record<TFact>(TFact fact, FactPublishDecision decision, FlowLifecycle current) where TFact : IGameFact
		{
			FactAuditRecord factAuditRecord = new FactAuditRecord(++_sequence, fact.Header.EventId, typeof(TFact).Name, decision, fact.Header.Lifecycle, current);
			if (_audit.Count >= 2000)
			{
				_audit.Dequeue();
			}
			_audit.Enqueue(factAuditRecord);
			if (this.AuditRecorded != null)
			{
				Delegate[] invocationList = this.AuditRecorded.GetInvocationList();
				for (int i = 0; i < invocationList.Length; i++)
				{
					Action<FactAuditRecord, IGameFact> action = (Action<FactAuditRecord, IGameFact>)invocationList[i];
					try
					{
						action(factAuditRecord, fact);
					}
					catch (Exception ex)
					{
						try
						{
							if (_handlerError != null)
							{
								_handlerError(ex);
								continue;
							}
							MainFile.Log($"[FactBus] 审计观察者异常: {ex}");
						}
						catch
						{
						}
					}
				}
			}
			return decision;
		}

		private void Unsubscribe(Type type, Delegate handler)
		{
			if (_handlers.TryGetValue(type, out List<Delegate> value))
			{
				value.Remove(handler);
				if (value.Count == 0)
				{
					_handlers.Remove(type);
				}
			}
		}
	}
	public static class LifecyclePolicy
	{
		public static bool IsCurrent(FlowLifecycle published, FlowLifecycle current, EmissionScope scope)
		{
			return EmissionScopePolicy.RequireValid(scope) switch
			{
				EmissionScope.Run => published.Run == current.Run, 
				EmissionScope.Room => published.Run == current.Run && published.Room == current.Room, 
				EmissionScope.Combat => published.Run == current.Run && published.Room == current.Room && published.Combat == current.Combat, 
				_ => false, 
			};
		}
	}
