	public static class MultiplayerCharacterSubstitute
	{
		public static bool IsActive(DanmakuTrigger trigger, string variant = "")
		{
			if (DanmakuMultiplayerState.IsMultiplayerSession && DanmakuModConfig.ShouldEmitMultiplayer())
			{
				return DanmakuLibrary.GetMultiplayerEntries(trigger, variant).Count > 0;
			}
			return false;
		}

		public static IReadOnlyList<DanmakuEntry> FilterSinglePlayerCandidates(IReadOnlyList<DanmakuEntry> candidates, DanmakuTrigger trigger, string variant = "")
		{
			if (!IsActive(trigger, variant))
			{
				return candidates;
			}
			return candidates.Where((DanmakuEntry entry) => entry.Style != DanmakuTextStyle.Character).ToArray();
		}
	}
	public static class MultiplayerRuleEvaluators
	{
		public static ConditionResult EvaluateMultiplayerSession(bool isMultiplayerSession)
		{
			if (!isMultiplayerSession)
			{
				return ConditionResult.Miss("singleplayer_session");
			}
			return ConditionResult.Match("multiplayer_session_active");
		}
	}
	public static class NetworkContextRefs
	{
		private static readonly HashSet<string> NumericKeys = new HashSet<string>(new global::<>z__ReadOnlyArray<string>(new string[3] { "x", "count", "hp" }), StringComparer.Ordinal);

		public static IReadOnlyList<KeyValuePair<string, string>> PrepareForSend(IEnumerable<KeyValuePair<string, string>> refs, int maximum)
		{
			List<KeyValuePair<string, string>> list = new List<KeyValuePair<string, string>>();
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			foreach (KeyValuePair<string, string> @ref in refs)
			{
				if (list.Count >= maximum)
				{
					break;
				}
				if (TryNormalize(@ref.Key, @ref.Value, out KeyValuePair<string, string> normalized) && hashSet.Add(normalized.Key))
				{
					list.Add(normalized);
				}
			}
			return list;
		}

		public static bool TryNormalize(string key, string value, out KeyValuePair<string, string> normalized)
		{
			normalized = default(KeyValuePair<string, string>);
			key = (key ?? string.Empty).Trim();
			value = (value ?? string.Empty).Trim();
			if (NumericKeys.Contains(key))
			{
				if (!decimal.TryParse(value, NumberStyles.Number, CultureInfo.InvariantCulture, out var result))
				{
					return false;
				}
				normalized = new KeyValuePair<string, string>(key, result.ToString(CultureInfo.InvariantCulture));
				return true;
			}
			switch (key)
			{
			case "char":
				if (!IsSafeStableId(value))
				{
					return false;
				}
				normalized = new KeyValuePair<string, string>(key, value);
				return true;
			case "card":
			{
				string text4 = StripPrefix(value, "card:");
				if (!IsSafeStableId(text4))
				{
					return false;
				}
				normalized = new KeyValuePair<string, string>(key, "card:" + text4);
				return true;
			}
			case "item":
			{
				int num = value.IndexOf(':');
				string text;
				string text3;
				if (num > 0)
				{
					text = value.Substring(0, num).ToLowerInvariant();
					string text2 = value;
					int num2 = num + 1;
					text3 = text2.Substring(num2, text2.Length - num2);
				}
				else
				{
					text = "item";
					text3 = value;
				}
				bool flag;
				switch (text)
				{
				case "card":
				case "relic":
				case "item":
					flag = true;
					break;
				default:
					flag = false;
					break;
				}
				if (!flag || !IsSafeStableId(text3))
				{
					return false;
				}
				normalized = new KeyValuePair<string, string>(key, text + ":" + text3);
				return true;
			}
			default:
				return false;
			}
		}

		public static bool TryResolve(KeyValuePair<string, string> pair, out KeyValuePair<string, string> resolved)
		{
			resolved = default(KeyValuePair<string, string>);
			if (!TryNormalize(pair.Key, pair.Value, out KeyValuePair<string, string> normalized))
			{
				return false;
			}
			string value = normalized.Key switch
			{
				"char" => CharacterNames.DisplayName(normalized.Value), 
				"card" => CardAlias.DisplayName(ResolveObjectName(ContentObjectKind.Card, StripPrefix(normalized.Value, "card:"))), 
				"item" => ResolveItem(normalized.Value), 
				_ => normalized.Value, 
			};
			resolved = new KeyValuePair<string, string>(normalized.Key, value);
			return true;
		}

		private static string ResolveItem(string reference)
		{
			int num = reference.IndexOf(':');
			string text = reference.Substring(0, num);
			string text2 = reference;
			int num2 = num + 1;
			string text3 = text2.Substring(num2, text2.Length - num2);
			if (!(text == "card"))
			{
				if (text == "relic")
				{
					return RelicAlias.DisplayName(ResolveObjectName(ContentObjectKind.Relic, text3));
				}
				return text3;
			}
			return CardAlias.DisplayName(ResolveObjectName(ContentObjectKind.Card, text3));
		}

		private static string ResolveObjectName(ContentObjectKind kind, string id)
		{
			string id2 = id;
			try
			{
				ContentObjectEntry? contentObjectEntry = ObjectCatalogProvider.Instance.TryGetAvailableCatalog()?.Objects.FirstOrDefault((ContentObjectEntry item) => item.Kind == kind && string.Equals(item.Id, id2, StringComparison.Ordinal));
				if (contentObjectEntry.HasValue)
				{
					ContentObjectEntry valueOrDefault = contentObjectEntry.GetValueOrDefault();
					if (!string.IsNullOrWhiteSpace(valueOrDefault.DisplayName))
					{
						return valueOrDefault.DisplayName;
					}
				}
			}
			catch
			{
			}
			return id2;
		}

		private static string StripPrefix(string value, string prefix)
		{
			if (!value.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
			{
				return value;
			}
			int length = prefix.Length;
			return value.Substring(length, value.Length - length);
		}

		private static bool IsSafeStableId(string value)
		{
			int length = value.Length;
			if (length > 0 && length <= 128)
			{
				return value.All(delegate(char ch)
				{
					bool flag = char.IsAsciiLetterOrDigit(ch);
					if (!flag)
					{
						bool flag2 = ((ch == '-' || ch == '.' || ch == '_') ? true : false);
						flag = flag2;
					}
					return flag;
				});
			}
			return false;
		}
	}
