	public static class AdditionalShopRuleEvaluators
	{
		public static CardRuleEvaluation EvaluateMissedDesirableCard(ShopMissedCardInput input)
		{
			ShopMissedCardInput input2 = input;
			ShopItemSnapshot shopItemSnapshot = (from item in input2.Items
				where item.Kind.Contains("Card", StringComparison.Ordinal) && !item.Purchased && item.Price >= 0 && input2.RemainingGold >= item.Price && RewardRuleEvaluators.IsDesirable(item.ItemId, input2.CharacterId) && !input2.Purchases.Any((ShopItemSnapshot purchased) => purchased.SlotIndex == item.SlotIndex && purchased.Kind == item.Kind)
				orderby item.SlotIndex
				select item).FirstOrDefault();
			if (!(shopItemSnapshot == null))
			{
				return new CardRuleEvaluation(ConditionResult.Match("affordable_desirable_shop_card_missed"), shopItemSnapshot.ItemId, string.IsNullOrWhiteSpace(shopItemSnapshot.DisplayName) ? shopItemSnapshot.ItemId : shopItemSnapshot.DisplayName);
			}
			return new CardRuleEvaluation(ConditionResult.Miss("no_affordable_desirable_shop_card_missed"));
		}

		public static CardRuleEvaluation EvaluateCardRemoval(string cardId, string cardName)
		{
			return new CardRuleEvaluation(ConditionResult.Match("shop_card_removal_completed"), cardId, (!string.IsNullOrWhiteSpace(cardName)) ? cardName : ((!string.IsNullOrWhiteSpace(cardId)) ? cardId : "未知卡牌"));
		}
	}
	public static class EventRuleEvaluators
	{
		public const string ArchitectEventId = "THE_ARCHITECT";

		public const string SlipperyBridgeEventId = "SLIPPERY_BRIDGE";

		public static ConditionResult EvaluateArchitect(string modelId, IReadOnlyList<string> potionIds)
		{
			if (!(modelId == "THE_ARCHITECT") || potionIds.Count <= 0)
			{
				return ConditionResult.Miss((modelId == "THE_ARCHITECT") ? "architect_entered_without_potion" : "event_not_architect");
			}
			return ConditionResult.Match("architect_entered_with_potion");
		}

		public static BridgeRuleEvaluation EvaluateBridge(string eventId, IReadOnlyList<CardStateSnapshot> removedCards, string characterId)
		{
			string characterId2 = characterId;
			if (eventId != "SLIPPERY_BRIDGE")
			{
				return BridgeRuleEvaluation.Miss("event_not_slippery_bridge");
			}
			CardStateSnapshot cardStateSnapshot = removedCards.FirstOrDefault((CardStateSnapshot card) => IsStrong(card, characterId2));
			if (cardStateSnapshot != null)
			{
				return BridgeRuleEvaluation.Match("strong", "bridge_removed_strong_card", cardStateSnapshot);
			}
			CardStateSnapshot cardStateSnapshot2 = removedCards.FirstOrDefault(IsWeak);
			if (!(cardStateSnapshot2 != null))
			{
				return BridgeRuleEvaluation.Miss("bridge_removed_unclassified_or_no_card");
			}
			return BridgeRuleEvaluation.Match("weak", "bridge_removed_weak_card", cardStateSnapshot2);
		}

		public static bool IsWeak(CardStateSnapshot card)
		{
			if (!card.CardId.StartsWith("STRIKE_", StringComparison.Ordinal) && !card.CardId.StartsWith("DEFEND_", StringComparison.Ordinal) && !card.CardType.Equals("Curse", StringComparison.OrdinalIgnoreCase))
			{
				return card.Rarity.Equals("Curse", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		public static bool IsStrong(CardStateSnapshot card, string characterId)
		{
			if (!RewardRuleEvaluators.IsDesirable(card.CardId, characterId))
			{
				return card.Rarity.Equals("Rare", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}
	}
