	{
		public static BridgeRuleEvaluation Match(string variant, string reason, CardStateSnapshot card)
		{
			return new BridgeRuleEvaluation(ConditionResult.Match(reason), variant, card);
		}

		public static BridgeRuleEvaluation Miss(string reason)
		{
			return new BridgeRuleEvaluation(ConditionResult.Miss(reason), "", null);
		}
	}
	public readonly record struct CloneEnchantmentEvaluation(ConditionResult Result, bool SeenAfter);
	public static class CloneEnchantmentRuleEvaluator
	{
		public const string CloneEnchantmentId = "CLONE";

		public const string CloneRestSiteOptionId = "CLONE";

		public static CloneEnchantmentEvaluation EvaluateFirstAcquisition(bool alreadySeen, string previousEnchantmentId, string currentEnchantmentId)
		{
			if (!currentEnchantmentId.Equals("CLONE", StringComparison.Ordinal))
			{
				return new CloneEnchantmentEvaluation(ConditionResult.Miss("enchantment_not_clone"), alreadySeen);
			}
			if (previousEnchantmentId.Equals("CLONE", StringComparison.Ordinal))
			{
				return new CloneEnchantmentEvaluation(ConditionResult.Miss("clone_enchantment_already_on_card"), SeenAfter: true);
			}
			if (!alreadySeen)
			{
				return new CloneEnchantmentEvaluation(ConditionResult.Match("first_clone_enchantment_acquired"), SeenAfter: true);
			}
			return new CloneEnchantmentEvaluation(ConditionResult.Miss("clone_already_seen_in_run"), SeenAfter: true);
		}

		public static ConditionResult EvaluateRestSiteUse(string optionId)
		{
			if (!optionId.Equals("CLONE", StringComparison.Ordinal))
			{
				return ConditionResult.Miss("rest_site_option_not_clone");
			}
			return ConditionResult.Match("clone_rest_site_option_completed");
		}
	}
	public sealed record PlayerStateSnapshot(IReadOnlyList<string> DeckCardIds, IReadOnlyList<string> PotionIds, int Gold, int CurrentHp, int MaxHp, string CharacterId = "", int CurrentActIndex = -1, IReadOnlyList<CardStateSnapshot>? CardStates = null, IReadOnlyList<string>? RelicIds = null)
	{
		public static PlayerStateSnapshot Empty { get; } = new PlayerStateSnapshot(Array.Empty<string>(), Array.Empty<string>(), 0, 0, 0);


		public IReadOnlyList<CardStateSnapshot> StableCardStates => CardStates ?? Array.Empty<CardStateSnapshot>();

		public IReadOnlyList<string> StableRelicIds => RelicIds ?? Array.Empty<string>();

		public PlayerStateSnapshot Copy()
		{
			return new PlayerStateSnapshot(DeckCardIds.ToArray(), PotionIds.ToArray(), Gold, CurrentHp, MaxHp, CharacterId, CurrentActIndex, StableCardStates.Select((CardStateSnapshot c) => c.<Clone>$()).ToArray(), StableRelicIds.ToArray());
		}

		[CompilerGenerated]
		private PlayerStateSnapshot(PlayerStateSnapshot original)
		{
			DeckCardIds = original.DeckCardIds;
			PotionIds = original.PotionIds;
			Gold = original.Gold;
			CurrentHp = original.CurrentHp;
			MaxHp = original.MaxHp;
			CharacterId = original.CharacterId;
			CurrentActIndex = original.CurrentActIndex;
			CardStates = original.CardStates;
			RelicIds = original.RelicIds;
		}
	}
	public sealed record PlayerStateDiff(IReadOnlyList<string> AddedCards, IReadOnlyList<string> RemovedCards, IReadOnlyList<string> AddedPotions, IReadOnlyList<string> RemovedPotions, int GoldDelta, int HpDelta)
	{
		public static PlayerStateDiff Between(PlayerStateSnapshot before, PlayerStateSnapshot after)
		{
			return new PlayerStateDiff(MultisetDifference(after.DeckCardIds, before.DeckCardIds), MultisetDifference(before.DeckCardIds, after.DeckCardIds), MultisetDifference(after.PotionIds, before.PotionIds), MultisetDifference(before.PotionIds, after.PotionIds), after.Gold - before.Gold, after.CurrentHp - before.CurrentHp);
		}

		private static IReadOnlyList<string> MultisetDifference(IReadOnlyList<string> minuend, IReadOnlyList<string> subtrahend)
		{
			Dictionary<string, int> dictionary = (from x in subtrahend
				group x by x).ToDictionary((IGrouping<string, string> g) => g.Key, (IGrouping<string, string> g) => g.Count());
			List<string> list = new List<string>();
			foreach (string item in minuend)
			{
				int valueOrDefault = dictionary.GetValueOrDefault(item);
				if (valueOrDefault > 0)
				{
					dictionary[item] = valueOrDefault - 1;
				}
				else
				{
					list.Add(item);
				}
			}
			return list;
		}
	}
	public enum SessionCloseKind
	{
		None,
		Completed,
		Skipped,
		Replaced,
		RunEnded,
		Aborted
	}
	public abstract class NonCombatSession
	{
		public long RoomSequence { get; private set; }

		public bool IsActive { get; private set; }

		public SessionCloseKind CloseKind { get; private set; }

		public string CloseReason { get; private set; } = "";


		public PlayerStateSnapshot Before { get; private set; } = PlayerStateSnapshot.Empty;


		public PlayerStateSnapshot? After { get; private set; }

		public PlayerStateDiff? Diff
		{
			get
			{
				if (!(After == null))
				{
					return PlayerStateDiff.Between(Before, After);
				}
				return null;
			}
		}

		public RulePlayerDiff? RuleDiff
		{
			get
			{
				if (!(After == null))
				{
					return RulePlayerDiff.Between(new RulePlayerSnapshot(Before, Before.StableCardStates), new RulePlayerSnapshot(After, After.StableCardStates));
				}
				return null;
			}
		}

		protected void Open(long roomSequence, PlayerStateSnapshot before)
		{
			if (IsActive)
			{
				Close(SessionCloseKind.Replaced, "reopened", before);
			}
			RoomSequence = roomSequence;
			IsActive = true;
			CloseKind = SessionCloseKind.None;
			CloseReason = "";
			Before = before.Copy();
			After = null;
			ResetDetails();
		}

		public void Close(SessionCloseKind kind, string reason, PlayerStateSnapshot after)
		{
			if (IsActive)
			{
				IsActive = false;
				CloseKind = kind;
				CloseReason = reason;
				After = after.Copy();
			}
		}

		public void Abort(string reason)
		{
			Close(SessionCloseKind.Aborted, reason, Before);
		}

		public void Reset()
		{
			RoomSequence = 0L;
			IsActive = false;
			CloseKind = SessionCloseKind.None;
			CloseReason = "";
			Before = PlayerStateSnapshot.Empty;
			After = null;
			ResetDetails();
		}

		protected abstract void ResetDetails();
	}
	public sealed class RewardSession : NonCombatSession
	{
		public IReadOnlyList<string> CandidateIds { get; private set; } = Array.Empty<string>();


		public IReadOnlyDictionary<string, string> CandidateNames { get; private set; } = new Dictionary<string, string>();


		public string? SelectedId { get; private set; }

		public string? SelectedName { get; private set; }

		public bool Skipped { get; private set; }

		public void Begin(long roomSequence, IReadOnlyList<string> candidateIds, PlayerStateSnapshot before, IReadOnlyDictionary<string, string>? candidateNames = null)
		{
			Open(roomSequence, before);
			CandidateIds = candidateIds.ToArray();
			CandidateNames = ((candidateNames == null) ? new Dictionary<string, string>() : new Dictionary<string, string>(candidateNames));
		}

		public void Select(string rewardId, string? rewardName = null)
		{
			SelectedId = rewardId;
			SelectedName = rewardName ?? CandidateNames.GetValueOrDefault(rewardId);
		}

		public void Skip()
		{
			Skipped = true;
		}

		public void RefreshCandidates(IReadOnlyList<string> candidateIds, IReadOnlyDictionary<string, string> candidateNames)
		{
			CandidateIds = candidateIds.ToArray();
			CandidateNames = new Dictionary<string, string>(candidateNames);
		}

		protected override void ResetDetails()
		{
			CandidateIds = Array.Empty<string>();
			CandidateNames = new Dictionary<string, string>();
			SelectedId = null;
			SelectedName = null;
			Skipped = false;
		}
	}
	public sealed record ShopItemSnapshot(string ItemId, string Kind, int SlotIndex, int Price, bool Purchased, string DisplayName = "", bool IsPremiumSlot = false, string Rarity = "");
	public sealed class ShopSession : NonCombatSession
	{
		public IReadOnlyList<ShopItemSnapshot> Items { get; private set; } = Array.Empty<ShopItemSnapshot>();


		public List<ShopItemSnapshot> Purchases { get; } = new List<ShopItemSnapshot>();


		public bool CardRemovalUsed { get; private set; }

		public string VisitKey { get; private set; } = "";


		public void Begin(long roomSequence, IReadOnlyList<ShopItemSnapshot> items, PlayerStateSnapshot before, string visitKey = "")
		{
			if (base.IsActive && base.RoomSequence == roomSequence && !string.IsNullOrWhiteSpace(visitKey) && string.Equals(VisitKey, visitKey, StringComparison.Ordinal))
			{
				Items = items.Select((ShopItemSnapshot i) => i.<Clone>$()).ToArray();
				return;
			}
			Open(roomSequence, before);
			VisitKey = visitKey;
			Items = items.Select((ShopItemSnapshot i) => i.<Clone>$()).ToArray();
		}

		public void Purchase(ShopItemSnapshot item)
		{
			ShopItemSnapshot purchased = item with
			{
				Purchased = true
			};
			Purchases.Add(purchased);
			Items = Items.Select((ShopItemSnapshot candidate) => (candidate.SlotIndex != purchased.SlotIndex || !(candidate.Kind == purchased.Kind) || !(candidate.ItemId == purchased.ItemId)) ? candidate : candidate with
			{
				Purchased = true
			}).ToArray();
		}

		public void MarkCardRemovalUsed()
		{
			CardRemovalUsed = true;
		}

		protected override void ResetDetails()
		{
			Items = Array.Empty<ShopItemSnapshot>();
			Purchases.Clear();
			CardRemovalUsed = false;
			VisitKey = "";
		}
	}
	public sealed class EventSession : NonCombatSession
	{
		public string ModelId { get; private set; } = "";


		public IReadOnlyList<string> OptionIds { get; private set; } = Array.Empty<string>();


		public string? SelectedOptionId { get; private set; }

		public PlayerStateSnapshot? LastChoiceAfter { get; private set; }

		public void Begin(long roomSequence, string modelId, IReadOnlyList<string> optionIds, PlayerStateSnapshot before)
		{
			Open(roomSequence, before);
			ModelId = modelId;
			OptionIds = optionIds.ToArray();
			LastChoiceAfter = null;
		}

		public void Select(string optionId)
		{
			SelectedOptionId = optionId;
		}

		public void RecordChoiceAfter(PlayerStateSnapshot after)
