	public sealed record PairCollectionProgress(string PairId, string SourceObservedIdentity, string TargetIdentity, long StartedAtNode, bool TimeoutEmitted, bool Completed);
	public enum PairCollectionDecision
	{
		None,
		Waiting,
		Completed,
		TimedOut
	}
	public sealed record PairCollectionResult(PairCollectionProgress? Progress, PairCollectionDecision Decision, CollectibleRef? MissingItem);
	public sealed record PairCollectionSnapshot(long CurrentNode, IReadOnlyList<PairCollectionProgress> Progress, IReadOnlyList<string> OwnedIdentities);
	public static class PairCollectionEvaluator
	{
		public const int TimeoutNodes = 20;

		public static PairCollectionResult OnObserved(CollectiblePairDefinition pair, PairCollectionProgress? progress, CollectibleObservation observation, IReadOnlySet<string> ownedBefore, long currentNode)
		{
			if ((object)progress != null && progress.Completed)
			{
				return new PairCollectionResult(progress, PairCollectionDecision.None, null);
			}
			bool flag = observation.Kind == CollectibleObservationKind.Obtained && pair.Target.Identity == observation.Item.Identity;
			if (progress != null && flag)
			{
				return new PairCollectionResult(progress with
				{
					Completed = true
				}, PairCollectionDecision.Completed, null);
			}
			if (progress != null)
			{
				return new PairCollectionResult(progress, PairCollectionDecision.None, null);
			}
			if (!pair.Source.Matches(observation))
			{
				return new PairCollectionResult(null, PairCollectionDecision.None, null);
			}
			if (ownedBefore.Contains(pair.Target.Identity))
			{
				return new PairCollectionResult(null, PairCollectionDecision.None, null);
			}
			return new PairCollectionResult(new PairCollectionProgress(pair.PairId, observation.Item.Identity, pair.Target.Identity, currentNode, TimeoutEmitted: false, Completed: false), PairCollectionDecision.Waiting, pair.Target);
		}

		public static PairCollectionResult OnNodeEnded(CollectiblePairDefinition pair, PairCollectionProgress? progress, long endedNode)
		{
			if (progress == null || progress.Completed || progress.TimeoutEmitted)
			{
				return new PairCollectionResult(progress, PairCollectionDecision.None, null);
			}
			if (endedNode - progress.StartedAtNode < 20)
			{
				return new PairCollectionResult(progress, PairCollectionDecision.None, null);
			}
			return new PairCollectionResult(progress with
			{
				TimeoutEmitted = true
			}, PairCollectionDecision.TimedOut, pair.Target);
		}
	}
	public sealed class PairCollectionState
	{
		private readonly IReadOnlyList<CollectiblePairDefinition> _definitions;

		private readonly Dictionary<string, PairCollectionProgress> _progress = new Dictionary<string, PairCollectionProgress>(StringComparer.Ordinal);

		private readonly HashSet<string> _owned = new HashSet<string>(StringComparer.Ordinal);

		public long CurrentNode { get; private set; }

		public IReadOnlyDictionary<string, PairCollectionProgress> Progress => _progress;

		public PairCollectionState(IReadOnlyList<CollectiblePairDefinition>? definitions = null)
		{
			_definitions = definitions ?? PowerfulCombos.All;
		}

		public void Begin(IEnumerable<CollectibleRef> initiallyOwned)
		{
			CurrentNode = 0L;
			_progress.Clear();
			_owned.Clear();
			foreach (CollectibleRef item in initiallyOwned)
			{
				_owned.Add(item.Identity);
			}
		}

		public void RestoreOwned(IEnumerable<CollectibleRef> currentlyOwned, long currentNode = 0L)
		{
			Begin(currentlyOwned);
			CurrentNode = Math.Max(0L, currentNode);
		}

		public void RestoreOwned(PlayerStateSnapshot snapshot, long currentNode = 0L)
		{
			HashSet<string> cards = snapshot.DeckCardIds.ToHashSet<string>(StringComparer.Ordinal);
			HashSet<string> relics = snapshot.StableRelicIds.ToHashSet<string>(StringComparer.Ordinal);
			RestoreOwned((from item in _definitions.SelectMany(delegate(CollectiblePairDefinition pair)
				{
					CollectibleRef? exactItem = pair.Source.ExactItem;
					if (!exactItem.HasValue)
					{
						return new CollectibleRef[1] { pair.Target };
					}
					CollectibleRef valueOrDefault = exactItem.GetValueOrDefault();
					return new CollectibleRef[2] { valueOrDefault, pair.Target };
				})
				where (item.Kind != 0) ? relics.Contains(item.ModelId) : cards.Contains(item.ModelId)
				select item).DistinctBy((CollectibleRef item) => item.Identity), currentNode);
		}

		public PairCollectionSnapshot Snapshot()
		{
			return new PairCollectionSnapshot(CurrentNode, _progress.Values.ToArray(), _owned.ToArray());
		}

		public void Restore(PairCollectionSnapshot snapshot)
		{
			CurrentNode = Math.Max(0L, snapshot.CurrentNode);
			_progress.Clear();
			_owned.Clear();
			HashSet<string> hashSet = _definitions.Select((CollectiblePairDefinition pair) => pair.PairId).ToHashSet<string>(StringComparer.Ordinal);
			foreach (PairCollectionProgress item in snapshot.Progress)
			{
				if (hashSet.Contains(item.PairId))
				{
					_progress[item.PairId] = item;
				}
			}
			foreach (string ownedIdentity in snapshot.OwnedIdentities)
			{
				if (!string.IsNullOrWhiteSpace(ownedIdentity))
				{
					_owned.Add(ownedIdentity);
				}
			}
		}

		public long BeginNode()
		{
			return ++CurrentNode;
		}

		public IReadOnlyList<(CollectiblePairDefinition Pair, PairCollectionResult Result)> Obtain(CollectibleRef item)
		{
			HashSet<string> ownedBefore = new HashSet<string>(_owned, StringComparer.Ordinal);
			_owned.Add(item.Identity);
			return Observe(new CollectibleObservation(CollectibleObservationKind.Obtained, item), ownedBefore);
		}

		public IReadOnlyList<(CollectiblePairDefinition Pair, PairCollectionResult Result)> ObserveEnchantedAttack(CollectibleRef card)
		{
			return Observe(new CollectibleObservation(CollectibleObservationKind.AttackEnchanted, card), new HashSet<string>(_owned, StringComparer.Ordinal));
		}

		private IReadOnlyList<(CollectiblePairDefinition Pair, PairCollectionResult Result)> Observe(CollectibleObservation observation, IReadOnlySet<string> ownedBefore)
		{
			List<(CollectiblePairDefinition, PairCollectionResult)> list = new List<(CollectiblePairDefinition, PairCollectionResult)>();
			foreach (CollectiblePairDefinition definition in _definitions)
			{
				_progress.TryGetValue(definition.PairId, out PairCollectionProgress value);
				PairCollectionResult pairCollectionResult = PairCollectionEvaluator.OnObserved(definition, value, observation, ownedBefore, CurrentNode);
				if (pairCollectionResult.Progress != null)
				{
					_progress[definition.PairId] = pairCollectionResult.Progress;
				}
				if (pairCollectionResult.Decision != 0)
				{
					list.Add((definition, pairCollectionResult));
				}
			}
			return list;
		}

		public IReadOnlyList<(CollectiblePairDefinition Pair, PairCollectionResult Result)> EndNode(long node)
		{
			List<(CollectiblePairDefinition, PairCollectionResult)> list = new List<(CollectiblePairDefinition, PairCollectionResult)>();
			foreach (CollectiblePairDefinition definition in _definitions)
			{
				_progress.TryGetValue(definition.PairId, out PairCollectionProgress value);
				PairCollectionResult pairCollectionResult = PairCollectionEvaluator.OnNodeEnded(definition, value, node);
				if (pairCollectionResult.Progress != null)
				{
					_progress[definition.PairId] = pairCollectionResult.Progress;
				}
				if (pairCollectionResult.Decision != 0)
				{
					list.Add((definition, pairCollectionResult));
				}
			}
			return list;
		}
	}
