	public sealed record RewardRuleInput(IReadOnlyList<string> CandidateIds, IReadOnlyDictionary<string, string> CandidateNames, string? SelectedId, string? SelectedName, bool Skipped, PlayerStateSnapshot Before, PlayerStateSnapshot After);
	public readonly record struct CardRuleEvaluation(ConditionResult Result, string CardId = "", string CardName = "");
	public static class RewardRuleEvaluators
	{
		public static class SkipRewardRuleEvaluators
		{
			public const int InitialProbability = 20;

			public const int ProbabilityStep = 10;

			public const int MaxProbability = 100;

			public static (bool Matched, string Reason, int NextProbability) Evaluate(bool skipped, int currentProbability, double roll)
			{
				int num = Math.Clamp(currentProbability, 0, 100);
				if (!skipped)
				{
					return (Matched: false, Reason: "card_reward_not_skipped", NextProbability: num);
				}
				double num2 = (double)num / 100.0;
				if (roll < num2)
				{
					return (Matched: true, Reason: "skip_card_reward_probability_hit", NextProbability: 20);
				}
				return (Matched: false, Reason: "skip_card_reward_probability_miss", NextProbability: Math.Min(100, num + 10));
			}
		}

		public static class CardObtainedRuleEvaluators
		{
			public static ConditionResult EvaluateDuplicate(int deckCountOfId)
			{
				if (deckCountOfId < 2)
				{
					return ConditionResult.Miss("card_not_already_in_deck");
				}
				return ConditionResult.Match("card_already_in_deck");
			}

			public static ConditionResult EvaluateKeyCard(string cardId, string characterId)
			{
				if (!SetRule.CardIs(cardId, CardSetKind.Key, characterId))
				{
					return ConditionResult.Miss("card_not_character_key");
				}
				return ConditionResult.Match("character_key_card_obtained");
			}

			public static ConditionResult EvaluateOverpoweredCard(string cardId)
			{
				if (!SetRule.CardIs(cardId, CardSetKind.Overpowered))
				{
					return ConditionResult.Miss("card_not_overpowered");
				}
				return ConditionResult.Match("overpowered_card_obtained");
			}

			public static ConditionResult EvaluateAttackDefenseCard(string cardId)
			{
				bool num = SetRule.CardIs(cardId, CardSetKind.Attack);
				bool flag = SetRule.CardIs(cardId, CardSetKind.Block);
				if (!(num && flag))
				{
					return ConditionResult.Miss("card_not_attack_and_block");
				}
				return ConditionResult.Match("attack_and_block_card_obtained");
			}
		}

		public const string ApotheosisId = "APOTHEOSIS";

		public static CardRuleEvaluation EvaluateDraftFutureCard(RewardRuleInput input)
		{
			return MatchSelected(input, input.Before.CurrentActIndex == 0 && SetRule.CardIs(input.SelectedId, CardSetKind.Future), (input.Before.CurrentActIndex == 0) ? "selected_card_not_future" : "outside_act_one", "act_one_future_card_selected");
		}

		public static CardRuleEvaluation EvaluateMissedKeyCard(RewardRuleInput input)
		{
			RewardRuleInput input2 = input;
			string text = input2.CandidateIds.FirstOrDefault((string cardId) => cardId != input2.SelectedId && IsDesirable(cardId, input2.Before.CharacterId));
			if (text != null)
			{
				return new CardRuleEvaluation(ConditionResult.Match("desirable_reward_card_missed"), text, DisplayName(input2, text));
			}
			return new CardRuleEvaluation(ConditionResult.Miss("no_desirable_reward_card_missed"));
		}

		public static CardRuleEvaluation EvaluateRejectFutureCard(RewardRuleInput input)
		{
			if (input.Before.CurrentActIndex != 0)
			{
				return new CardRuleEvaluation(ConditionResult.Miss("outside_act_one"));
			}
			string[] array = input.CandidateIds.Where((string cardId) => SetRule.CardIs(cardId, CardSetKind.Future)).ToArray();
			if (array.Length != 1)
			{
				return new CardRuleEvaluation(ConditionResult.Miss("future_candidate_count_not_one"));
			}
			if (!(array[0] == input.SelectedId))
			{
				return new CardRuleEvaluation(ConditionResult.Match("only_future_card_rejected"), array[0], DisplayName(input, array[0]));
			}
			return new CardRuleEvaluation(ConditionResult.Miss("only_future_card_selected"));
		}

		public static CardRuleEvaluation EvaluateFullApotheosis(RewardRuleInput input)
		{
			if (input.SelectedId == "APOTHEOSIS")
			{
				return Selected(input, ConditionResult.Match("apotheosis_selected"));
			}
			IReadOnlyList<CardStateSnapshot> stableCardStates = input.After.StableCardStates;
			if (stableCardStates.Count <= 0 || !stableCardStates.All((CardStateSnapshot card) => !card.Upgradable))
			{
				return new CardRuleEvaluation(ConditionResult.Miss("deck_not_fully_upgraded"));
			}
			return new CardRuleEvaluation(ConditionResult.Match("all_deck_cards_upgraded"));
		}

		public static ConditionResult EvaluateHardChoice(IReadOnlyList<string> candidateIds, string characterId)
		{
			string characterId2 = characterId;
			if (candidateIds.Count((string cardId) => IsDesirable(cardId, characterId2)) < 2)
			{
				return ConditionResult.Miss("fewer_than_two_desirable_reward_cards");
			}
			return ConditionResult.Match("multiple_desirable_reward_cards");
		}

		public static bool IsDesirable(string? cardId, string? characterId)
		{
			if (!SetRule.CardIs(cardId, CardSetKind.Key, characterId))
			{
				return SetRule.CardIs(cardId, CardSetKind.Overpowered);
			}
			return true;
		}

		private static CardRuleEvaluation MatchSelected(RewardRuleInput input, bool matched, string missReason, string matchReason)
		{
			if (input.SelectedId == null)
			{
				return new CardRuleEvaluation(ConditionResult.Miss("no_reward_card_selected"));
			}
			return Selected(input, matched ? ConditionResult.Match(matchReason) : ConditionResult.Miss(missReason));
		}

		private static CardRuleEvaluation Selected(RewardRuleInput input, ConditionResult result)
		{
			return new CardRuleEvaluation(result, input.SelectedId ?? "", input.SelectedName ?? DisplayName(input, input.SelectedId));
		}

		private static string DisplayName(RewardRuleInput input, string? cardId)
		{
			if (cardId != null)
			{
				return input.CandidateNames.GetValueOrDefault(cardId, cardId);
			}
			return "";
		}
	}
	public readonly record struct CardAppearanceThreshold(string CardId, string CardName, int PreviousCount, int CurrentCount);
	public static class CardAppearanceRuleEvaluator
	{
		public static int ThresholdFor(string rarity)
		{
			if (!(rarity == "Rare"))
			{
				if (rarity == "Uncommon")
				{
					return 4;
				}
				return 5;
			}
			return 3;
		}

		public static IReadOnlyList<CardAppearanceThreshold> Record(IDictionary<string, int> counts, IEnumerable<(string CardId, string CardName, string Rarity)> appearances, IReadOnlySet<string> ownedCardIds)
		{
			IReadOnlySet<string> ownedCardIds2 = ownedCardIds;
			List<CardAppearanceThreshold> list = new List<CardAppearanceThreshold>();
			foreach (IGrouping<string, (string, string, string)> item in appearances.Where<(string, string, string)>(((string CardId, string CardName, string Rarity) item) => !string.IsNullOrWhiteSpace(item.CardId) && !ownedCardIds2.Contains(item.CardId)).GroupBy<(string, string, string), string>(((string CardId, string CardName, string Rarity) item) => item.CardId, StringComparer.Ordinal))
			{
				int num = ThresholdFor(item.First().Item3);
				int value;
				int num2 = (counts.TryGetValue(item.Key, out value) ? Math.Max(0, value) : 0);
				int num3 = num2 + item.Count();
				counts[item.Key] = num3;
				if (num2 < num && num3 >= num)
				{
					list.Add(new CardAppearanceThreshold(item.Key, item.Select<(string, string, string), string>(((string CardId, string CardName, string Rarity) item) => item.CardName).FirstOrDefault((string name) => !string.IsNullOrWhiteSpace(name)) ?? item.Key, num2, num3));
				}
			}
			return list;
		}
	}
	public readonly record struct StrongMonsterEvaluation(ConditionResult Result, bool AClassMatched, bool BClassMatched, IReadOnlyList<string> MatchedMonsterIds);
	public readonly record struct VariantEvaluation(ConditionResult Result, string Variant = "");
	public readonly record struct CounterEvaluation(int Count, bool Counted, ConditionResult Result);
	public readonly record struct QueenDamageInput(bool QueenPresent, bool TorchHeadAlive, string TargetMonsterId, int TotalDamage, bool IsAttackCard, bool IsSingleEnemyTarget, bool AlreadyFired);
	public static class RuleBusinessEvaluators
	{
		public static ConditionResult EvaluateOverpoweredRelic(string relicId)
		{
			if (!ManualRelicSets.OverpoweredRelics.Contains(relicId))
			{
				return ConditionResult.Miss("obtained_relic_not_overpowered");
			}
			return ConditionResult.Match("obtained_overpowered_relic");
		}

		public static StrongMonsterEvaluation EvaluateStrongMonster(int actFloor, bool hasAoeCard, IReadOnlyList<string> monsterIds)
		{
			string[] source = monsterIds.Distinct<string>(StringComparer.Ordinal).ToArray();
			bool aClass = actFloor <= 2 && !hasAoeCard && source.Any(IsAClassStrongMonster);
			bool flag = source.Any(IsBClassStrongMonster);
			string[] matchedMonsterIds = source.Where((string id) => (aClass && IsAClassStrongMonster(id)) || IsBClassStrongMonster(id)).ToArray();
			return new StrongMonsterEvaluation((aClass || flag) ? ConditionResult.Match("strong_monster_encounter") : ConditionResult.Miss("strong_monster_condition_not_met"), aClass, flag, matchedMonsterIds);
		}

		public static ConditionResult EvaluateEncounteredBefore(IReadOnlyList<string> currentMonsterIds, IReadOnlySet<string> previouslyEncountered)
		{
			if (!currentMonsterIds.Any(previouslyEncountered.Contains))
			{
				return ConditionResult.Miss("monster_not_seen_in_previous_won_combat");
			}
			return ConditionResult.Match("monster_seen_in_previous_won_combat");
		}

		public static ConditionResult EvaluateLowHpElite(bool isElite, int currentHp, int maxHp)
		{
			if (!isElite)
			{
				return ConditionResult.Miss("room_not_elite");
			}
			if (maxHp <= 0)
			{
				return ConditionResult.Miss("max_hp_not_positive");
			}
			if (currentHp * 100 >= maxHp * 30)
			{
				return ConditionResult.Miss("hp_not_below_thirty_percent");
			}
			return ConditionResult.Match("low_hp_elite");
		}

		public static ConditionResult EvaluateStartupCard(string cardId)
		{
			if (!ManualCardSets.Startup.Contains(cardId))
			{
				return ConditionResult.Miss("card_not_startup");
			}
			return ConditionResult.Match("startup_card_played");
		}

		public static ConditionResult EvaluateSecondPotion(int potionUseCount, bool alreadyFired)
		{
			if (potionUseCount != 2 || alreadyFired)
			{
				return ConditionResult.Miss(alreadyFired ? "combat_binge_already_fired" : "potion_count_not_two");
			}
			return ConditionResult.Match("second_potion_used");
		}

		public static ConditionResult EvaluateDrawOverflow(int handCount, bool alreadyFired)
		{
			if (handCount < 10 || alreadyFired)
			{
				return ConditionResult.Miss(alreadyFired ? "draw_overflow_already_fired" : "hand_below_limit");
			}
			return ConditionResult.Match("hand_reached_limit_after_draw");
		}

		public static ConditionResult EvaluateStreakBreak(bool isStreakCombat, bool alreadyFired, int hpLost)
		{
			if (hpLost <= 0)
			{
				return ConditionResult.Miss("enemy_damage_dealt_no_hp_loss");
			}
			if (!isStreakCombat)
			{
				return ConditionResult.Miss("combat_not_streak_break_candidate");
			}
			if (!alreadyFired)
			{
				return ConditionResult.Match("first_enemy_damage_in_streak_combat");
			}
			return ConditionResult.Miss("streak_break_already_fired");
		}

		public static CounterEvaluation EvaluateExperimentHit(int currentHits, int totalDamage, bool isIntangible, bool alreadyFired)
		{
			if (alreadyFired)
			{
				return new CounterEvaluation(currentHits, Counted: false, ConditionResult.Miss("experiment_threshold_already_fired"));
			}
			if (!CombatRuleEvaluators.ShouldCountExperimentHit(totalDamage, isIntangible))
			{
				return new CounterEvaluation(currentHits, Counted: false, ConditionResult.Miss("experiment_hit_not_counted"));
			}
			int num = Math.Max(0, currentHits) + 1;
			return new CounterEvaluation(num, Counted: true, (num == 5) ? ConditionResult.Match("fifth_positive_hit_while_intangible") : ConditionResult.Miss("experiment_hit_threshold_not_reached"));
		}

		public static VariantEvaluation EvaluateCounterMatch(string cardId, int baseReplayCount, int enemyCount, string? targetMonsterId)
		{
			if (CardCategories.Aoe.Contains(cardId) && enemyCount >= 3)
			{
				return new VariantEvaluation(ConditionResult.Match("aoe_against_at_least_three_enemies"), "aoe");
			}
			if ((baseReplayCount < 3 && !CardCategories.MultiHit.Contains(cardId)) || !(targetMonsterId == "EXOSKELETON"))
			{
				return new VariantEvaluation(ConditionResult.Miss("counter_match_condition_not_met"));
			}
			return new VariantEvaluation(ConditionResult.Match("multihit_against_exoskeleton"), "exoskeleton");
		}

		public static ConditionResult EvaluateQueenTorchheadKill(bool queenPresent, string monsterId, bool alreadyFired)
		{
			if (!queenPresent || !(monsterId == "TORCH_HEAD_AMALGAM") || alreadyFired)
			{
				return ConditionResult.Miss("queen_torchhead_condition_not_met");
			}
			return ConditionResult.Match("torch_head_killed_in_queen_combat");
		}

		public static ConditionResult EvaluateQueenDamage(QueenDamageInput input)
		{
			if (!input.QueenPresent)
			{
				return ConditionResult.Miss("queen_not_present");
			}
			if (!input.TorchHeadAlive)
			{
				return ConditionResult.Miss("torch_head_not_alive");
			}
			if (!input.IsAttackCard)
			{
				return ConditionResult.Miss("damage_not_from_attack_card");
			}
			if (!input.IsSingleEnemyTarget)
			{
				return ConditionResult.Miss("attack_not_single_enemy_target");
			}
			if (input.TargetMonsterId != "QUEEN")
			{
				return ConditionResult.Miss("damage_target_not_queen");
			}
			if (input.TotalDamage <= 0)
			{
				return ConditionResult.Miss("queen_received_no_positive_damage");
			}
			if (input.AlreadyFired)
			{
				return ConditionResult.Miss("queen_damage_already_fired_this_turn");
			}
			return ConditionResult.Match("queen_hit_by_single_target_attack_while_torch_head_alive");
		}

		public static ConditionResult EvaluateSculptorChant(string monsterId, string moveId, bool alreadyRecorded)
		{
			if (!(monsterId == "DEVOTED_SCULPTOR") || !(moveId == "FORBIDDEN_INCANTATION_MOVE") || alreadyRecorded)
			{
				return ConditionResult.Miss("sculptor_chant_condition_not_met");
			}
			return ConditionResult.Match("forbidden_incantation_performed");
		}

		public static ConditionResult EvaluateSmallDeck(string changeKind, int deckCount)
		{
			if (!(changeKind == "removed") || deckCount > 10)
			{
				return ConditionResult.Miss((changeKind == "removed") ? "small_deck_above_threshold" : "small_deck_not_removal");
			}
			return ConditionResult.Match("small_deck_card_removed");
		}

		private static bool IsAClassStrongMonster(string entry)
		{
			switch (entry)
			{
			default:
				return entry.StartsWith("DECIMILLIPEDE_SEGMENT", StringComparison.Ordinal);
			case "PHROG_PARASITE":
			case "TERROR_EEL":
			case "EXOSKELETON":
				return true;
			}
		}

		private static bool IsBClassStrongMonster(string entry)
		{
			switch (entry)
			{
			default:
				return entry == "INFESTED_PRISM";
			case "BYRDONIS":
			case "LIVING_FOG":
			case "SKULKING_COLONY":
				return true;
			}
		}
	}
