	public static class SetRule
	{
		public static bool Contains(IReadOnlySet<string> set, string? modelId)
		{
			if (!string.IsNullOrEmpty(modelId))
			{
				return set.Contains(modelId);
			}
			return false;
		}

		public static bool ContainsAny(IReadOnlySet<string> set, IEnumerable<string> modelIds)
		{
