		public static bool CardIs(string? cardId, CardSetKind kind, string? characterId = null)
		{
			if (string.IsNullOrEmpty(cardId))
			{
				return false;
			}
			return kind switch
			{
				CardSetKind.Attack => CardCategories.Attack.Contains(cardId), 
				CardSetKind.Block => CardCategories.Block.Contains(cardId), 
				CardSetKind.Draw => CardCategories.Draw.Contains(cardId), 
				CardSetKind.Aoe => CardCategories.Aoe.Contains(cardId), 
				CardSetKind.MultiHit => CardCategories.MultiHit.Contains(cardId), 
				CardSetKind.XCost => CardCategories.XCost.Contains(cardId), 
				CardSetKind.Startup => ManualCardSets.Startup.Contains(cardId), 
				CardSetKind.Future => ManualCardSets.Future.Contains(cardId), 
				CardSetKind.Overpowered => ManualCardSets.Overpowered.Contains(cardId), 
				CardSetKind.Key => ManualCardSets.KeyCardsFor(characterId).Contains(cardId), 
				_ => throw new ArgumentOutOfRangeException("kind", kind, "未知卡牌集合"), 
			};
		}
