	public enum NumericOperator
	{
		Equal,
		GreaterThan,
		GreaterThanOrEqual,
		LessThan,
		LessThanOrEqual
	}
	public static class NumericRule
	{
		public static bool Compare(decimal actual, NumericOperator op, decimal expected)
		{
			return op switch
			{
				NumericOperator.Equal => actual == expected, 
				NumericOperator.GreaterThan => actual > expected, 
				NumericOperator.GreaterThanOrEqual => actual >= expected, 
				NumericOperator.LessThan => actual < expected, 
				NumericOperator.LessThanOrEqual => actual <= expected, 
				_ => throw new ArgumentOutOfRangeException("op", op, "未知数值运算符"), 
			};
		}

		public static bool Ratio(int numerator, int denominator, NumericOperator op, decimal expected)
		{
			if (denominator > 0)
			{
				return Compare((decimal)numerator / (decimal)denominator, op, expected);
			}
			return false;
		}

		public static bool InClosedRange(decimal actual, decimal minimum, decimal maximum)
		{
			if (minimum > maximum)
			{
				throw new ArgumentException("区间下限不得大于上限");
			}
			if (actual >= minimum)
			{
				return actual <= maximum;
			}
			return false;
		}
	}
	public readonly record struct ConditionResult(bool Matched, string ReasonCode)
	{
		public static ConditionResult Match(string reasonCode)
		{
			return new ConditionResult(Matched: true, reasonCode);
		}

		public static ConditionResult Miss(string reasonCode)
		{
			return new ConditionResult(Matched: false, reasonCode);
		}
	}
	public readonly record struct RuleVariant(string Name, int Priority, ConditionResult Result);
	public static class ConditionRule
	{
		public static ConditionResult All(string matchedReason, params ConditionResult[] conditions)
		{
			for (int i = 0; i < conditions.Length; i++)
			{
				ConditionResult result = conditions[i];
				if (!result.Matched)
				{
					return result;
				}
			}
			return ConditionResult.Match(matchedReason);
		}

		public static ConditionResult Any(string missedReason, params ConditionResult[] conditions)
		{
			for (int i = 0; i < conditions.Length; i++)
			{
				ConditionResult result = conditions[i];
				if (result.Matched)
				{
					return result;
				}
			}
			return ConditionResult.Miss(missedReason);
		}

		public static ConditionResult Not(ConditionResult condition, string matchedReason, string missedReason)
		{
			if (!condition.Matched)
			{
				return ConditionResult.Match(matchedReason);
			}
			return ConditionResult.Miss(missedReason);
		}

		public static RuleVariant? HighestPriority(IEnumerable<RuleVariant> variants)
		{
			return (from v in variants
				where v.Result.Matched
				orderby v.Priority descending
				select v).ThenBy<RuleVariant, string>((RuleVariant v) => v.Name, StringComparer.Ordinal).Cast<RuleVariant?>().FirstOrDefault();
		}
	}
	public sealed class RuleContext : IReadOnlyDictionary<string, string>, IEnumerable<KeyValuePair<string, string>>, IEnumerable, IReadOnlyCollection<KeyValuePair<string, string>>
	{
		private readonly IReadOnlyDictionary<string, string> _context;

		public IReadOnlyDictionary<string, string> Context => _context;

		public IReadOnlyDictionary<string, string> Refs { get; }

		public string this[string key] => _context[key];

		public IEnumerable<string> Keys => _context.Keys;

		public IEnumerable<string> Values => _context.Values;

		public int Count => _context.Count;

		public RuleContext(IReadOnlyDictionary<string, string> context, IReadOnlyDictionary<string, string> refs)
		{
			_context = context;
			Refs = refs;
		}

		public bool ContainsKey(string key)
		{
			return _context.ContainsKey(key);
		}

		public bool TryGetValue(string key, out string value)
		{
			return _context.TryGetValue(key, out value);
		}

		public IEnumerator<KeyValuePair<string, string>> GetEnumerator()
		{
			return _context.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public static IReadOnlyDictionary<string, string> ResolveRefs(IReadOnlyDictionary<string, string> refs)
		{
			if (refs.Count == 0)
			{
				return new Dictionary<string, string>(0);
			}
			Dictionary<string, string> dictionary = new Dictionary<string, string>(refs.Count, StringComparer.Ordinal);
			foreach (KeyValuePair<string, string> @ref in refs)
			{
				if (NetworkContextRefs.TryResolve(@ref, out KeyValuePair<string, string> resolved))
				{
					dictionary[resolved.Key] = resolved.Value;
				}
			}
			return dictionary;
		}
	}
	public sealed class RuleContextBuilder
	{
		private readonly Dictionary<string, string> _values = new Dictionary<string, string>(StringComparer.Ordinal);

		private readonly Dictionary<string, string> _refs = new Dictionary<string, string>(StringComparer.Ordinal);

		public RuleContextBuilder Card(string officialChineseName)
