		public RuleContextBuilder ItemReference(string officialChineseName, string modelId, string kind)
		{
			_values["item"] = CollectibleAlias.DisplayName(officialChineseName);
			string text = (kind.Equals("card", StringComparison.OrdinalIgnoreCase) ? "card" : (kind.Equals("relic", StringComparison.OrdinalIgnoreCase) ? "relic" : "item"));
