	public static class RuleDispatchFactory
	{
		public static (DanmakuSignal Signal, RuleEvidence Evidence) Create(DanmakuTrigger trigger, EventId eventId, TimingPhase phase, ConditionResult result, IReadOnlyDictionary<string, string>? snapshot = null, IReadOnlyDictionary<string, string>? context = null, string variant = "")
		{
			RuleEvidence item = new RuleEvidence(eventId, result.ReasonCode, snapshot ?? new Dictionary<string, string>(), phase, variant);
			DanmakuSignal danmakuSignal = new DanmakuSignal(trigger, context, variant);
			if (context is RuleContext ruleContext)
			{
				danmakuSignal = danmakuSignal with
