	public sealed record RuleAuditRecord(long Sequence, EventId EventId, DanmakuTrigger Trigger, string RuleId, string Variant, TimingPhase Phase, string ReasonCode, IReadOnlyDictionary<string, string> Snapshot, RuleDecision Decision, string SuppressionReason);
	public sealed class RuleDiagnostics
	{
		private const int Capacity = 2000;

		private readonly Queue<RuleAuditRecord> _records = new Queue<RuleAuditRecord>();

		private readonly HashSet<string> _eventAccepted = new HashSet<string>();

		private readonly Dictionary<string, int> _turnCounts = new Dictionary<string, int>();

		private readonly Dictionary<string, int> _combatCounts = new Dictionary<string, int>();

		private readonly Action<RuleAuditRecord>? _logger;

		private readonly bool _loggingEnabled;

		private long _sequence;

		public static RuleDiagnostics Instance { get; } = new RuleDiagnostics(null, loggingEnabled: false);


		public IReadOnlyList<RuleAuditRecord> Snapshot => _records.ToArray();

		public event Action<RuleAuditRecord>? AuditRecorded;

		public RuleDiagnostics(Action<RuleAuditRecord>? logger = null, bool loggingEnabled = true)
		{
			_logger = logger;
			_loggingEnabled = loggingEnabled;
		}

		public IReadOnlyList<RuleAuditRecord> Since(long sequence)
		{
			return _records.Where((RuleAuditRecord r) => r.Sequence > sequence).ToArray();
		}

		public void Clear()
		{
			_records.Clear();
			_eventAccepted.Clear();
			_turnCounts.Clear();
			_combatCounts.Clear();
		}

		public void RecordNotMatched(DanmakuTrigger trigger, RuleEvidence evidence)
		{
			Record(trigger, evidence, RuleDecision.NotMatched, "");
		}

		public void BeginCombat()
		{
			_eventAccepted.Clear();
			_turnCounts.Clear();
			_combatCounts.Clear();
		}

		public void BeginTurn()
		{
			_eventAccepted.Clear();
			_turnCounts.Clear();
		}

		public bool TryAccept(DanmakuTrigger trigger, RuleEvidence evidence)
		{
			RulePolicy rulePolicy = RulePolicies.Get(trigger);
			string value = (rulePolicy.ScopeByVariant ? evidence.Variant : "");
			string text = $"{trigger}:{value}";
			string item = $"{evidence.EventId}:{text}";
			string text2 = "";
			if (rulePolicy.MaxPerEvent > 0 && _eventAccepted.Contains(item))
			{
				text2 = "duplicate_event";
			}
			else
			{
				int? maxPerTurn = rulePolicy.MaxPerTurn;
				if (maxPerTurn.HasValue)
				{
					int valueOrDefault = maxPerTurn.GetValueOrDefault();
					if (_turnCounts.GetValueOrDefault(text) >= valueOrDefault)
					{
						text2 = "turn_limit";
						goto IL_010b;
					}
				}
				maxPerTurn = rulePolicy.MaxPerCombat;
				if (maxPerTurn.HasValue)
				{
					int valueOrDefault2 = maxPerTurn.GetValueOrDefault();
					if (_combatCounts.GetValueOrDefault(text) >= valueOrDefault2)
					{
						text2 = "combat_limit";
					}
				}
			}
			goto IL_010b;
			IL_010b:
			bool flag = text2.Length == 0;
			if (flag)
			{
				_eventAccepted.Add(item);
				_turnCounts[text] = _turnCounts.GetValueOrDefault(text) + 1;
				_combatCounts[text] = _combatCounts.GetValueOrDefault(text) + 1;
			}
			Record(trigger, evidence, flag ? RuleDecision.Accepted : RuleDecision.Suppressed, text2);
			return flag;
		}

		private void Record(DanmakuTrigger trigger, RuleEvidence evidence, RuleDecision decision, string suppression)
		{
			SortedDictionary<string, string> sortedDictionary = new SortedDictionary<string, string>();
			foreach (KeyValuePair<string, string> item in evidence.Snapshot)
			{
				sortedDictionary[item.Key] = item.Value;
			}
			RuleAuditRecord ruleAuditRecord = new RuleAuditRecord(++_sequence, evidence.EventId, trigger, DanmakuRuleIds.Get(trigger), evidence.Variant, evidence.Phase, evidence.ReasonCode, sortedDictionary, decision, suppression);
			if (_records.Count >= 2000)
			{
				_records.Dequeue();
			}
			_records.Enqueue(ruleAuditRecord);
			if (this.AuditRecorded != null)
			{
				Delegate[] invocationList = this.AuditRecorded.GetInvocationList();
				for (int i = 0; i < invocationList.Length; i++)
				{
					Action<RuleAuditRecord> action = (Action<RuleAuditRecord>)invocationList[i];
					try
					{
						action(ruleAuditRecord);
					}
					catch (Exception value)
					{
						try
						{
							MainFile.Log($"[RuleAudit] 审计观察者异常: {value}");
						}
						catch
						{
						}
					}
				}
			}
			if (_logger != null)
			{
				_logger(ruleAuditRecord);
			}
			else if (_loggingEnabled)
			{
				try
				{
					MainFile.Log("[RuleAudit] " + JsonSerializer.Serialize(ruleAuditRecord));
				}
				catch
				{
					MainFile.Log($"[RuleAudit] {trigger} {ruleAuditRecord.Decision} {suppression}");
				}
			}
		}
	}
