	public sealed class RuleFactConsumer<TFact> : IDisposable where TFact : IGameFact
	{
		private readonly DanmakuTrigger _trigger;

		private readonly TimingPhase _phase;

		private readonly Func<TFact, SessionCloseKind> _closeKind;

		private readonly bool _requireLocalPlayer;

		private readonly Action<RuleConsumptionContext<TFact>> _consume;

		private readonly IDisposable _subscription;

		public RuleFactConsumer(GameFactBus bus, DanmakuTrigger trigger, TimingPhase phase, Action<RuleConsumptionContext<TFact>> consume, bool requireLocalPlayer = false, Func<TFact, SessionCloseKind>? closeKind = null)
		{
			ArgumentNullException.ThrowIfNull(bus, "bus");
			ArgumentNullException.ThrowIfNull(consume, "consume");
			_trigger = trigger;
			_phase = phase;
			_consume = consume;
			_requireLocalPlayer = requireLocalPlayer || LocalPlayerFactKinds.IsLocalPlayerFact(typeof(TFact));
			_closeKind = closeKind ?? ((Func<TFact, SessionCloseKind>)((TFact _) => SessionCloseKind.None));
			RuleFactRegistry.RequireBinding(trigger, typeof(TFact), phase);
			_subscription = bus.Subscribe<TFact>(OnFact);
		}

		private void OnFact(TFact fact)
		{
			GameContextStore instance = GameContextStore.Instance;
			if (instance == null)
			{
				RecordRejected(fact, "context_store_unavailable");
				return;
			}
			ConditionResult conditionResult = RuleLifecycleGate.Evaluate(fact.Header, ModRunState.CurrentLifecycle, _phase, PoolManager.IsPhaseActive(_phase), _closeKind(fact), _requireLocalPlayer);
			if (!conditionResult.Matched)
			{
				RecordRejected(fact, conditionResult.ReasonCode);
			}
			else
			{
				_consume(new RuleConsumptionContext<TFact>(fact, RuleFactRegistry.RequireBinding(_trigger, typeof(TFact), _phase), instance, ModRunState.CurrentLifecycle));
			}
		}

		private void RecordRejected(TFact fact, string reasonCode)
		{
			RuleDiagnostics.Instance.RecordNotMatched(_trigger, new RuleEvidence(fact.Header.EventId, reasonCode, new Dictionary<string, string>
			{
				["factType"] = typeof(TFact).Name,
				["flowState"] = fact.Header.FlowState.ToString(),
				["scope"] = fact.Header.Scope.ToString()
			}, _phase));
		}

		public void Dispose()
		{
			_subscription.Dispose();
		}
	}
	public sealed class RuleConsumerGroup : IDisposable
	{
		private readonly List<IDisposable> _consumers = new List<IDisposable>();

		private bool _disposed;

		public T Add<T>(T consumer) where T : IDisposable
		{
			if (_disposed)
			{
				throw new ObjectDisposedException("RuleConsumerGroup");
			}
			_consumers.Add(consumer);
			return consumer;
		}

		public void Dispose()
		{
			if (_disposed)
			{
				return;
			}
			_disposed = true;
			foreach (IDisposable consumer in _consumers)
			{
				consumer.Dispose();
			}
			_consumers.Clear();
		}
	}
