	public sealed record RuleFactRegistration(DanmakuTrigger Trigger, IReadOnlyList<RuleFactBinding> Bindings, RuleImplementationStatus Status)
	{
		public Type? FactType => Bindings.FirstOrDefault()?.FactType;

		public TimingPhase? Phase => Bindings.FirstOrDefault()?.Phase;

		public IReadOnlyList<string> RequiredContexts => Bindings.SelectMany((RuleFactBinding b) => b.RequiredContexts).Distinct().ToArray();

		public bool Implemented => Status == RuleImplementationStatus.Ready;

		public bool Consumes(Type factType, TimingPhase phase)
		{
			Type factType2 = factType;
			return Bindings.Any((RuleFactBinding b) => b.FactType == factType2 && b.Phase == phase);
		}
	}
	public static class RuleFactRegistry
	{
		private static readonly IReadOnlyDictionary<DanmakuTrigger, RuleFactRegistration> Registrations = Build();

		public static IReadOnlyList<RuleFactRegistration> All => Registrations.Values.OrderBy((RuleFactRegistration r) => r.Trigger).ToArray();

		public static RuleFactRegistration Get(DanmakuTrigger trigger)
		{
			if (!Registrations.TryGetValue(trigger, out RuleFactRegistration value))
			{
				throw new ArgumentOutOfRangeException("trigger", trigger, "规则尚未登记公共事实依赖");
			}
			return value;
		}

		public static RuleFactBinding RequireBinding(DanmakuTrigger trigger, Type factType, TimingPhase phase)
		{
			Type factType2 = factType;
			return Get(trigger).Bindings.FirstOrDefault((RuleFactBinding b) => b.FactType == factType2 && b.Phase == phase) ?? throw new InvalidOperationException($"{trigger} 未登记消费 {factType2.Name}/{phase}");
		}

		private static IReadOnlyDictionary<DanmakuTrigger, RuleFactRegistration> Build()
		{
			Dictionary<DanmakuTrigger, List<RuleFactBinding>> dictionary = new Dictionary<DanmakuTrigger, List<RuleFactBinding>>();
			Add(dictionary, typeof(CombatStartedFact), TimingPhase.CombatStart, new global::<>z__ReadOnlyArray<string>(new string[3] { "Run", "Room", "Combat" }), DanmakuTrigger.StrongMonster, DanmakuTrigger.LowHpElite, DanmakuTrigger.EliteStreak, DanmakuTrigger.EncounteredBefore);
			Add(dictionary, typeof(HandDrawCompletedFact), TimingPhase.Combat, new global::<>z__ReadOnlyArray<string>(new string[2] { "Combat", "Turn" }), DanmakuTrigger.DefenseLack, DanmakuTrigger.OffenseLack);
