	public readonly record struct ThresholdTransition(int Previous, int Current, int Threshold, int? Step = null)
	{
		public bool Reached
		{
			get
			{
				if (Previous < Threshold)
				{
					return Current >= Threshold;
				}
				return false;
			}
		}

		public IReadOnlyList<int> CrossedSteps()
		{
			int? step = Step;
			if (!step.HasValue || step.GetValueOrDefault() <= 0 || Current <= Previous)
			{
				return Array.Empty<int>();
			}
			int num = Math.Max(Threshold, (Previous / Step.Value + 1) * Step.Value);
			if (num % Step.Value != 0)
			{
				num += Step.Value - num % Step.Value;
			}
			List<int> list = new List<int>();
			for (int i = num; i <= Current; i += Step.Value)
			{
				list.Add(i);
			}
			return list;
		}
	}
	public sealed class ThresholdGate
	{
		private bool _reached;

		private int _lastValue;

		public bool TryReach(int current, int threshold)
		{
			bool result = !_reached && current >= threshold;
			_reached |= current >= threshold;
			_lastValue = current;
			return result;
		}

		public IReadOnlyList<int> RecordSteps(int current, int firstThreshold, int step)
		{
			ThresholdTransition thresholdTransition = new ThresholdTransition(_lastValue, current, firstThreshold, step);
			_lastValue = current;
			return thresholdTransition.CrossedSteps();
		}

		public void Reset(int initialValue = 0)
		{
			_reached = false;
			_lastValue = initialValue;
		}
	}
	public sealed class ScopedCounter<TKey> where TKey : notnull
	{
		private readonly Dictionary<(string Scope, TKey Key), int> _counts = new Dictionary<(string, TKey), int>();

		public int Increment(string scope, TKey key, int amount = 1)
		{
			ArgumentException.ThrowIfNullOrEmpty(scope, "scope");
			if (amount < 0)
			{
				throw new ArgumentOutOfRangeException("amount");
			}
			(string, TKey) key2 = (scope, key);
			int num = _counts.GetValueOrDefault(key2) + amount;
			_counts[key2] = num;
			return num;
		}

		public int Get(string scope, TKey key)
		{
			return _counts.GetValueOrDefault((scope, key));
		}

		public void ResetScope(string scope)
		{
			string scope2 = scope;
			(string, TKey)[] array = _counts.Keys.Where<(string, TKey)>(((string Scope, TKey Key) k) => k.Scope == scope2).ToArray();
			foreach ((string, TKey) key in array)
			{
				_counts.Remove(key);
			}
		}

		public void Clear()
		{
			_counts.Clear();
		}
	}
	public readonly record struct ConsecutiveCounter(int Count)
	{
		public ConsecutiveCounter Record(bool succeeded)
		{
			return new ConsecutiveCounter(succeeded ? (Count + 1) : 0);
		}

		public bool Reached(int threshold)
		{
			if (threshold > 0)
			{
				return Count >= threshold;
			}
			return false;
		}
	}
	public readonly record struct BigDeckGateState(int Countdown)
	{
		public (BigDeckGateState State, bool Matched) RecordAddedCards(int addedCount, int deckCount)
		{
			if (addedCount <= 0)
			{
				return (State: this, Matched: false);
			}
			int num = Countdown - addedCount;
			if (deckCount > 40 && num <= 0)
			{
				return (State: new BigDeckGateState(5), Matched: true);
			}
			return (State: new BigDeckGateState(num), Matched: false);
		}
	}
	public sealed class DwellWindow
	{
		private double? _startedAt;

		public bool Fired { get; private set; }

		public ConditionResult Observe(bool active, double nowSeconds, double requiredSeconds)
		{
			if (requiredSeconds < 0.0)
			{
				throw new ArgumentOutOfRangeException("requiredSeconds");
			}
			if (!active)
			{
				_startedAt = null;
				Fired = false;
				return ConditionResult.Miss("window_inactive");
			}
			double valueOrDefault = _startedAt.GetValueOrDefault();
			if (!_startedAt.HasValue)
			{
				valueOrDefault = nowSeconds;
				_startedAt = valueOrDefault;
			}
			if (Fired)
			{
				return ConditionResult.Miss("window_already_fired");
			}
			if (nowSeconds - _startedAt.Value < requiredSeconds)
			{
				return ConditionResult.Miss("window_threshold_not_reached");
			}
			Fired = true;
			return ConditionResult.Match("window_threshold_reached");
		}

		public void Reset()
		{
			_startedAt = null;
			Fired = false;
		}
	}
