		}
	}
	public sealed record RunPersistenceDocument(string RunIdentity, RunPersistentState State);
	public sealed record RunLaunchState(string Identity, bool IsLoaded, RunPersistentState? PersistentState);
	public static class RunPersistenceCoordinator
	{
		private static readonly JsonSerializerOptions JsonOptions = new JsonSerializerOptions
		{
			WriteIndented = true
		};

		private static string? _pendingLoadIdentity;

		private static bool _started;

		public static void Start()
		{
			if (!_started)
			{
				_started = true;
				SaveManager.Instance.Saved += PersistActive;
			}
		}

		public static void Stop()
		{
			if (_started)
			{
				PersistActive();
				SaveManager.Instance.Saved -= PersistActive;
				_pendingLoadIdentity = null;
				_started = false;
			}
		}

		public static void MarkLoaded(SerializableRun save)
		{
			_pendingLoadIdentity = CreateIdentity(save);
		}

		public static RunLaunchState ConsumeLaunch(RunState state)
		{
			string identity;
			try
			{
				identity = CreateIdentity(RunManager.Instance.ToSave((AbstractRoom)null));
			}
			catch (Exception ex)
			{
				identity = $"profile:{SafeProfileId()}:seed:{state.Rng.StringSeed}";
				MainFile.Log("[RunState] 无法读取完整 Run 身份，使用种子后备身份：" + ex.GetType().Name);
			}
			bool num = _pendingLoadIdentity != null;
			if (num)
			{
				identity = _pendingLoadIdentity;
			}
			_pendingLoadIdentity = null;
			if (!num)
			{
				DeleteStoredState();
				return new RunLaunchState(identity, IsLoaded: false, null);
			}
			return new RunLaunchState(identity, IsLoaded: true, TryLoad(identity));
		}

		public static void PersistActive()
		{
			RunContext runContext = GameContextStore.Instance?.Run;
			if (runContext == null || !runContext.IsActive || string.IsNullOrEmpty(runContext.LoadIdentity))
			{
				return;
			}
			try
			{
				string statePath = GetStatePath();
				Directory.CreateDirectory(Path.GetDirectoryName(statePath));
				string text = statePath + ".tmp";
				File.WriteAllText(text, JsonSerializer.Serialize(new RunPersistenceDocument(runContext.LoadIdentity, runContext.ExportPersistentState()), JsonOptions));
				File.Move(text, statePath, overwrite: true);
			}
			catch (Exception value)
			{
				MainFile.Log($"[RunState] 保存模组 Run 状态失败：{value}");
			}
		}

		public static void DeleteStoredState()
		{
			try
			{
				string statePath = GetStatePath();
				if (File.Exists(statePath))
				{
					File.Delete(statePath);
				}
				if (File.Exists(statePath + ".tmp"))
				{
					File.Delete(statePath + ".tmp");
				}
			}
			catch (Exception value)
			{
				MainFile.Log($"[RunState] 清理模组 Run 状态失败：{value}");
			}
		}

		private static RunPersistentState? TryLoad(string identity)
		{
			try
			{
				string statePath = GetStatePath();
				if (!File.Exists(statePath))
				{
					return null;
				}
				RunPersistenceDocument runPersistenceDocument = JsonSerializer.Deserialize<RunPersistenceDocument>(File.ReadAllText(statePath), JsonOptions);
				if (runPersistenceDocument == null || runPersistenceDocument.RunIdentity != identity)
				{
					MainFile.Log("[RunState] 模组状态身份不匹配，本次继续游戏从空状态开始。");
					return null;
				}
				RunPersistentState runPersistentState = UpgradeCompatibleState(runPersistenceDocument.State);
				if (runPersistentState == null)
				{
					MainFile.Log($"[RunState] 不支持模组状态版本 {runPersistenceDocument.State.SchemaVersion}，本次继续游戏从空状态开始。");
					return null;
				}
				if (runPersistenceDocument.State.SchemaVersion != runPersistentState.SchemaVersion)
				{
					MainFile.Log($"[RunState] 已把模组状态 v{runPersistenceDocument.State.SchemaVersion} 兼容迁移到 v{runPersistentState.SchemaVersion}。");
				}
				return runPersistentState;
			}
			catch (Exception value)
			{
				MainFile.Log($"[RunState] 读取模组 Run 状态失败，本次从空状态开始：{value}");
				return null;
			}
		}

		public static RunPersistentState? UpgradeCompatibleState(RunPersistentState? state)
		{
			if (state == null)
			{
				return null;
			}
			if (state.SchemaVersion == 6)
			{
				return state with
				{
					UgcShuffleBags = (state.UgcShuffleBags ?? Array.Empty<UgcShuffleBagSnapshot>())
				};
			}
			if (state.SchemaVersion == 5)
			{
				return state with
				{
					SchemaVersion = 6,
					UgcShuffleBags = Array.Empty<UgcShuffleBagSnapshot>()
				};
			}
			return null;
		}

		private static string CreateIdentity(SerializableRun save)
		{
			DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(21, 3);
			defaultInterpolatedStringHandler.AppendLiteral("profile:");
			defaultInterpolatedStringHandler.AppendFormatted(SafeProfileId());
			defaultInterpolatedStringHandler.AppendLiteral(":start:");
			defaultInterpolatedStringHandler.AppendFormatted(save.StartTime);
			defaultInterpolatedStringHandler.AppendLiteral(":seed:");
			SerializableRunRngSet serializableRng = save.SerializableRng;
			defaultInterpolatedStringHandler.AppendFormatted(((serializableRng != null) ? serializableRng.Seed : null) ?? string.Empty);
			return defaultInterpolatedStringHandler.ToStringAndClear();
		}

		private static int SafeProfileId()
		{
			try
			{
				return SaveManager.Instance.CurrentProfileId;
			}
			catch
			{
				return -1;
			}
		}

		private static string GetStatePath()
