	public static class RuntimeAuditCursor
	{
		private static readonly object Gate = new object();

		private static long _ruleSequence;

		private static long _factSequence;

		public static RuntimeAuditCursorSnapshot Position
		{
			get
			{
				lock (Gate)
				{
					return new RuntimeAuditCursorSnapshot(_ruleSequence, _factSequence);
				}
			}
		}

		public static DanmakuRuntimeAuditSnapshot ReadAndAdvance()
		{
			lock (Gate)
			{
				DanmakuRuntimeAuditSnapshot danmakuRuntimeAuditSnapshot = RuntimeAuditQuery.Capture(_ruleSequence, _factSequence);
				if (danmakuRuntimeAuditSnapshot.RuleAudit.Count > 0)
				{
					_ruleSequence = danmakuRuntimeAuditSnapshot.RuleAudit.Max((RuleAuditRecord item) => item.Sequence);
				}
				if (danmakuRuntimeAuditSnapshot.FactAudit.Count > 0)
				{
					_factSequence = danmakuRuntimeAuditSnapshot.FactAudit.Max((FactAuditRecord item) => item.Sequence);
				}
				return danmakuRuntimeAuditSnapshot;
			}
		}

		public static RuntimeAuditCursorSnapshot Reset()
		{
			lock (Gate)
			{
				_ruleSequence = 0L;
				_factSequence = 0L;
				return Position;
			}
		}

		public static RuntimeAuditCursorSnapshot MarkCurrent()
		{
			lock (Gate)
			{
				_ruleSequence = RuleDiagnostics.Instance.Snapshot.LastOrDefault()?.Sequence ?? _ruleSequence;
				_factSequence = GameFactBus.Instance.AuditSnapshot.LastOrDefault()?.Sequence ?? _factSequence;
				return Position;
			}
		}
	}
	public static class RuntimeAuditQuery
	{
		public static DanmakuRuntimeAuditSnapshot Capture(long afterRuleSequence = 0L, long afterFactSequence = 0L)
		{
			RuleReadinessSnapshot[] array = (from item in RuleFactRegistry.All
				where item.Status != RuleImplementationStatus.Meta
				select new RuleReadinessSnapshot(DanmakuRuleIds.Get(item.Trigger), item.Trigger.ToString(), item.Status, item.Bindings.Select((RuleFactBinding binding) => binding.FactType.Name).Distinct().ToArray())).OrderBy<RuleReadinessSnapshot, string>((RuleReadinessSnapshot item) => item.RuleId, StringComparer.Ordinal).ToArray();
			HashSet<string> businessTriggers = array.Select((RuleReadinessSnapshot item) => item.Trigger).ToHashSet<string>(StringComparer.Ordinal);
			DanmakuEntry[] array2 = DanmakuLibrary.Groups.Where<KeyValuePair<DanmakuTrigger, DanmakuGroup>>((KeyValuePair<DanmakuTrigger, DanmakuGroup> pair) => businessTriggers.Contains(pair.Key.ToString())).SelectMany((KeyValuePair<DanmakuTrigger, DanmakuGroup> pair) => pair.Value.Entries).ToArray();
			return new DanmakuRuntimeAuditSnapshot(DateTimeOffset.UtcNow, DanmakuRuleCatalog.All.Count, array.Length, array2.Length, array2.Count((DanmakuEntry entry) => entry.Style == DanmakuTextStyle.Character), array2.Count((DanmakuEntry entry) => entry.Style == DanmakuTextStyle.Narration), array, HarmonyPatchRuntimeState.Status, RuleDiagnostics.Instance.Since(afterRuleSequence), GameFactBus.Instance.AuditSince(afterFactSequence));
		}

		public static string CaptureJson(long afterRuleSequence = 0L, long afterFactSequence = 0L)
		{
			return JsonSerializer.Serialize(Capture(afterRuleSequence, afterFactSequence));
		}
	}
	public sealed class RunContext
	{
		public long Sequence { get; private set; }

		public bool IsActive { get; private set; }

		public string LoadIdentity { get; private set; } = "";


		public int NoDamageStreak { get; set; }

		public bool StrongMonsterTriggered { get; set; }

		public HashSet<string> EncounteredMonsterTypes { get; } = new HashSet<string>();


		public HashSet<string> KilledMonsterTypes { get; } = new HashSet<string>();


		public Dictionary<string, int> CardAppearanceCount { get; } = new Dictionary<string, int>();


		public int BigDeckCountdown { get; set; }

		public int UpgradeStreak { get; set; }

		public bool CloneEnchantmentSeen { get; set; }

		public Dictionary<int, HashSet<string>> EliteNodeKeysByAct { get; } = new Dictionary<int, HashSet<string>>();


		public HashSet<string> ObservedShopVisitKeys { get; } = new HashSet<string>(StringComparer.Ordinal);


		public PairCollectionState PairCollections { get; } = new PairCollectionState();


		public int SkipRewardProbability { get; set; } = 20;


		internal void Begin(long sequence, string loadIdentity)
		{
			Sequence = sequence;
			IsActive = true;
			LoadIdentity = loadIdentity;
			NoDamageStreak = 0;
			StrongMonsterTriggered = false;
			BigDeckCountdown = 0;
			UpgradeStreak = 0;
			CloneEnchantmentSeen = false;
			SkipRewardProbability = 20;
			EncounteredMonsterTypes.Clear();
			KilledMonsterTypes.Clear();
			CardAppearanceCount.Clear();
			EliteNodeKeysByAct.Clear();
			ObservedShopVisitKeys.Clear();
			PairCollections.Begin(Array.Empty<CollectibleRef>());
		}

		internal void End()
		{
			IsActive = false;
			LoadIdentity = "";
		}

		public RunContextSnapshot Snapshot()
		{
			return new RunContextSnapshot(Sequence, IsActive, LoadIdentity, NoDamageStreak, StrongMonsterTriggered, BigDeckCountdown, CloneEnchantmentSeen, EncounteredMonsterTypes.ToArray(), KilledMonsterTypes.ToArray(), new Dictionary<string, int>(CardAppearanceCount));
		}

		public RunPersistentState ExportPersistentState()
		{
			return new RunPersistentState(6, NoDamageStreak, StrongMonsterTriggered, BigDeckCountdown, UpgradeStreak, CloneEnchantmentSeen, SkipRewardProbability, EncounteredMonsterTypes.ToArray(), KilledMonsterTypes.ToArray(), new Dictionary<string, int>(CardAppearanceCount), EliteNodeKeysByAct.ToDictionary<KeyValuePair<int, HashSet<string>>, int, IReadOnlyList<string>>((KeyValuePair<int, HashSet<string>> pair) => pair.Key, (KeyValuePair<int, HashSet<string>> pair) => pair.Value.ToArray()), ObservedShopVisitKeys.ToArray(), PairCollections.Snapshot(), UgcRuntime.Instance?.SnapshotShuffleBags() ?? Array.Empty<UgcShuffleBagSnapshot>());
		}

		internal void Restore(RunPersistentState state)
		{
			NoDamageStreak = Math.Max(0, state.NoDamageStreak);
			StrongMonsterTriggered = state.StrongMonsterTriggered;
			BigDeckCountdown = Math.Max(0, state.BigDeckCountdown);
			UpgradeStreak = Math.Max(0, state.UpgradeStreak);
			CloneEnchantmentSeen = state.CloneEnchantmentSeen;
			SkipRewardProbability = Math.Clamp(state.SkipRewardProbability, 20, 100);
			EncounteredMonsterTypes.UnionWith(state.EncounteredMonsterTypes);
			KilledMonsterTypes.UnionWith(state.KilledMonsterTypes);
			foreach (KeyValuePair<string, int> item in state.CardAppearanceCount)
			{
				if (!string.IsNullOrWhiteSpace(item.Key) && item.Value > 0)
				{
					CardAppearanceCount[item.Key] = item.Value;
				}
			}
			foreach (KeyValuePair<int, IReadOnlyList<string>> item2 in state.EliteNodeKeysByAct)
			{
				EliteNodeKeysByAct[item2.Key] = item2.Value.Where((string key) => !string.IsNullOrWhiteSpace(key)).ToHashSet<string>(StringComparer.Ordinal);
			}
			ObservedShopVisitKeys.UnionWith(state.ObservedShopVisitKeys.Where((string key) => !string.IsNullOrWhiteSpace(key)));
			PairCollections.Restore(state.PairCollections);
		}
	}
	public sealed record RunContextSnapshot(long Sequence, bool IsActive, string LoadIdentity, int NoDamageStreak, bool StrongMonsterTriggered, int BigDeckCountdown, bool CloneEnchantmentSeen, IReadOnlyList<string> EncounteredMonsterTypes, IReadOnlyList<string> KilledMonsterTypes, IReadOnlyDictionary<string, int> CardAppearanceCount);
	public sealed class RoomContext
	{
		public long Sequence { get; private set; }

		public bool IsActive { get; private set; }

		public string Kind { get; private set; } = "";


		public string CloseReason { get; private set; } = "";


		public bool WasInterrupted { get; private set; }

		internal void Enter(long sequence, string kind)
		{
			if (IsActive)
			{
				Close("replaced_without_leaving", interrupted: true);
			}
			Sequence = sequence;
			IsActive = true;
			Kind = kind;
			CloseReason = "";
			WasInterrupted = false;
		}

		internal void Leave(long sequence, string reason)
		{
			if (IsActive && Sequence == sequence)
			{
				Close(reason, reason != "next_room_entered" && reason != "completed");
			}
		}

		internal void Reset()
		{
			Sequence = 0L;
			IsActive = false;
			Kind = "";
			CloseReason = "";
			WasInterrupted = false;
		}

		private void Close(string reason, bool interrupted)
		{
			IsActive = false;
			CloseReason = reason;
			WasInterrupted = interrupted;
		}

		public RoomContextSnapshot Snapshot()
		{
			return new RoomContextSnapshot(Sequence, IsActive, Kind, CloseReason, WasInterrupted);
		}
	}
	public sealed record RoomContextSnapshot(long Sequence, bool IsActive, string Kind, string CloseReason, bool WasInterrupted);
	public sealed class CombatContext
	{
		public long Sequence { get; private set; }

		public bool IsActive { get; private set; }

		public int EnemyCountAtStart { get; private set; }

		public bool? Won { get; private set; }

		public int LocalPlayerHpLost { get; private set; }

		public int LocalCardsPlayed { get; private set; }

		public int LocalCardsDrawn { get; private set; }

		public int ConfirmedCreatureDeaths { get; private set; }

		public bool DamagedByEnemy { get; private set; }

		internal void Begin(long sequence, int enemyCount)
		{
			Sequence = sequence;
			IsActive = true;
			EnemyCountAtStart = enemyCount;
			Won = null;
			LocalPlayerHpLost = 0;
			LocalCardsPlayed = 0;
			LocalCardsDrawn = 0;
			ConfirmedCreatureDeaths = 0;
			DamagedByEnemy = false;
		}

		internal void Record(CardPlayedFact fact)
		{
			if (Matches(fact.Header))
			{
				LocalCardsPlayed++;
			}
		}

		internal void Record(CardDrawnFact fact)
		{
			if (Matches(fact.Header))
			{
				LocalCardsDrawn++;
			}
		}

		internal void Record(DamageResolvedFact fact)
		{
			if (Matches(fact.Header) && fact.Header.Boundary == FactBoundary.LocalPlayer)
			{
				LocalPlayerHpLost += Math.Max(0, fact.HpLost);
			}
		}

		internal void Record(CreatureDeathConfirmedFact fact)
		{
			if (Matches(fact.Header))
			{
				ConfirmedCreatureDeaths++;
			}
		}

		internal void End(long sequence, bool won, bool damagedByEnemy)
		{
			if (IsActive && Sequence == sequence)
			{
				IsActive = false;
				Won = won;
				DamagedByEnemy = damagedByEnemy;
			}
		}

		internal void Reset()
		{
			Sequence = 0L;
			IsActive = false;
			EnemyCountAtStart = 0;
			Won = null;
			LocalPlayerHpLost = 0;
			LocalCardsPlayed = 0;
			LocalCardsDrawn = 0;
			ConfirmedCreatureDeaths = 0;
			DamagedByEnemy = false;
		}

		private bool Matches(GameFactHeader header)
		{
			if (IsActive)
			{
				return header.EventId.CombatSequence == Sequence;
			}
			return false;
		}

		public CombatContextSnapshot Snapshot()
		{
			return new CombatContextSnapshot(Sequence, IsActive, EnemyCountAtStart, Won, LocalPlayerHpLost, LocalCardsPlayed, LocalCardsDrawn, ConfirmedCreatureDeaths, DamagedByEnemy);
		}
	}
	public sealed record CombatContextSnapshot(long Sequence, bool IsActive, int EnemyCountAtStart, bool? Won, int LocalPlayerHpLost, int LocalCardsPlayed, int LocalCardsDrawn, int ConfirmedCreatureDeaths, bool DamagedByEnemy);
	public sealed class TurnContext
	{
		public long Sequence { get; private set; }

		public bool IsActive { get; private set; }

		public bool IsPlayerTurn { get; private set; }

		public bool EndTurnRequested { get; private set; }

