		public IReadOnlyList<string> OpeningHandCardIds { get; private set; } = Array.Empty<string>();


		public bool EnemyIntendsToAttackAtOpening { get; private set; }

		internal void Begin(long sequence, bool isPlayerTurn)
		{
			if (isPlayerTurn || !IsActive || Sequence != sequence)
			{
				Sequence = sequence;
				EndTurnRequested = false;
				EnemyTurnCompleted = false;
				OpeningHandCardIds = Array.Empty<string>();
				EnemyIntendsToAttackAtOpening = false;
			}
			IsActive = true;
			IsPlayerTurn = isPlayerTurn;
		}

		internal void Record(HandDrawCompletedFact fact)
		{
			if (Matches(fact.Header))
			{
				OpeningHandCardIds = fact.HandCardIds.ToArray();
				EnemyIntendsToAttackAtOpening = fact.EnemyIntendsToAttack;
			}
		}

		internal void RequestEnd(long sequence)
		{
			if (IsActive && Sequence == sequence)
			{
				EndTurnRequested = true;
			}
		}

		internal void CompleteEnemyTurn(long sequence)
		{
			if (IsActive && Sequence == sequence)
			{
				EnemyTurnCompleted = true;
				IsActive = false;
			}
		}

		internal void Reset()
		{
			Sequence = 0L;
			IsActive = false;
			IsPlayerTurn = false;
			EndTurnRequested = false;
			EnemyTurnCompleted = false;
			OpeningHandCardIds = Array.Empty<string>();
			EnemyIntendsToAttackAtOpening = false;
		}

		private bool Matches(GameFactHeader header)
		{
			if (IsActive)
			{
				return header.EventId.TurnSequence == Sequence;
			}
			return false;
		}

		public TurnContextSnapshot Snapshot()
		{
			return new TurnContextSnapshot(Sequence, IsActive, IsPlayerTurn, EndTurnRequested, EnemyTurnCompleted, OpeningHandCardIds.ToArray(), EnemyIntendsToAttackAtOpening);
		}
	}
