	public sealed record CardStateChange(CardStateSnapshot Before, CardStateSnapshot After);
	public sealed record RulePlayerSnapshot(PlayerStateSnapshot State, IReadOnlyList<CardStateSnapshot> Cards)
	{
		public static RulePlayerSnapshot Empty { get; } = new RulePlayerSnapshot(PlayerStateSnapshot.Empty, Array.Empty<CardStateSnapshot>());


		public RulePlayerSnapshot Copy()
		{
			return new RulePlayerSnapshot(State.Copy(), Cards.Select((CardStateSnapshot c) => c.<Clone>$()).ToArray());
		}

		[CompilerGenerated]
		private RulePlayerSnapshot(RulePlayerSnapshot original)
		{
			State = original.State;
