	public sealed record RulePlayerDiff(PlayerStateDiff State, IReadOnlyList<CardStateSnapshot> AddedCardStates, IReadOnlyList<CardStateSnapshot> RemovedCardStates, IReadOnlyList<CardStateChange> Upgrades, IReadOnlyList<CardStateChange> EnchantmentChanges)
	{
		private sealed record CardMatch(CardStateSnapshot? Before, CardStateSnapshot? After);

		public static RulePlayerDiff Between(RulePlayerSnapshot before, RulePlayerSnapshot after)
		{
			IReadOnlyList<CardMatch> source = MatchCards(before.Cards, after.Cards);
			CardStateSnapshot[] addedCardStates = (from m in source
				where m.Before == null
				select m.After.<Clone>$()).ToArray();
			CardStateSnapshot[] removedCardStates = (from m in source
				where m.After == null
				select m.Before.<Clone>$()).ToArray();
			CardStateChange[] upgrades = (from m in source
				where m.Before != null && m.After != null && m.Before.UpgradeLevel != m.After.UpgradeLevel
				select new CardStateChange(m.Before.<Clone>$(), m.After.<Clone>$())).ToArray();
			CardStateChange[] enchantmentChanges = (from m in source
				where m.Before != null && m.After != null && (m.Before.EnchantmentId != m.After.EnchantmentId || m.Before.EnchantmentAmount != m.After.EnchantmentAmount)
				select new CardStateChange(m.Before.<Clone>$(), m.After.<Clone>$())).ToArray();
			return new RulePlayerDiff(PlayerStateDiff.Between(before.State, after.State), addedCardStates, removedCardStates, upgrades, enchantmentChanges);
		}

		private static IReadOnlyList<CardMatch> MatchCards(IReadOnlyList<CardStateSnapshot> before, IReadOnlyList<CardStateSnapshot> after)
		{
			List<CardMatch> list = new List<CardMatch>();
			foreach (string cardId in before.Select((CardStateSnapshot c) => c.CardId).Concat(after.Select((CardStateSnapshot c) => c.CardId)).Distinct())
			{
				List<CardStateSnapshot> old = before.Where((CardStateSnapshot c) => c.CardId == cardId).ToList();
				List<CardStateSnapshot> list2 = after.Where((CardStateSnapshot c) => c.CardId == cardId).ToList();
				int i;
				for (i = old.Count - 1; i >= 0; i--)
				{
					int num = list2.FindIndex((CardStateSnapshot c) => SameState(old[i], c));
					if (num >= 0)
					{
						list.Add(new CardMatch(old[i], list2[num]));
						old.RemoveAt(i);
						list2.RemoveAt(num);
					}
				}
				while (old.Count > 0 && list2.Count > 0)
				{
					(int, int, int) tuple = (0, 0, int.MaxValue);
					for (int j = 0; j < old.Count; j++)
					{
						for (int k = 0; k < list2.Count; k++)
						{
							int num2 = StateDistance(old[j], list2[k]);
							if (num2 < tuple.Item3)
							{
								tuple = (j, k, num2);
							}
						}
					}
					list.Add(new CardMatch(old[tuple.Item1], list2[tuple.Item2]));
					old.RemoveAt(tuple.Item1);
					list2.RemoveAt(tuple.Item2);
				}
				list.AddRange(old.Select((CardStateSnapshot c) => new CardMatch(c, null)));
				list.AddRange(list2.Select((CardStateSnapshot c) => new CardMatch(null, c)));
			}
			return list;
		}

		private static bool SameState(CardStateSnapshot left, CardStateSnapshot right)
		{
			if (left.UpgradeLevel == right.UpgradeLevel && left.EnchantmentId == right.EnchantmentId)
			{
				return left.EnchantmentAmount == right.EnchantmentAmount;
			}
			return false;
		}

		private static int StateDistance(CardStateSnapshot left, CardStateSnapshot right)
		{
			return Math.Abs(left.UpgradeLevel - right.UpgradeLevel) + ((!(left.EnchantmentId == right.EnchantmentId)) ? 1000 : 0) + (int)Math.Min(999m, Math.Abs(left.EnchantmentAmount - right.EnchantmentAmount));
		}
	}
	public static class RuleLifecycleGate
	{
		public static ConditionResult Evaluate(GameFactHeader header, FlowLifecycle current, TimingPhase expectedPhase, bool phaseActive, SessionCloseKind closeKind = SessionCloseKind.None, bool requireLocalPlayer = false)
		{
			if (!LifecyclePolicy.IsCurrent(header.Lifecycle, current, header.Scope))
			{
				return ConditionResult.Miss("stale_lifecycle");
			}
			if (!phaseActive)
			{
				return ConditionResult.Miss("inactive_rule_phase");
			}
			if (requireLocalPlayer && header.Boundary != FactBoundary.LocalPlayer)
			{
				return ConditionResult.Miss("not_local_player_fact");
			}
			if ((uint)(closeKind - 3) <= 2u)
			{
				return ConditionResult.Miss("session_interrupted");
			}
			return ConditionResult.Match(expectedPhase.ToString().ToLowerInvariant() + "_lifecycle_current");
		}
	}
	public readonly record struct RestSiteRuleInput(string OptionId, int CurrentHpBefore, int MaxHpBefore, bool HasMiniatureTent);
	public static class RestSiteRuleEvaluators
	{
		public const string HealOptionId = "HEAL";

		public const string MiniatureTentId = "MINIATURE_TENT";

		public static ConditionResult EvaluateSleep(RestSiteRuleInput input)
		{
			if (!(input.OptionId == "HEAL"))
			{
				return ConditionResult.Miss("rest_site_heal_not_selected");
			}
			return ConditionResult.Match("rest_site_heal_selected");
		}

		public static ConditionResult EvaluateFullHpSleep(RestSiteRuleInput input)
		{
			if (!(input.OptionId == "HEAL") || input.MaxHpBefore <= 0 || input.CurrentHpBefore < input.MaxHpBefore)
			{
				return ConditionResult.Miss("rest_site_full_hp_sleep_condition_not_met");
			}
			return ConditionResult.Match("rest_site_heal_selected_at_full_hp");
		}

		public static ConditionResult EvaluateLowHpSkippedRest(RestSiteRuleInput input)
		{
			if (input.HasMiniatureTent)
			{
				return ConditionResult.Miss("miniature_tent_exempts_skipped_rest");
			}
			if (input.MaxHpBefore <= 0 || input.CurrentHpBefore * 100 >= input.MaxHpBefore * 30)
			{
				return ConditionResult.Miss("hp_not_below_thirty_percent");
			}
			if (!(input.OptionId != "HEAL"))
			{
				return ConditionResult.Miss("low_hp_rest_site_heal_selected");
			}
			return ConditionResult.Match("low_hp_rest_site_heal_skipped");
		}
	}
	public static class ScrollOfBitingRuleEvaluators
	{
		public static ConditionResult EvaluateMaxHpLoss(bool scrollPresent, int oldMaxHp, int newMaxHp)
		{
			if (!scrollPresent || newMaxHp >= oldMaxHp)
			{
				return ConditionResult.Miss("scroll_max_hp_loss_condition_not_met");
			}
			return ConditionResult.Match("scroll_of_biting_reduced_local_max_hp");
		}

		public static ConditionResult EvaluateProtected(bool scrollPresent, bool maxHpLost, bool combatWon)
		{
			if (!(scrollPresent && !maxHpLost && combatWon))
			{
				return ConditionResult.Miss("scroll_max_hp_protection_condition_not_met");
			}
			return ConditionResult.Match("scroll_combat_won_without_max_hp_loss");
		}
	}
	public sealed record EliteStreakEvaluation(int Count, bool Added, ConditionResult Result);
	public static class EliteStreakRuleEvaluator
	{
		public const int RequiredEliteRooms = 3;

		public static EliteStreakEvaluation Evaluate(RunNodeSnapshot? node, IReadOnlySet<string> visitedEliteNodes)
		{
			if (node == null || !string.Equals(node.PointType, "Elite", StringComparison.OrdinalIgnoreCase))
			{
				return new EliteStreakEvaluation(visitedEliteNodes.Count, Added: false, ConditionResult.Miss("not_elite_room"));
			}
			if (visitedEliteNodes.Contains(node.StableKey))
			{
				return new EliteStreakEvaluation(visitedEliteNodes.Count, Added: false, ConditionResult.Miss("elite_node_already_counted"));
			}
			int num = visitedEliteNodes.Count + 1;
			return new EliteStreakEvaluation(num, Added: true, (num == 3) ? ConditionResult.Match("third_distinct_elite_room_in_act") : ConditionResult.Miss("elite_streak_threshold_not_reached"));
		}
	}
	public sealed record ConsecutiveRuleEvaluation(int Count, bool Ignored, ConditionResult Result);
	public static class NoDamageStreakRuleEvaluator
	{
		public const int FirstMilestone = 5;

		public const int MilestoneStep = 2;

		public static ConsecutiveRuleEvaluation Evaluate(int current, bool won, bool damagedByEnemy)
		{
			int num = ((won && !damagedByEnemy) ? (Math.Max(0, current) + 1) : 0);
			bool flag = num >= 5 && (num - 5) % 2 == 0;
			return new ConsecutiveRuleEvaluation(num, Ignored: false, flag ? ConditionResult.Match("no_damage_combat_streak_milestone") : ConditionResult.Miss((won && !damagedByEnemy) ? "no_damage_streak_milestone_not_reached" : "combat_not_won_without_enemy_damage"));
		}
	}
	public static class UpgradeStreakRuleEvaluator
	{
		public const int RequiredUpgrades = 3;

		public static ConsecutiveRuleEvaluation Evaluate(int current, bool upgradedCard, bool hasMiniatureTent)
		{
			if (hasMiniatureTent)
			{
				return new ConsecutiveRuleEvaluation(Math.Max(0, current), Ignored: true, ConditionResult.Miss("miniature_tent_exempts_upgrade_streak"));
			}
			int num = (upgradedCard ? (Math.Max(0, current) + 1) : 0);
			return new ConsecutiveRuleEvaluation(num, Ignored: false, (num == 3) ? ConditionResult.Match("third_consecutive_rest_site_upgrade") : ConditionResult.Miss(upgradedCard ? "upgrade_streak_threshold_not_reached" : "rest_site_non_upgrade_resets_streak"));
		}
	}
	public enum TimingPhase
	{
		Run,
		CombatStart,
		Combat,
		TurnEnd,
		Reward,
		Shop,
		RestSite,
		Event,
		Map
	}
}
namespace DanmakuSpire.DanmakuSpireCode.Core.Multiplayer
{
	public sealed class ZzzDanmakuHandshakeMessage : INetMessage, IPacketSerializable
	{
		private const int MaxVersionLength = 64;

		public string ModVersion = "";

		public bool ShouldBroadcast => true;

		public NetTransferMode Mode => (NetTransferMode)2;

		public LogLevel LogLevel => (LogLevel)0;

		public bool ShouldBuffer => true;

		public bool Corrupt { get; private set; }

		public void Serialize(PacketWriter writer)
		{
			writer.WriteString(ModVersion);
		}

		public void Deserialize(PacketReader reader)
		{
			try
			{
				ModVersion = reader.ReadString();
				if (ModVersion.Length > 64)
				{
					Corrupt = true;
					ModVersion = "";
				}
			}
			catch (Exception)
			{
				Corrupt = true;
				ModVersion = "";
			}
		}
	}
	public sealed class ZzzDanmakuNetMessage : INetMessage, IPacketSerializable
	{
		public const int MaxContextRefCount = 16;

		private const int MaxStringLength = 512;

		public int Trigger;

		public int EntryIndex = -1;

		public string Variant = "";

		public string SourceCharacterId = "";

		public ulong SourcePlayerNetId;

		public string CorrelationId = "";

		public int Scope;

		public IReadOnlyList<KeyValuePair<string, string>> ContextRefs = Array.Empty<KeyValuePair<string, string>>();

		public bool ShouldBroadcast => true;

		public NetTransferMode Mode => (NetTransferMode)1;

		public LogLevel LogLevel => (LogLevel)0;

		public bool ShouldBuffer => false;

		public bool Corrupt { get; private set; }

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(Trigger, 32);
			writer.WriteInt(EntryIndex, 32);
			writer.WriteInt(Scope, 32);
			writer.WriteULong(SourcePlayerNetId, 64);
			writer.WriteString(Variant);
			writer.WriteString(SourceCharacterId);
			writer.WriteString(CorrelationId);
			IReadOnlyList<KeyValuePair<string, string>> readOnlyList = NetworkContextRefs.PrepareForSend(ContextRefs, 16);
			writer.WriteInt(readOnlyList.Count, 32);
			for (int i = 0; i < readOnlyList.Count; i++)
			{
				writer.WriteString(readOnlyList[i].Key);
				writer.WriteString(readOnlyList[i].Value);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			try
			{
				Trigger = reader.ReadInt(32);
				EntryIndex = reader.ReadInt(32);
				Scope = reader.ReadInt(32);
				SourcePlayerNetId = reader.ReadULong(64);
				Variant = ReadSafeString(reader);
				SourceCharacterId = ReadSafeString(reader);
				CorrelationId = ReadSafeString(reader);
				int num = reader.ReadInt(32);
				if ((num < 0 || num > 16) ? true : false)
				{
					Corrupt = true;
					ContextRefs = Array.Empty<KeyValuePair<string, string>>();
					return;
				}
				List<KeyValuePair<string, string>> list = new List<KeyValuePair<string, string>>(num);
				HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
				for (int i = 0; i < num; i++)
				{
					string key = ReadSafeString(reader);
					string value = ReadSafeString(reader);
					if (!NetworkContextRefs.TryNormalize(key, value, out KeyValuePair<string, string> normalized) || !hashSet.Add(normalized.Key))
					{
						Corrupt = true;
						list.Clear();
						break;
					}
					list.Add(normalized);
				}
				ContextRefs = list;
			}
			catch (Exception)
			{
				Corrupt = true;
				ContextRefs = Array.Empty<KeyValuePair<string, string>>();
			}
		}

		private static string ReadSafeString(PacketReader reader)
		{
			string text = reader.ReadString();
			if (text.Length <= 512)
			{
				return text;
			}
			return "";
		}
	}
	public sealed class DanmakuNetworkForwarder : INetworkForwarder
	{
		private enum IncomingMessageKind
		{
			Rule,
			Ugc,
			Chat
		}

		private const int CorrelationDedupeCapacity = 4096;

		private const int MaxMessagesPerSenderPerSecond = 40;

		private const int RateWindowSeconds = 1;

		private readonly object _sync = new object();

		private readonly HashSet<(ulong SenderId, string CorrelationId)> _seenCorrelations = new HashSet<(ulong, string)>();

		private readonly Queue<(ulong SenderId, string CorrelationId)> _correlationOrder = new Queue<(ulong, string)>();

		private readonly Dictionary<ulong, Queue<DateTimeOffset>> _globalRateBuckets = new Dictionary<ulong, Queue<DateTimeOffset>>();

		private readonly Dictionary<(ulong SenderId, IncomingMessageKind Kind), Queue<DateTimeOffset>> _rateBuckets = new Dictionary<(ulong, IncomingMessageKind), Queue<DateTimeOffset>>();

		private INetGameService? _netService;

		private MessageHandlerDelegate<ZzzDanmakuNetMessage>? _messageHandler;

		private MessageHandlerDelegate<ZzzDanmakuHandshakeMessage>? _handshakeHandler;

		private MessageHandlerDelegate<ZzzDanmakuChatMessage>? _chatHandler;

		private MessageHandlerDelegate<ZzzDanmakuUgcMessage>? _ugcHandler;

		private bool _attached;

		private DateTimeOffset _lastHandshakeRetry = DateTimeOffset.MinValue;

		private DateTimeOffset _lastHandshakeReply = DateTimeOffset.MinValue;

		private bool _sendFailureLogged;

		public static DanmakuNetworkForwarder Instance { get; } = new DanmakuNetworkForwarder();


		public void EnsureAttached(INetGameService? netService)
		{
			//IL_0060: Unknown result type (might be due to invalid IL or missing references)
			lock (_sync)
			{
				if (netService == null)
				{
					DetachCore();
					return;
				}
				if (_attached && _netService == netService)
				{
					RetryHandshakeIfNeeded();
					return;
				}
				DetachCore();
				_netService = netService;
				string text = $"挂接网络服务：Type={netService.Type}, IsConnected={netService.IsConnected}, NetId={netService.NetId}。";
				MainFile.Log("[Multiplayer] " + text);
				_messageHandler = OnDanmakuMessage;
				_handshakeHandler = OnHandshake;
				_chatHandler = OnChatMessage;
				_ugcHandler = OnUgcMessage;
				try
				{
					netService.RegisterMessageHandler<ZzzDanmakuNetMessage>(_messageHandler);
					netService.RegisterMessageHandler<ZzzDanmakuHandshakeMessage>(_handshakeHandler);
					netService.RegisterMessageHandler<ZzzDanmakuChatMessage>(_chatHandler);
					netService.RegisterMessageHandler<ZzzDanmakuUgcMessage>(_ugcHandler);
					_attached = true;
					_lastHandshakeRetry = DateTimeOffset.MinValue;
					TrySend(new ZzzDanmakuHandshakeMessage
					{
						ModVersion = DanmakuMultiplayerState.ModVersion
					});
				}
				catch (Exception value)
				{
					MainFile.Log($"[Multiplayer] 网络消息注册失败，多人弹幕不可用：{value}");
					_attached = false;
					_netService = null;
				}
			}
		}

		public void Shutdown()
		{
			lock (_sync)
			{
				DetachCore();
			}
		}

		public void Forward(DanmakuSignal signal)
		{
			if (signal.Channel != DanmakuChannel.Multiplayer || !DanmakuMultiplayerState.IsMultiplayerSession || !DanmakuModConfig.ShouldEmitMultiplayer() || !DanmakuModConfig.ShouldForwardMultiplayer())
			{
				return;
			}
			RunManager instance = RunManager.Instance;
			EnsureAttached((instance != null) ? instance.NetService : null);
			lock (_sync)
			{
				if (!_attached || _netService == null)
				{
					return;
				}
				if (!DanmakuMultiplayerState.HasCompatiblePeers)
				{
					RetryHandshakeIfNeeded();
					return;
				}
				ZzzDanmakuNetMessage message = new ZzzDanmakuNetMessage
				{
					Trigger = (int)signal.Trigger,
					EntryIndex = (int)((signal.EntryIndex >= 0 && signal.EntryIndex <= int.MaxValue) ? signal.EntryIndex : (-1)),
					Variant = signal.Variant,
					SourceCharacterId = signal.SourceCharacterId,
					SourcePlayerNetId = DanmakuMultiplayerState.LocalPlayerNetId,
					CorrelationId = signal.CorrelationId,
					Scope = (int)signal.Scope,
					ContextRefs = (from pair in signal.ContextRefs.Take(16)
						select new KeyValuePair<string, string>(pair.Key, pair.Value)).ToArray()
				};
				TrySend(message);
			}
		}

		public void ForwardChat(string body, string sourceCharacterId, string correlationId, string color = "", bool rainbow = false)
		{
			if (!DanmakuMultiplayerState.IsMultiplayerSession || !DanmakuModConfig.ShouldEmitChat() || !DanmakuModConfig.ShouldForwardChat())
			{
				return;
			}
			RunManager instance = RunManager.Instance;
			EnsureAttached((instance != null) ? instance.NetService : null);
			lock (_sync)
			{
				if (_attached && _netService != null)
				{
					if (!DanmakuMultiplayerState.HasCompatiblePeers)
					{
						RetryHandshakeIfNeeded();
						return;
					}
					ZzzDanmakuChatMessage message = new ZzzDanmakuChatMessage
					{
						Text = body,
						SourceCharacterId = sourceCharacterId,
						SourcePlayerNetId = DanmakuMultiplayerState.LocalPlayerNetId,
						CorrelationId = correlationId,
						Color = color,
						Rainbow = rainbow
					};
					TrySend(message);
				}
			}
		}

		public void ForwardUgc(string entryId, IReadOnlyList<KeyValuePair<string, string>> contextRefs, string sourceCharacterId, string correlationId)
		{
			if (!DanmakuMultiplayerState.IsMultiplayerSession || !DanmakuModConfig.ShouldEmitMultiplayer() || !DanmakuModConfig.ShouldForwardMultiplayer())
			{
				return;
			}
			RunManager instance = RunManager.Instance;
			EnsureAttached((instance != null) ? instance.NetService : null);
			lock (_sync)
			{
				if (!_attached || _netService == null)
				{
					return;
				}
				if (!DanmakuMultiplayerState.HasCompatiblePeers)
				{
					RetryHandshakeIfNeeded();
					return;
				}
				ZzzDanmakuUgcMessage message = new ZzzDanmakuUgcMessage
				{
					EntryId = entryId,
					SourceCharacterId = sourceCharacterId,
					SourcePlayerNetId = DanmakuMultiplayerState.LocalPlayerNetId,
					CorrelationId = correlationId,
					ContextRefs = (from pair in contextRefs.Take(16)
						select new KeyValuePair<string, string>(pair.Key, pair.Value)).ToArray()
				};
				TrySend(message);
			}
		}

		private void OnChatMessage(ZzzDanmakuChatMessage message, ulong senderId)
		{
			if (!message.Corrupt)
			{
				if (!DanmakuMultiplayerState.IsCompatiblePeer(senderId))
				{
					ReplyHandshakeIfNeeded();
				}
				else if (DanmakuModConfig.ShouldEmitMultiplayer() && DanmakuModConfig.ShouldReceiveMultiplayerChat() && RateLimit(senderId, IncomingMessageKind.Chat, 5) && TryAcceptCorrelation(senderId, message.CorrelationId) && !string.IsNullOrWhiteSpace(message.Text) && ContentValidator.CountTextCharacters(message.Text) <= 40 && ContentValidator.IsValidAvatar(message.SourceCharacterId))
				{
					DanmakuHub.Instance?.DispatchRemoteChat(message.Text, message.SourceCharacterId, DanmakuMultiplayerState.ResolvePlayerName(senderId), message.CorrelationId, message.Color, message.Rainbow);
				}
			}
		}

		private void OnUgcMessage(ZzzDanmakuUgcMessage message, ulong senderId)
		{
			if (!message.Corrupt)
			{
				if (!DanmakuMultiplayerState.IsCompatiblePeer(senderId))
				{
					ReplyHandshakeIfNeeded();
				}
				else if (DanmakuModConfig.ShouldEmitMultiplayer() && DanmakuModConfig.ShouldReceiveMultiplayer() && DanmakuModConfig.ShouldEmitUgc() && RateLimit(senderId, IncomingMessageKind.Ugc, 20) && TryAcceptCorrelation(senderId, message.CorrelationId) && !string.IsNullOrWhiteSpace(message.EntryId) && ContentValidator.IsValidAvatar(message.SourceCharacterId))
				{
					UgcRuntime.Instance?.EmitRemote(message.EntryId, message.SourceCharacterId);
				}
			}
		}

		private void OnDanmakuMessage(ZzzDanmakuNetMessage message, ulong senderId)
		{
			if (message.Corrupt)
			{
				return;
			}
			if (!DanmakuMultiplayerState.IsCompatiblePeer(senderId))
			{
				ReplyHandshakeIfNeeded();
			}
			else if (DanmakuModConfig.ShouldEmitMultiplayer() && DanmakuModConfig.ShouldReceiveMultiplayer() && RateLimit(senderId, IncomingMessageKind.Rule, 30) && TryAcceptCorrelation(senderId, message.CorrelationId) && Enum.IsDefined(typeof(DanmakuTrigger), message.Trigger) && message.EntryIndex >= 0 && Enum.IsDefined(typeof(EmissionScope), message.Scope) && ContentValidator.IsValidAvatar(message.SourceCharacterId) && PhaseRouter.Instance != null)
			{
				DanmakuSignal danmakuSignal = new DanmakuSignal((DanmakuTrigger)message.Trigger, null, message.Variant, DanmakuChannel.Multiplayer);
				danmakuSignal.EntryIndex = message.EntryIndex;
				danmakuSignal.SourceCharacterId = message.SourceCharacterId;
				danmakuSignal.SourcePlayerNetId = senderId;
				danmakuSignal.SourcePlayerName = DanmakuMultiplayerState.ResolvePlayerName(senderId);
				danmakuSignal.CorrelationId = message.CorrelationId;
				danmakuSignal.Scope = (EmissionScope)message.Scope;
				danmakuSignal.ContextRefs = new Dictionary<string, string>(message.ContextRefs.Select<KeyValuePair<string, string>, KeyValuePair<string, string>>((KeyValuePair<string, string> pair) => new KeyValuePair<string, string>(pair.Key, pair.Value)), StringComparer.Ordinal);
				DanmakuSignal signal = danmakuSignal;
				DanmakuHub.Instance?.DispatchRemote(signal);
			}
		}

		private void OnHandshake(ZzzDanmakuHandshakeMessage message, ulong senderId)
		{
			if (!message.Corrupt && senderId != DanmakuMultiplayerState.LocalPlayerNetId)
			{
				DanmakuMultiplayerState.RecordPeer(senderId, message.ModVersion);
				string text = $"握手：玩家 {senderId} 模组版本 {message.ModVersion}（兼容={DanmakuMultiplayerState.IsCompatiblePeer(senderId)}）。";
				MainFile.Log("[Multiplayer] " + text);
				ReplyHandshakeIfNeeded();
			}
		}

		private bool RateLimit(ulong senderId, IncomingMessageKind kind, int kindLimit)
		{
			lock (_sync)
			{
				DateTimeOffset utcNow = DateTimeOffset.UtcNow;
				if (!_globalRateBuckets.TryGetValue(senderId, out Queue<DateTimeOffset> value))
				{
					value = new Queue<DateTimeOffset>();
					_globalRateBuckets[senderId] = value;
				}
				(ulong, IncomingMessageKind) key = (senderId, kind);
				if (!_rateBuckets.TryGetValue(key, out Queue<DateTimeOffset> value2))
				{
					value2 = new Queue<DateTimeOffset>();
					_rateBuckets[key] = value2;
				}
				TrimRateBucket(value, utcNow);
				TrimRateBucket(value2, utcNow);
				if (value.Count >= 40 || value2.Count >= kindLimit)
				{
					return false;
				}
				value.Enqueue(utcNow);
				value2.Enqueue(utcNow);
				return true;
			}
		}

		private static void TrimRateBucket(Queue<DateTimeOffset> bucket, DateTimeOffset now)
		{
			while (bucket.Count > 0 && (now - bucket.Peek()).TotalSeconds >= 1.0)
			{
				bucket.Dequeue();
			}
		}

		private bool TryAcceptCorrelation(ulong senderId, string correlationId)
		{
			if (string.IsNullOrWhiteSpace(correlationId) || correlationId.Length > 128)
			{
				return false;
			}
			lock (_sync)
			{
				(ulong, string) item = (senderId, correlationId);
				if (!_seenCorrelations.Add(item))
				{
					return false;
				}
				_correlationOrder.Enqueue(item);
				while (_correlationOrder.Count > 4096)
				{
					_seenCorrelations.Remove(_correlationOrder.Dequeue());
				}
				return true;
			}
		}

		private void TrySend<T>(T message) where T : INetMessage
		{
			try
			{
				INetGameService netService = _netService;
				if (netService != null && netService.IsConnected)
				{
					_netService.SendMessage<T>(message);
					_sendFailureLogged = false;
				}
				else if (!_sendFailureLogged)
				{
					_sendFailureLogged = true;
					MainFile.Log("[Multiplayer] 网络未连接，跳过发送 " + typeof(T).Name + "（IsConnected=false）。");
				}
			}
			catch (Exception ex)
			{
				MainFile.Log("[Multiplayer] 发送 " + typeof(T).Name + " 失败：" + ex.Message);
			}
		}

		private void DetachCore()
		{
			if (_netService != null && _attached)
			{
				try
				{
					if (_messageHandler != null)
					{
						_netService.UnregisterMessageHandler<ZzzDanmakuNetMessage>(_messageHandler);
					}
					if (_handshakeHandler != null)
					{
						_netService.UnregisterMessageHandler<ZzzDanmakuHandshakeMessage>(_handshakeHandler);
					}
					if (_chatHandler != null)
					{
						_netService.UnregisterMessageHandler<ZzzDanmakuChatMessage>(_chatHandler);
					}
					if (_ugcHandler != null)
					{
						_netService.UnregisterMessageHandler<ZzzDanmakuUgcMessage>(_ugcHandler);
					}
				}
				catch (Exception ex)
				{
					MainFile.Log("[Multiplayer] 注销网络消息失败（不影响主链路）：" + ex.Message);
				}
			}
			_netService = null;
			_messageHandler = null;
			_handshakeHandler = null;
			_chatHandler = null;
			_ugcHandler = null;
			_attached = false;
			_seenCorrelations.Clear();
			_correlationOrder.Clear();
			_globalRateBuckets.Clear();
			_rateBuckets.Clear();
			_lastHandshakeRetry = DateTimeOffset.MinValue;
			_lastHandshakeReply = DateTimeOffset.MinValue;
			_sendFailureLogged = false;
		}

		private void RetryHandshakeIfNeeded()
		{
			INetGameService netService = _netService;
			if (netService != null && netService.IsConnected && !DanmakuMultiplayerState.HasCompatiblePeers)
			{
				DateTimeOffset utcNow = DateTimeOffset.UtcNow;
				if (!(utcNow - _lastHandshakeRetry < TimeSpan.FromSeconds(5L)))
				{
					_lastHandshakeRetry = utcNow;
					TrySend(new ZzzDanmakuHandshakeMessage
					{
						ModVersion = DanmakuMultiplayerState.ModVersion
					});
				}
			}
		}

		private void ReplyHandshakeIfNeeded()
		{
			INetGameService netService = _netService;
			if (netService != null && netService.IsConnected)
			{
				DateTimeOffset utcNow = DateTimeOffset.UtcNow;
				if (!(utcNow - _lastHandshakeReply < TimeSpan.FromSeconds(5L)))
				{
					_lastHandshakeReply = utcNow;
					TrySend(new ZzzDanmakuHandshakeMessage
					{
						ModVersion = DanmakuMultiplayerState.ModVersion
					});
				}
			}
		}
	}
	public sealed class ZzzDanmakuChatMessage : INetMessage, IPacketSerializable
	{
		public const int MaxTextLength = 40;

		private const int MaxStringLength = 128;

		public string Text = "";

		public string SourceCharacterId = "";

		public ulong SourcePlayerNetId;

		public string CorrelationId = "";

		public string Color = "";

		public bool Rainbow;

		public bool ShouldBroadcast => true;

		public NetTransferMode Mode => (NetTransferMode)2;

		public LogLevel LogLevel => (LogLevel)0;

		public bool ShouldBuffer => false;

		public bool Corrupt { get; private set; }

		public void Serialize(PacketWriter writer)
		{
			writer.WriteString(Text);
			writer.WriteString(SourceCharacterId);
			writer.WriteULong(SourcePlayerNetId, 64);
			writer.WriteString(CorrelationId);
			writer.WriteString(Color);
			writer.WriteBool(Rainbow);
		}

		public void Deserialize(PacketReader reader)
		{
			try
			{
				Text = ReadSafeString(reader);
				SourceCharacterId = ReadSafeString(reader);
				SourcePlayerNetId = reader.ReadULong(64);
				CorrelationId = ReadSafeString(reader);
				Color = ReadSafeString(reader);
				Rainbow = reader.ReadBool();
				if (ContentValidator.CountTextCharacters(Text) > 40)
				{
					Corrupt = true;
					Text = "";
				}
				if (!ContentValidator.IsValidColor(Color))
				{
					Corrupt = true;
					Color = "";
				}
			}
			catch (Exception)
			{
				Corrupt = true;
				Text = "";
				SourceCharacterId = "";
				CorrelationId = "";
				Color = "";
			}
		}

		private static string ReadSafeString(PacketReader reader)
		{
			string text = reader.ReadString();
			if (text.Length <= 128)
			{
				return text;
			}
			return "";
		}
	}
	public sealed class ZzzDanmakuUgcMessage : INetMessage, IPacketSerializable
	{
		public const int MaxContextRefCount = 16;

		private const int MaxStringLength = 512;

		public string EntryId = "";

		public IReadOnlyList<KeyValuePair<string, string>> ContextRefs = Array.Empty<KeyValuePair<string, string>>();

		public string SourceCharacterId = "";

		public ulong SourcePlayerNetId;

		public string CorrelationId = "";

		public bool ShouldBroadcast => true;

		public NetTransferMode Mode => (NetTransferMode)1;

		public LogLevel LogLevel => (LogLevel)0;

		public bool ShouldBuffer => false;

		public bool Corrupt { get; private set; }

		public void Serialize(PacketWriter writer)
		{
			writer.WriteString(EntryId);
			writer.WriteString(SourceCharacterId);
			writer.WriteULong(SourcePlayerNetId, 64);
			writer.WriteString(CorrelationId);
			IReadOnlyList<KeyValuePair<string, string>> readOnlyList = NetworkContextRefs.PrepareForSend(ContextRefs, 16);
			writer.WriteInt(readOnlyList.Count, 32);
			for (int i = 0; i < readOnlyList.Count; i++)
			{
				writer.WriteString(readOnlyList[i].Key);
				writer.WriteString(readOnlyList[i].Value);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			try
			{
				EntryId = ReadSafeString(reader);
				SourceCharacterId = ReadSafeString(reader);
				SourcePlayerNetId = reader.ReadULong(64);
				CorrelationId = ReadSafeString(reader);
				int num = reader.ReadInt(32);
				if ((num < 0 || num > 16) ? true : false)
				{
					Corrupt = true;
					ContextRefs = Array.Empty<KeyValuePair<string, string>>();
					return;
				}
				List<KeyValuePair<string, string>> list = new List<KeyValuePair<string, string>>(num);
				HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
				for (int i = 0; i < num; i++)
				{
					string key = ReadSafeString(reader);
					string value = ReadSafeString(reader);
					if (!NetworkContextRefs.TryNormalize(key, value, out KeyValuePair<string, string> normalized) || !hashSet.Add(normalized.Key))
					{
						Corrupt = true;
						list.Clear();
						break;
					}
					list.Add(normalized);
				}
				ContextRefs = list;
			}
			catch (Exception)
			{
				Corrupt = true;
				ContextRefs = Array.Empty<KeyValuePair<string, string>>();
			}
		}

		private static string ReadSafeString(PacketReader reader)
		{
			string text = reader.ReadString();
			if (text.Length <= 512)
			{
				return text;
			}
			return "";
		}
	}
