		public static CharacterCatalog ParseCharacters(string json)
		{
			Dictionary<string, CharacterInfo> dictionary = new Dictionary<string, CharacterInfo>(StringComparer.Ordinal);
			using JsonDocument jsonDocument = JsonDocument.Parse(json);
			if (jsonDocument.RootElement.TryGetProperty("characters", out var value))
			{
				foreach (JsonProperty item in value.EnumerateObject())
				{
					JsonElement value2;
					string name = (item.Value.TryGetProperty("name", out value2) ? (value2.GetString() ?? "") : "");
					JsonElement value3;
					string color = ((item.Value.TryGetProperty("color", out value3) && value3.ValueKind == JsonValueKind.String) ? value3.GetString() : null);
					JsonElement value4;
					string avatar = ((item.Value.TryGetProperty("avatar", out value4) && value4.ValueKind == JsonValueKind.String) ? value4.GetString() : null);
					dictionary[item.Name] = new CharacterInfo(name, color, avatar);
				}
			}
			return new CharacterCatalog(dictionary);
