		public void ApplyCharacters(CharacterCatalog catalog)
		{
			foreach (KeyValuePair<string, CharacterInfo> character in catalog.Characters)
			{
				CharacterInfo value = character.Value;
				if (!string.IsNullOrWhiteSpace(value.Name))
				{
					_characterNames[character.Key] = value.Name;
				}
				if (!string.IsNullOrWhiteSpace(value.Color))
				{
					_characterColors[character.Key] = value.Color;
				}
				if (!string.IsNullOrWhiteSpace(value.Avatar))
				{
					_characterAvatars[character.Key] = value.Avatar;
				}
			}
		}

		public void ApplyAliases(AliasCatalog catalog)
		{
			foreach (KeyValuePair<string, string> card in catalog.Cards)
			{
				_cardAliases[card.Key] = card.Value;
			}
			foreach (KeyValuePair<string, string> relic in catalog.Relics)
			{
				_relicAliases[relic.Key] = relic.Value;
			}
		}

		public void Reset()
		{
			ResetInto(_characterNames, DefaultCharacterNames);
			ResetInto(_characterColors, DefaultCharacterColors);
			ResetInto(_characterAvatars, DefaultCharacterAvatars);
			ResetInto(_cardAliases, DefaultCardAliases);
			ResetInto(_relicAliases, DefaultRelicAliases);
		}

		private static void ResetInto(Dictionary<string, string> target, Dictionary<string, string> source)
		{
			target.Clear();
			foreach (KeyValuePair<string, string> item in source)
			{
				target[item.Key] = item.Value;
			}
		}

		public string CharacterName(string? id)
		{
			return Lookup(_characterNames, id);
		}

		public string? CharacterColor(string? id)
		{
			if (string.IsNullOrEmpty(id) || !_characterColors.TryGetValue(id, out string value))
			{
				return null;
			}
			return value;
		}

		public string? CharacterAvatar(string? id)
		{
			if (string.IsNullOrEmpty(id) || !_characterAvatars.TryGetValue(id, out string value))
			{
				return null;
			}
			return value;
		}

		public string CardAliasName(string? name)
		{
			return Lookup(_cardAliases, name);
		}

		public string RelicAliasName(string? name)
		{
			return Lookup(_relicAliases, name);
		}

		private static string Lookup(Dictionary<string, string> map, string? key)
		{
			string text;
			if (string.IsNullOrEmpty(key) || !map.TryGetValue(key, out string value))
			{
				text = key;
				if (text == null)
				{
					return string.Empty;
				}
			}
			else
			{
				text = value;
			}
			return text;
		}
	}
