		private static IReadOnlyList<string> ParseStringArray(JsonElement item, string propertyName)
		{
			if (!item.TryGetProperty(propertyName, out var value2) || value2.ValueKind != JsonValueKind.Array)
			{
				return Array.Empty<string>();
			}
			return (from value in value2.EnumerateArray()
				where value.ValueKind == JsonValueKind.String
				select value.GetString() ?? "").ToArray();
		}

		private static ContentTrigger ParseTrigger(JsonElement item)
