		private static SubmissionStatus ParseStatus(string value)
		{
			string text = value.Trim().ToLowerInvariant();
			if (!(text == "approved"))
			{
				if (text == "rejected")
				{
					return SubmissionStatus.Rejected;
				}
				return SubmissionStatus.Pending;
			}
			return SubmissionStatus.Approved;
		}

		private static SubmissionRequestType ParseRequestType(string value)
		{
			string text = value.Trim().ToLowerInvariant();
			if (!(text == "delete"))
			{
				if (text == "edit")
				{
					return SubmissionRequestType.Edit;
				}
				return SubmissionRequestType.Submit;
			}
			return SubmissionRequestType.Delete;
		}

		private static ContentObjectKind ParseKind(string? value)
		{
			return value switch
			{
				"character" => ContentObjectKind.Character, 
				"relic" => ContentObjectKind.Relic, 
				"monster" => ContentObjectKind.Monster, 
				"event" => ContentObjectKind.Event, 
				"act" => ContentObjectKind.Act, 
				"turn" => ContentObjectKind.Turn, 
				_ => ContentObjectKind.Card, 
			};
		}

		private static ContentInstant ParseInstant(string? value)
