				"played" => ContentInstant.Played, 
				"encountered" => ContentInstant.Encountered, 
				"defeated" => ContentInstant.Defeated, 
				"combat" => ContentInstant.Combat, 
				"entered" => ContentInstant.Entered, 
				"optionSelected" => ContentInstant.OptionSelected, 
				"actEntered" => ContentInstant.ActEntered, 
