	public sealed record CollectibleSets(IReadOnlyDictionary<string, IReadOnlySet<string>> KeyCardsByCharacter, IReadOnlySet<string> OverpoweredCards, IReadOnlySet<string> StartupCards, IReadOnlySet<string> FutureCards, IReadOnlySet<string> OverpoweredRelics, IReadOnlyList<ComboDefinition> Combos);
	public static class CollectibleSetsCodec
	{
		private static readonly JsonSerializerOptions Indented = new JsonSerializerOptions
		{
			WriteIndented = true,
			Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
		};

		public static CollectibleSets Parse(string json)
		{
			using JsonDocument jsonDocument = JsonDocument.Parse(json);
			JsonElement rootElement = jsonDocument.RootElement;
			Dictionary<string, IReadOnlySet<string>> dictionary = new Dictionary<string, IReadOnlySet<string>>(StringComparer.Ordinal);
			if (rootElement.TryGetProperty("keyCardsByCharacter", out var value))
			{
				foreach (JsonProperty item in value.EnumerateObject())
				{
					dictionary[item.Name] = ReadSet(item.Value);
				}
			}
			IReadOnlySet<string> readOnlySet2;
			if (!rootElement.TryGetProperty("overpoweredCards", out var value2))
			{
				IReadOnlySet<string> readOnlySet = new HashSet<string>(StringComparer.Ordinal);
				readOnlySet2 = readOnlySet;
			}
			else
			{
				readOnlySet2 = ReadSet(value2);
			}
			IReadOnlySet<string> overpoweredCards = readOnlySet2;
			IReadOnlySet<string> readOnlySet3;
			if (!rootElement.TryGetProperty("startupCards", out var value3))
			{
				IReadOnlySet<string> readOnlySet = new HashSet<string>(StringComparer.Ordinal);
				readOnlySet3 = readOnlySet;
			}
			else
			{
				readOnlySet3 = ReadSet(value3);
			}
			IReadOnlySet<string> startupCards = readOnlySet3;
			IReadOnlySet<string> readOnlySet4;
			if (!rootElement.TryGetProperty("futureCards", out var value4))
			{
				IReadOnlySet<string> readOnlySet = new HashSet<string>(StringComparer.Ordinal);
				readOnlySet4 = readOnlySet;
			}
			else
			{
				readOnlySet4 = ReadSet(value4);
			}
			IReadOnlySet<string> futureCards = readOnlySet4;
			IReadOnlySet<string> readOnlySet5;
			if (!rootElement.TryGetProperty("overpoweredRelics", out var value5))
			{
				IReadOnlySet<string> readOnlySet = new HashSet<string>(StringComparer.Ordinal);
				readOnlySet5 = readOnlySet;
			}
			else
			{
				readOnlySet5 = ReadSet(value5);
			}
			IReadOnlySet<string> overpoweredRelics = readOnlySet5;
			List<ComboDefinition> list = new List<ComboDefinition>();
			if (rootElement.TryGetProperty("combos", out var value6))
			{
				foreach (JsonElement item2 in value6.EnumerateArray())
				{
					list.Add(ParseCombo(item2));
				}
			}
			return new CollectibleSets(dictionary, overpoweredCards, startupCards, futureCards, overpoweredRelics, list);
		}

		public static string Serialize(CollectibleSets sets)
		{
			return JsonSerializer.Serialize(new
			{
				schemaVersion = 1,
				keyCardsByCharacter = sets.KeyCardsByCharacter.ToDictionary<KeyValuePair<string, IReadOnlySet<string>>, string, string[]>((KeyValuePair<string, IReadOnlySet<string>> pair) => pair.Key, (KeyValuePair<string, IReadOnlySet<string>> pair) => pair.Value.Order<string>(StringComparer.Ordinal).ToArray()),
				overpoweredCards = sets.OverpoweredCards.Order<string>(StringComparer.Ordinal).ToArray(),
				startupCards = sets.StartupCards.Order<string>(StringComparer.Ordinal).ToArray(),
				futureCards = sets.FutureCards.Order<string>(StringComparer.Ordinal).ToArray(),
				overpoweredRelics = sets.OverpoweredRelics.Order<string>(StringComparer.Ordinal).ToArray(),
				combos = sets.Combos.Select(SerializeCombo)
			}, Indented);
		}

		private static IReadOnlySet<string> ReadSet(JsonElement element)
		{
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			if (element.ValueKind == JsonValueKind.Array)
			{
				foreach (JsonElement item in element.EnumerateArray())
				{
					hashSet.Add(item.GetString() ?? "");
				}
			}
			return hashSet;
		}

		private static ComboDefinition ParseCombo(JsonElement element)
		{
			string? id = element.GetProperty("id").GetString() ?? "";
			ComboSource source = ParseSource(element.GetProperty("source"));
			ComboItem target = ParseItem(element.GetProperty("target"));
			return new ComboDefinition(id, source, target);
		}

		private static ComboSource ParseSource(JsonElement element)
		{
			string text = element.GetProperty("kind").GetString() ?? "";
			if (!(text == "xcost"))
			{
				if (text == "enchantedAttack")
				{
					return new ComboSource(ComboSourceKind.EnchantedAttack, null);
				}
				return new ComboSource(ComboSourceKind.Exact, ParseItem(element));
			}
			return new ComboSource(ComboSourceKind.XCost, null);
		}

		private static ComboItem ParseItem(JsonElement element)
		{
			return new ComboItem(element.GetProperty("kind").GetString() ?? "", element.GetProperty("id").GetString() ?? "", element.GetProperty("name").GetString() ?? "", element.GetProperty("typeName").GetString() ?? "");
		}

		private static object SerializeCombo(ComboDefinition combo)
		{
			return new
			{
				id = combo.Id,
				source = SerializeSource(combo.Source),
				target = SerializeItem(combo.Target)
			};
		}

		private static object SerializeSource(ComboSource source)
		{
			return source.Kind switch
			{
				ComboSourceKind.XCost => new
				{
					kind = "xcost"
				}, 
				ComboSourceKind.EnchantedAttack => new
				{
					kind = "enchantedAttack"
				}, 
				_ => SerializeItem(source.Item.Value), 
			};
		}

		private static object SerializeItem(ComboItem item)
		{
			return new
			{
				kind = item.ItemKind,
				id = item.ModelId,
				name = item.Name,
				typeName = item.TypeName
			};
		}
	}
