				CollectibleSubmissionCategory.OverpoweredCard => "用于 E4「获得超模牌」，并参与 E6「错过关键牌」与 E10「难以抉择」。", 
				CollectibleSubmissionCategory.StartupCard => "用于 B4「战斗启动」：战斗中打出后累计本场启动次数。", 
				CollectibleSubmissionCategory.FutureCard => "用于 E1「一层抓未来牌」与 E7「不选择未来牌」，主要服务第一幕选牌判断。", 
				CollectibleSubmissionCategory.PowerfulRelic => "用于 E4「获得超模牌」的遗物分支：获得该遗物时触发对应弹幕。", 
				_ => "用于 E13「强力组合」：按 A→B 单向判定，第 1 个是先观察到的 A，第 2 个是目标 B；两端都可选卡牌或遗物。", 
			};
		}

		public static IReadOnlyList<string> Validate(CollectibleSubmissionRequest request)
		{
			List<string> list = new List<string>();
			if (ContentValidator.CountCharacters(request.Nickname) > 16)
			{
				list.Add($"昵称超过 {16} 字");
			}
			bool flag = request.Category == CollectibleSubmissionCategory.PowerfulCombo;
			if (flag && request.Items.Count != 2)
			{
				list.Add("强力组合必须按 A→B 顺序选择 2 个对象");
			}
			if (!flag && request.Items.Count != 1)
			{
				list.Add("该分类每次请选择 1 个对象");
			}
			if (request.Category == CollectibleSubmissionCategory.KeyCard && string.IsNullOrWhiteSpace(request.CharacterId))
			{
				list.Add("关键牌投稿必须选择所属角色");
			}
			string text = ((request.Category == CollectibleSubmissionCategory.PowerfulRelic) ? "relic" : "card");
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			foreach (CollectibleSubmissionItem item in request.Items)
			{
				string kind = item.Kind;
				bool flag2 = ((kind == "card" || kind == "relic") ? true : false);
				if (!flag2 || (!flag && item.Kind != text))
				{
					list.Add("所选对象类型与投稿分类不匹配");
				}
				if (!ContentValidator.IsValidObjectId(item.Id))
				{
					list.Add("所选对象无效");
				}
				if (!hashSet.Add(item.Kind + ":" + item.Id))
				{
					list.Add("同一对象不能重复选择");
				}
			}
			return list;
		}

		public static string Serialize(CollectibleSubmissionRequest request, string deviceId)
		{
			return JsonSerializer.Serialize(new
			{
				nickname = request.Nickname,
				category = StableName(request.Category),
				characterId = request.CharacterId,
				items = request.Items.Select((CollectibleSubmissionItem item) => new { item.Kind, item.Id, item.Name }),
				device_id = deviceId
			}, Json);
		}

		public static string SerializeFeedback(string nickname, string text, string deviceId)
		{
			return JsonSerializer.Serialize(new
			{
				nickname = nickname,
				text = text,
				device_id = deviceId
			}, Json);
		}
	}
	public readonly record struct CatalogLoadResult(int Loaded, int Failed);
	public static class ContentCatalogLoader
	{
		public static CatalogLoadResult Load(string dir)
		{
			if (!Directory.Exists(dir))
			{
				return new CatalogLoadResult(0, 0);
			}
			int failed = 0;
			return new CatalogLoadResult(0 + LoadFile(Path.Combine(dir, "catalogs", "characters.json"), delegate(string json)
			{
				CatalogStore.Instance.ApplyCharacters(CatalogParser.ParseCharacters(json));
			}, ref failed) + LoadFile(Path.Combine(dir, "catalogs", "aliases.json"), delegate(string json)
			{
				CatalogStore.Instance.ApplyAliases(CatalogParser.ParseAliases(json));
			}, ref failed) + LoadFile(Path.Combine(dir, "catalogs", "names-zh.json"), delegate(string json)
			{
				OriginalChineseNames.Apply(json);
			}, ref failed) + LoadFile(Path.Combine(dir, "catalogs", "collectible-sets.json"), delegate(string json)
			{
				CollectibleSets sets = CollectibleSetsCodec.Parse(json);
				ManualCardSets.Apply(sets);
				ManualRelicSets.Apply(sets);
				PowerfulCombos.Apply(sets);
			}, ref failed) + LoadFile(Path.Combine(dir, "danmaku", "rules.json"), delegate(string json)
			{
				DanmakuLibrary.Apply(RuleLibraryCodec.Parse(json));
			}, ref failed), failed);
		}

		private static int LoadFile(string path, Action<string> apply, ref int failed)
		{
			if (!File.Exists(path))
			{
				return 0;
			}
			try
			{
				apply(File.ReadAllText(path, Encoding.UTF8));
				return 1;
			}
			catch
			{
				failed++;
				return 0;
			}
		}
	}
