	public readonly record struct ContentShardInfo(string Name, long Version, string Sha256);
	public sealed record ContentManifest(int SchemaVersion, string ModVersion, long UgcVersion, IReadOnlyList<ContentShardInfo> Shards, string Signature = "");
	public static class ContentManifestValidator
	{
		public const int SupportedSchemaVersion = 1;

		public const int SupportedModMajor = 1;

		public const int SupportedModMinor = 2;

		public const int MaxShardCount = 8;

		public const int MaxShardBytes = 2097152;

		private static readonly HashSet<string> AllowedShardNames = new HashSet<string>(StringComparer.Ordinal) { "characters.json", "cards.json", "relics.json", "monsters.json", "events.json", "rules-contrib.json", "acts.json", "turns.json" };

		public static IReadOnlyList<string> Validate(ContentManifest manifest)
		{
			List<string> list = new List<string>();
			if (manifest.SchemaVersion != 1)
			{
				list.Add($"不支持的 schemaVersion：{manifest.SchemaVersion}");
			}
			if (!Version.TryParse(manifest.ModVersion, out Version result))
			{
				list.Add("modVersion 不是合法版本号");
			}
			else if (result.Major != 1 || result.Minor != 2)
			{
				list.Add($"内容适配模组 {manifest.ModVersion}，当前仅支持 {1}.{2}.x");
			}
			if (manifest.UgcVersion <= 0)
			{
				list.Add("ugcVersion 必须为正数");
			}
			if (manifest.Signature.Length != 128 || !manifest.Signature.All(char.IsAsciiHexDigit))
			{
				list.Add("signature 必须是 64 字节 ECDSA P-256 十六进制签名");
			}
			if (manifest.Shards.Count > 8)
			{
				list.Add($"分片数量超过 {8}");
			}
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			foreach (ContentShardInfo shard in manifest.Shards)
			{
				if (!TryGetCanonicalShardName(shard.Name, manifest.UgcVersion, out string canonicalName))
				{
					list.Add("分片对象键非法：" + shard.Name);
				}
				else if (!hashSet.Add(canonicalName))
				{
					list.Add("分片重复：" + canonicalName);
				}
				if (shard.Version != manifest.UgcVersion)
				{
					list.Add("分片版本与快照版本不一致：" + shard.Name);
				}
				if (shard.Sha256.Length != 64 || !shard.Sha256.All(char.IsAsciiHexDigit))
				{
					list.Add("分片 SHA-256 非法：" + shard.Name);
				}
			}
			return list;
		}

		public static bool TryGetCanonicalShardName(string remoteName, long ugcVersion, out string canonicalName)
		{
			canonicalName = "";
			if (AllowedShardNames.Contains(remoteName))
			{
				canonicalName = remoteName;
				return true;
			}
			string text = $"snapshots/{ugcVersion}/";
			if (!remoteName.StartsWith(text, StringComparison.Ordinal))
			{
				return false;
			}
			int length = text.Length;
			string text2 = remoteName.Substring(length, remoteName.Length - length);
			if (!AllowedShardNames.Contains(text2))
			{
				return false;
			}
			canonicalName = text2;
			return true;
		}

		public static bool IsCanonicalShardName(string name)
		{
			return AllowedShardNames.Contains(name);
		}
	}
