	public static class ContentConditionRules
	{
		public static bool IsValidInterval(ContentObjectKind kind, ContentInterval timing)
		{
			return kind switch
			{
				ContentObjectKind.Character => timing == ContentInterval.Using, 
				ContentObjectKind.Card => timing == ContentInterval.Own, 
				ContentObjectKind.Relic => timing == ContentInterval.Own, 
				ContentObjectKind.Monster => timing == ContentInterval.InCombat, 
				ContentObjectKind.Event => timing == ContentInterval.InEvent, 
				ContentObjectKind.Act => timing == ContentInterval.AtAct, 
				ContentObjectKind.Turn => timing == ContentInterval.AtTurn, 
				_ => false, 
			};
		}

		public static bool IsValidInstant(ContentObjectKind kind, ContentInstant timing)
		{
			switch (kind)
			{
			case ContentObjectKind.Character:
				switch (timing)
				{
				case ContentInstant.Preselected:
					return true;
				case ContentInstant.Confirmed:
					return true;
				}
				break;
			case ContentObjectKind.Card:
				switch (timing)
				{
				case ContentInstant.Obtained:
					return true;
				case ContentInstant.Upgraded:
					return true;
				case ContentInstant.Removed:
					return true;
				case ContentInstant.Played:
					return true;
				}
				break;
			case ContentObjectKind.Relic:
				if (timing != ContentInstant.Obtained)
				{
					break;
				}
				return true;
			case ContentObjectKind.Monster:
				switch (timing)
				{
				case ContentInstant.Encountered:
					return true;
				case ContentInstant.Defeated:
					return true;
				case ContentInstant.Combat:
					return true;
				}
				break;
			case ContentObjectKind.Event:
				switch (timing)
				{
				case ContentInstant.Entered:
					return true;
				case ContentInstant.OptionSelected:
					return true;
				}
				break;
			case ContentObjectKind.Act:
				if (timing != ContentInstant.ActEntered)
				{
					break;
				}
				return true;
			case ContentObjectKind.Turn:
				if (timing != ContentInstant.TurnEntered)
				{
					break;
				}
				return true;
			}
			return false;
		}

		public static bool IsContextInterval(ContentObjectKind kind, ContentInterval timing)
		{
			if (kind != ContentObjectKind.Act || timing != ContentInterval.AtAct)
			{
				if (kind == ContentObjectKind.Turn)
				{
					return timing == ContentInterval.AtTurn;
				}
				return false;
			}
			return true;
		}

		public static bool IsContextInstant(ContentObjectKind kind, ContentInstant timing)
		{
			if (kind != ContentObjectKind.Act || timing != ContentInstant.ActEntered)
			{
				if (kind == ContentObjectKind.Turn)
				{
					return timing == ContentInstant.TurnEntered;
				}
				return false;
			}
			return true;
		}

		public static bool IsValidContextValue(string? id)
		{
			if (int.TryParse(id, out var result))
			{
				return result >= 1;
			}
			return false;
		}

		public static bool IsValidContextTriggerId(string? id)
		{
			if (!(id == "*"))
			{
				return IsValidContextValue(id);
			}
			return true;
		}
	}
	public readonly record struct ContentObjectEntry(string Id, string DisplayName, ContentObjectKind Kind, bool FromMod, string OwnerCharacterName = "", string ModName = "", int SourceOrder = 0)
