	public static class ContentObjectCatalogCodec
	{
		private static readonly JsonSerializerOptions Json = new JsonSerializerOptions
		{
			Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
		};

		public static string Serialize(ContentObjectCatalog catalog)
		{
			return JsonSerializer.Serialize(new
			{
				fingerprint = catalog.Fingerprint,
				objects = catalog.Objects.Select((ContentObjectEntry o) => new
				{
					id = o.Id,
					name = o.DisplayName,
					kind = (int)o.Kind,
					fromMod = o.FromMod,
					ownerCharacterName = o.OwnerCharacterName,
					modName = o.ModName,
					sourceOrder = o.SourceOrder
				}),
				eventOptions = catalog.EventOptions.Select((EventOptionEntry o) => new
				{
					eventId = o.EventId,
					optionKey = o.OptionKey,
					name = o.DisplayName
				})
			}, Json);
		}

		public static ContentObjectCatalog? Deserialize(string json)
		{
			try
			{
				using JsonDocument jsonDocument = JsonDocument.Parse(json);
				JsonElement rootElement = jsonDocument.RootElement;
				JsonElement value;
				string fingerprint = (rootElement.TryGetProperty("fingerprint", out value) ? (value.GetString() ?? "") : "");
				List<ContentObjectEntry> list = new List<ContentObjectEntry>();
				if (rootElement.TryGetProperty("objects", out var value2))
				{
					foreach (JsonElement item in value2.EnumerateArray())
					{
						string text = item.GetProperty("id").GetString() ?? "";
						string displayName = item.GetProperty("name").GetString() ?? text;
						JsonElement value3;
						ContentObjectKind kind = (item.TryGetProperty("kind", out value3) ? ((ContentObjectKind)value3.GetInt32()) : ContentObjectKind.Character);
						JsonElement value4;
						bool fromMod = item.TryGetProperty("fromMod", out value4) && value4.GetBoolean();
						JsonElement value5;
						string ownerCharacterName = (item.TryGetProperty("ownerCharacterName", out value5) ? (value5.GetString() ?? "") : "");
						JsonElement value6;
						string modName = (item.TryGetProperty("modName", out value6) ? (value6.GetString() ?? "") : "");
						JsonElement value7;
						int sourceOrder = ((item.TryGetProperty("sourceOrder", out value7) && value7.ValueKind == JsonValueKind.Number) ? value7.GetInt32() : list.Count);
						if (!string.IsNullOrWhiteSpace(text))
						{
							list.Add(new ContentObjectEntry(text, displayName, kind, fromMod, ownerCharacterName, modName, sourceOrder));
						}
					}
				}
				List<EventOptionEntry> list2 = new List<EventOptionEntry>();
				if (rootElement.TryGetProperty("eventOptions", out var value8))
				{
					foreach (JsonElement item2 in value8.EnumerateArray())
					{
						string text2 = item2.GetProperty("eventId").GetString() ?? "";
						string text3 = item2.GetProperty("optionKey").GetString() ?? "";
						string displayName2 = item2.GetProperty("name").GetString() ?? text3;
						if (!string.IsNullOrWhiteSpace(text2) && !string.IsNullOrWhiteSpace(text3))
						{
							list2.Add(new EventOptionEntry(text2, text3, displayName2));
						}
					}
				}
				return new ContentObjectCatalog(list, list2, fingerprint);
			}
			catch
			{
				return null;
			}
		}
	}
	public static class ObjectScanner
	{
		private const string EventsTable = "events";

		public static ContentObjectCatalog Scan()
		{
			List<ContentObjectEntry> list = new List<ContentObjectEntry>();
			IReadOnlyList<Mod> loadedMods = LoadMods();
			IReadOnlyDictionary<string, string> cardOwnerByPool = BuildCardOwnerByPool();
			try
			{
				list.AddRange(ScanKind(ContentObjectKind.Character, (IEnumerable<AbstractModel>)ModelDb.AllCharacters, typeof(CharacterModel), loadedMods, cardOwnerByPool));
				list.AddRange(ScanKind(ContentObjectKind.Card, (IEnumerable<AbstractModel>)ModelDb.AllCards, typeof(CardModel), loadedMods, cardOwnerByPool));
				list.AddRange(ScanKind(ContentObjectKind.Relic, (IEnumerable<AbstractModel>)ModelDb.AllRelics, typeof(RelicModel), loadedMods, cardOwnerByPool));
				list.AddRange(ScanKind(ContentObjectKind.Monster, (IEnumerable<AbstractModel>)ModelDb.Monsters, typeof(MonsterModel), loadedMods, cardOwnerByPool));
				list.AddRange(ScanKind(ContentObjectKind.Event, (IEnumerable<AbstractModel>)ModelDb.AllEvents.Concat((IEnumerable<EventModel>)ModelDb.AllAncients), typeof(EventModel), loadedMods, cardOwnerByPool));
			}
			catch (Exception ex)
			{
				MainFile.Log("[ObjectCatalog] 对象扫描异常（继续）：" + ex.Message);
			}
			List<EventOptionEntry> list2 = new List<EventOptionEntry>();
			try
			{
				list2.AddRange(ScanAllEventOptions());
			}
			catch (Exception ex2)
			{
				MainFile.Log("[ObjectCatalog] 事件选项扫描异常（继续）：" + ex2.Message);
			}
			list = (from o in list.GroupBy((ContentObjectEntry o) => (Kind: o.Kind, Id: o.Id), ((ContentObjectKind Kind, string Id) key, IEnumerable<ContentObjectEntry> @group) => @group.First())
				orderby o.Kind, o.FromMod, o.SourceOrder
				select o).ToList();
			list2 = list2.GroupBy((EventOptionEntry o) => (EventId: o.EventId, OptionKey: o.OptionKey), ((string EventId, string OptionKey) key, IEnumerable<EventOptionEntry> group) => group.First()).OrderBy<EventOptionEntry, string>((EventOptionEntry o) => o.EventId, StringComparer.Ordinal).ThenBy<EventOptionEntry, string>((EventOptionEntry o) => o.OptionKey, StringComparer.Ordinal)
				.ToList();
			return new ContentObjectCatalog(list, list2, ComputeFingerprint());
		}

		private static IReadOnlyList<ContentObjectEntry> ScanKind(ContentObjectKind kind, IEnumerable<AbstractModel> builtin, Type baseType, IReadOnlyList<Mod> loadedMods, IReadOnlyDictionary<string, string> cardOwnerByPool)
		{
			List<ContentObjectEntry> list = new List<ContentObjectEntry>();
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			int num = 0;
			foreach (AbstractModel item in builtin)
			{
				string entry = item.Id.Entry;
				if (!string.IsNullOrWhiteSpace(entry) && hashSet.Add(entry))
				{
					string displayName = FormatDisplayName(ReadTitle(item), entry);
					bool flag = IsModType(((object)item).GetType());
					CardModel val = (CardModel)(object)((item is CardModel) ? item : null);
					list.Add(new ContentObjectEntry(entry, displayName, kind, flag, (val != null) ? ResolveCardOwner(val, cardOwnerByPool) : "", flag ? ResolveModName(((object)item).GetType(), loadedMods) : "", num++));
				}
			}
			try
			{
				foreach (Type subtypesInMod in ReflectionHelper.GetSubtypesInMods(baseType))
				{
					if ((subtypesInMod.Namespace == null || !subtypesInMod.Namespace.Contains(".Mocks")) && !subtypesInMod.Name.Contains("Deprecated", StringComparison.Ordinal))
					{
						string entry2 = ModelDb.GetId(subtypesInMod).Entry;
						if (!string.IsNullOrWhiteSpace(entry2) && hashSet.Add(entry2))
						{
							AbstractModel val2 = TryResolveCanonical(subtypesInMod, kind);
							string displayName2 = FormatDisplayName((val2 == null) ? ReadTitleByType(subtypesInMod, kind) : ReadTitle(val2), entry2);
							CardModel val3 = (CardModel)(object)((val2 is CardModel) ? val2 : null);
							list.Add(new ContentObjectEntry(entry2, displayName2, kind, FromMod: true, (val3 != null) ? ResolveCardOwner(val3, cardOwnerByPool) : "", ResolveModName(subtypesInMod, loadedMods), num++));
						}
					}
				}
			}
			catch (Exception ex)
			{
				MainFile.Log($"[ObjectCatalog] 模组 {kind} 扫描跳过：{ex.Message}");
			}
			return list;
		}

		private static IReadOnlyList<Mod> LoadMods()
		{
			try
			{
				return ModManager.GetLoadedMods().ToArray();
			}
			catch
			{
				return Array.Empty<Mod>();
			}
		}

		private static IReadOnlyDictionary<string, string> BuildCardOwnerByPool()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			List<CharacterModel> list = new List<CharacterModel>(ModelDb.AllCharacters);
			foreach (CharacterModel item in list)
			{
				hashSet.Add(((AbstractModel)item).Id.Entry);
			}
			try
			{
				foreach (Type subtypesInMod in ReflectionHelper.GetSubtypesInMods(typeof(CharacterModel)))
				{
					string entry = ModelDb.GetId(subtypesInMod).Entry;
					if (hashSet.Add(entry))
					{
						CharacterModel byIdOrNull = ModelDb.GetByIdOrNull<CharacterModel>(ModelDb.GetId(subtypesInMod));
						if (byIdOrNull != null)
						{
							list.Add(byIdOrNull);
						}
					}
				}
			}
			catch (Exception ex)
			{
				MainFile.Log("[ObjectCatalog] 模组角色卡池扫描跳过：" + ex.Message);
			}
			foreach (CharacterModel item2 in list)
			{
				try
				{
					string entry2 = ((AbstractModel)item2.CardPool).Id.Entry;
					string value = FormatDisplayName(ReadLoc(item2.Title), ((AbstractModel)item2).Id.Entry);
					if (!string.IsNullOrWhiteSpace(entry2))
					{
						dictionary[entry2] = value;
					}
				}
				catch (Exception ex2)
				{
					MainFile.Log("[ObjectCatalog] 角色 " + ((AbstractModel)item2).Id.Entry + " 卡池归属解析失败：" + ex2.Message);
				}
			}
			return dictionary;
		}

		private static string ResolveCardOwner(CardModel card, IReadOnlyDictionary<string, string> cardOwnerByPool)
		{
			try
			{
				string entry = ((AbstractModel)card.Pool).Id.Entry;
				if (cardOwnerByPool.TryGetValue(entry, out string value))
				{
					return value;
				}
				string text = entry.ToUpperInvariant();
				if (text.Contains("COLORLESS"))
				{
					return "无色";
				}
				if (text.Contains("ANCIENT"))
				{
					return "远古";
				}
				if (text.Contains("CURSE"))
				{
					return "诅咒";
				}
				if (text.Contains("STATUS"))
				{
					return "状态";
				}
				if (text.Contains("EVENT"))
				{
					return "事件";
				}
				if (text.Contains("QUEST"))
				{
					return "任务";
				}
				if (text.Contains("TOKEN"))
				{
					return "衍生";
				}
				string text2 = card.Pool.Title?.Trim() ?? "";
				return string.IsNullOrWhiteSpace(text2) ? "其他" : text2;
			}
			catch
			{
				return "其他";
			}
		}

		private static bool IsModType(Type type)
		{
			return type.Assembly != typeof(ModelDb).Assembly;
		}

		private static string ResolveModName(Type type, IReadOnlyList<Mod> loadedMods)
		{
			Type type2 = type;
			Mod val = ((IEnumerable<Mod>)loadedMods).FirstOrDefault((Func<Mod, bool>)((Mod mod) => ModContainsAssembly(mod, type2.Assembly)));
			string text = val?.manifest?.name?.Trim() ?? "";
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text;
			}
			return val?.manifest?.id?.Trim() ?? type2.Assembly.GetName().Name ?? "未知模组";
		}

		private static bool ModContainsAssembly(Mod mod, Assembly assembly)
		{
			Assembly assembly2 = assembly;
			try
			{
				if (((object)mod).GetType().GetField("assemblies")?.GetValue(mod) is IEnumerable<Assembly> source)
				{
					return source.Any((Assembly candidate) => (object)candidate == assembly2);
				}
			}
			catch
			{
			}
			try
			{
				return ((object)mod).GetType().GetField("assembly")?.GetValue(mod) == assembly2;
			}
			catch
			{
				return false;
			}
		}

		private static AbstractModel? TryResolveCanonical(Type type, ContentObjectKind kind)
		{
			try
			{
				ModelId id = ModelDb.GetId(type);
				return (AbstractModel?)(kind switch
				{
					ContentObjectKind.Character => ModelDb.GetByIdOrNull<CharacterModel>(id), 
					ContentObjectKind.Card => ModelDb.GetByIdOrNull<CardModel>(id), 
					ContentObjectKind.Relic => ModelDb.GetByIdOrNull<RelicModel>(id), 
					ContentObjectKind.Monster => ModelDb.GetByIdOrNull<MonsterModel>(id), 
					ContentObjectKind.Event => ModelDb.GetByIdOrNull<EventModel>(id), 
					_ => null, 
				});
			}
			catch
			{
				return null;
			}
		}

		private static string? ReadTitle(AbstractModel model)
		{
			//IL_0067: Unknown result type (might be due to invalid IL or missing references)
			//IL_006d: Expected O, but got Unknown
			//IL_0089: Unknown result type (might be due to invalid IL or missing references)
			//IL_008f: Expected O, but got Unknown
