			//IL_016f: Expected O, but got Unknown
			//IL_018c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0192: Expected O, but got Unknown
			//IL_01af: Unknown result type (might be due to invalid IL or missing references)
			//IL_01b5: Expected O, but got Unknown
			CardModel val = (CardModel)(object)((model is CardModel) ? model : null);
			if (val == null)
			{
				CharacterModel val2 = (CharacterModel)(object)((model is CharacterModel) ? model : null);
				if (val2 == null)
				{
					RelicModel val3 = (RelicModel)(object)((model is RelicModel) ? model : null);
					if (val3 == null)
					{
						MonsterModel val4 = (MonsterModel)(object)((model is MonsterModel) ? model : null);
						if (val4 == null)
						{
							EventModel val5 = (EventModel)(object)((model is EventModel) ? model : null);
