							{
								return ReadEventTitle(((AbstractModel)val5).Id.Entry, new LocString("events", ((AbstractModel)val5).Id.Entry), new LocString("events", ((AbstractModel)val5).Id.Entry + ".title"), new LocString("events", ((AbstractModel)val5).Id.Entry + ".name"), val5.Title);
							}
							return null;
						}
						return ReadLocPreferChinese(MonsterModel.L10NMonsterLookup(((AbstractModel)val4).Id.Entry + ".name"), MonsterModel.L10NMonsterLookup(((AbstractModel)val4).Id.Entry), val4.Title);
					}
					return ReadLocPreferChinese(new LocString("relics", ((AbstractModel)val3).Id.Entry), new LocString("relics", ((AbstractModel)val3).Id.Entry + ".title"), val3.Title);
				}
				return ReadLocPreferChinese(new LocString("characters", ((AbstractModel)val2).Id.Entry), new LocString("characters", ((AbstractModel)val2).Id.Entry + ".title"), val2.Title);
			}
			return val.Title;
		}

