		private static string? ReadLocPreferChinese(params LocString[] candidates)
		{
			string text = null;
			for (int i = 0; i < candidates.Length; i++)
			{
				string text2 = ReadLoc(candidates[i]);
				if (!string.IsNullOrWhiteSpace(text2))
				{
					if (text == null)
					{
						text = text2;
					}
					if (ContainsCjk(text2))
					{
						return text2;
					}
				}
			}
			return text;
		}

		private static bool ContainsCjk(string value)
		{
			foreach (char c in value)
			{
				if ((c >= '一' && c <= '\u9fff') || (c >= '㐀' && c <= '䶿'))
				{
					return true;
				}
			}
			return false;
		}

		private static string? ReadEventTitle(string eventId, params LocString[] candidates)
		{
			string text = ReadLocPreferChinese(candidates);
			if (ContainsCjk(text ?? ""))
			{
				return text;
			}
			return OriginalChineseNames.EventName(eventId) ?? text;
		}

		private static string? ReadLoc(LocString locString)
		{
			try
			{
				return locString.GetFormattedText();
			}
			catch
			{
				return null;
			}
		}

		private static string FormatDisplayName(string? name, string id)
		{
			if (string.IsNullOrWhiteSpace(name) || string.Equals(name, id, StringComparison.OrdinalIgnoreCase))
			{
				return id;
			}
			return name.Trim();
		}

		private static IReadOnlyList<EventOptionEntry> ScanAllEventOptions()
		{
			//IL_008c: Unknown result type (might be due to invalid IL or missing references)
			List<EventOptionEntry> list = new List<EventOptionEntry>();
			HashSet<(string, string)> hashSet = new HashSet<(string, string)>();
			foreach (LocString item2 in LocManager.Instance.GetTable("events").GetLocStringsWithPrefix(""))
			{
				string locEntryKey = item2.LocEntryKey;
				(string, string)? tuple = ParseEventOptionKey(locEntryKey);
				if (tuple.HasValue && hashSet.Add((tuple.Value.Item1, tuple.Value.Item2)))
				{
					string item = tuple.Value.Item2;
					try
					{
						item = new LocString("events", locEntryKey).GetFormattedText() ?? tuple.Value.Item2;
					}
					catch
					{
						item = tuple.Value.Item2;
					}
					if (string.IsNullOrWhiteSpace(item) || string.Equals(item, tuple.Value.Item2, StringComparison.Ordinal))
					{
						item = tuple.Value.Item2;
					}
					string text = OriginalChineseNames.EventOptionName(tuple.Value.Item1, tuple.Value.Item2);
					if (!string.IsNullOrWhiteSpace(text) && !ContainsCjk(item))
					{
						item = text;
					}
					list.Add(new EventOptionEntry(tuple.Value.Item1, tuple.Value.Item2, item.Trim()));
				}
			}
			foreach (var (text2, text3, text4) in OriginalChineseNames.EnumerateEventOptions())
			{
				if (hashSet.Add((text2, text3)))
				{
					list.Add(new EventOptionEntry(text2, text3, text4.Trim()));
				}
			}
			return list;
		}

		public static (string EventId, string OptionKey)? ParseEventOptionKey(string key)
		{
			if (string.IsNullOrWhiteSpace(key))
			{
				return null;
			}
			if (!key.EndsWith(".title", StringComparison.Ordinal))
			{
				return null;
			}
			int num = key.IndexOf(".options.", StringComparison.Ordinal);
			if (num <= 0)
			{
				return null;
			}
			string text = key.Substring(0, num);
			int num2 = text.LastIndexOf(".pages.", StringComparison.Ordinal);
			if (num2 <= 0)
			{
				return null;
			}
			string text2 = text.Substring(0, num2);
			string text3 = key.Substring(num + ".options.".Length);
			string text4 = text3.Substring(0, text3.Length - ".title".Length);
			if (string.IsNullOrWhiteSpace(text2) || string.IsNullOrWhiteSpace(text4))
			{
				return null;
			}
			if (string.Equals(text4, "PROCEED", StringComparison.OrdinalIgnoreCase))
			{
				return null;
			}
			return (text2, text4);
		}

		public static string ComputeFingerprint()
		{
			try
			{
				string text = typeof(RunManager).Assembly.GetName().Version?.ToString() ?? "unknown";
				string text2 = "";
				try
				{
					LocManager instance = LocManager.Instance;
					text2 = ((instance != null) ? instance.Language : null) ?? "";
				}
				catch
				{
					text2 = "";
				}
				List<string> list = new List<string>();
				try
				{
					foreach (Mod loadedMod in ModManager.GetLoadedMods())
					{
						string text3 = loadedMod.manifest?.id ?? loadedMod.path ?? "?";
						string text4 = ((object)loadedMod.version)?.ToString() ?? "?";
						list.Add(text3 + "@" + text4);
					}
				}
				catch
				{
				}
				list.Sort(StringComparer.Ordinal);
				string s = "catalog-v6|" + text + "|" + text2 + "|" + string.Join(",", list);
				return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s))).ToLowerInvariant();
			}
			catch
			{
				return "fingerprint-unavailable";
			}
		}
	}
	public sealed record ContentParseResult(IReadOnlyList<ContentEntry> Entries, IReadOnlyList<string> Errors);
	public sealed record ContentShardParse(IReadOnlyList<ContentEntry> Entries, IReadOnlyList<string> Errors, IReadOnlyList<string> DeletedIds);
	public static class ContentPackParser
	{
		public static ContentManifest ParseManifest(string json)
		{
			using JsonDocument jsonDocument = JsonDocument.Parse(StripBom(json));
			JsonElement rootElement = jsonDocument.RootElement;
			int @int = rootElement.GetProperty("schemaVersion").GetInt32();
			string modVersion = rootElement.GetProperty("modVersion").GetString() ?? "";
			long int2 = rootElement.GetProperty("ugcVersion").GetInt64();
			JsonElement value;
			string signature = ((rootElement.TryGetProperty("signature", out value) && value.ValueKind == JsonValueKind.String) ? (value.GetString() ?? "") : "");
			List<ContentShardInfo> list = new List<ContentShardInfo>();
			if (rootElement.TryGetProperty("shards", out var value2))
			{
				foreach (JsonElement item in value2.EnumerateArray())
				{
					list.Add(new ContentShardInfo(item.GetProperty("name").GetString() ?? "", item.GetProperty("version").GetInt64(), item.GetProperty("sha256").GetString() ?? ""));
				}
			}
			return new ContentManifest(@int, modVersion, int2, list, signature);
		}

		public static ContentParseResult ParseEntries(string json)
		{
			ContentShardParse contentShardParse = ParseShard(json);
			return new ContentParseResult(contentShardParse.Entries, contentShardParse.Errors);
		}

		public static ContentShardParse ParseShard(string json)
		{
			List<ContentEntry> list = new List<ContentEntry>();
			List<string> list2 = new List<string>();
			List<string> list3 = new List<string>();
			using JsonDocument jsonDocument = JsonDocument.Parse(StripBom(json));
			JsonElement rootElement = jsonDocument.RootElement;
			if (rootElement.TryGetProperty("deletedIds", out var value) && value.ValueKind == JsonValueKind.Array)
			{
				foreach (JsonElement item in value.EnumerateArray())
				{
					if (item.ValueKind == JsonValueKind.String && !string.IsNullOrEmpty(item.GetString()))
					{
						list3.Add(item.GetString());
					}
				}
			}
			if (rootElement.TryGetProperty("entries", out var value2))
			{
				int num = 0;
				foreach (JsonElement item2 in value2.EnumerateArray())
				{
					string position = $"第 {num} 条";
					if (TryParseEntry(item2, position, out ContentEntry entry, out string error))
					{
						list.Add(entry);
					}
					else
					{
						list2.Add(error ?? "未知解析错误");
					}
					num++;
				}
			}
			return new ContentShardParse(list, list2, list3);
		}

		private static string StripBom(string json)
		{
			if (json.Length <= 0 || json[0] != '\ufeff')
			{
				return json;
			}
			return json.Substring(1, json.Length - 1);
		}

		private static bool TryParseEntry(JsonElement element, string position, out ContentEntry entry, out string? error)
		{
			entry = default(ContentEntry);
			error = null;
			try
			{
				string id = element.GetProperty("id").GetString() ?? "";
				string text = element.GetProperty("text").GetString() ?? "";
				string text2 = element.GetProperty("style").GetString() ?? "";
				JsonElement value;
				string author = (element.TryGetProperty("author", out value) ? (value.GetString() ?? "") : "");
				JsonElement value2;
				string text3 = ((element.TryGetProperty("color", out value2) && value2.ValueKind == JsonValueKind.String) ? value2.GetString() : null);
				if (string.IsNullOrWhiteSpace(text3))
				{
					text3 = null;
				}
				JsonElement value3;
				string avatar = ((element.TryGetProperty("avatar", out value3) && value3.ValueKind == JsonValueKind.String) ? value3.GetString() : null);
				JsonElement value4;
				int source = (element.TryGetProperty("source", out value4) ? value4.GetInt32() : (-1));
				JsonElement value5;
				bool topPinned = element.TryGetProperty("top", out value5) && value5.ValueKind == JsonValueKind.True;
				JsonElement value6;
				bool rainbow = element.TryGetProperty("rainbow", out value6) && value6.ValueKind == JsonValueKind.True;
				IReadOnlyList<string> continuationTexts = ParseStringArray(element, "continuation");
				JsonElement value7;
				DanmakuSequenceSpeed sequenceSpeed = DanmakuSequence.Parse((element.TryGetProperty("sequenceSpeed", out value7) && value7.ValueKind == JsonValueKind.String) ? value7.GetString() : null);
				if (!TryParseStyle(text2, out var style))
				{
					error = position + " 未知 style：" + text2;
					return false;
				}
				if (!element.TryGetProperty("trigger", out var value8) || !TryParseTrigger(value8, out var trigger))
				{
					error = position + " trigger 缺失或非法";
					return false;
				}
				List<ContentPrecondition> list = new List<ContentPrecondition>();
				if (element.TryGetProperty("pre", out var value9) && value9.ValueKind == JsonValueKind.Array)
				{
					foreach (JsonElement item in value9.EnumerateArray())
					{
						if (TryParsePrecondition(item, out var precondition))
						{
							list.Add(precondition);
							continue;
						}
						error = position + " 前置条件非法";
						return false;
					}
				}
				entry = new ContentEntry(id, text, style, author, text3, avatar, trigger, list, source, topPinned, rainbow, continuationTexts, sequenceSpeed);
				return true;
			}
			catch (Exception ex) when (((ex is JsonException || ex is KeyNotFoundException || ex is InvalidOperationException) ? 1 : 0) != 0)
			{
				error = position + " 解析失败：" + ex.Message;
				return false;
			}
		}

		private static IReadOnlyList<string> ParseStringArray(JsonElement element, string propertyName)
		{
			if (!element.TryGetProperty(propertyName, out var value2) || value2.ValueKind != JsonValueKind.Array)
			{
				return Array.Empty<string>();
			}
			return (from value in value2.EnumerateArray()
				where value.ValueKind == JsonValueKind.String
				select value.GetString() ?? "").ToArray();
		}

		private static bool TryParseTrigger(JsonElement element, out ContentTrigger trigger)
		{
			trigger = default(ContentTrigger);
			if (!TryParseKind(element.GetProperty("kind").GetString() ?? "", out var kind))
			{
				return false;
			}
			if (!TryParseInstant(element.GetProperty("timing").GetString() ?? "", out var instant))
			{
				return false;
			}
			string id = element.GetProperty("id").GetString() ?? "";
			trigger = new ContentTrigger(kind, instant, id);
			return true;
		}

		private static bool TryParsePrecondition(JsonElement element, out ContentPrecondition precondition)
		{
			precondition = default(ContentPrecondition);
			if (!TryParseKind(element.GetProperty("kind").GetString() ?? "", out var kind))
			{
				return false;
			}
			if (!TryParseInterval(element.GetProperty("timing").GetString() ?? "", out var interval))
			{
				return false;
			}
			string id = element.GetProperty("id").GetString() ?? "";
			precondition = new ContentPrecondition(kind, interval, id);
			return true;
		}

		private static bool TryParseKind(string value, out ContentObjectKind kind)
		{
			switch (value)
			{
			case "character":
				kind = ContentObjectKind.Character;
				return true;
			case "card":
				kind = ContentObjectKind.Card;
				return true;
			case "relic":
				kind = ContentObjectKind.Relic;
				return true;
			case "monster":
				kind = ContentObjectKind.Monster;
				return true;
			case "event":
				kind = ContentObjectKind.Event;
				return true;
			case "act":
				kind = ContentObjectKind.Act;
				return true;
			case "turn":
				kind = ContentObjectKind.Turn;
				return true;
			default:
				kind = ContentObjectKind.Character;
				return false;
			}
		}

		private static bool TryParseStyle(string value, out ContentStyle style)
		{
			if (!(value == "character"))
			{
				if (value == "narration")
				{
					style = ContentStyle.Narration;
					return true;
				}
				style = ContentStyle.Character;
				return false;
			}
			style = ContentStyle.Character;
			return true;
		}

		private static bool TryParseInterval(string value, out ContentInterval interval)
		{
			switch (value)
			{
			case "using":
				interval = ContentInterval.Using;
				return true;
			case "own":
				interval = ContentInterval.Own;
				return true;
			case "inCombat":
				interval = ContentInterval.InCombat;
				return true;
			case "inEvent":
				interval = ContentInterval.InEvent;
				return true;
			case "atAct":
				interval = ContentInterval.AtAct;
				return true;
			case "atTurn":
				interval = ContentInterval.AtTurn;
				return true;
			default:
				interval = ContentInterval.Using;
				return false;
			}
		}

		private static bool TryParseInstant(string value, out ContentInstant instant)
		{
			switch (value)
			{
			case "preselected":
				instant = ContentInstant.Preselected;
				return true;
			case "confirmed":
				instant = ContentInstant.Confirmed;
				return true;
			case "obtained":
				instant = ContentInstant.Obtained;
				return true;
			case "upgraded":
				instant = ContentInstant.Upgraded;
				return true;
			case "removed":
				instant = ContentInstant.Removed;
				return true;
			case "played":
				instant = ContentInstant.Played;
				return true;
			case "encountered":
				instant = ContentInstant.Encountered;
				return true;
			case "defeated":
				instant = ContentInstant.Defeated;
				return true;
			case "combat":
				instant = ContentInstant.Combat;
				return true;
			case "entered":
				instant = ContentInstant.Entered;
				return true;
			case "optionSelected":
				instant = ContentInstant.OptionSelected;
				return true;
			case "actEntered":
				instant = ContentInstant.ActEntered;
				return true;
			case "turnEntered":
				instant = ContentInstant.TurnEntered;
				return true;
			default:
				instant = ContentInstant.Preselected;
				return false;
			}
		}
	}
	public static class ContentSigning
	{
		private const string PublicKeyHex = "04254313988494ccf5fad6cf16360ad1f990f186af7725a35ab244820841a4c3639df9aa1495f1faad0c3eb5dd3dc97496efa7a0718f9d3211e0169c854edb8208";

		private static readonly ECParameters PublicParameters = ParsePublicKey("04254313988494ccf5fad6cf16360ad1f990f186af7725a35ab244820841a4c3639df9aa1495f1faad0c3eb5dd3dc97496efa7a0718f9d3211e0169c854edb8208");

		public static string BuildSignatureInput(ContentManifest manifest)
		{
			List<string> list = new List<string>
			{
				"danmaku-manifest-v1",
				manifest.SchemaVersion.ToString(CultureInfo.InvariantCulture),
				manifest.ModVersion,
				manifest.UgcVersion.ToString(CultureInfo.InvariantCulture)
			};
			foreach (ContentShardInfo shard in manifest.Shards)
			{
				list.Add($"{shard.Name}:{shard.Version}:{shard.Sha256}");
			}
			return string.Join("\n", list);
		}

		public static bool VerifyManifestSignature(ContentManifest manifest, string signatureHex)
		{
			if (string.IsNullOrEmpty(signatureHex))
			{
				return false;
			}
			try
			{
				using ECDsa eCDsa = ECDsa.Create(PublicParameters);
				byte[] bytes = Encoding.UTF8.GetBytes(BuildSignatureInput(manifest));
				byte[] signature = Convert.FromHexString(signatureHex);
				return eCDsa.VerifyData(bytes, signature, HashAlgorithmName.SHA256, DSASignatureFormat.IeeeP1363FixedFieldConcatenation);
			}
			catch
			{
				return false;
			}
		}

		private static ECParameters ParsePublicKey(string hex)
		{
			byte[] array = Convert.FromHexString(hex);
			if (array.Length != 65 || array[0] != 4)
			{
				throw new ArgumentException("公钥格式非法，应为 65 字节未压缩点。");
			}
			ECParameters result = default(ECParameters);
			result.Curve = ECCurve.NamedCurves.nistP256;
			result.Q = new ECPoint
			{
				X = array[1..33],
				Y = array[33..65]
			};
			return result;
		}
	}
	public enum ContentLayer
	{
		Baseline,
		Ugc,
		Overlay
	}
	public readonly record struct ContentLoadResult(int Added, int Replaced, int Skipped);
	public sealed class ContentStore
	{
		private readonly Dictionary<string, ContentEntry> _byId = new Dictionary<string, ContentEntry>(StringComparer.Ordinal);

		private readonly Dictionary<string, ContentLayer> _layerById = new Dictionary<string, ContentLayer>(StringComparer.Ordinal);

		private readonly Dictionary<ContentTrigger, List<ContentEntry>> _triggerIndex = new Dictionary<ContentTrigger, List<ContentEntry>>();

		private readonly List<ContentEntry> _entries = new List<ContentEntry>();

		public IReadOnlyList<ContentEntry> Entries => _entries;

		public ContentEntry? GetById(string id)
		{
			if (!_byId.TryGetValue(id, out var value))
			{
				return null;
			}
			return value;
		}

		public ContentLoadResult Load(IReadOnlyList<ContentEntry> entries, ContentLayer layer)
		{
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			foreach (ContentEntry entry in entries)
			{
				if (_layerById.TryGetValue(entry.Id, out var value))
				{
					if (layer >= value)
					{
						if (_byId.TryGetValue(entry.Id, out var value2))
						{
							RemoveFromTriggerIndex(value2);
						}
						int num4 = _entries.FindIndex((ContentEntry e) => e.Id == entry.Id);
						if (num4 >= 0)
						{
							_entries[num4] = entry;
						}
						else
						{
							_entries.Add(entry);
						}
						_byId[entry.Id] = entry;
						_layerById[entry.Id] = layer;
						AddToTriggerIndex(entry);
						num2++;
					}
					else
					{
						num3++;
					}
				}
				else
				{
					_entries.Add(entry);
					_byId[entry.Id] = entry;
					_layerById[entry.Id] = layer;
					AddToTriggerIndex(entry);
					num++;
				}
			}
			return new ContentLoadResult(num, num2, num3);
		}

		public int RemoveIds(IReadOnlyList<string> ids, ContentLayer layer)
		{
			int num = 0;
			foreach (string id in ids)
			{
				if (_layerById.TryGetValue(id, out var value) && value == layer)
				{
					if (_byId.TryGetValue(id, out var value2))
					{
						RemoveFromTriggerIndex(value2);
					}
					_byId.Remove(id);
					int num2 = _entries.FindIndex((ContentEntry e) => e.Id == id);
					if (num2 >= 0)
					{
						_entries.RemoveAt(num2);
					}
					_layerById.Remove(id);
					num++;
				}
			}
			return num;
		}

		public void Clear()
		{
			_byId.Clear();
			_layerById.Clear();
			_triggerIndex.Clear();
			_entries.Clear();
		}

		public IReadOnlyList<ContentEntry> Query(ContentTrigger trigger)
		{
			_triggerIndex.TryGetValue(trigger, out List<ContentEntry> value);
			List<ContentEntry> value2 = null;
			if (!trigger.IsWildcard)
			{
				_triggerIndex.TryGetValue(trigger with
				{
					Id = "*"
				}, out value2);
			}
			if (value == null && value2 == null)
			{
				return Array.Empty<ContentEntry>();
			}
			List<ContentEntry> list = new List<ContentEntry>((value?.Count ?? 0) + (value2?.Count ?? 0));
			if (value != null)
			{
				list.AddRange(value);
			}
			if (value2 != null)
			{
				list.AddRange(value2);
			}
			return list;
		}

		private void AddToTriggerIndex(ContentEntry entry)
		{
			if (!_triggerIndex.TryGetValue(entry.Trigger, out List<ContentEntry> value))
			{
				value = new List<ContentEntry>();
				_triggerIndex[entry.Trigger] = value;
			}
			value.Add(entry);
		}

		private void RemoveFromTriggerIndex(ContentEntry entry)
		{
			if (_triggerIndex.TryGetValue(entry.Trigger, out List<ContentEntry> value))
			{
				value.RemoveAll((ContentEntry candidate) => candidate.Id == entry.Id);
				if (value.Count == 0)
				{
					_triggerIndex.Remove(entry.Trigger);
				}
			}
		}

		public static bool Matches(ContentTrigger entryTrigger, ContentTrigger queryTrigger)
		{
			if (entryTrigger.Kind == queryTrigger.Kind && entryTrigger.Timing == queryTrigger.Timing)
			{
				if (!(entryTrigger.Id == queryTrigger.Id))
				{
					return entryTrigger.IsWildcard;
				}
				return true;
			}
			return false;
		}
	}
	public static class ContentValidator
	{
		public const int MaxTextLength = 40;

		public const int MaxAuthorLength = 16;

		public const int MaxPreconditions = 5;

		public const int MaxObjectIdLength = 128;

		public static int CountCharacters(string text)
		{
			if (string.IsNullOrEmpty(text))
			{
				return 0;
			}
			int num = 0;
			for (int i = 0; i < text.Length; i++)
			{
				num++;
				if (char.IsHighSurrogate(text[i]) && i + 1 < text.Length && char.IsLowSurrogate(text[i + 1]))
				{
					i++;
				}
			}
			return num;
		}

		public static int CountTextCharacters(string text)
		{
			return CountCharacters(text);
		}

		public static string TruncateCharacters(string text, int maximum)
		{
			if (string.IsNullOrEmpty(text) || maximum <= 0)
			{
				if (maximum > 0)
				{
					return text;
				}
				return string.Empty;
			}
			int num = 0;
			for (int i = 0; i < text.Length; i++)
			{
				bool flag = char.IsHighSurrogate(text[i]) && i + 1 < text.Length && char.IsLowSurrogate(text[i + 1]);
				num++;
				if (num > maximum)
				{
					return text.Substring(0, i);
				}
				if (flag)
				{
					i++;
				}
			}
			return text;
		}

		public static IReadOnlyList<string> ValidateEntry(ContentEntry entry)
		{
			List<string> list = new List<string>();
			if (string.IsNullOrWhiteSpace(entry.Id))
			{
				list.Add("id 不能为空");
			}
			if (string.IsNullOrWhiteSpace(entry.Text))
			{
				list.Add("text 不能为空");
			}
			else if (CountCharacters(entry.Text) > 40)
			{
				list.Add($"text 超过 {40} 字：{CountCharacters(entry.Text)}");
			}
			if (entry.AllTexts.Count > 5)
			{
				list.Add($"连续弹幕超过 {5} 条：{entry.AllTexts.Count}");
			}
			for (int i = 0; i < entry.StableContinuationTexts.Count; i++)
			{
				string text = entry.StableContinuationTexts[i];
				if (string.IsNullOrWhiteSpace(text))
				{
					list.Add($"第 {i + 2} 条连续弹幕不能为空");
				}
				else if (CountTextCharacters(text) > 40)
				{
					list.Add($"第 {i + 2} 条连续弹幕超过 {40} 字");
				}
			}
			if (CountCharacters(entry.Author) > 16)
			{
				list.Add($"author 超过 {16} 字：{CountCharacters(entry.Author)}");
			}
			if (!IsValidColor(entry.Color))
			{
				list.Add("color 格式非法：" + entry.Color);
			}
			if (!IsValidAvatar(entry.Avatar))
			{
				list.Add("avatar 格式非法：" + entry.Avatar);
			}
			if (entry.Source < 0)
			{
				list.Add("source 必须非负（来源必填）");
			}
			if (!ContentConditionRules.IsValidInstant(entry.Trigger.Kind, entry.Trigger.Timing))
			{
				list.Add($"触发对象与时机不配对：{entry.Trigger.Kind}/{entry.Trigger.Timing}");
			}
			if (!IsValidObjectId(entry.Trigger.Id))
			{
				list.Add($"触发对象 id 不能为空且不得超过 {128} 字");
			}
			if (ContentConditionRules.IsContextInstant(entry.Trigger.Kind, entry.Trigger.Timing) && !ContentConditionRules.IsValidContextTriggerId(entry.Trigger.Id))
			{
				list.Add("「进入幕/回合」触发 id 必须为正整数或通配 *：" + entry.Trigger.Id);
			}
			if (entry.Trigger.Timing == ContentInstant.Combat && !entry.Trigger.IsWildcard)
			{
				list.Add("敌怪「战中」时机必须用通配 *（具体敌怪请用前置「所处 inCombat」限定）");
			}
			if (entry.Preconditions.Count > 5)
			{
				list.Add($"前置条件超过 {5} 个：{entry.Preconditions.Count}");
			}
			HashSet<ContentObjectKind> hashSet = new HashSet<ContentObjectKind>();
			foreach (ContentPrecondition precondition in entry.Preconditions)
			{
				if (!ContentConditionRules.IsValidInterval(precondition.Kind, precondition.Timing))
				{
					list.Add($"前置对象与时机不配对：{precondition.Kind}/{precondition.Timing}");
				}
				if (!IsValidObjectId(precondition.Id))
				{
					list.Add($"前置对象 id 不能为空且不得超过 {128} 字");
				}
				if (ContentConditionRules.IsContextInterval(precondition.Kind, precondition.Timing) && !ContentConditionRules.IsValidContextValue(precondition.Id))
				{
					list.Add("「处于幕/回合」前置 id 必须为正整数（不允许通配）：" + precondition.Id);
				}
				if (!hashSet.Add(precondition.Kind))
				{
					list.Add($"同一对象类型出现多个前置：{precondition.Kind}");
				}
			}
			return list;
		}

		public static IReadOnlyList<string> ValidatePackIds(IReadOnlyList<ContentEntry> entries)
		{
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			List<string> list = new List<string>();
			foreach (ContentEntry entry in entries)
			{
				if (!hashSet.Add(entry.Id))
				{
					list.Add(entry.Id);
				}
			}
			return list;
		}

		public static bool IsValidColor(string? color)
		{
			if (string.IsNullOrWhiteSpace(color))
			{
				return true;
			}
			string text;
			if (!color.StartsWith('#'))
			{
				text = color;
			}
			else
			{
				text = color.Substring(1, color.Length - 1);
			}
			string text2 = text;
			if (text2.Length == 6)
			{
				return text2.All(char.IsAsciiHexDigit);
			}
			return false;
		}

		public static bool IsValidObjectId(string? id)
		{
			if (!string.IsNullOrWhiteSpace(id))
			{
				return CountCharacters(id) <= 128;
			}
			return false;
		}

		public static bool IsValidAvatar(string? avatar)
		{
			if (string.IsNullOrWhiteSpace(avatar))
			{
				return true;
			}
			if (CountCharacters(avatar) <= 128)
			{
				return avatar.All(delegate(char ch)
				{
					bool flag = char.IsAsciiLetterOrDigit(ch);
					if (!flag)
					{
						bool flag2 = ((ch == '-' || ch == '_') ? true : false);
						flag = flag2;
					}
					return flag;
				});
			}
			return false;
		}
	}
	public sealed record DanmakuLikeUploadResult(bool Ok, int Added, int Removed, string? Error = null);
	public sealed class DanmakuLikeClient
	{
		private readonly HttpClient _http;

		private readonly string _baseUrl;

		public DanmakuLikeClient(HttpClient http, string baseUrl)
		{
			_http = http;
			_baseUrl = baseUrl.TrimEnd('/');
		}

		public async Task<DanmakuLikeUploadResult> UploadAsync(IReadOnlyList<string> add, IReadOnlyList<string> remove, CancellationToken token = default(CancellationToken))
		{
			string[] array = Normalize(add);
			string[] array2 = Normalize(remove);
			if (array.Length == 0 && array2.Length == 0)
			{
				return new DanmakuLikeUploadResult(Ok: true, 0, 0);
			}
			try
			{
				string content2 = JsonSerializer.Serialize(new
				{
					device_id = DeviceIdentity.GetDeviceId(),
					add = array,
					remove = array2
				});
				using StringContent content = new StringContent(content2, Encoding.UTF8, "application/json");
				using HttpResponseMessage response = await _http.PostAsync(_baseUrl + "/likes", content, token).ConfigureAwait(continueOnCapturedContext: false);
				string json = await response.Content.ReadAsStringAsync(token).ConfigureAwait(continueOnCapturedContext: false);
				if (!response.IsSuccessStatusCode)
				{
					return new DanmakuLikeUploadResult(Ok: false, 0, 0, "server_error");
				}
				using JsonDocument jsonDocument = JsonDocument.Parse(json);
				JsonElement value;
				int added = ((jsonDocument.RootElement.TryGetProperty("added", out value) && value.ValueKind == JsonValueKind.Number) ? value.GetInt32() : 0);
				JsonElement value2;
				int removed = ((jsonDocument.RootElement.TryGetProperty("removed", out value2) && value2.ValueKind == JsonValueKind.Number) ? value2.GetInt32() : 0);
				return new DanmakuLikeUploadResult(Ok: true, added, removed);
			}
			catch (Exception ex) when (((ex is HttpRequestException || ex is TaskCanceledException || ex is ObjectDisposedException || ex is JsonException) ? 1 : 0) != 0)
			{
				return new DanmakuLikeUploadResult(Ok: false, 0, 0, "network");
			}
		}

		private static string[] Normalize(IReadOnlyList<string> entryIds)
		{
			return entryIds.Where((string id) => !string.IsNullOrWhiteSpace(id)).Distinct<string>(StringComparer.Ordinal).ToArray();
		}
	}
	public static class DanmakuLikeService
	{
		private static DanmakuLikeStore? _store;

		private static DanmakuLikeClient? _client;

		public static IReadOnlyList<string> PendingAdd => _store?.PendingAdd ?? Array.Empty<string>();

		public static IReadOnlyList<string> PendingRemove => _store?.PendingRemove ?? Array.Empty<string>();

		public static void Initialize(string storePath, HttpClient? http = null)
		{
			_store = new DanmakuLikeStore(storePath);
			_client = new DanmakuLikeClient(http ?? new HttpClient
			{
				Timeout = TimeSpan.FromSeconds(8L)
			}, "https://danmaku.danmakuspire.top");
		}

		public static void Shutdown()
		{
			_store = null;
			_client = null;
		}

		public static bool IsLiked(string entryId)
		{
			return _store?.IsLiked(entryId) ?? false;
		}

		public static bool Like(string entryId)
		{
			return _store?.TryAdd(entryId) ?? false;
		}

		public static bool Unlike(string entryId)
		{
			return _store?.TryRemove(entryId) ?? false;
		}

		public static async Task FlushPendingAsync(CancellationToken token = default(CancellationToken))
		{
			if (_store != null && _client != null)
			{
				IReadOnlyList<string> adds = _store.PendingAdd;
				IReadOnlyList<string> removes = _store.PendingRemove;
				if ((adds.Count != 0 || removes.Count != 0) && (await _client.UploadAsync(adds, removes, token).ConfigureAwait(continueOnCapturedContext: false)).Ok)
				{
					_store.MarkUploaded(adds, removes);
				}
			}
		}
	}
	public sealed class DanmakuLikeStore
	{
		private static readonly JsonSerializerOptions Json = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
		};

		private readonly object _sync = new object();

		private readonly string _path;

		private readonly HashSet<string> _liked = new HashSet<string>(StringComparer.Ordinal);

		private readonly HashSet<string> _pendingAdd = new HashSet<string>(StringComparer.Ordinal);

		private readonly HashSet<string> _pendingRemove = new HashSet<string>(StringComparer.Ordinal);

		private bool _loaded;

		public IReadOnlyList<string> PendingAdd
		{
			get
			{
				EnsureLoaded();
				lock (_sync)
				{
					return _pendingAdd.ToArray();
				}
			}
		}

		public IReadOnlyList<string> PendingRemove
		{
			get
			{
				EnsureLoaded();
				lock (_sync)
				{
					return _pendingRemove.ToArray();
				}
			}
		}

		public DanmakuLikeStore(string path)
		{
			_path = path;
		}

		public bool IsLiked(string entryId)
		{
			if (string.IsNullOrWhiteSpace(entryId))
			{
				return false;
			}
			EnsureLoaded();
			lock (_sync)
			{
				return _liked.Contains(entryId);
			}
		}

		public bool TryAdd(string entryId)
		{
			if (string.IsNullOrWhiteSpace(entryId))
			{
				return false;
			}
			EnsureLoaded();
			lock (_sync)
			{
				if (!_liked.Add(entryId))
				{
					return false;
				}
				if (!_pendingRemove.Remove(entryId))
				{
					_pendingAdd.Add(entryId);
				}
				Save();
				return true;
			}
		}

		public bool TryRemove(string entryId)
		{
			if (string.IsNullOrWhiteSpace(entryId))
			{
				return false;
			}
			EnsureLoaded();
			lock (_sync)
			{
				if (!_liked.Remove(entryId))
				{
					return false;
				}
				if (!_pendingAdd.Remove(entryId))
				{
					_pendingRemove.Add(entryId);
				}
				Save();
				return true;
			}
		}

		public void MarkUploaded(IEnumerable<string> added, IEnumerable<string> removed)
		{
			EnsureLoaded();
			lock (_sync)
			{
				bool flag = false;
				foreach (string item in added)
				{
					if (!string.IsNullOrWhiteSpace(item) && _pendingAdd.Remove(item))
					{
						flag = true;
					}
				}
				foreach (string item2 in removed)
				{
					if (!string.IsNullOrWhiteSpace(item2) && _pendingRemove.Remove(item2))
					{
						flag = true;
					}
				}
				if (flag)
				{
					Save();
				}
			}
		}

		private void EnsureLoaded()
		{
			if (_loaded)
			{
				return;
			}
			lock (_sync)
			{
				if (_loaded)
				{
					return;
				}
				try
				{
					if (File.Exists(_path))
					{
						using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(_path, Encoding.UTF8));
						if (jsonDocument.RootElement.TryGetProperty("liked", out var value) && value.ValueKind == JsonValueKind.Array)
						{
							foreach (JsonElement item in value.EnumerateArray())
							{
								if (item.ValueKind == JsonValueKind.String)
								{
									_liked.Add(item.GetString());
								}
							}
						}
						if (jsonDocument.RootElement.TryGetProperty("pendingAdd", out var value2) && value2.ValueKind == JsonValueKind.Array)
						{
							foreach (JsonElement item2 in value2.EnumerateArray())
							{
								if (item2.ValueKind == JsonValueKind.String)
								{
									_pendingAdd.Add(item2.GetString());
								}
							}
						}
						if (jsonDocument.RootElement.TryGetProperty("pendingRemove", out var value3) && value3.ValueKind == JsonValueKind.Array)
						{
							foreach (JsonElement item3 in value3.EnumerateArray())
							{
								if (item3.ValueKind == JsonValueKind.String)
								{
									_pendingRemove.Add(item3.GetString());
								}
							}
						}
						if (jsonDocument.RootElement.TryGetProperty("pending", out var value4) && value4.ValueKind == JsonValueKind.Array)
						{
							foreach (JsonElement item4 in value4.EnumerateArray())
							{
								if (item4.ValueKind == JsonValueKind.String)
								{
									_pendingAdd.Add(item4.GetString());
								}
							}
						}
					}
				}
				catch
				{
				}
				_loaded = true;
			}
		}

		private void Save()
		{
			try
			{
				string directoryName = Path.GetDirectoryName(_path);
				if (!string.IsNullOrEmpty(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				string contents = JsonSerializer.Serialize(new
				{
					liked = _liked.OrderBy<string, string>((string id) => id, StringComparer.Ordinal).ToArray(),
					pendingAdd = _pendingAdd.OrderBy<string, string>((string id) => id, StringComparer.Ordinal).ToArray(),
					pendingRemove = _pendingRemove.OrderBy<string, string>((string id) => id, StringComparer.Ordinal).ToArray()
				}, Json);
				string text = _path + ".new";
				File.WriteAllText(text, contents, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				File.Move(text, _path, overwrite: true);
			}
			catch
			{
			}
		}
	}
	public static class DeviceIdentity
	{
		private static readonly object Sync = new object();

		private static string? _cached;

		private static Func<string?> _rawDeviceIdProvider = () => (string?)null;

		private static Func<string?> _persistentFallbackIdProvider = () => (string?)null;

		public static Func<string?> RawDeviceIdProvider
		{
			get
			{
				return _rawDeviceIdProvider;
			}
			set
			{
				lock (Sync)
				{
					_rawDeviceIdProvider = value ?? ((Func<string>)(() => (string?)null));
					_cached = null;
				}
			}
		}

		public static Func<string?> PersistentFallbackIdProvider
		{
			get
			{
				return _persistentFallbackIdProvider;
			}
			set
			{
				lock (Sync)
				{
					_persistentFallbackIdProvider = value ?? ((Func<string>)(() => (string?)null));
					_cached = null;
				}
			}
		}

		public static string GetDeviceId()
		{
			lock (Sync)
			{
				if (_cached != null)
				{
					return _cached;
				}
				string text = "";
				try
				{
					text = _rawDeviceIdProvider() ?? "";
				}
				catch
				{
					text = "";
				}
				if (string.IsNullOrWhiteSpace(text))
				{
					try
					{
						text = _persistentFallbackIdProvider() ?? "";
					}
					catch
					{
						text = "";
					}
				}
				if (string.IsNullOrWhiteSpace(text))
				{
					text = "device-" + Guid.NewGuid().ToString("N");
				}
				_cached = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
				return _cached;
			}
		}
	}
	public readonly record struct HotspotEmission(ContentTrigger Trigger, string EntryId);
	public sealed class Hotspot
	{
		private readonly Random _random;

		private double _nextEmissionAt;

		public ContentTrigger Trigger { get; }

		public double StartedAt { get; }

		public double Duration { get; }

		public DanmakuDensity Density { get; private set; }

		public IReadOnlyList<string>? FrozenCandidates { get; }

		public ShuffleBag Bag { get; }

		public int EmittedCount { get; private set; }

		public Hotspot(ContentTrigger trigger, double startedAt, DanmakuDensity density, Random random, IReadOnlyList<string>? frozenCandidates = null, ShuffleBag? bag = null)
		{
			Trigger = trigger;
			StartedAt = startedAt;
			Duration = HotspotSchedule.Duration(trigger.Kind, trigger.Timing);
			Density = density;
			FrozenCandidates = frozenCandidates;
			_random = random;
			Bag = bag ?? new ShuffleBag(random);
			_nextEmissionAt = (HotspotSchedule.IsCombat(trigger.Kind, trigger.Timing) ? (startedAt + 8.0 + random.NextDouble() * 7.0) : (startedAt + 1.0));
		}

		public bool IsExpired(double now)
		{
			return now >= StartedAt + Duration;
		}

		public bool IsReady(double now)
		{
			if (!IsExpired(now))
			{
				return now >= _nextEmissionAt;
			}
			return false;
		}

		public void UpdateDensity(DanmakuDensity density)
		{
			Density = density;
		}

		public string? TryEmit(double now, IReadOnlyList<string> candidates)
		{
			if (IsExpired(now))
			{
				return null;
			}
			if (now < _nextEmissionAt)
			{
				return null;
			}
			string text = Bag.Draw(candidates, allowReshuffle: false);
			if (text == null)
			{
				return null;
			}
			EmittedCount++;
			double num = (HotspotSchedule.IsCombat(Trigger.Kind, Trigger.Timing) ? (8.0 + _random.NextDouble() * 7.0) : HotspotSchedule.IntervalSeconds(HotspotSchedule.Decay(Density), EmittedCount, 0.6 + _random.NextDouble() * 0.7999999999999999));
			_nextEmissionAt = now + num;
			return text;
		}
	}
	public sealed class HotspotPool
	{
		public const int MaxActiveHotspots = 32;

		public const int MaxPersistedBags = 512;

		public const int MaxPersistedEntriesPerBag = 4096;

		private readonly Dictionary<ContentTrigger, Hotspot> _active = new Dictionary<ContentTrigger, Hotspot>();

		private readonly Dictionary<ContentTrigger, ShuffleBag> _bags = new Dictionary<ContentTrigger, ShuffleBag>();

		private readonly Random _random;

		public int ActiveCount => _active.Count;

		public HotspotPool(Random? random = null)
		{
			_random = random ?? Random.Shared;
		}

		public bool IsActive(ContentTrigger trigger)
		{
			return _active.ContainsKey(trigger);
		}

		public bool Trigger(ContentTrigger trigger, double now, DanmakuDensity density, IReadOnlyList<string>? frozenCandidates = null)
		{
			if (_active.ContainsKey(trigger))
			{
				return true;
			}
			if (_active.Count >= 32 && !EvictOldestFiniteHotspot())
			{
				return false;
			}
			if (!_bags.TryGetValue(trigger, out ShuffleBag value))
			{
				value = new ShuffleBag(_random);
				_bags[trigger] = value;
			}
			value.Reset();
			_active[trigger] = new Hotspot(trigger, now, density, _random, frozenCandidates, value);
			return true;
		}

		public IReadOnlyList<HotspotEmission> Advance(double now, Func<ContentTrigger, IReadOnlyList<string>> candidatesProvider)
		{
			RemoveExpired(now);
			List<HotspotEmission> list = new List<HotspotEmission>();
			List<ContentTrigger> list2 = new List<ContentTrigger>();
			foreach (var (contentTrigger2, hotspot2) in _active)
			{
				if (!hotspot2.IsReady(now))
				{
					continue;
				}
				IReadOnlyList<string> readOnlyList = hotspot2.FrozenCandidates ?? candidatesProvider(contentTrigger2);
				if (readOnlyList.Count == 0)
				{
					if (hotspot2.FrozenCandidates == null)
					{
						list2.Add(contentTrigger2);
					}
					continue;
				}
				string text = hotspot2.TryEmit(now, readOnlyList);
				if (text != null)
				{
					list.Add(new HotspotEmission(contentTrigger2, text));
				}
			}
			foreach (ContentTrigger item in list2)
			{
				_active.Remove(item);
			}
			return list;
		}

		public void RemoveExpired(double now)
		{
			foreach (ContentTrigger item in (from pair in _active
				where pair.Value.IsExpired(now)
				select pair.Key).ToList())
			{
				_active.Remove(item);
			}
		}

		public void CancelWhere(Func<ContentTrigger, bool> predicate)
		{
			foreach (ContentTrigger item in _active.Keys.Where(predicate).ToList())
			{
				_active.Remove(item);
			}
		}

		public void CancelWhereLive(Func<ContentTrigger, bool> predicate)
		{
			Func<ContentTrigger, bool> predicate2 = predicate;
			foreach (ContentTrigger item in (from pair in _active
				where pair.Value.FrozenCandidates == null && predicate2(pair.Key)
				select pair.Key).ToList())
			{
				_active.Remove(item);
			}
		}

		public void UpdateDensity(DanmakuDensity density)
		{
			foreach (Hotspot value in _active.Values)
			{
				value.UpdateDensity(density);
			}
		}

		public void ClearActive()
		{
			_active.Clear();
		}

		public void Clear()
		{
			_active.Clear();
			_bags.Clear();
		}

		public IReadOnlyList<UgcShuffleBagSnapshot> SnapshotBags()
		{
			return (from pair in (from pair in _bags
					where pair.Value.DrawnCount > 0
					orderby pair.Key.Kind, pair.Key.Timing
					select pair).ThenBy<KeyValuePair<ContentTrigger, ShuffleBag>, string>((KeyValuePair<ContentTrigger, ShuffleBag> pair) => pair.Key.Id, StringComparer.Ordinal).Take(512)
				select new UgcShuffleBagSnapshot(pair.Key.Kind, pair.Key.Timing, pair.Key.Id, pair.Value.Drawn.Take(4096).ToArray())).ToArray();
		}

		public void RestoreBags(IEnumerable<UgcShuffleBagSnapshot>? snapshots)
		{
			_active.Clear();
			_bags.Clear();
			if (snapshots == null)
			{
				return;
			}
			foreach (UgcShuffleBagSnapshot item in snapshots.Take(512))
			{
				if (Enum.IsDefined(item.Kind) && Enum.IsDefined(item.Timing) && ContentConditionRules.IsValidInstant(item.Kind, item.Timing) && !string.IsNullOrWhiteSpace(item.Id))
				{
					ContentTrigger key = new ContentTrigger(item.Kind, item.Timing, item.Id);
					ShuffleBag shuffleBag = new ShuffleBag(_random);
					shuffleBag.Restore((item.DrawnEntryIds ?? Array.Empty<string>()).Take(4096));
					if (shuffleBag.DrawnCount > 0)
					{
						_bags[key] = shuffleBag;
					}
				}
			}
		}

		private bool EvictOldestFiniteHotspot()
		{
			KeyValuePair<ContentTrigger, Hotspot>? keyValuePair = ((IEnumerable<KeyValuePair<ContentTrigger, Hotspot>>)(from pair in _active
				where !HotspotSchedule.IsCombat(pair.Key.Kind, pair.Key.Timing)
				orderby pair.Value.StartedAt, pair.Key.Kind, pair.Key.Timing
				select pair).ThenBy<KeyValuePair<ContentTrigger, Hotspot>, string>((KeyValuePair<ContentTrigger, Hotspot> pair) => pair.Key.Id, StringComparer.Ordinal)).Select((Func<KeyValuePair<ContentTrigger, Hotspot>, KeyValuePair<ContentTrigger, Hotspot>?>)((KeyValuePair<ContentTrigger, Hotspot> pair) => pair)).FirstOrDefault();
			if (keyValuePair.HasValue)
			{
				KeyValuePair<ContentTrigger, Hotspot> valueOrDefault = keyValuePair.GetValueOrDefault();
				return _active.Remove(valueOrDefault.Key);
			}
			return false;
		}
	}
	public enum DanmakuDensity
	{
		Sparse,
		Standard,
		Dense
	}
	public readonly record struct DecayParams(double Base, double Growth);
	public static class HotspotSchedule
	{
		public const double FirstEntryDelaySeconds = 1.0;

		public const double CombatMinIntervalSeconds = 8.0;

		public const double CombatMaxIntervalSeconds = 15.0;

		public const double JitterMin = 0.6;

		public const double JitterMax = 1.4;

		public static double Duration(ContentObjectKind kind, ContentInstant instant)
		{
			switch (kind)
			{
			case ContentObjectKind.Card:
				switch (instant)
				{
				case ContentInstant.Obtained:
					return 6.0;
				case ContentInstant.Upgraded:
					return 6.0;
				case ContentInstant.Removed:
					return 4.0;
				case ContentInstant.Played:
					return 4.0;
				}
				break;
			case ContentObjectKind.Relic:
				if (instant != ContentInstant.Obtained)
				{
					break;
				}
				return 8.0;
			case ContentObjectKind.Monster:
				switch (instant)
				{
				case ContentInstant.Encountered:
					return 8.0;
				case ContentInstant.Defeated:
					return 4.0;
				case ContentInstant.Combat:
					return double.PositiveInfinity;
				}
				break;
			case ContentObjectKind.Character:
				switch (instant)
				{
				case ContentInstant.Preselected:
					return 6.0;
				case ContentInstant.Confirmed:
					return 12.0;
				}
				break;
			case ContentObjectKind.Event:
				switch (instant)
				{
				case ContentInstant.Entered:
					return 8.0;
				case ContentInstant.OptionSelected:
					return 4.0;
				}
				break;
			case ContentObjectKind.Act:
				if (instant != ContentInstant.ActEntered)
				{
					break;
				}
				return 8.0;
			case ContentObjectKind.Turn:
				if (instant != ContentInstant.TurnEntered)
				{
					break;
				}
				return 4.0;
			}
			return 4.0;
		}

		public static DecayParams Decay(DanmakuDensity density)
		{
			return density switch
			{
				DanmakuDensity.Sparse => new DecayParams(2.2, 1.5), 
				DanmakuDensity.Standard => new DecayParams(1.1, 1.3), 
				DanmakuDensity.Dense => new DecayParams(0.7, 1.15), 
				_ => new DecayParams(1.1, 1.3), 
			};
		}

		public static double IntervalSeconds(DecayParams decay, int entryIndex, double jitter)
		{
			if (entryIndex <= 0)
			{
				return 1.0;
			}
			return decay.Base * Math.Pow(decay.Growth, entryIndex - 1) * jitter;
		}

		public static bool IsCombat(ContentObjectKind kind, ContentInstant instant)
		{
			if (kind == ContentObjectKind.Monster)
			{
				return instant == ContentInstant.Combat;
			}
			return false;
		}
	}
	public sealed class IntervalStateSnapshot
	{
		private readonly HashSet<(ContentObjectKind Kind, ContentInterval Timing, string Id)> _satisfied = new HashSet<(ContentObjectKind, ContentInterval, string)>();

		public int Count => _satisfied.Count;

		public void Set(ContentObjectKind kind, ContentInterval timing, string id)
		{
			_satisfied.Add((kind, timing, id));
		}

		public void Remove(ContentObjectKind kind, ContentInterval timing, string id)
		{
			_satisfied.Remove((kind, timing, id));
		}

		public void RemoveAll(ContentObjectKind kind, ContentInterval timing)
		{
			_satisfied.RemoveWhere(((ContentObjectKind Kind, ContentInterval Timing, string Id) item) => item.Kind == kind && item.Timing == timing);
		}

		public bool Satisfies(ContentPrecondition precondition)
		{
			return _satisfied.Contains((precondition.Kind, precondition.Timing, precondition.Id));
		}

		public void Clear()
		{
			_satisfied.Clear();
		}
	}
	public sealed class ObjectCatalogProvider
	{
		private ContentObjectCatalog? _catalog;

		private string? _cachePath;

		public static ObjectCatalogProvider Instance { get; } = new ObjectCatalogProvider();


		private string? CachePath => _cachePath;

		public void Initialize(string? cachePath)
		{
			_cachePath = cachePath;
		}

		public ContentObjectCatalog GetCatalog()
		{
			if (_catalog != null)
			{
				return _catalog;
			}
			string text = ObjectScanner.ComputeFingerprint();
			ContentObjectCatalog contentObjectCatalog = TryLoadCache();
			if (contentObjectCatalog != null && contentObjectCatalog.Fingerprint == text && contentObjectCatalog.Objects.Count > 0)
			{
				_catalog = contentObjectCatalog;
				return _catalog;
			}
			_catalog = ObjectScanner.Scan();
			if (_catalog.Objects.Count == 0 && _catalog.EventOptions.Count == 0)
			{
				MainFile.Log("[ObjectCatalog] 扫描结果为空，可能是扫描被早期异常中断；本次不写缓存，下次打开会重试。");
				return _catalog;
			}
			TrySaveCache(_catalog);
			return _catalog;
		}

		public ContentObjectCatalog? TryGetAvailableCatalog()
		{
			if (_catalog != null)
			{
				return _catalog;
			}
			ContentObjectCatalog contentObjectCatalog = TryLoadCache();
			if (contentObjectCatalog != null)
			{
				_catalog = contentObjectCatalog;
			}
			return contentObjectCatalog;
		}

		public ContentObjectCatalog Refresh()
		{
			_catalog = ObjectScanner.Scan();
			if (_catalog.Objects.Count == 0 && _catalog.EventOptions.Count == 0)
			{
				MainFile.Log("[ObjectCatalog] 手动刷新结果为空，可能是扫描被早期异常中断；本次不写缓存。");
				return _catalog;
			}
			TrySaveCache(_catalog);
			return _catalog;
		}

		private ContentObjectCatalog? TryLoadCache()
		{
			try
			{
				string cachePath = CachePath;
				if (string.IsNullOrWhiteSpace(cachePath) || !File.Exists(cachePath))
				{
					return null;
				}
				return ContentObjectCatalogCodec.Deserialize(File.ReadAllText(cachePath, Encoding.UTF8));
			}
			catch
			{
				return null;
			}
		}

		private void TrySaveCache(ContentObjectCatalog catalog)
		{
			try
			{
				string cachePath = CachePath;
				if (!string.IsNullOrWhiteSpace(cachePath))
				{
					string directoryName = Path.GetDirectoryName(cachePath);
					if (!string.IsNullOrWhiteSpace(directoryName))
					{
						Directory.CreateDirectory(directoryName);
					}
					string contents = ContentObjectCatalogCodec.Serialize(catalog);
					string text = cachePath + ".new";
					File.WriteAllText(text, contents, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
					File.Move(text, cachePath, overwrite: true);
				}
			}
			catch (Exception ex)
			{
				MainFile.Log("[ObjectCatalog] 缓存写入失败，忽略：" + ex.Message);
			}
		}
	}
