	public static class RuleLibraryCodec
	{
		private static readonly JsonSerializerOptions Indented = new JsonSerializerOptions
		{
			WriteIndented = true,
			Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
		};

		public static RuleLibrary Parse(string json)
		{
			using JsonDocument jsonDocument = JsonDocument.Parse(json);
			JsonElement rootElement = jsonDocument.RootElement;
			List<RuleGroup> list = new List<RuleGroup>();
			if (!rootElement.TryGetProperty("groups", out var value))
			{
				return new RuleLibrary(list);
			}
			foreach (JsonElement item in value.EnumerateArray())
			{
				string ruleId = item.GetProperty("ruleId").GetString() ?? "";
				IReadOnlyList<RuleEntry> entries = ParseEntries(item, "entries");
				IReadOnlyList<RuleEntry> multiplayerEntries = ParseEntries(item, "multiplayerEntries");
				list.Add(new RuleGroup(ruleId, entries, multiplayerEntries));
			}
			return new RuleLibrary(list);
		}

		public static string Serialize(RuleLibrary library)
		{
			var groups = library.Groups.Select((RuleGroup group) => new
			{
				ruleId = group.RuleId,
				entries = group.Entries.Select(SerializeEntry),
				multiplayerEntries = group.MultiplayerEntries.Select(SerializeEntry)
			});
			return JsonSerializer.Serialize(new
			{
				schemaVersion = 1,
				groups = groups
			}, Indented);
		}

		private static IReadOnlyList<RuleEntry> ParseEntries(JsonElement groupElement, string propertyName)
		{
			List<RuleEntry> list = new List<RuleEntry>();
			if (!groupElement.TryGetProperty(propertyName, out var value2))
			{
				return list;
			}
			foreach (JsonElement item in value2.EnumerateArray())
			{
				string id = item.GetProperty("id").GetString() ?? "";
				string text = item.GetProperty("text").GetString() ?? "";
				ContentStyle style = ((!((item.GetProperty("style").GetString() ?? "") == "character")) ? ContentStyle.Narration : ContentStyle.Character);
				JsonElement value3;
				string variant = (item.TryGetProperty("variant", out value3) ? (value3.GetString() ?? "") : "");
				JsonElement value4;
				string author = (item.TryGetProperty("author", out value4) ? (value4.GetString() ?? "") : "");
				JsonElement value5;
				string color = (item.TryGetProperty("color", out value5) ? (value5.GetString() ?? "") : "");
				JsonElement value6;
				bool topPinned = item.TryGetProperty("top", out value6) && value6.ValueKind == JsonValueKind.True;
				JsonElement value7;
				bool rainbow = item.TryGetProperty("rainbow", out value7) && value7.ValueKind == JsonValueKind.True;
				IReadOnlyList<string> continuationTexts = null;
				if (item.TryGetProperty("continuation", out var value8) && value8.ValueKind == JsonValueKind.Array)
				{
					List<string> list2 = (from value in value8.EnumerateArray()
						where value.ValueKind == JsonValueKind.String
						select value.GetString() ?? "" into value
						where !string.IsNullOrWhiteSpace(value)
						select value).ToList();
					if (list2.Count > 0)
					{
						continuationTexts = list2;
					}
				}
				JsonElement value9;
				DanmakuSequenceSpeed sequenceSpeed = DanmakuSequence.Parse((item.TryGetProperty("sequenceSpeed", out value9) && value9.ValueKind == JsonValueKind.String) ? value9.GetString() : null);
				list.Add(new RuleEntry(id, text, style, variant, author, color, topPinned, rainbow, continuationTexts, sequenceSpeed));
			}
			return list;
		}

		private static object SerializeEntry(RuleEntry entry)
		{
			return new
			{
				id = entry.Id,
				text = entry.Text,
				style = ((entry.Style == ContentStyle.Character) ? "character" : "narration"),
				variant = entry.Variant,
				author = entry.Author,
				color = entry.Color,
				top = entry.TopPinned,
				rainbow = entry.Rainbow,
				continuation = entry.StableContinuationTexts,
				sequenceSpeed = DanmakuSequence.StableName(entry.SequenceSpeed)
			};
		}
	}
	public static class RuleContributionValidator
	{
		public static bool TryParse(string json, out RuleLibrary library, out string error)
		{
			library = new RuleLibrary(Array.Empty<RuleGroup>());
			error = "";
			try
			{
				using JsonDocument jsonDocument = JsonDocument.Parse(json);
				JsonElement rootElement = jsonDocument.RootElement;
				if (rootElement.ValueKind != JsonValueKind.Object)
				{
					error = "规则分片根节点必须是对象";
					return false;
				}
				if (!rootElement.TryGetProperty("groups", out var value) || value.ValueKind != JsonValueKind.Array)
				{
					error = "规则分片缺少 groups 数组";
					return false;
				}
				foreach (JsonElement item in value.EnumerateArray())
				{
					if (item.ValueKind != JsonValueKind.Object)
					{
						error = "规则组必须是对象";
						return false;
					}
					if (!HasValidEntryArray(item, "entries", out error) || !HasValidEntryArray(item, "multiplayerEntries", out error))
					{
						return false;
					}
				}
				RuleLibrary ruleLibrary = RuleLibraryCodec.Parse(json);
				HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
				HashSet<string> hashSet2 = new HashSet<string>(StringComparer.Ordinal);
				foreach (RuleGroup group in ruleLibrary.Groups)
				{
					string text = group.RuleId.Trim();
					if (!hashSet.Add(text))
					{
						error = "规则组 ID 重复：" + text;
						return false;
					}
					if (!RuleDisplayCatalog.Contains(text.ToUpperInvariant()))
					{
						error = "规则编号不存在：" + text;
						return false;
					}
					foreach (RuleEntry item2 in group.Entries.Concat(group.MultiplayerEntries))
					{
						if (!ContentValidator.IsValidObjectId(item2.Id))
						{
							error = "规则词条 id 不能为空且不得超过对象 ID 上限";
							return false;
						}
						if (!hashSet2.Add(item2.Id))
						{
							error = "规则词条 ID 重复：" + item2.Id;
							return false;
						}
						if (string.IsNullOrWhiteSpace(item2.Text))
						{
							error = "规则词条正文为空：" + item2.Id;
							return false;
						}
						if (ContentValidator.CountTextCharacters(item2.Text) > 40)
						{
							error = $"规则词条正文超过 {40} 字：{item2.Id}";
							return false;
						}
						if (item2.AllTexts.Count > 5)
						{
							error = $"规则连续弹幕超过 {5} 条：{item2.Id}";
							return false;
						}
						for (int i = 0; i < item2.StableContinuationTexts.Count; i++)
						{
							string text2 = item2.StableContinuationTexts[i];
							if (string.IsNullOrWhiteSpace(text2) || ContentValidator.CountTextCharacters(text2) > 40)
							{
								error = $"规则词条第 {i + 2} 条连续正文非法：{item2.Id}";
								return false;
							}
						}
						if (ContentValidator.CountCharacters(item2.Author) > 16)
						{
							error = $"规则词条作者超过 {16} 字：{item2.Id}";
							return false;
						}
						if (!ContentValidator.IsValidColor(item2.Color))
						{
							error = "规则词条颜色非法：" + item2.Id;
							return false;
						}
					}
				}
				library = ruleLibrary;
				return true;
			}
			catch (Exception ex) when (((ex is JsonException || ex is InvalidOperationException || ex is KeyNotFoundException) ? 1 : 0) != 0)
			{
				error = ex.Message;
				return false;
			}
		}

		private static bool HasValidEntryArray(JsonElement group, string propertyName, out string error)
		{
			error = "";
			if (!group.TryGetProperty(propertyName, out var value) || value.ValueKind != JsonValueKind.Array)
			{
				error = "规则组缺少 " + propertyName + " 数组";
				return false;
			}
			foreach (JsonElement item in value.EnumerateArray())
			{
				if (item.ValueKind != JsonValueKind.Object)
				{
					error = "规则词条必须是对象";
					return false;
				}
				JsonElement value2;
				bool flag = !item.TryGetProperty("style", out value2) || value2.ValueKind != JsonValueKind.String;
				if (!flag)
				{
					string @string = value2.GetString();
					bool flag2 = ((@string == "character" || @string == "narration") ? true : false);
					flag = !flag2;
				}
				if (flag)
				{
					error = "规则词条 style 只能是 character 或 narration";
					return false;
				}
			}
			return true;
		}
	}
	public enum RuleSubmissionStyle
	{
		Character,
		Narration
	}
	public sealed record RuleSubmissionRequest(string Nickname, string Text, string RuleId, RuleSubmissionStyle Style);
	public static class RuleSubmissionValidator
	{
		public static IReadOnlyList<string> Validate(RuleSubmissionRequest request)
		{
			List<string> list = new List<string>();
			if (string.IsNullOrWhiteSpace(request.Text))
			{
				list.Add("弹幕文本不能为空");
			}
			else if (ContentValidator.CountTextCharacters(request.Text) > 40)
			{
				list.Add($"弹幕文本超过 {40} 字");
			}
			if (ContentValidator.CountCharacters(request.Nickname) > 16)
			{
				list.Add($"昵称超过 {16} 字");
			}
			if (string.IsNullOrWhiteSpace(request.RuleId) || !RuleDisplayCatalog.Contains(request.RuleId))
			{
				list.Add("未选择有效的触发规则");
			}
			else if (!RuleDisplayCatalog.CanSubmit(request.RuleId))
			{
				list.Add("该规则不可投稿");
			}
			return list;
		}
	}
