	public enum SceneRoomKind
	{
		Unknown,
		Combat,
		Shop,
		Event,
		RestSite,
		Reward,
		Map
	}
	public sealed record SceneTriggerCandidate(ContentObjectKind Kind, ContentInstant Timing, string Id);
	public sealed record SceneCapture(string Id, string CapturedAt, long RunEpoch, string CharacterId, string RoomKind, int ActIndex, int Floor, int Gold, int CurrentHp, int MaxHp, IReadOnlyList<SceneTriggerCandidate> TriggerCandidates, IReadOnlyList<string> CharacterIds, IReadOnlyList<string> CardIds, IReadOnlyList<string> RelicIds, IReadOnlyList<string> MonsterIds, IReadOnlyList<string> EventIds, IReadOnlyList<string> EventOptionIds, int PlayerTurn = 0)
	{
		public SceneRoomKind RoomKindEnum
		{
			get
			{
				if (!Enum.TryParse<SceneRoomKind>(RoomKind, out var result))
				{
					return SceneRoomKind.Unknown;
				}
				return result;
			}
		}
	}
	public static class SceneCaptureService
	{
		private static SceneCaptureStore? _store;

		public static SceneCaptureStore? Store => _store;

		public static void Initialize(string storePath)
		{
			_store = new SceneCaptureStore(storePath);
		}

		public static void Shutdown()
		{
			_store = null;
		}

		public static SceneCapture? Capture()
		{
			try
			{
				GameContextStore instance = GameContextStore.Instance;
				if (instance != null)
				{
					RunContext run = instance.Run;
					if (run != null && run.IsActive)
					{
						PlayerStateSnapshot playerStateSnapshot = PlayerSnapshotFactory.CaptureLocal();
						string text = playerStateSnapshot.CharacterId;
						if (string.IsNullOrWhiteSpace(text))
						{
							text = DanmakuSourceIdentity.ResolveCurrentCharacterId();
						}
						SceneRoomKind sceneRoomKind = ResolveRoomKind();
						List<SceneTriggerCandidate> list = new List<SceneTriggerCandidate>();
						List<string> list2 = new List<string>();
						List<string> list3 = playerStateSnapshot.DeckCardIds.Distinct<string>(StringComparer.Ordinal).ToList();
						List<string> list4 = playerStateSnapshot.StableRelicIds.Distinct<string>(StringComparer.Ordinal).ToList();
						List<string> list5 = ModRunState.CurrentCombatMonsterTypes.ToList();
						List<string> list6 = new List<string>();
						List<string> list7 = new List<string>();
						if (!string.IsNullOrWhiteSpace(text))
						{
							list2.Add(text);
						}
						GameContextStore instance2 = GameContextStore.Instance;
						if (instance2 != null)
						{
							if (instance2.Shop.IsActive)
							{
								sceneRoomKind = SceneRoomKind.Shop;
								foreach (ShopItemSnapshot item in instance2.Shop.Items.Where((ShopItemSnapshot item) => !item.Purchased))
								{
									ContentObjectKind contentObjectKind = ((item.Kind == "card") ? ContentObjectKind.Card : ContentObjectKind.Relic);
									list.Add(new SceneTriggerCandidate(contentObjectKind, ContentInstant.Obtained, item.ItemId));
									if (contentObjectKind == ContentObjectKind.Card)
									{
										list3.Add(item.ItemId);
									}
									else
									{
										list4.Add(item.ItemId);
									}
								}
							}
							else if (instance2.Event.IsActive)
							{
								sceneRoomKind = SceneRoomKind.Event;
								if (!string.IsNullOrWhiteSpace(instance2.Event.ModelId))
								{
									list6.Add(instance2.Event.ModelId);
									list.Add(new SceneTriggerCandidate(ContentObjectKind.Event, ContentInstant.Entered, instance2.Event.ModelId));
								}
								foreach (string optionId in instance2.Event.OptionIds)
								{
									list7.Add(optionId);
									list.Add(new SceneTriggerCandidate(ContentObjectKind.Event, ContentInstant.OptionSelected, instance2.Event.ModelId + ":" + optionId));
								}
							}
							else if (instance2.RestSite.IsActive)
							{
								sceneRoomKind = SceneRoomKind.RestSite;
							}
							else if (instance2.Reward.IsActive)
							{
								sceneRoomKind = SceneRoomKind.Reward;
							}
							else if (instance2.Combat.IsActive)
							{
								sceneRoomKind = SceneRoomKind.Combat;
							}
							else if (instance2.Room.IsActive)
							{
								sceneRoomKind = SceneRoomKind.Map;
							}
						}
						foreach (string item2 in list5)
						{
							list.Add(new SceneTriggerCandidate(ContentObjectKind.Monster, ContentInstant.Combat, item2));
						}
						list = (from t in list
							group t by (Kind: t.Kind, Timing: t.Timing, Id: t.Id) into @group
							select @group.First()).ToList();
						int actIndex = ((playerStateSnapshot.CurrentActIndex >= 0) ? playerStateSnapshot.CurrentActIndex : 0);
						int num = 0;
						try
						{
							RunState obj = RunManager.Instance.DebugOnlyGetState();
							num = ((obj != null) ? obj.ActFloor : 0);
						}
						catch
						{
							num = 0;
						}
						int playerTurn = (int)ModRunState.TurnSequence;
						return new SceneCapture(Guid.NewGuid().ToString("N"), DateTime.UtcNow.ToString("o"), ModRunState.RunEpoch, text, sceneRoomKind.ToString(), actIndex, num, playerStateSnapshot.Gold, playerStateSnapshot.CurrentHp, playerStateSnapshot.MaxHp, list, list2, list3, list4, list5, list6, list7, playerTurn);
					}
				}
				return null;
			}
			catch (Exception ex)
			{
				MainFile.Log("[SceneCapture] 捕获场景失败：" + ex.Message);
				return null;
			}
		}

		public static string BuildSummary(SceneCapture scene)
		{
			string item = ResolveCharacterName(scene.CharacterId);
			string text = ((scene.ActIndex >= 0) ? $"第{scene.ActIndex + 1}幕" : "");
			string text2 = ((scene.Floor > 0) ? $"第{scene.Floor}层" : "");
			string text3 = ((scene.PlayerTurn > 0) ? $"第{scene.PlayerTurn}回合" : "");
			string item2 = RoomKindLabel(scene.RoomKindEnum);
			if (scene.RoomKindEnum == SceneRoomKind.Combat && scene.MonsterIds.Count > 0)
			{
				item2 = "遭遇 " + string.Join("/", scene.MonsterIds.Select(ResolveMonsterName));
			}
			else if (scene.RoomKindEnum == SceneRoomKind.Event && scene.EventIds.Count > 0)
			{
				item2 = "事件 " + string.Join("/", scene.EventIds.Select(ResolveEventName));
			}
			List<string> list = new List<string> { item };
			if (!string.IsNullOrWhiteSpace(text))
			{
				list.Add(text);
			}
			if (!string.IsNullOrWhiteSpace(text2))
			{
				list.Add(text2);
			}
			if (!string.IsNullOrWhiteSpace(text3))
			{
				list.Add(text3);
			}
			list.Add(item2);
			return string.Join(" · ", list);
		}

		public static string FormatTime(SceneCapture scene)
		{
			if (DateTime.TryParse(scene.CapturedAt, out var result))
			{
				return result.ToLocalTime().ToString("MM-dd HH:mm");
			}
			return "";
		}

		public static string RoomKindLabel(SceneRoomKind kind)
		{
			return kind switch
			{
				SceneRoomKind.Combat => "战斗", 
				SceneRoomKind.Shop => "商店", 
				SceneRoomKind.Event => "事件", 
				SceneRoomKind.RestSite => "火堆", 
				SceneRoomKind.Reward => "奖励", 
				SceneRoomKind.Map => "地图", 
				_ => "未知", 
			};
		}

		private static SceneRoomKind ResolveRoomKind()
		{
			GameContextStore instance = GameContextStore.Instance;
			if (instance == null)
			{
				return SceneRoomKind.Unknown;
			}
			string text = instance.Room.Kind ?? "";
			if (text.Contains("combat", StringComparison.OrdinalIgnoreCase))
			{
				return SceneRoomKind.Combat;
			}
			if (text.Contains("shop", StringComparison.OrdinalIgnoreCase))
			{
				return SceneRoomKind.Shop;
			}
			if (text.Contains("event", StringComparison.OrdinalIgnoreCase))
			{
				return SceneRoomKind.Event;
			}
			if (text.Contains("rest", StringComparison.OrdinalIgnoreCase))
			{
				return SceneRoomKind.RestSite;
			}
			if (instance.Combat.IsActive)
			{
				return SceneRoomKind.Combat;
			}
			if (instance.Shop.IsActive)
			{
				return SceneRoomKind.Shop;
			}
			if (instance.Event.IsActive)
			{
				return SceneRoomKind.Event;
			}
			if (instance.RestSite.IsActive)
			{
				return SceneRoomKind.RestSite;
			}
			if (instance.Reward.IsActive)
			{
				return SceneRoomKind.Reward;
			}
			if (!instance.Room.IsActive)
			{
				return SceneRoomKind.Unknown;
			}
			return SceneRoomKind.Map;
		}

		private static string ParseTime(string capturedAt)
		{
			if (DateTime.TryParse(capturedAt, out var result))
			{
				return result.ToLocalTime().ToString("MM-dd HH:mm");
			}
			return "";
		}

		private static string ResolveCharacterName(string id)
		{
			if (string.IsNullOrWhiteSpace(id))
			{
				return "未知角色";
			}
			try
			{
				return CharacterNames.DisplayName(id);
			}
			catch
			{
				return id;
			}
		}

		private static string ResolveMonsterName(string id)
		{
			string id2 = id;
			try
			{
				ContentObjectEntry? contentObjectEntry = ObjectCatalogProvider.Instance.TryGetAvailableCatalog()?.Objects.FirstOrDefault((ContentObjectEntry item) => item.Kind == ContentObjectKind.Monster && item.Id == id2);
				return string.IsNullOrWhiteSpace(contentObjectEntry?.DisplayName) ? id2 : contentObjectEntry.Value.DisplayName;
			}
			catch
			{
				return id2;
			}
		}

		private static string ResolveEventName(string id)
		{
			if (string.IsNullOrWhiteSpace(id))
			{
				return "";
			}
			int num = id.IndexOf(':');
			string baseId = ((num > 0) ? id.Substring(0, num) : id);
			try
			{
				ContentObjectEntry? contentObjectEntry = ObjectCatalogProvider.Instance.TryGetAvailableCatalog()?.Objects.FirstOrDefault((ContentObjectEntry item) => item.Kind == ContentObjectKind.Event && item.Id == baseId);
				return string.IsNullOrWhiteSpace(contentObjectEntry?.DisplayName) ? id : contentObjectEntry.Value.DisplayName;
			}
			catch
			{
				return id;
			}
		}
	}
	public sealed class SceneCaptureStore
	{
		private static readonly JsonSerializerOptions Json = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
			Converters = { (JsonConverter)new JsonStringEnumConverter() }
		};

		private readonly object _sync = new object();

		private readonly string _path;

		private readonly List<SceneCapture> _scenes = new List<SceneCapture>();

		private bool _loaded;

		public IReadOnlyList<SceneCapture> All
		{
			get
			{
				EnsureLoaded();
				lock (_sync)
				{
					return _scenes.OrderByDescending<SceneCapture, string>((SceneCapture scene) => scene.CapturedAt, StringComparer.Ordinal).ToArray();
				}
			}
		}

		public SceneCaptureStore(string path)
		{
			_path = path;
		}

		public SceneCapture? Find(string id)
		{
			string id2 = id;
			EnsureLoaded();
			lock (_sync)
			{
				return _scenes.FirstOrDefault((SceneCapture scene) => scene.Id == id2);
			}
		}

		public void Add(SceneCapture scene)
		{
			SceneCapture scene2 = scene;
			if (string.IsNullOrWhiteSpace(scene2.Id))
			{
				return;
			}
			EnsureLoaded();
			lock (_sync)
			{
				_scenes.RemoveAll((SceneCapture existing) => existing.Id == scene2.Id);
				_scenes.Add(scene2);
				Save();
			}
		}

		public bool Remove(string id)
		{
			string id2 = id;
			EnsureLoaded();
			lock (_sync)
			{
				int num = _scenes.RemoveAll((SceneCapture scene) => scene.Id == id2);
				if (num > 0)
				{
					Save();
				}
				return num > 0;
			}
		}

		public void Clear()
		{
			EnsureLoaded();
			lock (_sync)
			{
				if (_scenes.Count != 0)
				{
					_scenes.Clear();
					Save();
				}
			}
		}

		private void EnsureLoaded()
		{
			if (_loaded)
			{
				return;
			}
			lock (_sync)
			{
				if (_loaded)
				{
					return;
				}
				try
				{
					if (File.Exists(_path))
					{
						using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(_path, Encoding.UTF8));
						if (jsonDocument.RootElement.TryGetProperty("scenes", out var value) && value.ValueKind == JsonValueKind.Array)
						{
							foreach (JsonElement item in value.EnumerateArray())
							{
								SceneCapture sceneCapture = Deserialize(item);
								if (sceneCapture != null)
								{
									_scenes.Add(sceneCapture);
								}
							}
						}
					}
				}
				catch
				{
				}
				_loaded = true;
			}
		}

		private static SceneCapture? Deserialize(JsonElement element)
		{
			try
			{
				string text = element.GetProperty("id").GetString() ?? "";
				if (string.IsNullOrWhiteSpace(text))
				{
					return null;
				}
				string capturedAt = element.GetProperty("capturedAt").GetString() ?? DateTime.UtcNow.ToString("o");
				JsonElement value;
				long runEpoch = ((element.TryGetProperty("runEpoch", out value) && value.ValueKind == JsonValueKind.Number) ? value.GetInt64() : 0);
				JsonElement value2;
				string characterId = (element.TryGetProperty("characterId", out value2) ? (value2.GetString() ?? "") : "");
				JsonElement value3;
				string roomKind = (element.TryGetProperty("roomKind", out value3) ? (value3.GetString() ?? "Unknown") : "Unknown");
				JsonElement value4;
				int actIndex = ((element.TryGetProperty("actIndex", out value4) && value4.ValueKind == JsonValueKind.Number) ? value4.GetInt32() : 0);
				JsonElement value5;
				int floor = ((element.TryGetProperty("floor", out value5) && value5.ValueKind == JsonValueKind.Number) ? value5.GetInt32() : 0);
				JsonElement value6;
				int gold = ((element.TryGetProperty("gold", out value6) && value6.ValueKind == JsonValueKind.Number) ? value6.GetInt32() : 0);
				JsonElement value7;
				int currentHp = ((element.TryGetProperty("currentHp", out value7) && value7.ValueKind == JsonValueKind.Number) ? value7.GetInt32() : 0);
				JsonElement value8;
				int maxHp = ((element.TryGetProperty("maxHp", out value8) && value8.ValueKind == JsonValueKind.Number) ? value8.GetInt32() : 0);
				JsonElement value9;
				int playerTurn = ((element.TryGetProperty("playerTurn", out value9) && value9.ValueKind == JsonValueKind.Number) ? value9.GetInt32() : 0);
				List<SceneTriggerCandidate> list = new List<SceneTriggerCandidate>();
				if (element.TryGetProperty("triggerCandidates", out var value10) && value10.ValueKind == JsonValueKind.Array)
				{
					foreach (JsonElement item in value10.EnumerateArray())
					{
						if (Enum.TryParse<ContentObjectKind>(item.GetProperty("kind").GetString(), out var result) && Enum.TryParse<ContentInstant>(item.GetProperty("timing").GetString(), out var result2))
						{
							string text2 = item.GetProperty("id").GetString() ?? "";
							if (!string.IsNullOrWhiteSpace(text2))
							{
								list.Add(new SceneTriggerCandidate(result, result2, text2));
							}
						}
					}
				}
				return new SceneCapture(text, capturedAt, runEpoch, characterId, roomKind, actIndex, floor, gold, currentHp, maxHp, list, ReadStrings(element, "characterIds"), ReadStrings(element, "cardIds"), ReadStrings(element, "relicIds"), ReadStrings(element, "monsterIds"), ReadStrings(element, "eventIds"), ReadStrings(element, "eventOptionIds"), playerTurn);
			}
			catch
			{
				return null;
			}
		}

		private static IReadOnlyList<string> ReadStrings(JsonElement element, string propertyName)
		{
			List<string> list = new List<string>();
			if (element.TryGetProperty(propertyName, out var value) && value.ValueKind == JsonValueKind.Array)
			{
				foreach (JsonElement item in value.EnumerateArray())
				{
					if (item.ValueKind == JsonValueKind.String)
					{
						string text = item.GetString() ?? "";
						if (!string.IsNullOrWhiteSpace(text))
						{
							list.Add(text);
						}
					}
				}
			}
			return list;
		}

		private void Save()
		{
			try
			{
				string directoryName = Path.GetDirectoryName(_path);
				if (!string.IsNullOrEmpty(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				string contents = JsonSerializer.Serialize(new
				{
					scenes = _scenes.OrderByDescending<SceneCapture, string>((SceneCapture scene) => scene.CapturedAt, StringComparer.Ordinal).ToArray()
				}, Json);
				string text = _path + ".new";
				File.WriteAllText(text, contents, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				File.Move(text, _path, overwrite: true);
			}
			catch
			{
			}
		}
	}
	public sealed record UgcShuffleBagSnapshot(ContentObjectKind Kind, ContentInstant Timing, string Id, IReadOnlyList<string> DrawnEntryIds);
	public sealed class ShuffleBag
	{
		private readonly HashSet<string> _drawn = new HashSet<string>(StringComparer.Ordinal);

		private readonly Random _random;

		public int DrawnCount => _drawn.Count;

		public IReadOnlyCollection<string> Drawn => _drawn;

		public ShuffleBag(Random? random = null)
		{
			_random = random ?? Random.Shared;
		}

		public string? Draw(IReadOnlyList<string> candidates, bool allowReshuffle = true)
		{
			if (candidates.Count == 0)
			{
				return null;
			}
			List<string> list = new List<string>(candidates.Count);
			foreach (string candidate in candidates)
			{
				if (!_drawn.Contains(candidate))
				{
					list.Add(candidate);
				}
			}
			if (list.Count == 0)
			{
				if (!allowReshuffle)
				{
					return null;
				}
				_drawn.Clear();
				list.AddRange(candidates);
			}
			string text = list[_random.Next(list.Count)];
			_drawn.Add(text);
			return text;
		}

		public void Reset()
		{
			_drawn.Clear();
		}

		public void Restore(IEnumerable<string> drawnEntryIds)
		{
			_drawn.Clear();
			foreach (string drawnEntryId in drawnEntryIds)
			{
				if (!string.IsNullOrWhiteSpace(drawnEntryId))
				{
					_drawn.Add(drawnEntryId);
				}
			}
		}
	}
