		public async Task<CloudApiContract.SubmitResult> SubmitAsync(SubmissionRequest request, CancellationToken token = default(CancellationToken))
		{
			string content2 = CloudApiContract.SerializeSubmission(request, DeviceIdentity.GetDeviceId());
			try
			{
				using StringContent content = new StringContent(content2, Encoding.UTF8, "application/json");
				using HttpResponseMessage response = await _http.PostAsync(_baseUrl + "/submissions", content, token).ConfigureAwait(continueOnCapturedContext: false);
				string json = await response.Content.ReadAsStringAsync(token).ConfigureAwait(continueOnCapturedContext: false);
				if (!response.IsSuccessStatusCode)
				{
					return CloudApiContract.ParseErrorResponse(json) ?? new CloudApiContract.SubmitResult(0L, "server_error", "服务器拒绝");
				}
				CloudApiContract.SubmitResponse submitResponse = CloudApiContract.ParseSubmitResponse(json);
				if (submitResponse == null)
				{
					return new CloudApiContract.SubmitResult(0L, "bad_response", "服务器返回异常");
				}
				return new CloudApiContract.SubmitResult(submitResponse.Id, null, null, submitResponse.Token);
			}
			catch (Exception ex) when (((ex is HttpRequestException || ex is TaskCanceledException || ex is ObjectDisposedException) ? 1 : 0) != 0)
			{
				return new CloudApiContract.SubmitResult(0L, "network", "无法连接服务器");
			}
		}

