		public async Task<IReadOnlyList<SubmissionRecord>?> FetchMineAsync(CancellationToken token = default(CancellationToken))
		{
			_ = 1;
			try
			{
				string deviceId = DeviceIdentity.GetDeviceId();
				long? beforeId = null;
				List<SubmissionRecord> records = new List<SubmissionRecord>();
				HashSet<long> seenIds = new HashSet<long>();
				for (int page = 0; page < 20; page++)
				{
					using HttpResponseMessage response = await _http.GetAsync(_baseUrl + CloudApiContract.MinePathWithDevice(deviceId, beforeId), token).ConfigureAwait(continueOnCapturedContext: false);
					if (!response.IsSuccessStatusCode)
					{
						return null;
					}
					CloudApiContract.MineResponse mineResponse = CloudApiContract.ParseMineResponse(await response.Content.ReadAsStringAsync(token).ConfigureAwait(continueOnCapturedContext: false));
					if (mineResponse == null)
					{
						return null;
					}
					foreach (CloudApiContract.MineSubmission submission in mineResponse.Submissions)
					{
						if (!seenIds.Add(submission.Id))
						{
							return null;
						}
						records.Add(new SubmissionRecord(submission.Id, "", submission.Request, submission.Status, submission.RequestType, submission.OriginalId, submission.ReviewReason, submission.ReviewedAt));
					}
					beforeId = mineResponse.NextCursor;
					if (!beforeId.HasValue)
					{
						return records;
					}
				}
				return null;
			}
			catch (Exception ex) when (((ex is HttpRequestException || ex is TaskCanceledException || ex is ObjectDisposedException) ? 1 : 0) != 0)
			{
				return null;
			}
		}

