	public static class SubmissionPersistence
	{
		private static readonly JsonSerializerOptions Json = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
		};

		public static string Serialize(IReadOnlyList<SubmissionRecord> records)
		{
			return JsonSerializer.Serialize(records.Select((SubmissionRecord record) => new
			{
				id = record.Id,
				token = record.Token,
				status = StatusName(record.Status),
				requestType = RequestTypeName(record.RequestType),
				originalId = record.OriginalId,
				reviewReason = record.ReviewReason,
				reviewedAt = record.ReviewedAt,
				kind = ((record.Request.Kind == SubmissionKind.Rule) ? "rule" : "ugc"),
				nickname = record.Request.Nickname,
				text = record.Request.Text,
				ruleId = record.Request.RuleId,
				style = ((record.Request.RuleStyle == RuleSubmissionStyle.Character) ? "character" : "narration"),
				color = record.Request.Color,
				top = record.Request.TopPinned,
				rainbow = record.Request.Rainbow,
				continuation = record.Request.StableContinuationTexts,
				sequenceSpeed = DanmakuSequence.StableName(record.Request.SequenceSpeed),
				note = record.Request.Note,
				trigger = new
				{
					kind = KindName(record.Request.Trigger.Kind),
					id = record.Request.Trigger.Id,
					timing = InstantName(record.Request.Trigger.Timing)
				},
				pre = record.Request.Preconditions.Select((ContentPrecondition pre) => new
				{
					kind = KindName(pre.Kind),
					id = pre.Id,
					timing = IntervalName(pre.Timing)
				})
			}), Json);
		}

		public static IReadOnlyList<SubmissionRecord>? Deserialize(string json)
		{
			try
			{
				using JsonDocument jsonDocument = JsonDocument.Parse(json);
				List<SubmissionRecord> list = new List<SubmissionRecord>();
				foreach (JsonElement item in jsonDocument.RootElement.EnumerateArray())
				{
					string token = item.GetProperty("token").GetString() ?? "";
					JsonElement value;
					long id = ((item.TryGetProperty("id", out value) && value.ValueKind == JsonValueKind.Number) ? value.GetInt64() : 0);
					JsonElement value2;
					SubmissionRequestType requestType = ParseRequestType(item.TryGetProperty("requestType", out value2) ? value2.GetString() : null);
					JsonElement value3;
					long originalId = ((item.TryGetProperty("originalId", out value3) && value3.ValueKind == JsonValueKind.Number) ? value3.GetInt64() : 0);
					JsonElement value4;
					string reviewReason = ((item.TryGetProperty("reviewReason", out value4) && value4.ValueKind == JsonValueKind.String) ? value4.GetString() : null);
					JsonElement value5;
					string reviewedAt = ((item.TryGetProperty("reviewedAt", out value5) && value5.ValueKind == JsonValueKind.String) ? value5.GetString() : null);
					string? value6 = item.GetProperty("status").GetString() ?? "pending";
					string nickname = item.GetProperty("nickname").GetString() ?? "";
					string text = item.GetProperty("text").GetString() ?? "";
					JsonElement value7;
					string text2 = (item.TryGetProperty("kind", out value7) ? (value7.GetString() ?? "ugc") : "ugc");
					SubmissionStatus status = ParseStatus(value6);
					JsonElement value8;
					string color = ((item.TryGetProperty("color", out value8) && value8.ValueKind == JsonValueKind.String) ? value8.GetString() : null);
					JsonElement value9;
					bool topPinned = item.TryGetProperty("top", out value9) && value9.ValueKind == JsonValueKind.True;
					JsonElement value10;
					bool rainbow = item.TryGetProperty("rainbow", out value10) && value10.ValueKind == JsonValueKind.True;
					IReadOnlyList<string> continuationTexts = ParseStringArray(item, "continuation");
					JsonElement value11;
					DanmakuSequenceSpeed sequenceSpeed = DanmakuSequence.Parse((item.TryGetProperty("sequenceSpeed", out value11) && value11.ValueKind == JsonValueKind.String) ? value11.GetString() : null);
					JsonElement value12;
					string note = ((item.TryGetProperty("note", out value12) && value12.ValueKind == JsonValueKind.String) ? value12.GetString() : null);
					if (text2 == "rule")
					{
						JsonElement value13;
						string ruleId = (item.TryGetProperty("ruleId", out value13) ? (value13.GetString() ?? "") : "");
						JsonElement value14;
						string text3 = (item.TryGetProperty("style", out value14) ? (value14.GetString() ?? "narration") : "narration");
						list.Add(new SubmissionRecord(id, token, new SubmissionRequest(nickname, text, new ContentTrigger(ContentObjectKind.Event, ContentInstant.Entered, "*"), Array.Empty<ContentPrecondition>(), color, topPinned, SubmissionKind.Rule, ruleId, (!(text3 == "character")) ? RuleSubmissionStyle.Narration : RuleSubmissionStyle.Character, rainbow, continuationTexts, sequenceSpeed, note), status, requestType, originalId, reviewReason, reviewedAt));
						continue;
					}
					JsonElement property = item.GetProperty("trigger");
					ContentTrigger trigger = new ContentTrigger(ParseKind(property.GetProperty("kind").GetString()), ParseInstant(property.GetProperty("timing").GetString()), property.GetProperty("id").GetString() ?? "");
					List<ContentPrecondition> list2 = new List<ContentPrecondition>();
					if (item.TryGetProperty("pre", out var value15) && value15.ValueKind == JsonValueKind.Array)
					{
						foreach (JsonElement item2 in value15.EnumerateArray())
						{
							list2.Add(new ContentPrecondition(ParseKind(item2.GetProperty("kind").GetString()), ParseInterval(item2.GetProperty("timing").GetString()), item2.GetProperty("id").GetString() ?? ""));
						}
					}
					list.Add(new SubmissionRecord(id, token, new SubmissionRequest(nickname, text, trigger, list2, color, topPinned, SubmissionKind.Ugc, "", RuleSubmissionStyle.Narration, rainbow, continuationTexts, sequenceSpeed, note), status, requestType, originalId, reviewReason, reviewedAt));
				}
				return list;
			}
			catch
			{
				return null;
			}
		}

		private static IReadOnlyList<string> ParseStringArray(JsonElement element, string propertyName)
		{
			if (!element.TryGetProperty(propertyName, out var value2) || value2.ValueKind != JsonValueKind.Array)
			{
				return Array.Empty<string>();
			}
			return (from value in value2.EnumerateArray()
				where value.ValueKind == JsonValueKind.String
				select value.GetString() ?? "").ToArray();
		}

		private static string KindName(ContentObjectKind kind)
		{
			return kind switch
			{
				ContentObjectKind.Character => "character", 
				ContentObjectKind.Card => "card", 
				ContentObjectKind.Relic => "relic", 
				ContentObjectKind.Monster => "monster", 
				ContentObjectKind.Event => "event", 
				ContentObjectKind.Act => "act", 
				ContentObjectKind.Turn => "turn", 
				_ => "card", 
			};
		}

		private static string InstantName(ContentInstant instant)
		{
			return instant switch
			{
				ContentInstant.Preselected => "preselected", 
				ContentInstant.Confirmed => "confirmed", 
				ContentInstant.Obtained => "obtained", 
				ContentInstant.Upgraded => "upgraded", 
				ContentInstant.Removed => "removed", 
				ContentInstant.Played => "played", 
				ContentInstant.Encountered => "encountered", 
				ContentInstant.Defeated => "defeated", 
				ContentInstant.Combat => "combat", 
				ContentInstant.Entered => "entered", 
				ContentInstant.OptionSelected => "optionSelected", 
				ContentInstant.ActEntered => "actEntered", 
				ContentInstant.TurnEntered => "turnEntered", 
				_ => "obtained", 
			};
		}

		private static string IntervalName(ContentInterval interval)
		{
			return interval switch
			{
				ContentInterval.Using => "using", 
				ContentInterval.Own => "own", 
				ContentInterval.InCombat => "inCombat", 
				ContentInterval.InEvent => "inEvent", 
				ContentInterval.AtAct => "atAct", 
				ContentInterval.AtTurn => "atTurn", 
				_ => "own", 
			};
		}

		private static string StatusName(SubmissionStatus status)
		{
			return status switch
			{
				SubmissionStatus.Approved => "approved", 
				SubmissionStatus.Rejected => "rejected", 
				_ => "pending", 
			};
		}

		private static ContentObjectKind ParseKind(string? value)
		{
			return value?.Trim().ToLowerInvariant() switch
			{
				"character" => ContentObjectKind.Character, 
				"relic" => ContentObjectKind.Relic, 
				"monster" => ContentObjectKind.Monster, 
				"event" => ContentObjectKind.Event, 
				"act" => ContentObjectKind.Act, 
				"turn" => ContentObjectKind.Turn, 
				_ => ContentObjectKind.Card, 
			};
		}

		private static ContentInstant ParseInstant(string? value)
		{
			return value?.Trim().ToLowerInvariant() switch
			{
				"preselected" => ContentInstant.Preselected, 
				"confirmed" => ContentInstant.Confirmed, 
				"upgraded" => ContentInstant.Upgraded, 
				"removed" => ContentInstant.Removed, 
				"played" => ContentInstant.Played, 
				"encountered" => ContentInstant.Encountered, 
				"defeated" => ContentInstant.Defeated, 
				"combat" => ContentInstant.Combat, 
				"entered" => ContentInstant.Entered, 
				"optionselected" => ContentInstant.OptionSelected, 
				"actentered" => ContentInstant.ActEntered, 
				"turnentered" => ContentInstant.TurnEntered, 
				_ => ContentInstant.Obtained, 
			};
		}

		private static ContentInterval ParseInterval(string? value)
		{
			return value?.Trim().ToLowerInvariant() switch
			{
				"using" => ContentInterval.Using, 
				"incombat" => ContentInterval.InCombat, 
				"inevent" => ContentInterval.InEvent, 
				"atact" => ContentInterval.AtAct, 
				"atturn" => ContentInterval.AtTurn, 
				_ => ContentInterval.Own, 
			};
		}

		private static SubmissionStatus ParseStatus(string value)
		{
			string text = value?.Trim().ToLowerInvariant();
			if (!(text == "approved"))
			{
				if (text == "rejected")
				{
					return SubmissionStatus.Rejected;
				}
				return SubmissionStatus.Pending;
			}
			return SubmissionStatus.Approved;
		}

		private static string RequestTypeName(SubmissionRequestType type)
		{
			return type switch
			{
				SubmissionRequestType.Delete => "delete", 
				SubmissionRequestType.Edit => "edit", 
				_ => "submit", 
			};
		}

		private static SubmissionRequestType ParseRequestType(string? value)
		{
			string text = value?.Trim().ToLowerInvariant();
			if (!(text == "delete"))
			{
				if (text == "edit")
				{
					return SubmissionRequestType.Edit;
				}
				return SubmissionRequestType.Submit;
			}
			return SubmissionRequestType.Delete;
		}
	}
	public enum SubmissionStatus
	{
		Pending,
		Approved,
		Rejected
	}
	public enum SubmissionKind
	{
		Ugc,
		Rule
	}
	public sealed record SubmissionRequest(string Nickname, string Text, ContentTrigger Trigger, IReadOnlyList<ContentPrecondition> Preconditions, string? Color = null, bool TopPinned = false, SubmissionKind Kind = SubmissionKind.Ugc, string RuleId = "", RuleSubmissionStyle RuleStyle = RuleSubmissionStyle.Narration, bool Rainbow = false, IReadOnlyList<string>? ContinuationTexts = null, DanmakuSequenceSpeed SequenceSpeed = DanmakuSequenceSpeed.Medium, string? Note = null)
	{
		public IReadOnlyList<string> StableContinuationTexts => ContinuationTexts ?? Array.Empty<string>();

		public IReadOnlyList<string> AllTexts => new string[1] { Text }.Concat(StableContinuationTexts).ToArray();
	}
	public enum SubmissionRequestType
	{
		Submit,
		Delete,
		Edit
	}
	public sealed record SubmissionRecord(long Id, string Token, SubmissionRequest Request, SubmissionStatus Status, SubmissionRequestType RequestType = SubmissionRequestType.Submit, long OriginalId = 0L, string? ReviewReason = null, string? ReviewedAt = null, IReadOnlyList<SubmissionRecord>? RelatedRequests = null)
	{
		public IReadOnlyList<SubmissionRecord> StableRelatedRequests => RelatedRequests ?? Array.Empty<SubmissionRecord>();

		public SubmissionRecord? LatestApprovedChange => StableRelatedRequests.Where((SubmissionRecord record) => record.Status == SubmissionStatus.Approved).OrderByDescending<SubmissionRecord, string>((SubmissionRecord record) => record.ReviewedAt ?? "", StringComparer.Ordinal).ThenByDescending((SubmissionRecord record) => record.Id)
			.FirstOrDefault();

		public bool IsEffectivelyDeleted
		{
			get
			{
				SubmissionRecord? latestApprovedChange = LatestApprovedChange;
				if ((object)latestApprovedChange == null)
				{
					return false;
				}
				return latestApprovedChange.RequestType == SubmissionRequestType.Delete;
			}
		}

		public bool HasPendingRequest => StableRelatedRequests.Any((SubmissionRecord record) => record.Status == SubmissionStatus.Pending);

		public SubmissionRequest EffectiveRequest
		{
			get
			{
				SubmissionRecord latestApprovedChange = LatestApprovedChange;
				if ((object)latestApprovedChange == null || latestApprovedChange.RequestType != SubmissionRequestType.Edit)
				{
					return Request;
				}
				return latestApprovedChange.Request;
			}
		}
	}
	public static class SubmissionValidator
	{
		public const int MaxNoteLength = 500;

		public static IReadOnlyList<string> Validate(SubmissionRequest request)
		{
			if (request.Kind != SubmissionKind.Rule)
			{
				return ValidateUgc(request);
			}
			return ValidateRule(request);
		}

		public static IReadOnlyList<string> ValidateRule(SubmissionRequest request)
		{
			List<string> list = new List<string>();
			ValidateTexts(request, list, "弹幕文本");
			if (ContentValidator.CountCharacters(request.Nickname) > 16)
			{
				list.Add($"昵称超过 {16} 字");
			}
			if (ContentValidator.CountCharacters(request.Note ?? "") > 500)
			{
				list.Add($"投稿说明超过 {500} 字");
			}
			if (string.IsNullOrWhiteSpace(request.RuleId) || !RuleDisplayCatalog.Contains(request.RuleId))
			{
				list.Add("未选择有效的触发规则");
			}
			else if (!RuleDisplayCatalog.CanSubmit(request.RuleId))
			{
				list.Add("该规则不可投稿");
			}
			if (!ContentValidator.IsValidColor(request.Color))
			{
				list.Add("color 格式非法：" + request.Color);
			}
			return list;
		}

		public static IReadOnlyList<string> ValidateUgc(SubmissionRequest request)
		{
			List<string> list = new List<string>();
			ValidateTexts(request, list, "弹幕文本");
			if (ContentValidator.CountCharacters(request.Nickname) > 16)
			{
				list.Add($"nickname 超过 {16} 字");
			}
			if (ContentValidator.CountCharacters(request.Note ?? "") > 500)
			{
				list.Add($"投稿说明超过 {500} 字");
			}
			if (!ContentConditionRules.IsValidInstant(request.Trigger.Kind, request.Trigger.Timing))
			{
				list.Add("触发对象与时机不配对");
			}
			if (!ContentValidator.IsValidObjectId(request.Trigger.Id))
			{
				list.Add($"触发对象 id 不能为空且不得超过 {128} 字");
			}
			if (ContentConditionRules.IsContextInstant(request.Trigger.Kind, request.Trigger.Timing) && !ContentConditionRules.IsValidContextTriggerId(request.Trigger.Id))
			{
				list.Add("「进入幕/回合」触发 id 必须为正整数或通配 *");
			}
			if (request.Trigger.Timing == ContentInstant.Combat && !request.Trigger.IsWildcard)
			{
				list.Add("敌怪「战中」时机必须使用任意对象");
			}
			if (!ContentValidator.IsValidColor(request.Color))
			{
				list.Add("color 格式非法：" + request.Color);
			}
			if (request.Preconditions.Count > 5)
			{
				list.Add($"前置条件超过 {5} 个");
			}
			HashSet<ContentObjectKind> hashSet = new HashSet<ContentObjectKind>();
			foreach (ContentPrecondition precondition in request.Preconditions)
			{
				if (!ContentConditionRules.IsValidInterval(precondition.Kind, precondition.Timing))
				{
					list.Add($"前置对象与时机不配对：{precondition.Kind}/{precondition.Timing}");
				}
				if (!ContentValidator.IsValidObjectId(precondition.Id))
				{
					list.Add($"前置对象 id 不能为空且不得超过 {128} 字");
				}
				if (ContentConditionRules.IsContextInterval(precondition.Kind, precondition.Timing) && !ContentConditionRules.IsValidContextValue(precondition.Id))
				{
					list.Add("「处于幕/回合」前置 id 必须为正整数（不允许通配）");
				}
				if (!hashSet.Add(precondition.Kind))
				{
					list.Add($"同一对象类型只能有一个前置：{precondition.Kind}");
				}
			}
			return list;
		}

		private static void ValidateTexts(SubmissionRequest request, List<string> errors, string fieldName)
		{
			IReadOnlyList<string> allTexts = request.AllTexts;
			if (allTexts.Count > 5)
			{
				errors.Add($"连续弹幕最多 {5} 条");
			}
			for (int i = 0; i < allTexts.Count; i++)
			{
				string text = allTexts[i];
				string text2 = ((allTexts.Count == 1) ? fieldName : $"第 {i + 1} 条弹幕");
				if (string.IsNullOrWhiteSpace(text))
				{
					errors.Add(text2 + "不能为空");
				}
				else if (ContentValidator.CountTextCharacters(text) > 40)
				{
					errors.Add($"{text2}超过 {40} 字");
				}
			}
		}
	}
	public sealed class SubmissionStore
	{
		private readonly Dictionary<long, SubmissionRecord> _records = new Dictionary<long, SubmissionRecord>();

		public IReadOnlyList<SubmissionRecord> AllRecords => _records.Values.OrderByDescending((SubmissionRecord record) => record.Id).ToList();

		public IReadOnlyList<SubmissionRecord> Records
		{
			get
			{
				Dictionary<long, IReadOnlyList<SubmissionRecord>> children = (from record in _records.Values
					where record.RequestType != 0 && record.OriginalId > 0
					group record by record.OriginalId).ToDictionary((Func<IGrouping<long, SubmissionRecord>, long>)((IGrouping<long, SubmissionRecord> group) => group.Key), (Func<IGrouping<long, SubmissionRecord>, IReadOnlyList<SubmissionRecord>>)((IGrouping<long, SubmissionRecord> group) => group.OrderByDescending((SubmissionRecord record) => record.Id).ToList()));
				return (from record in _records.Values
					where record.RequestType == SubmissionRequestType.Submit
					orderby record.Id descending
					select record with
					{
						RelatedRequests = children.GetValueOrDefault(record.Id, Array.Empty<SubmissionRecord>())
					}).ToList();
			}
		}

		public void Record(long id, string token, SubmissionRequest request, SubmissionStatus status, SubmissionRequestType requestType = SubmissionRequestType.Submit, long originalId = 0L)
		{
			_records[id] = new SubmissionRecord(id, token, request, status, requestType, originalId);
		}

		public void SyncFromServer(IReadOnlyList<SubmissionRecord> serverRecords)
		{
			Dictionary<long, string> dictionary = _records.ToDictionary<KeyValuePair<long, SubmissionRecord>, long, string>((KeyValuePair<long, SubmissionRecord> pair) => pair.Key, (KeyValuePair<long, SubmissionRecord> pair) => pair.Value.Token);
			_records.Clear();
			foreach (SubmissionRecord serverRecord in serverRecords)
			{
				string token = (string.IsNullOrWhiteSpace(serverRecord.Token) ? dictionary.GetValueOrDefault(serverRecord.Id, "") : serverRecord.Token);
				_records[serverRecord.Id] = serverRecord with
				{
					Token = token,
					RelatedRequests = null
				};
			}
		}

		public bool Remove(long id)
		{
			return _records.Remove(id);
		}

		public void Restore(IReadOnlyList<SubmissionRecord> records)
		{
			_records.Clear();
			foreach (SubmissionRecord record in records)
			{
				_records[record.Id] = record with
				{
					RelatedRequests = null
				};
			}
		}
	}
