		public static (string EventId, string OptionKey) SplitEventOptionTriggerId(string id)
		{
			if (string.IsNullOrWhiteSpace(id))
			{
				return (EventId: "*", OptionKey: "*");
			}
			int num = id.IndexOf(':');
			if (num <= 0 || num >= id.Length - 1)
			{
				return (EventId: id, OptionKey: "*");
			}
			string item = id.Substring(0, num);
			int num2 = num + 1;
			return (EventId: item, OptionKey: id.Substring(num2, id.Length - num2));
		}

