		public static string Describe(SubmissionRequest request, Func<ContentObjectKind, string, string>? resolveName = null)
		{
			Func<ContentObjectKind, string, string> resolveName2 = resolveName;
			string text = (string.IsNullOrWhiteSpace(request.Text) ? "……" : request.Text);
			string text2 = TriggerPhrase(request.Trigger.Kind, request.Trigger.Timing, request.Trigger.Id, resolveName2);
			if (request.Preconditions.Count == 0)
			{
				return text2 + "时，发射弹幕：" + text;
			}
			string value = string.Join("、", request.Preconditions.Select((ContentPrecondition p) => PreconditionPhrase(p.Kind, p.Timing, p.Id, resolveName2)));
			return $"{value}，{text2}时，发射弹幕：{text}";
		}

		private static string TriggerPhrase(ContentObjectKind kind, ContentInstant timing, string id, Func<ContentObjectKind, string, string>? resolveName)
		{
			string text = TargetName(kind, id, resolveName);
			switch (kind)
			{
			case ContentObjectKind.Character:
				switch (timing)
				{
				case ContentInstant.Preselected:
					return (id == "*") ? "点击预选任意角色" : ("点击预选角色「" + (resolveName?.Invoke(kind, id) ?? id) + "」");
				case ContentInstant.Confirmed:
					return "确认使用" + text;
				}
				break;
			case ContentObjectKind.Card:
				switch (timing)
				{
				case ContentInstant.Obtained:
					return "获得" + text;
				case ContentInstant.Upgraded:
					return "升级" + text;
				case ContentInstant.Removed:
					return "失去" + text;
				case ContentInstant.Played:
					return "打出" + text;
				}
				break;
			case ContentObjectKind.Relic:
				if (timing != ContentInstant.Obtained)
				{
					break;
				}
				return "获得" + text;
			case ContentObjectKind.Monster:
				switch (timing)
				{
				case ContentInstant.Encountered:
					return "遭遇" + text;
				case ContentInstant.Defeated:
					return "击败" + text;
				case ContentInstant.Combat:
					return "与" + text + "交战";
				}
				break;
			case ContentObjectKind.Event:
				switch (timing)
				{
				case ContentInstant.Entered:
					return "进入" + text;
				case ContentInstant.OptionSelected:
					return "在" + text + "中选择选项";
				}
				break;
			case ContentObjectKind.Act:
				if (timing != ContentInstant.ActEntered)
				{
					break;
				}
				return (id == "*") ? "进入任意幕" : ("进入第" + id + "幕");
			case ContentObjectKind.Turn:
				if (timing != ContentInstant.TurnEntered)
				{
					break;
				}
				return (id == "*") ? "进入任意回合" : ("进入第" + id + "回合");
			}
			return "触发" + text;
		}

		private static string PreconditionPhrase(ContentObjectKind kind, ContentInterval timing, string id, Func<ContentObjectKind, string, string>? resolveName)
		{
			string text = TargetName(kind, id, resolveName);
			switch (kind)
			{
			case ContentObjectKind.Character:
				if (timing != 0)
				{
					break;
				}
				return "正在使用" + text;
			case ContentObjectKind.Card:
				if (timing != ContentInterval.Own)
				{
					break;
				}
				return "拥有" + text;
			case ContentObjectKind.Relic:
				if (timing != ContentInterval.Own)
				{
					break;
				}
				return "拥有" + text;
			case ContentObjectKind.Monster:
				if (timing != ContentInterval.InCombat)
				{
					break;
				}
				return "与" + text + "交战";
			case ContentObjectKind.Event:
				if (timing != ContentInterval.InEvent)
				{
					break;
				}
				return "正处于" + text;
			case ContentObjectKind.Act:
				if (timing != ContentInterval.AtAct)
				{
					break;
				}
				return "处于第" + id + "幕";
			case ContentObjectKind.Turn:
				if (timing != ContentInterval.AtTurn)
				{
					break;
				}
				return "处于第" + id + "回合";
			}
			return "处于" + text;
		}

		private static string TargetName(ContentObjectKind kind, string id, Func<ContentObjectKind, string, string>? resolveName)
		{
			if (id == "*")
			{
				return "任意" + KindLabel(kind);
			}
			return KindLabel(kind) + "「" + (resolveName?.Invoke(kind, id) ?? id) + "」";
		}

		public static string DescribeTriggerOnly(SubmissionRequest request, Func<ContentObjectKind, string, string>? resolveName = null)
		{
			if (request.Kind == SubmissionKind.Rule)
			{
				string value = RuleDisplayCatalog.NameOf(request.RuleId) ?? request.RuleId;
				string value2 = RuleStyleLabel(request.RuleStyle);
				return $"{value}（{request.RuleId}·{value2}）";
			}
			string text = Describe(request, resolveName);
			int num = text.LastIndexOf("时，发射弹幕：", StringComparison.Ordinal);
			if (num < 0)
			{
				return text;
			}
			return text.Substring(0, num + 1);
		}

