		{
			return style switch
			{
				RuleSubmissionStyle.Character => "角色", 
				RuleSubmissionStyle.Narration => "旁白", 
				_ => "旁白", 
			};
		}

		public static string DescribeRule(RuleSubmissionRequest request)
		{
			string value = RuleDisplayCatalog.NameOf(request.RuleId) ?? request.RuleId;
			string value2 = RuleStyleLabel(request.Style);
			string value3 = (string.IsNullOrWhiteSpace(request.Text) ? "……" : request.Text);
			return $"{value}时（{request.RuleId}·{value2}），发射弹幕：{value3}";
		}

