	public sealed class UgcCacheStore
	{
		private const string ManifestFileName = "manifest.json";

		private const string ActiveDirectoryName = "active";

		private static readonly JsonSerializerOptions Indented = new JsonSerializerOptions
		{
			WriteIndented = true,
			Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
		};

		private readonly string _dir;

		public string DirectoryPath => _dir;

		public string ActiveDirectoryPath => Path.Combine(_dir, "active");

		public UgcCacheStore(string dir)
		{
			_dir = dir;
			Directory.CreateDirectory(dir);
		}

		public ContentManifest? LoadManifest()
		{
			string path = Path.Combine(ActiveDirectoryPath, "manifest.json");
			if (!File.Exists(path))
			{
				path = Path.Combine(_dir, "manifest.json");
			}
			if (!File.Exists(path))
			{
				return null;
			}
			try
			{
				return ContentPackParser.ParseManifest(File.ReadAllText(path, Encoding.UTF8));
			}
			catch
			{
				return null;
			}
		}

		public void SaveShard(string name, string content)
		{
			EnsureCanonicalShardName(name);
			Directory.CreateDirectory(ActiveDirectoryPath);
			AtomicWrite(Path.Combine(ActiveDirectoryPath, name), content);
		}

		public string? LoadShard(string name)
		{
			EnsureCanonicalShardName(name);
			string path = Path.Combine(ActiveDirectoryPath, name);
			if (!File.Exists(path))
			{
				path = Path.Combine(_dir, name);
			}
			if (!File.Exists(path))
			{
				return null;
			}
			return File.ReadAllText(path, Encoding.UTF8);
		}

		public void SaveManifest(ContentManifest manifest)
		{
			Directory.CreateDirectory(ActiveDirectoryPath);
			AtomicWrite(Path.Combine(ActiveDirectoryPath, "manifest.json"), SerializeManifest(manifest));
		}

		public void SaveSnapshot(ContentManifest manifest, IReadOnlyDictionary<string, string> remoteContents)
		{
			string text = Path.Combine(_dir, $".snapshot-{manifest.UgcVersion}-{Guid.NewGuid():N}");
			string text2 = Path.Combine(_dir, $".active-backup-{Guid.NewGuid():N}");
			bool flag = false;
			bool flag2 = false;
			try
			{
				Directory.CreateDirectory(text);
				foreach (ContentShardInfo shard in manifest.Shards)
				{
					if (!ContentManifestValidator.TryGetCanonicalShardName(shard.Name, manifest.UgcVersion, out string canonicalName))
					{
						throw new InvalidDataException("非法分片对象键：" + shard.Name);
					}
					if (!remoteContents.TryGetValue(shard.Name, out string value))
					{
						throw new InvalidDataException("缺少已校验分片：" + shard.Name);
					}
					File.WriteAllText(Path.Combine(text, canonicalName), value, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				}
				File.WriteAllText(Path.Combine(text, "manifest.json"), SerializeManifest(manifest), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				if (Directory.Exists(ActiveDirectoryPath))
				{
					Directory.Move(ActiveDirectoryPath, text2);
					flag = true;
				}
				Directory.Move(text, ActiveDirectoryPath);
				flag2 = true;
				if (flag)
				{
					TryDeleteDirectory(text2);
				}
			}
			catch
			{
				if (!flag2 && flag && !Directory.Exists(ActiveDirectoryPath) && Directory.Exists(text2))
				{
					Directory.Move(text2, ActiveDirectoryPath);
				}
				throw;
			}
			finally
			{
				if (Directory.Exists(text))
				{
					TryDeleteDirectory(text);
				}
				if (flag2 && Directory.Exists(text2))
				{
					TryDeleteDirectory(text2);
				}
			}
		}

		private static string SerializeManifest(ContentManifest manifest)
		{
			return JsonSerializer.Serialize(new
			{
				schemaVersion = manifest.SchemaVersion,
				modVersion = manifest.ModVersion,
				ugcVersion = manifest.UgcVersion,
				signature = manifest.Signature,
				shards = manifest.Shards.Select((ContentShardInfo shard) => new
				{
					name = shard.Name,
					version = shard.Version,
					sha256 = shard.Sha256
				})
			}, Indented);
		}

		public static string ComputeSha256(string content)
		{
			return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(content))).ToLowerInvariant();
		}

		public static bool VerifySha256(string content, string expectedSha256)
		{
			return string.Equals(ComputeSha256(content), expectedSha256, StringComparison.OrdinalIgnoreCase);
		}

		private static void AtomicWrite(string path, string content)
		{
			Directory.CreateDirectory(Path.GetDirectoryName(path));
			string text = path + ".new";
			try
			{
				File.WriteAllText(text, content, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				File.Move(text, path, overwrite: true);
			}
			finally
			{
				try
				{
					if (File.Exists(text))
					{
						File.Delete(text);
					}
				}
				catch
				{
				}
			}
		}

		private static void EnsureCanonicalShardName(string name)
		{
			if (!ContentManifestValidator.IsCanonicalShardName(name))
			{
				throw new ArgumentException("未知或不安全的分片文件名：" + name, "name");
			}
		}

		private static void TryDeleteDirectory(string path)
		{
			try
			{
				Directory.Delete(path, recursive: true);
			}
			catch
			{
			}
		}
	}
