	public readonly record struct UgcLoadResult(int Loaded, int Failed);
	public sealed class UgcContentLoader
	{
		public static readonly IReadOnlyList<string> ShardNames = new string[7] { "characters.json", "cards.json", "relics.json", "monsters.json", "events.json", "acts.json", "turns.json" };

		private readonly string _dir;

		public string DirectoryPath => _dir;

		public UgcContentLoader(string dir)
		{
			_dir = dir;
		}

		public UgcLoadResult LoadAll(UgcRuntime runtime, ContentLayer layer)
		{
			if (!Directory.Exists(_dir))
			{
				return new UgcLoadResult(0, 0);
			}
			int num = 0;
			int num2 = 0;
			foreach (string shardName in ShardNames)
			{
				string path = Path.Combine(_dir, shardName);
				if (File.Exists(path))
				{
					try
					{
						UgcLoadResult ugcLoadResult = runtime.LoadShard(File.ReadAllText(path, Encoding.UTF8), layer);
						num += ugcLoadResult.Loaded;
						num2 += ugcLoadResult.Failed;
					}
					catch
					{
						num2++;
					}
				}
			}
			return new UgcLoadResult(num, num2);
		}
	}
	public readonly record struct UgcEmissionPlan(string Text, ContentStyle Style, string? ColorHex, string? Avatar, string Author, bool TopPinned = false, bool Rainbow = false, IReadOnlyList<string>? ContinuationTexts = null, DanmakuSequenceSpeed SequenceSpeed = DanmakuSequenceSpeed.Medium)
	{
		public IReadOnlyList<string> StableContinuationTexts => ContinuationTexts ?? Array.Empty<string>();

		public IReadOnlyList<string> AllTexts => new string[1] { Text }.Concat(StableContinuationTexts).ToArray();
	}
	public static class UgcEmissionPlanner
	{
		public static UgcEmissionPlan Plan(ContentEntry entry, IReadOnlyDictionary<string, string>? context = null)
		{
			IReadOnlyDictionary<string, string> context2 = context;
			return new UgcEmissionPlan(ResolveTemplate(entry.Text, context2), entry.Style, entry.Color, entry.Avatar, entry.Author, entry.TopPinned, entry.Rainbow, entry.StableContinuationTexts.Select((string text) => ResolveTemplate(text, context2)).ToArray(), entry.SequenceSpeed);
		}

		public static string ResolveTemplate(string text, IReadOnlyDictionary<string, string>? context)
		{
			if (string.IsNullOrEmpty(text) || context == null || context.Count == 0)
			{
				return text;
			}
			string text2 = text;
			foreach (KeyValuePair<string, string> item in context)
			{
				text2 = text2.Replace("{" + item.Key + "}", item.Value);
			}
			return text2;
		}

		public static IReadOnlyList<string> GetMissingKeys(string text, IReadOnlyDictionary<string, string> context)
		{
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			if (string.IsNullOrEmpty(text))
			{
				return Array.Empty<string>();
			}
			int num = 0;
			while (num < text.Length)
			{
				int num2 = text.IndexOf('{', num);
				if (num2 < 0)
				{
					break;
				}
				int num3 = text.IndexOf('}', num2 + 1);
				if (num3 < 0)
				{
					break;
				}
				int num4 = num2 + 1;
				string text2 = text.Substring(num4, num3 - num4);
				if (text2.Length > 0 && !context.ContainsKey(text2))
				{
					hashSet.Add(text2);
				}
				num = num3 + 1;
			}
			return hashSet.OrderBy<string, string>((string key) => key, StringComparer.Ordinal).ToArray();
		}
	}
	public sealed class UgcEngine
	{
		private readonly ContentStore _store;

		private readonly HotspotPool _pool;

		private readonly IntervalStateSnapshot _state;

		private DanmakuDensity _density = DanmakuDensity.Standard;

		public DanmakuDensity Density
		{
			get
			{
				return _density;
			}
			set
			{
				_density = value;
				_pool.UpdateDensity(value);
			}
		}

		public IntervalStateSnapshot State => _state;

		public int ActiveHotspotCount => _pool.ActiveCount;

		public UgcEngine(ContentStore store, HotspotPool? pool = null, IntervalStateSnapshot? state = null)
		{
			_store = store;
			_pool = pool ?? new HotspotPool();
			_state = state ?? new IntervalStateSnapshot();
		}

		public bool OnObjectEvent(ContentTrigger trigger, double now, bool freezeCandidates = false)
		{
			IReadOnlyList<string> readOnlyList = UgcQuery.QueryIds(_store, trigger, _state);
			if (readOnlyList.Count == 0)
			{
				return false;
			}
			return _pool.Trigger(trigger, now, _density, freezeCandidates ? readOnlyList.ToArray() : null);
		}

		public IReadOnlyList<HotspotEmission> Advance(double now)
		{
			return _pool.Advance(now, (ContentTrigger trigger) => UgcQuery.QueryIds(_store, trigger, _state));
		}

		public void RefreshPreconditions()
		{
			_pool.CancelWhereLive((ContentTrigger trigger) => UgcQuery.QueryIds(_store, trigger, _state).Count == 0);
		}

		public void ClearHotspots()
		{
			_pool.ClearActive();
		}

		public IReadOnlyList<UgcShuffleBagSnapshot> SnapshotShuffleBags()
		{
			return _pool.SnapshotBags();
		}

		public void RestoreShuffleBags(IEnumerable<UgcShuffleBagSnapshot>? snapshots)
		{
			_pool.RestoreBags(snapshots);
		}

		public void EndCombat()
		{
			_pool.CancelWhere((ContentTrigger trigger) => HotspotSchedule.IsCombat(trigger.Kind, trigger.Timing));
			_state.RemoveAll(ContentObjectKind.Monster, ContentInterval.InCombat);
			_state.RemoveAll(ContentObjectKind.Turn, ContentInterval.AtTurn);
			RefreshPreconditions();
		}

		public void Clear()
		{
			_pool.Clear();
			_state.Clear();
		}
	}
	public sealed class UgcHttpClient
	{
		private readonly HttpClient _http;

		public UgcHttpClient(HttpClient http)
		{
			_http = http;
		}

		public async Task<string?> FetchAsync(string url, CancellationToken token = default(CancellationToken))
		{
			_ = 1;
			try
			{
				using HttpResponseMessage response = await _http.GetAsync(url, token).ConfigureAwait(continueOnCapturedContext: false);
				if (!response.IsSuccessStatusCode)
				{
					return null;
				}
				return await response.Content.ReadAsStringAsync(token).ConfigureAwait(continueOnCapturedContext: false);
			}
			catch
			{
				return null;
			}
		}

		public string? Fetch(string url)
		{
			return FetchAsync(url).GetAwaiter().GetResult();
		}
	}
	public static class UgcQuery
	{
		public static IReadOnlyList<ContentEntry> Query(ContentStore store, ContentTrigger trigger, IntervalStateSnapshot state)
		{
			IntervalStateSnapshot state2 = state;
			return (from entry in store.Query(trigger)
				where entry.Preconditions.All(state2.Satisfies)
				select entry).ToList();
		}

		public static IReadOnlyList<string> QueryIds(ContentStore store, ContentTrigger trigger, IntervalStateSnapshot state)
		{
			return (from entry in Query(store, trigger, state)
				select entry.Id).ToList();
		}
	}
	public sealed class UgcRuntime
	{
		private readonly ContentStore _store = new ContentStore();

		private readonly UgcEngine _engine;

		private double _logicalNow;

		public static UgcRuntime? Instance { get; private set; }

		public UgcEngine Engine => _engine;

		public ContentStore Store => _store;

		public IntervalStateSnapshot State => _engine.State;

		public double LogicalNow => _logicalNow;

		public Action<string, string>? RemoteEmitter { get; set; }

		public UgcRuntime()
		{
			_engine = new UgcEngine(_store);
			Instance = this;
		}

		public double AdvanceClock(double delta)
		{
			if (double.IsFinite(delta) && delta > 0.0)
			{
				_logicalNow += delta;
			}
			return _logicalNow;
		}

		public int LoadEntries(string json)
		{
			return LoadShard(json, ContentLayer.Ugc).Loaded;
		}

		public UgcLoadResult LoadShard(string json, ContentLayer layer)
		{
			ContentShardParse contentShardParse = ContentPackParser.ParseShard(json);
			List<ContentEntry> list = contentShardParse.Entries.Where((ContentEntry entry) => ContentValidator.ValidateEntry(entry).Count == 0).ToList();
			int failed = contentShardParse.Errors.Count + (contentShardParse.Entries.Count - list.Count);
			_store.Load(list, layer);
			_store.RemoveIds(contentShardParse.DeletedIds, layer);
			return new UgcLoadResult(list.Count, failed);
		}

		public bool OnCollectibleObtained(ContentObjectKind kind, string modelId, double now)
		{
			ContentTrigger trigger = new ContentTrigger(kind, ContentInstant.Obtained, modelId);
			_engine.State.Set(kind, ContentInterval.Own, modelId);
			return _engine.OnObjectEvent(trigger, now);
		}

		public bool OnCardRemoved(string cardId, double now)
		{
			ContentTrigger trigger = new ContentTrigger(ContentObjectKind.Card, ContentInstant.Removed, cardId);
			_engine.State.Remove(ContentObjectKind.Card, ContentInterval.Own, cardId);
			return _engine.OnObjectEvent(trigger, now);
		}

		public IReadOnlyList<HotspotEmission> Advance(double now)
		{
			return _engine.Advance(now);
		}

		public void Clear()
		{
			_engine.Clear();
			_logicalNow = 0.0;
		}

		public void ClearContent()
		{
			_store.Clear();
		}

		public IReadOnlyList<UgcShuffleBagSnapshot> SnapshotShuffleBags()
		{
			return _engine.SnapshotShuffleBags();
		}

		public void RestoreShuffleBags(IEnumerable<UgcShuffleBagSnapshot>? snapshots)
		{
			_engine.RestoreShuffleBags(snapshots);
		}

		public bool EmitRemote(string entryId, string sourceCharacterId)
		{
			if (RemoteEmitter == null)
			{
				return false;
			}
			if (!_store.GetById(entryId).HasValue)
			{
				return false;
			}
			RemoteEmitter(entryId, sourceCharacterId);
			return true;
		}

		public void Shutdown()
		{
			if (Instance == this)
			{
				Instance = null;
			}
		}
	}
	public sealed record UgcSyncPlan(bool NeedsUpdate, IReadOnlyList<ContentShardInfo> ShardsToDownload);
	public static class UgcSyncPlanner
	{
		public static UgcSyncPlan Plan(ContentManifest remote, ContentManifest? local)
		{
			if (local == null)
			{
				return new UgcSyncPlan(remote.Shards.Count > 0, remote.Shards);
			}
			if (remote.UgcVersion == local.UgcVersion && ContentSigning.BuildSignatureInput(remote) == ContentSigning.BuildSignatureInput(local) && remote.Signature == local.Signature)
			{
				return new UgcSyncPlan(NeedsUpdate: false, Array.Empty<ContentShardInfo>());
			}
			return new UgcSyncPlan(NeedsUpdate: true, remote.Shards);
		}

		public static IReadOnlyList<ContentEntry> ApplyTombstones(IReadOnlyList<ContentEntry> entries, IReadOnlySet<string>? deletedIds)
		{
			IReadOnlySet<string> deletedIds2 = deletedIds;
			if (deletedIds2 == null || deletedIds2.Count == 0)
			{
				return entries;
			}
			return entries.Where((ContentEntry entry) => !deletedIds2.Contains(entry.Id)).ToList();
		}
	}
	public enum UgcSyncStatus
	{
		UpToDate,
		Updated,
		Failed
	}
	public sealed record UgcSyncResult(bool Updated, IReadOnlyList<string> DownloadedShards, IReadOnlyList<string> FailedShards, ContentManifest? ActiveManifest, UgcSyncStatus Status = UgcSyncStatus.UpToDate, string? Error = null);
	public sealed class UgcSyncService
	{
		private readonly UgcCacheStore _cache;

		private readonly Func<string, string?> _fetch;

		private readonly Func<ContentManifest, bool> _verifySignature;

		public UgcSyncService(UgcCacheStore cache, Func<string, string?> fetch, Func<ContentManifest, bool>? verifySignature = null)
		{
			_cache = cache;
			_fetch = fetch;
			_verifySignature = verifySignature ?? ((Func<ContentManifest, bool>)((ContentManifest manifest) => ContentSigning.VerifyManifestSignature(manifest, manifest.Signature)));
		}

		public UgcSyncResult Sync(string manifestUrl, Func<ContentShardInfo, string> shardUrl)
		{
			ContentManifest contentManifest = _cache.LoadManifest();
			string text = _fetch(manifestUrl);
			if (text == null)
			{
				return new UgcSyncResult(Updated: false, Array.Empty<string>(), Array.Empty<string>(), contentManifest, UgcSyncStatus.Failed, "无法连接服务器，请检查网络后重试。");
			}
			ContentManifest contentManifest2;
			try
			{
				contentManifest2 = ContentPackParser.ParseManifest(text);
			}
			catch
			{
				return new UgcSyncResult(Updated: false, Array.Empty<string>(), Array.Empty<string>(), contentManifest, UgcSyncStatus.Failed, "服务器返回的内容格式不正确。");
			}
			IReadOnlyList<string> readOnlyList = ContentManifestValidator.Validate(contentManifest2);
			if (readOnlyList.Count > 0)
			{
				return new UgcSyncResult(Updated: false, Array.Empty<string>(), Array.Empty<string>(), contentManifest, UgcSyncStatus.Failed, "内容清单非法：" + string.Join("；", readOnlyList));
			}
			if (!_verifySignature(contentManifest2))
			{
				return new UgcSyncResult(Updated: false, Array.Empty<string>(), Array.Empty<string>(), contentManifest, UgcSyncStatus.Failed, "内容签名校验失败，已拒绝更新并沿用旧缓存。");
			}
			if (contentManifest != null && contentManifest2.UgcVersion < contentManifest.UgcVersion)
			{
				return new UgcSyncResult(Updated: false, Array.Empty<string>(), Array.Empty<string>(), contentManifest, UgcSyncStatus.Failed, "服务器内容版本低于本地版本，已拒绝回滚。");
			}
			if (contentManifest != null && contentManifest2.UgcVersion == contentManifest.UgcVersion && (ContentSigning.BuildSignatureInput(contentManifest2) != ContentSigning.BuildSignatureInput(contentManifest) || contentManifest2.Signature != contentManifest.Signature))
			{
				return new UgcSyncResult(Updated: false, Array.Empty<string>(), Array.Empty<string>(), contentManifest, UgcSyncStatus.Failed, "服务器复用了现有版本号但内容不同，已拒绝冲突快照。");
			}
			UgcSyncPlan ugcSyncPlan = UgcSyncPlanner.Plan(contentManifest2, contentManifest);
			if (!ugcSyncPlan.NeedsUpdate)
			{
				return new UgcSyncResult(Updated: false, Array.Empty<string>(), Array.Empty<string>(), contentManifest ?? contentManifest2);
			}
			List<string> list = new List<string>();
			List<string> list2 = new List<string>();
			Dictionary<string, string> dictionary = new Dictionary<string, string>(StringComparer.Ordinal);
			foreach (ContentShardInfo item in ugcSyncPlan.ShardsToDownload)
			{
				string text2 = _fetch(shardUrl(item));
				if (text2 == null || Encoding.UTF8.GetByteCount(text2) > 2097152 || !UgcCacheStore.VerifySha256(text2, item.Sha256) || !ValidateShardContent(item, contentManifest2.UgcVersion, text2, out string _))
				{
					list2.Add(item.Name);
					continue;
				}
				dictionary[item.Name] = text2;
				list.Add(item.Name);
			}
			if (list2.Count == 0)
			{
				try
				{
					_cache.SaveSnapshot(contentManifest2, dictionary);
					return new UgcSyncResult(Updated: true, list, list2, _cache.LoadManifest() ?? contentManifest, UgcSyncStatus.Updated);
				}
				catch (Exception ex)
				{
					return new UgcSyncResult(Updated: false, list, contentManifest2.Shards.Select((ContentShardInfo shard) => shard.Name).ToArray(), contentManifest, UgcSyncStatus.Failed, "内容快照切换失败，已恢复旧缓存：" + ex.Message);
				}
			}
			return new UgcSyncResult(Updated: false, list, list2, _cache.LoadManifest() ?? contentManifest, UgcSyncStatus.Failed, "部分内容下载失败或校验未通过，已沿用旧缓存。");
		}

		private static bool ValidateShardContent(ContentShardInfo shard, long ugcVersion, string content, out string error)
		{
			error = "";
			if (!ContentManifestValidator.TryGetCanonicalShardName(shard.Name, ugcVersion, out string canonicalName))
			{
				error = "对象键非法";
				return false;
			}
			try
			{
				using JsonDocument jsonDocument = JsonDocument.Parse(content);
				if (jsonDocument.RootElement.ValueKind != JsonValueKind.Object)
				{
					error = "分片根节点必须是对象";
					return false;
				}
				RuleLibrary library;
				if (canonicalName == "rules-contrib.json")
				{
					return RuleContributionValidator.TryParse(content, out library, out error);
				}
				if (!jsonDocument.RootElement.TryGetProperty("entries", out var value) || value.ValueKind != JsonValueKind.Array)
				{
					error = "共创分片缺少 entries 数组";
					return false;
				}
				ContentShardParse contentShardParse = ContentPackParser.ParseShard(content);
				if (contentShardParse.Errors.Count > 0 || ContentValidator.ValidatePackIds(contentShardParse.Entries).Count > 0 || contentShardParse.Entries.Any((ContentEntry entry) => ContentValidator.ValidateEntry(entry).Count > 0))
				{
					error = "共创分片语义校验失败";
					return false;
				}
				return true;
			}
			catch (Exception ex) when (((ex is JsonException || ex is InvalidOperationException || ex is KeyNotFoundException) ? 1 : 0) != 0)
			{
				error = ex.Message;
				return false;
			}
		}
	}
