		private void ShowPage(PageMode mode)
		{
			_mode = mode;
			PrefillNickname();
			if (_title != null)
			{
				_title.Text = ((mode == PageMode.Collectible) ? "投稿卡牌组与遗物" : "意见反馈");
			}
			if (_collectibleForm != null)
			{
				((CanvasItem)_collectibleForm).Visible = mode == PageMode.Collectible;
			}
			if (_feedbackForm != null)
			{
				((CanvasItem)_feedbackForm).Visible = mode == PageMode.Feedback;
			}
			if (_rightPane != null)
			{
				((CanvasItem)_rightPane).Visible = mode == PageMode.Feedback;
			}
			if (_submit != null)
			{
				_submit.Text = ((mode == PageMode.Collectible) ? "提交资料投稿" : "提交意见反馈");
			}
			if (mode == PageMode.Collectible)
			{
				InitializeCatalogControls();
			}
			if (mode == PageMode.Feedback)
			{
				CancelFeedbackEdit();
				RefreshFeedbackMine();
			}
			SetStatus("", error: false);
			if (_overlay != null)
			{
				((CanvasItem)_overlay).Visible = true;
				((CanvasItem)_overlay).MoveToFront();
			}
		}

		private void InitializeCatalogControls()
		{
			SearchableOptionSelect.Item[] array = (from entry in ObjectCatalogProvider.Instance.GetCatalog().OfKind(ContentObjectKind.Character)
				select new SearchableOptionSelect.Item(entry.OptionLabel, entry.Id)).ToArray();
			_character?.SetItems(array, array.FirstOrDefault().Id);
			RefreshCollectibleFields();
		}

		private CollectibleSubmissionCategory SelectedCategory()
		{
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			if (_category == null || _category.Selected < 0)
			{
				return CollectibleSubmissionCategory.KeyCard;
			}
			Variant itemMetadata = _category.GetItemMetadata(_category.Selected);
			return (CollectibleSubmissionCategory)int.Parse(((Variant)(ref itemMetadata)).AsString());
		}

		private void RefreshCollectibleFields()
		{
			CollectibleSubmissionCategory collectibleSubmissionCategory = SelectedCategory();
			if (_usage != null)
			{
				_usage.Text = "判定用途：" + CommunitySubmissionModel.RuleUsage(collectibleSubmissionCategory);
			}
			if (_characterRow != null)
			{
				((CanvasItem)_characterRow).Visible = collectibleSubmissionCategory == CollectibleSubmissionCategory.KeyCard;
			}
			if (_itemKindRow != null)
			{
				((CanvasItem)_itemKindRow).Visible = collectibleSubmissionCategory == CollectibleSubmissionCategory.PowerfulCombo;
			}
			if (_itemKind != null && collectibleSubmissionCategory == CollectibleSubmissionCategory.PowerfulRelic)
			{
				_itemKind.Select(1);
			}
			else if (_itemKind != null && collectibleSubmissionCategory != CollectibleSubmissionCategory.PowerfulCombo)
			{
				_itemKind.Select(0);
			}
			_selectedItems.Clear();
			RenderSelectedItems();
			PopulateItems();
			if (_selectionHint != null)
			{
				_selectionHint.Text = ((collectibleSubmissionCategory == CollectibleSubmissionCategory.PowerfulCombo) ? "强力组合固定为 A→B：先加入前置 A，再加入目标 B；两端都可切换为卡牌或遗物。" : "搜索并选择对象后点击“加入”；再次选择会替换当前对象。");
			}
		}

		private string SelectedItemKind()
		{
			//IL_0034: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			switch (SelectedCategory())
			{
			case CollectibleSubmissionCategory.PowerfulRelic:
				return "relic";
			case CollectibleSubmissionCategory.PowerfulCombo:
				if (_itemKind != null)
				{
					Variant itemMetadata = _itemKind.GetItemMetadata(_itemKind.Selected);
					return ((Variant)(ref itemMetadata)).AsString();
				}
				goto default;
			default:
				return "card";
			}
		}

		private void PopulateItems()
		{
			if (_item != null)
			{
				ContentObjectKind kind = ((!(SelectedItemKind() == "relic")) ? ContentObjectKind.Card : ContentObjectKind.Relic);
				ContentObjectEntry[] source = ObjectCatalogProvider.Instance.GetCatalog().OfKind(kind).ToArray();
				_item.SetItems(source.Select((ContentObjectEntry entry) => new SearchableOptionSelect.Item(entry.OptionLabel, entry.Id)).ToArray(), source.FirstOrDefault().Id);
			}
		}

		private void AddSelectedItem()
		{
			if (_item != null && !string.IsNullOrWhiteSpace(_item.SelectedId))
			{
				string text = SelectedItemKind();
				ContentObjectKind kind = ((!(text == "relic")) ? ContentObjectKind.Card : ContentObjectKind.Relic);
				ContentObjectEntry contentObjectEntry = ObjectCatalogProvider.Instance.GetCatalog().OfKind(kind).FirstOrDefault((ContentObjectEntry entry) => entry.Id == _item.SelectedId);
				string name = (string.IsNullOrWhiteSpace(contentObjectEntry.Id) ? _item.SelectedId : contentObjectEntry.OptionLabel);
				CollectibleSubmissionItem item = new CollectibleSubmissionItem(text, _item.SelectedId, name);
				if (SelectedCategory() != CollectibleSubmissionCategory.PowerfulCombo)
				{
					_selectedItems.Clear();
				}
				if (_selectedItems.Any((CollectibleSubmissionItem existing) => existing.Kind == item.Kind && existing.Id == item.Id))
				{
					SetStatus("这个对象已经在当前选择中。", error: true);
					return;
				}
				if (_selectedItems.Count >= 2)
				{
					SetStatus("强力组合已经选满 A、B 两个对象。", error: true);
					return;
				}
				_selectedItems.Add(item);
				RenderSelectedItems();
				SetStatus("", error: false);
			}
		}

		private void RenderSelectedItems()
		{
			//IL_0070: Unknown result type (might be due to invalid IL or missing references)
			//IL_0077: Expected O, but got Unknown
			if (_selectedList == null)
			{
				return;
			}
			foreach (Node child in ((Node)_selectedList).GetChildren(false))
			{
				((Node)_selectedList).RemoveChild(child);
				child.QueueFree();
			}
			for (int i = 0; i < _selectedItems.Count; i++)
			{
				CollectibleSubmissionItem item = _selectedItems[i];
				HBoxContainer val = new HBoxContainer();
				string value = ((SelectedCategory() == CollectibleSubmissionCategory.PowerfulCombo) ? ((i == 0) ? "A（先观察）" : "B（目标）") : "已选择");
				Label val2 = LabelOf($"{value} · {((item.Kind == "card") ? "卡牌" : "遗物")} · {item.Name}", 17);
				((Control)val2).SizeFlagsHorizontal = (SizeFlags)3;
				val2.AutowrapMode = (AutowrapMode)3;
				((Node)val).AddChild((Node)(object)val2, false, (InternalMode)0);
				Button val3 = ButtonOf("移除", 76f);
				((BaseButton)val3).Pressed += delegate
				{
					_selectedItems.Remove(item);
					RenderSelectedItems();
				};
				((Node)val).AddChild((Node)(object)val3, false, (InternalMode)0);
				((Node)_selectedList).AddChild((Node)(object)val, false, (InternalMode)0);
			}
		}

		private void SubmitCurrent()
		{
			if (_busy)
			{
				return;
			}
			LineEdit? nickname = _nickname;
			string nickname2 = (((nickname != null) ? nickname.Text : null) ?? "").Trim();
			if (_mode == PageMode.Feedback)
			{
				TextEdit? feedback = _feedback;
				string text = (((feedback != null) ? feedback.Text : null) ?? "").Trim();
				if (string.IsNullOrWhiteSpace(text))
				{
					SetStatus("反馈内容不能为空。", error: true);
				}
				else if (ContentValidator.CountCharacters(text) > 1000)
				{
					SetStatus("反馈内容超过 1000 字。", error: true);
				}
				else if (_editingFeedbackId > 0)
				{
					long editingFeedbackId = _editingFeedbackId;
					BeginBusy("正在提交改动…");
					EditFeedbackAsync(editingFeedbackId, nickname2, text);
				}
				else
				{
					BeginBusy("正在提交意见反馈…");
					SubmitFeedbackAsync(nickname2, text);
				}
			}
			else
			{
				CollectibleSubmissionCategory collectibleSubmissionCategory = SelectedCategory();
				CollectibleSubmissionRequest request = new CollectibleSubmissionRequest(nickname2, collectibleSubmissionCategory, (collectibleSubmissionCategory != 0) ? "" : (_character?.SelectedId ?? ""), _selectedItems.ToArray());
				IReadOnlyList<string> readOnlyList = CommunitySubmissionModel.Validate(request);
				if (readOnlyList.Count > 0)
				{
					SetStatus("校验未通过：" + string.Join("；", readOnlyList), error: true);
					return;
				}
				BeginBusy("正在提交资料投稿…");
				SubmitCollectibleAsync(request);
			}
		}

		private async Task SubmitFeedbackAsync(string nickname, string body)
		{
			CloudApiContract.SubmitResult result = await Client.SubmitFeedbackAsync(nickname, body, _lifetime.Token).ConfigureAwait(continueOnCapturedContext: false);
			Post(delegate
			{
				FinishSubmit(result, delegate
				{
					if (_feedback != null)
					{
						_feedback.Text = "";
					}
				});
				if (result.Id > 0)
				{
					RefreshFeedbackMine();
				}
			});
		}

		private async Task EditFeedbackAsync(long id, string nickname, string body)
		{
			bool ok = await Client.EditFeedbackAsync(id, nickname, body, _lifetime.Token).ConfigureAwait(continueOnCapturedContext: false);
			Post(delegate
			{
				_busy = false;
				if (_submit != null)
				{
					((BaseButton)_submit).Disabled = false;
				}
				if (ok)
				{
					CancelFeedbackEdit();
					SetStatus("反馈已更新，等待重新审核。", error: false);
					RefreshFeedbackMine();
				}
				else
				{
					SetStatus("改动失败，请检查网络。", error: true);
				}
			});
		}

		private async void DeleteFeedbackAsync(long id)
		{
			bool ok = await Client.DeleteFeedbackAsync(id, _lifetime.Token).ConfigureAwait(continueOnCapturedContext: false);
			Post(delegate
			{
				if (ok)
				{
					SetStatus("反馈已删除。", error: false);
					RefreshFeedbackMine();
				}
				else
				{
					SetStatus("删除失败，请检查网络。", error: true);
				}
			});
		}

		private void StartFeedbackEdit(CloudApiContract.FeedbackRecord record)
		{
			_editingFeedbackId = record.Id;
			if (_nickname != null)
			{
				_nickname.Text = record.Nickname;
			}
			if (_feedback != null)
			{
				_feedback.Text = record.Text;
			}
			if (_submit != null)
			{
				_submit.Text = "确认改动并提交";
			}
			SetStatus($"正在改动反馈 #{record.Id}，修改后提交。", error: false);
		}

		private void CancelFeedbackEdit()
		{
			_editingFeedbackId = 0L;
			if (_submit != null)
			{
				_submit.Text = "提交意见反馈";
			}
		}

		private void OnCopyDiagnosticsPressed()
		{
			bool flag = DanmakuDiagnostics.TryCopyToClipboard(DanmakuDiagnostics.CaptureSnapshot());
			SetStatus(flag ? "诊断信息已复制，请粘贴到反馈中。" : "复制失败，请手动查看日志目录。", !flag);
		}

		private void RefreshFeedbackMine()
		{
			if (!_feedbackRefreshing && !_lifetime.IsCancellationRequested)
			{
				_feedbackRefreshing = true;
				RefreshFeedbackMineAsync(_lifetime.Token);
			}
		}

		private async Task RefreshFeedbackMineAsync(CancellationToken token)
		{
			CloudApiContract.FeedbackMineResponse response = await Client.FetchFeedbackMineAsync(token).ConfigureAwait(continueOnCapturedContext: false);
			Post(delegate
			{
				_feedbackRefreshing = false;
				if (response == null)
				{
					SetStatus("无法连接服务器，请检查网络。", error: true);
				}
				else
				{
					RenderFeedbackMine(response.Submissions);
				}
			});
		}

