		private async void SendFeedbackReply(long id, LineEdit input)
		{
			string text = (((input != null) ? input.Text : null) ?? "").Trim();
			if (string.IsNullOrWhiteSpace(text))
			{
				SetStatus("回复内容不能为空。", error: true);
				return;
			}
			bool ok = await Client.ReplyFeedbackAsync(id, text, _lifetime.Token).ConfigureAwait(continueOnCapturedContext: false);
			Post(delegate
			{
				if (ok)
				{
					SetStatus("回复已提交。", error: false);
					RefreshFeedbackMine();
				}
				else
				{
					SetStatus("回复失败，请检查网络。", error: true);
				}
			});
		}

		private async Task SubmitCollectibleAsync(CollectibleSubmissionRequest request)
		{
			CloudApiContract.SubmitResult result = await Client.SubmitCollectibleAsync(request, _lifetime.Token).ConfigureAwait(continueOnCapturedContext: false);
			Post(delegate
			{
				FinishSubmit(result, delegate
				{
					_selectedItems.Clear();
					RenderSelectedItems();
				});
			});
		}

		private void FinishSubmit(CloudApiContract.SubmitResult result, Action clear)
		{
			_busy = false;
			if (_submit != null)
			{
				((BaseButton)_submit).Disabled = false;
			}
			if (result.Id > 0)
			{
				clear();
				SetStatus("提交成功，等待作者人工审核。", error: false);
				return;
			}
			SetStatus(result.Error switch
			{
				"cooldown" => result.Message ?? "提交太频繁，请 60 秒后再试。", 
				"rate_limited" => result.Message ?? "本小时提交已达上限。", 
				"network" => "无法连接服务器，请检查网络。", 
				_ => result.Message ?? "提交失败，请稍后重试。", 
			}, error: true);
		}

		private void BeginBusy(string message)
		{
			_busy = true;
			if (_submit != null)
			{
				((BaseButton)_submit).Disabled = true;
			}
			SetStatus(message, error: false);
		}

		private void Post(Action action)
		{
			if (!_lifetime.IsCancellationRequested)
			{
				_mainThread.Enqueue(action);
			}
		}

		private void PrefillNickname()
		{
			if (_nickname != null && string.IsNullOrWhiteSpace(_nickname.Text))
			{
				string text = DanmakuMultiplayerState.ResolveLocalPlayerDisplayName();
				_nickname.Text = ContentValidator.TruncateCharacters(text ?? "", 16);
			}
		}

