	public static class DanmakuFrontendUiGate
	{
		private const string MainMenuTypeName = "MegaCrit.Sts2.Core.Nodes.Screens.MainMenu.NMainMenu";

		public static bool IsAvailable { get; private set; }

		public static void Activate()
		{
			if (!IsAvailable)
			{
				IsAvailable = true;
				DanmakuChatComposer.SetFrontendAvailable(available: true);
				DanmakuPauseButton.SetFrontendAvailable(available: true);
				MainFile.Log("[FrontendUI] 主菜单已就绪，聊天弹幕入口与暂停按钮开始显示。");
			}
		}

		public static void ActivateIfMainMenuPresent()
		{
			if (IsAvailable)
			{
				return;
			}
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			if (val == null || val.Root == null)
			{
				return;
			}
			Stack<Node> stack = new Stack<Node>();
			stack.Push((Node)(object)val.Root);
			while (stack.Count > 0)
			{
				Node val2 = stack.Pop();
				if (string.Equals(((object)val2).GetType().FullName, "MegaCrit.Sts2.Core.Nodes.Screens.MainMenu.NMainMenu", StringComparison.Ordinal))
				{
					Activate();
					break;
				}
				foreach (Node child in val2.GetChildren(false))
				{
					stack.Push(child);
				}
			}
		}

		public static void Reset()
		{
			IsAvailable = false;
			DanmakuChatComposer.SetFrontendAvailable(available: false);
			DanmakuPauseButton.SetFrontendAvailable(available: false);
		}
	}
