			if (!(type == null))
			{
				return AccessTools.DeclaredMethod(type, "_Ready", (Type[])null, (Type[])null);
			}
			return null;
		}

		public static void Postfix()
		{
			DanmakuFrontendUiGate.Activate();
		}
	}
