		public static bool IsRuleEnabled(string ruleId)
		{
			if (!string.IsNullOrWhiteSpace(ruleId))
			{
				return !DisabledRuleIdsInternal.Contains(ruleId.Trim());
			}
			return false;
		}

		public static void SetRuleEnabled(string ruleId, bool enabled)
		{
			string text = ruleId?.Trim().ToUpperInvariant() ?? "";
			if (!RuleDisplayCatalog.Contains(text))
			{
				return;
			}
			lock (Sync)
			{
				if (enabled ? DisabledRuleIdsInternal.Remove(text) : DisabledRuleIdsInternal.Add(text))
				{
					DanmakuModConfig.Changed?.Invoke();
					SaveDebounced();
				}
			}
		}

		public static void SetAllRulesEnabled(bool enabled)
		{
			lock (Sync)
			{
				bool flag = false;
				foreach (RuleDisplayEntry item in RuleDisplayCatalog.All)
				{
					flag = ((!enabled) ? (flag | DisabledRuleIdsInternal.Add(item.Id)) : (flag | DisabledRuleIdsInternal.Remove(item.Id)));
				}
				if (flag)
				{
					DanmakuModConfig.Changed?.Invoke();
					SaveDebounced();
				}
			}
		}

		public static DanmakuConfigLoadResult Initialize()
		{
			return InitializeCore(Path.Combine(OS.GetUserDataDir(), "DanmakuSpire", "settings.json"), Path.Combine(OS.GetUserDataDir(), "mod_configs", "DanmakuSpire.cfg"), MainFile.Log);
		}

		public static DanmakuConfigLoadResult Initialize(string configPath, string? legacyConfigPath)
		{
			return InitializeCore(configPath, legacyConfigPath, null);
		}

		private static DanmakuConfigLoadResult InitializeCore(string configPath, string? legacyConfigPath, Action<string>? logger)
		{
			if (string.IsNullOrWhiteSpace(configPath))
			{
				throw new ArgumentException("配置路径不能为空", "configPath");
			}
			lock (Sync)
			{
				_saveDebounce?.Cancel();
				_saveDebounce?.Dispose();
				_saveDebounce = null;
				_configPath = Path.GetFullPath(configPath);
				_legacyConfigPath = (string.IsNullOrWhiteSpace(legacyConfigPath) ? "" : Path.GetFullPath(legacyConfigPath));
				_logger = logger;
				_loadedSchemaVersion = 1;
				ResetDefaultsCore();
				DanmakuConfigLoadResult danmakuConfigLoadResult;
				if (File.Exists(_configPath))
				{
					danmakuConfigLoadResult = LoadCurrentConfigCore(_configPath);
				}
				else if (!string.IsNullOrWhiteSpace(_legacyConfigPath) && File.Exists(_legacyConfigPath))
				{
					danmakuConfigLoadResult = MigrateLegacyConfigCore(_legacyConfigPath, _configPath);
				}
				else
				{
					NormalizeCore();
					WriteCurrentConfigCore(_configPath);
					danmakuConfigLoadResult = new DanmakuConfigLoadResult(Loaded: true, MigratedLegacyConfig: false, UsedDefaults: true, _configPath, "未发现旧配置，已创建默认配置");
				}
				_initialized = true;
				Log("[Config] " + danmakuConfigLoadResult.Message + "：" + _configPath);
				return danmakuConfigLoadResult;
			}
		}

		public static bool SaveNow()
		{
			lock (Sync)
			{
				if (!_initialized || string.IsNullOrWhiteSpace(_configPath))
				{
					return false;
				}
				if (IsReadOnlyForFutureSchema)
				{
					Log($"[Config] 当前文件结构版本 {_loadedSchemaVersion} 高于本模组支持的 {1}，" + "本次运行只读使用可识别设置，已跳过保存以保留未知字段。");
					return false;
				}
				try
				{
					NormalizeCore();
					WriteCurrentConfigCore(_configPath);
					return true;
				}
				catch (Exception value)
				{
					Log($"[Config] 保存失败，继续使用内存中的设置：{value}");
					return false;
				}
			}
		}

		public static void SaveDebounced(int delayMilliseconds = 500)
		{
			CancellationToken token;
			lock (Sync)
			{
				if (!_initialized)
				{
					return;
				}
				_saveDebounce?.Cancel();
				_saveDebounce?.Dispose();
				_saveDebounce = new CancellationTokenSource();
				token = _saveDebounce.Token;
			}
			Task.Run(async delegate
			{
				try
				{
					await Task.Delay(Math.Max(0, delayMilliseconds), token).ConfigureAwait(continueOnCapturedContext: false);
					if (!token.IsCancellationRequested)
					{
						SaveNow();
					}
				}
				catch (OperationCanceledException)
				{
				}
			}, CancellationToken.None);
		}

		public static void Shutdown()
		{
			lock (Sync)
			{
				_saveDebounce?.Cancel();
				_saveDebounce?.Dispose();
				_saveDebounce = null;
			}
			SaveNow();
			lock (Sync)
			{
				_initialized = false;
				_configPath = "";
				_legacyConfigPath = "";
				_logger = null;
			}
		}

		public static void RestoreDefaults()
		{
			lock (Sync)
			{
				ResetDefaultsCore();
				NormalizeCore();
			}
			DanmakuModConfig.Changed?.Invoke();
			SaveNow();
		}

		public static object GetSettingValue(string key)
		{
			return key switch
			{
				"danmaku_mode" => ToToken(弹幕开关), 
				"font_size" => 文字字号, 
				"opacity_percent" => 弹幕不透明度, 
				"background_style" => ToToken(背景样式), 
				"speed" => ToToken(弹幕速度), 
				"top_danmaku" => ToToken(顶部弹幕), 
				"lane_count" => 轨道数, 
				"danmaku_density" => ToToken(弹幕密度), 
				"forward_multiplayer" => 转发多人模式弹幕, 
				"receive_multiplayer" => 接收多人模式弹幕, 
				"receive_multiplayer_chat" => 接收多人聊天弹幕, 
				"ugc_enabled" => 启用共创弹幕, 
				_ => throw new KeyNotFoundException("未知弹幕设置键：" + key), 
			};
		}

		public static bool TrySetSettingValue(string key, object value)
		{
			bool flag;
			lock (Sync)
			{
				object settingValue = GetSettingValue(key);
				switch (key)
				{
				case "danmaku_mode":
					弹幕开关 = ParseDanmakuMode(Convert.ToString(value, CultureInfo.InvariantCulture));
					break;
				case "font_size":
					文字字号 = Convert.ToDouble(value, CultureInfo.InvariantCulture);
					break;
				case "opacity_percent":
					弹幕不透明度 = Convert.ToDouble(value, CultureInfo.InvariantCulture);
					break;
				case "background_style":
					背景样式 = ParseBackground(Convert.ToString(value, CultureInfo.InvariantCulture));
					break;
				case "speed":
					弹幕速度 = ParseSpeed(Convert.ToString(value, CultureInfo.InvariantCulture));
					break;
				case "top_danmaku":
					顶部弹幕 = ParseTopDanmaku(Convert.ToString(value, CultureInfo.InvariantCulture));
					break;
				case "lane_count":
					轨道数 = Convert.ToInt32(value, CultureInfo.InvariantCulture);
					break;
				case "danmaku_density":
					弹幕密度 = ParseDensity(Convert.ToString(value, CultureInfo.InvariantCulture));
					break;
				case "forward_multiplayer":
					转发多人模式弹幕 = Convert.ToBoolean(value, CultureInfo.InvariantCulture);
					break;
				case "receive_multiplayer":
					接收多人模式弹幕 = Convert.ToBoolean(value, CultureInfo.InvariantCulture);
					break;
				case "receive_multiplayer_chat":
					接收多人聊天弹幕 = Convert.ToBoolean(value, CultureInfo.InvariantCulture);
					break;
				case "ugc_enabled":
					启用共创弹幕 = Convert.ToBoolean(value, CultureInfo.InvariantCulture);
					break;
				default:
					return false;
				}
				NormalizeCore();
				flag = !object.Equals(settingValue, GetSettingValue(key));
			}
			if (flag)
			{
				DanmakuModConfig.Changed?.Invoke();
				SaveDebounced();
			}
			return true;
		}

		public static int ResolveLaneLimit()
		{
