		}

		private static DanmakuConfigLoadResult LoadCurrentConfigCore(string path)
		{
			try
			{
				DanmakuSettingsDocument danmakuSettingsDocument = JsonSerializer.Deserialize<DanmakuSettingsDocument>(File.ReadAllText(path, Encoding.UTF8), JsonOptions) ?? throw new JsonException("配置内容为空");
				_loadedSchemaVersion = danmakuSettingsDocument.SchemaVersion;
				ApplyDocumentCore(danmakuSettingsDocument);
				NormalizeCore();
				if (danmakuSettingsDocument.SchemaVersion < 1)
				{
					WriteCurrentConfigCore(path);
				}
				return new DanmakuConfigLoadResult(Loaded: true, MigratedLegacyConfig: false, UsedDefaults: false, path, (danmakuSettingsDocument.SchemaVersion > 1) ? $"已只读加载较新结构版本 {danmakuSettingsDocument.SchemaVersion} 中可识别的设置；不会覆盖原文件" : "已读取自有配置");
			}
			catch (Exception ex)
			{
				_loadedSchemaVersion = 1;
				string text = BackupBrokenConfig(path);
				ResetDefaultsCore();
				NormalizeCore();
				WriteCurrentConfigCore(path);
				return new DanmakuConfigLoadResult(Loaded: true, MigratedLegacyConfig: false, UsedDefaults: true, path, "配置损坏，已恢复默认值；备份 " + text + "；原因 " + ex.Message);
			}
		}

		private static DanmakuConfigLoadResult MigrateLegacyConfigCore(string legacyPath, string targetPath)
		{
			try
			{
				Dictionary<string, string>? legacy = JsonSerializer.Deserialize<Dictionary<string, string>>(File.ReadAllText(legacyPath, Encoding.UTF8), JsonOptions) ?? throw new JsonException("旧配置内容为空");
				ApplyLegacyValue(legacy, "弹幕开关", delegate(string value)
				{
					弹幕开关 = ParseDanmakuMode(value);
				});
				ApplyLegacyValue(legacy, "文字字号", delegate(string value)
				{
					文字字号 = ParseDouble(value, 文字字号);
				});
				ApplyLegacyValue(legacy, "弹幕不透明度", delegate(string value)
				{
					弹幕不透明度 = ParseDouble(value, 弹幕不透明度);
				});
				ApplyLegacyValue(legacy, "背景样式", delegate(string value)
				{
					背景样式 = ParseBackground(value);
				});
				ApplyLegacyValue(legacy, "弹幕速度", delegate(string value)
				{
					弹幕速度 = ParseSpeed(value);
				});
				ApplyLegacyValue(legacy, "顶部弹幕", delegate(string value)
				{
					顶部弹幕 = ParseTopDanmaku(value);
				});
				ApplyLegacyValue(legacy, "显示区域", delegate(string value)
				{
					轨道数 = Math.Clamp((int)Math.Round(ParseDouble(value, 62.5) / 100.0 * 16.0), 4, 16);
				});
				ApplyLegacyValue(legacy, "词条密度", delegate(string value)
				{
					弹幕密度 = ParseLegacyDensity(value);
				});
				ApplyLegacyValue(legacy, "转发多人模式弹幕", delegate(string value)
				{
					转发多人模式弹幕 = ParseBool(value, fallback: true);
				});
				ApplyLegacyValue(legacy, "接收多人模式弹幕", delegate(string value)
				{
					接收多人模式弹幕 = ParseBool(value, fallback: true);
				});
				NormalizeCore();
				WriteCurrentConfigCore(targetPath);
				return new DanmakuConfigLoadResult(Loaded: true, MigratedLegacyConfig: true, UsedDefaults: false, targetPath, "已从旧 BaseLib 配置迁移，旧文件保留在 " + legacyPath);
			}
			catch (Exception ex)
			{
				ResetDefaultsCore();
				NormalizeCore();
				WriteCurrentConfigCore(targetPath);
				return new DanmakuConfigLoadResult(Loaded: true, MigratedLegacyConfig: false, UsedDefaults: true, targetPath, "旧配置迁移失败，已使用默认值且未修改旧文件；原因 " + ex.Message);
			}
		}

		private static void ApplyLegacyValue(IReadOnlyDictionary<string, string> legacy, string key, Action<string> apply)
		{
			if (legacy.TryGetValue(key, out string value) && !string.IsNullOrWhiteSpace(value))
			{
				apply(value);
			}
		}

		private static void ApplyDocumentCore(DanmakuSettingsDocument document)
		{
			弹幕开关 = ParseDanmakuMode(document.DanmakuMode);
			文字字号 = document.FontSize;
			弹幕不透明度 = document.OpacityPercent;
			背景样式 = ParseBackground(document.BackgroundStyle);
			弹幕速度 = ParseSpeed(document.Speed);
			顶部弹幕 = ParseTopDanmaku(document.TopDanmaku);
			if (document.LaneCount > 0)
			{
				轨道数 = document.LaneCount;
			}
			else if (document.DisplayAreaPercent >= 0.0)
			{
				轨道数 = Math.Clamp((int)Math.Round(document.DisplayAreaPercent / 100.0 * 16.0), 4, 16);
			}
			弹幕密度 = ParseDensity(document.DanmakuDensity);
			转发多人模式弹幕 = document.ForwardMultiplayer;
			接收多人模式弹幕 = document.ReceiveMultiplayer;
			接收多人聊天弹幕 = document.ReceiveMultiplayerChat;
			启用共创弹幕 = document.UgcEnabled;
			DisabledRuleIdsInternal.Clear();
			if (document.DisabledRuleIds == null)
			{
				return;
			}
			foreach (string disabledRuleId in document.DisabledRuleIds)
			{
				string text = disabledRuleId?.Trim().ToUpperInvariant() ?? "";
				if (RuleDisplayCatalog.Contains(text))
				{
					DisabledRuleIdsInternal.Add(text);
				}
			}
		}

		private static void WriteCurrentConfigCore(string path)
		{
			string directoryName = Path.GetDirectoryName(path);
			if (!string.IsNullOrWhiteSpace(directoryName))
			{
				Directory.CreateDirectory(directoryName);
			}
			string text = path + ".new";
			try
			{
				string contents = JsonSerializer.Serialize(CaptureDocumentCore(), JsonOptions);
				File.WriteAllText(text, contents, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				File.Move(text, path, overwrite: true);
			}
			finally
			{
				try
				{
					if (File.Exists(text))
					{
						File.Delete(text);
					}
				}
				catch
				{
				}
			}
		}

		private static DanmakuSettingsDocument CaptureDocumentCore()
		{
			return new DanmakuSettingsDocument
			{
				SchemaVersion = 1,
				DanmakuMode = ToToken(弹幕开关),
				FontSize = 文字字号,
				OpacityPercent = 弹幕不透明度,
				BackgroundStyle = ToToken(背景样式),
				Speed = ToToken(弹幕速度),
				TopDanmaku = ToToken(顶部弹幕),
				LaneCount = 轨道数,
				DanmakuDensity = ToToken(弹幕密度),
				ForwardMultiplayer = 转发多人模式弹幕,
				ReceiveMultiplayer = 接收多人模式弹幕,
				ReceiveMultiplayerChat = 接收多人聊天弹幕,
				UgcEnabled = 启用共创弹幕,
				DisabledRuleIds = DisabledRuleIdsInternal.OrderBy<string, string>((string id) => id, StringComparer.OrdinalIgnoreCase).ToList()
			};
		}

		private static string BackupBrokenConfig(string path)
		{
			string text = path + $".broken-{DateTimeOffset.UtcNow:yyyyMMddHHmmss}";
			try
			{
				File.Move(path, text, overwrite: true);
				return text;
			}
			catch
			{
				return "备份失败，原文件仍保留";
			}
		}

		private static void ResetDefaultsCore()
		{
			弹幕开关 = 弹幕开关档位.所有;
			文字字号 = 24.0;
			弹幕不透明度 = 100.0;
			背景样式 = 背景样式档位.烟雾;
			弹幕速度 = 弹幕速度档位.中等;
			顶部弹幕 = 顶部弹幕档位.标准;
			轨道数 = 10;
			弹幕密度 = 弹幕密度档位.标准;
			转发多人模式弹幕 = true;
			接收多人模式弹幕 = true;
			接收多人聊天弹幕 = true;
			启用共创弹幕 = true;
			DisabledRuleIdsInternal.Clear();
		}

		private static void NormalizeCore()
		{
			文字字号 = Snap(文字字号, 16.0, 40.0, 1.0);
			弹幕不透明度 = Snap(弹幕不透明度, 30.0, 100.0, 5.0);
			轨道数 = Math.Clamp(轨道数, 4, 16);
			if (!Enum.IsDefined(弹幕密度))
			{
				弹幕密度 = 弹幕密度档位.标准;
			}
			if (!Enum.IsDefined(弹幕开关))
			{
				弹幕开关 = 弹幕开关档位.所有;
			}
			if (!Enum.IsDefined(背景样式))
			{
				背景样式 = 背景样式档位.烟雾;
			}
			if (!Enum.IsDefined(弹幕速度))
			{
				弹幕速度 = 弹幕速度档位.中等;
			}
			if (!Enum.IsDefined(顶部弹幕))
			{
				顶部弹幕 = 顶部弹幕档位.标准;
			}
			DisabledRuleIdsInternal.RemoveWhere((string id) => !RuleDisplayCatalog.Contains(id));
		}

		private static double Snap(double value, double minimum, double maximum, double step)
		{
			if (double.IsNaN(value) || double.IsInfinity(value))
			{
				value = minimum;
			}
			return Math.Round((Math.Clamp(value, minimum, maximum) - minimum) / step, MidpointRounding.AwayFromZero) * step + minimum;
		}

		private static double ParseDouble(string value, double fallback)
		{
			if (!double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out var result))
			{
				return fallback;
			}
			return result;
		}

		private static bool ParseBool(string value, bool fallback)
		{
			if (!bool.TryParse(value, out var result))
			{
				return fallback;
			}
			return result;
		}

		private static 弹幕开关档位 ParseDanmakuMode(string? value)
		{
			switch (value?.Trim().ToLowerInvariant())
			{
			case "off":
			case "关闭":
				return 弹幕开关档位.关闭;
			case "仅单人弹幕":
			case "single":
				return 弹幕开关档位.仅单人弹幕;
			case "仅多人弹幕":
			case "multiplayer":
				return 弹幕开关档位.仅多人弹幕;
			case "all":
			case "所有":
				return 弹幕开关档位.所有;
			default:
				return 弹幕开关档位.所有;
			}
		}

		private static 背景样式档位 ParseBackground(string? value)
		{
			string text = value?.Trim().ToLowerInvariant();
			if (text == "transparent" || text == "透明")
			{
				return 背景样式档位.透明;
			}
			return 背景样式档位.烟雾;
		}

		private static 弹幕速度档位 ParseSpeed(string? value)
		{
			switch (value?.Trim().ToLowerInvariant())
			{
			case "slow":
			case "慢":
				return 弹幕速度档位.慢;
			case "slower":
			case "较慢":
				return 弹幕速度档位.较慢;
			case "faster":
			case "较快":
				return 弹幕速度档位.较快;
			case "fast":
			case "快":
				return 弹幕速度档位.快;
			default:
				return 弹幕速度档位.中等;
			}
		}

		private static 顶部弹幕档位 ParseTopDanmaku(string? value)
		{
			switch (value?.Trim().ToLowerInvariant())
			{
			case "none":
			case "无":
				return 顶部弹幕档位.无;
			case "all":
			case "全部":
				return 顶部弹幕档位.全部;
			default:
				return 顶部弹幕档位.标准;
			}
		}

		private static string ToToken(弹幕开关档位 value)
		{
			return value switch
			{
				弹幕开关档位.关闭 => "off", 
				弹幕开关档位.仅单人弹幕 => "single", 
				弹幕开关档位.仅多人弹幕 => "multiplayer", 
				_ => "all", 
			};
		}

		private static string ToToken(背景样式档位 value)
		{
			if (value != 背景样式档位.透明)
			{
				return "smoke";
			}
			return "transparent";
		}

		private static string ToToken(弹幕速度档位 value)
		{
			return value switch
			{
				弹幕速度档位.慢 => "slow", 
				弹幕速度档位.较慢 => "slower", 
				弹幕速度档位.较快 => "faster", 
				弹幕速度档位.快 => "fast", 
				_ => "medium", 
			};
		}

		private static string ToToken(顶部弹幕档位 value)
		{
			return value switch
			{
				顶部弹幕档位.无 => "none", 
				顶部弹幕档位.全部 => "all", 
				_ => "standard", 
			};
		}

		private static string ToToken(弹幕密度档位 value)
		{
			return value switch
			{
				弹幕密度档位.稀疏 => "sparse", 
				弹幕密度档位.密集 => "dense", 
				_ => "standard", 
			};
		}

		private static 弹幕密度档位 ParseDensity(string? value)
		{
			switch (value?.Trim().ToLowerInvariant())
			{
			case "sparse":
			case "稀疏":
				return 弹幕密度档位.稀疏;
			case "dense":
			case "密集":
				return 弹幕密度档位.密集;
			default:
				return 弹幕密度档位.标准;
			}
		}

		private static 弹幕密度档位 ParseLegacyDensity(string value)
		{
			double num = ParseDouble(value, 100.0);
			if (!(num < 75.0))
			{
				if (!(num > 150.0))
				{
					return 弹幕密度档位.标准;
				}
				return 弹幕密度档位.密集;
			}
			return 弹幕密度档位.稀疏;
		}

		private static void Log(string message)
		{
			try
			{
				_logger?.Invoke(message);
			}
			catch
			{
			}
		}
	}
