		private static string RuleGroupName(string group)
		{
			return group.ToUpperInvariant() switch
			{
				"A" => "战斗与敌怪", 
				"B" => "手牌与回合", 
				"C" => "伤害与格挡", 
				"D" => "特殊敌怪", 
				"E" => "奖励选牌", 
				"F" => "商店", 
				"G" => "事件与火堆", 
				"H" => "Run 生命周期", 
				"I" => "多人专用", 
				_ => "其他", 
			};
		}

