		}

		public static string? ResolveCjkFallbackFontPath(string? locale, bool bold)
		{
			string text = (locale ?? "").Trim().Replace('_', '-').ToLowerInvariant();
			bool flag = text.StartsWith("zh", StringComparison.Ordinal);
			if (!flag)
			{
				bool flag2 = ((text == "zhs" || text == "zht") ? true : false);
				flag = flag2;
			}
			if (!flag)
			{
				return null;
			}
			if (!bold)
			{
				return "res://themes/fonts/zhs/noto_sans_mono_cjksc_regular_shared.tres";
			}
			return "res://themes/fonts/zhs/source_han_serif_sc_bold_shared.tres";
		}

