		}

		private static SubmissionClient EnsureClient()
		{
			if (_client == null)
			{
				_http = new HttpClient
				{
					Timeout = TimeSpan.FromSeconds(8L)
				};
				_client = new SubmissionClient(_http, "https://danmaku.danmakuspire.top");
			}
			return _client;
		}

		private static string LoadOrCreateDeviceSeed(string path)
		{
			if (File.Exists(path))
			{
				string text = File.ReadAllText(path, Encoding.UTF8).Trim();
				if (!string.IsNullOrWhiteSpace(text))
				{
					return text;
				}
			}
			string text2 = "device-" + Guid.NewGuid().ToString("N");
			string directoryName = Path.GetDirectoryName(path);
			if (!string.IsNullOrWhiteSpace(directoryName))
			{
				Directory.CreateDirectory(directoryName);
			}
			string text3 = path + ".new";
			File.WriteAllText(text3, text2, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
			File.Move(text3, path, overwrite: true);
			return text2;
		}

		private static void LoadPersistence()
		{
			try
			{
				string persistencePath = PersistencePath;
				if (File.Exists(persistencePath))
				{
					IReadOnlyList<SubmissionRecord> readOnlyList = SubmissionPersistence.Deserialize(File.ReadAllText(persistencePath, Encoding.UTF8));
					if (readOnlyList != null)
					{
						Store.Restore(readOnlyList);
					}
				}
			}
			catch (Exception ex)
			{
				MainFile.Log("[SubmissionUI] 投稿记录加载失败，忽略：" + ex.Message);
			}
		}

		private static void SavePersistence()
		{
			try
			{
				string persistencePath = PersistencePath;
				string directoryName = Path.GetDirectoryName(persistencePath);
				if (!string.IsNullOrWhiteSpace(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				string contents = SubmissionPersistence.Serialize(Store.AllRecords);
				string text = persistencePath + ".new";
				File.WriteAllText(text, contents, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				File.Move(text, persistencePath, overwrite: true);
			}
			catch (Exception ex)
			{
				MainFile.Log("[SubmissionUI] 投稿记录保存失败，忽略：" + ex.Message);
			}
		}

		public override void _Ready()
		{
			_font = TryLoadFont("res://themes/fonts/zhs/noto_sans_mono_cjksc_regular_shared.tres");
			_boldFont = TryLoadFont("res://themes/fonts/zhs/source_han_serif_sc_bold_shared.tres") ?? _font;
			DanmakuEmojiFont.AttachFallback(_font);
			BuildInterface();
		}

		public override void _ExitTree()
		{
			_networkLifetime.Cancel();
			Viewport viewport = ((Node)this).GetViewport();
			if (viewport != null)
			{
				viewport.SizeChanged -= RefreshViewportLayout;
			}
			if (_instance == this)
			{
				_instance = null;
			}
		}

		public override void _Process(double delta)
		{
			Action result;
			while (_mainThreadActions.TryDequeue(out result))
			{
				try
				{
					result();
				}
				catch (Exception value)
				{
					MainFile.Log($"[SubmissionUI] 主线程回调失败：{value}");
				}
			}
			if (_noticeUnlockRemaining > 0.0)
			{
				_noticeUnlockRemaining = Math.Max(0.0, _noticeUnlockRemaining - delta);
				UpdateNoticeConfirmState();
			}
		}

		public override void _UnhandledInput(InputEvent @event)
		{
			if (IsOpen && @event.IsActionPressed(StringName.op_Implicit("ui_cancel"), false, false))
			{
				ClosePanel();
				((Node)this).GetViewport().SetInputAsHandled();
			}
		}

