		private void ToggleSceneSelection(string sceneId)
		{
			if (_selectedSceneId == sceneId)
			{
				ClearSceneSelection();
			}
			else
			{
				SceneCapture sceneCapture = SceneCaptureService.Store?.Find(sceneId);
				if (sceneCapture == null)
				{
					return;
				}
				_selectedSceneId = sceneId;
				ApplySceneToForm(sceneCapture);
			}
			RefreshInspirationList();
			UpdateSummary();
		}

		private void ClearSceneSelection()
		{
			_selectedSceneId = "";
			_activeSceneCandidates = null;
			RestoreDefaultObjectCandidates();
			RefreshPreconditionRows();
		}

		private void RemoveScene(string sceneId)
		{
			SceneCaptureService.Store?.Remove(sceneId);
			if (_selectedSceneId == sceneId)
			{
				ClearSceneSelection();
			}
			RefreshInspirationList();
		}

		private void ApplySceneToForm(SceneCapture scene)
		{
			SceneTriggerCandidate sceneTriggerCandidate = scene.TriggerCandidates.FirstOrDefault();
			if (sceneTriggerCandidate != null)
			{
				_selectedKind = sceneTriggerCandidate.Kind;
				_selectedInstant = sceneTriggerCandidate.Timing;
				SyncKindSelect();
				RefreshTriggerInstants();
				PopulateObjectSelect(sceneTriggerCandidate.Id);
				RefreshEventOptionRow();
			}
			Dictionary<ContentObjectKind, IReadOnlyList<string>> dictionary = new Dictionary<ContentObjectKind, IReadOnlyList<string>>();
			if (scene.CharacterIds.Count > 0)
			{
				dictionary[ContentObjectKind.Character] = scene.CharacterIds;
			}
			if (scene.CardIds.Count > 0)
			{
				dictionary[ContentObjectKind.Card] = scene.CardIds;
			}
			if (scene.RelicIds.Count > 0)
			{
				dictionary[ContentObjectKind.Relic] = scene.RelicIds;
			}
			if (scene.MonsterIds.Count > 0)
			{
				dictionary[ContentObjectKind.Monster] = scene.MonsterIds;
			}
			if (scene.EventIds.Count > 0)
			{
				dictionary[ContentObjectKind.Event] = scene.EventIds;
			}
			if (scene.ActIndex >= 0)
			{
				dictionary[ContentObjectKind.Act] = new string[1] { (scene.ActIndex + 1).ToString(CultureInfo.InvariantCulture) };
			}
			if (scene.PlayerTurn > 0)
			{
				dictionary[ContentObjectKind.Turn] = new string[1] { scene.PlayerTurn.ToString(CultureInfo.InvariantCulture) };
			}
			_activeSceneCandidates = dictionary;
			RefreshPreconditionRows();
		}

