		private string ResolveObjectName(ContentObjectKind kind, string id)
		{
			string id2 = id;
			if (id2 == "*")
			{
				return "任意";
			}
			switch (kind)
			{
			case ContentObjectKind.Act:
				return "第 " + id2 + " 幕";
			case ContentObjectKind.Turn:
				return "第 " + id2 + " 回合";
			default:
				try
				{
					ContentObjectCatalog contentObjectCatalog = LoadCatalog();
					ContentObjectEntry? contentObjectEntry = contentObjectCatalog.OfKind(kind).FirstOrDefault((ContentObjectEntry item) => item.Id == id2);
					return string.IsNullOrWhiteSpace(contentObjectEntry?.DisplayName) ? id2 : contentObjectEntry.Value.DisplayName;
				}
				catch
				{
					return id2;
				}
			}
		}

