		private static bool HasAcceptedNotice()
		{
			try
			{
				return File.Exists(NoticeAcceptancePath) && File.ReadAllText(NoticeAcceptancePath, Encoding.UTF8).Trim() == "accepted";
			}
			catch
			{
				return false;
			}
		}

		private static void SaveNoticeAcceptance()
		{
			try
			{
				string noticeAcceptancePath = NoticeAcceptancePath;
				string directoryName = Path.GetDirectoryName(noticeAcceptancePath);
				if (!string.IsNullOrWhiteSpace(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				string text = noticeAcceptancePath + ".new";
				File.WriteAllText(text, "accepted", new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				File.Move(text, noticeAcceptancePath, overwrite: true);
			}
			catch (Exception ex)
			{
				MainFile.Log("[SubmissionUI] 投稿须知确认状态保存失败：" + ex.Message);
			}
		}

