		private void RefreshMineRecords()
		{
			if (!_recordsRefreshing && !_networkLifetime.IsCancellationRequested)
			{
				_recordsRefreshing = true;
				int count = Store.Records.Count;
				RefreshMineRecordsAsync(count, _networkLifetime.Token);
			}
		}

		private async Task RefreshMineRecordsAsync(int before, CancellationToken token)
		{
			IReadOnlyList<SubmissionRecord> records = await EnsureClient().FetchMineAsync(token).ConfigureAwait(continueOnCapturedContext: false);
			PostToMainThread(delegate
			{
				_recordsRefreshing = false;
				if (records == null)
				{
					SetStatus("无法连接服务器，请检查网络。", error: true);
				}
				else
				{
					Store.SyncFromServer(records);
					SavePersistence();
					RenderMineRecords();
					int num = Store.Records.Count - before;
					if (num > 0)
					{
						SetStatus($"刷新成功，已获取 {num} 条新投稿。", error: false);
					}
					else
					{
						Label? statusLabel = _statusLabel;
						if (((statusLabel != null) ? statusLabel.Text : null) == "正在刷新投稿记录…")
						{
							SetStatus("", error: false);
						}
					}
				}
			});
		}

