		private void PopulateObjectSelect(string? selectedId = null)
		{
			if (_objectSelect == null)
			{
				return;
			}
			ContentObjectKind selectedKind = _selectedKind;
			string current = selectedId ?? _objectSelect.SelectedId;
			List<SearchableOptionSelect.Item> list = new List<SearchableOptionSelect.Item>
			{
				new SearchableOptionSelect.Item("任意" + SubmissionUiModel.KindLabel(selectedKind), "*")
			};
			if (selectedKind == ContentObjectKind.Act || selectedKind == ContentObjectKind.Turn)
			{
				int num = ((selectedKind == ContentObjectKind.Act) ? 3 : 99);
				for (int i = 1; i <= num; i++)
				{
					string label = ((selectedKind == ContentObjectKind.Act) ? $"第 {i} 幕" : $"第 {i} 回合");
					list.Add(new SearchableOptionSelect.Item(label, i.ToString(CultureInfo.InvariantCulture)));
				}
			}
			else
			{
				foreach (ContentObjectEntry item in LoadCatalog().OfKind(selectedKind))
				{
					list.Add(new SearchableOptionSelect.Item(item.OptionLabel, item.Id));
				}
			}
			if (!string.IsNullOrWhiteSpace(current) && !list.Any((SearchableOptionSelect.Item item) => item.Id == current))
			{
				list.Add(new SearchableOptionSelect.Item("目录中暂缺（" + current + "）", current));
			}
			_objectSelect.SetItems(list, current);
		}

