		private void PopulatePreconditionObjects(SearchableOptionSelect objectSelect, ContentObjectKind kind, string? selectedId = null)
		{
			string current = selectedId ?? objectSelect.SelectedId;
			List<SearchableOptionSelect.Item> list = new List<SearchableOptionSelect.Item>();
			if (kind == ContentObjectKind.Act || kind == ContentObjectKind.Turn)
			{
				int num = ((kind == ContentObjectKind.Act) ? 3 : 99);
				for (int i = 1; i <= num; i++)
				{
					string label = ((kind == ContentObjectKind.Act) ? $"第 {i} 幕" : $"第 {i} 回合");
					list.Add(new SearchableOptionSelect.Item(label, i.ToString(CultureInfo.InvariantCulture)));
				}
			}
			else
			{
				list.Add(new SearchableOptionSelect.Item("任意", "*"));
				if (_activeSceneCandidates != null && _activeSceneCandidates.TryGetValue(kind, out IReadOnlyList<string> value) && value.Count > 0)
				{
					foreach (string item in value)
					{
						list.Add(new SearchableOptionSelect.Item(ResolveObjectName(kind, item), item));
					}
				}
				else
				{
					foreach (ContentObjectEntry item2 in LoadCatalog().OfKind(kind))
					{
						list.Add(new SearchableOptionSelect.Item(item2.OptionLabel, item2.Id));
					}
				}
			}
			if (!string.IsNullOrWhiteSpace(current) && !list.Any((SearchableOptionSelect.Item item) => item.Id == current))
			{
				if (kind == ContentObjectKind.Act || kind == ContentObjectKind.Turn)
				{
					current = ((list.Count > 0) ? list[0].Id : "*");
				}
				else
				{
					list.Add(new SearchableOptionSelect.Item("目录中暂缺（" + current + "）", current));
				}
			}
			objectSelect.SetItems(list, current);
		}

