		private void SubmitRule()
		{
			LineEdit? nicknameInput = _nicknameInput;
			string nickname = (((nicknameInput != null) ? nicknameInput.Text : null) ?? "").Trim();
			LineEdit? textInput = _textInput;
			string text = (((textInput != null) ? textInput.Text : null) ?? "").Trim();
			string ruleId = SelectedRuleId();
			RuleSubmissionStyle ruleSubmissionStyle = SelectedRuleStyle();
			IReadOnlyList<string> readOnlyList = RuleSubmissionValidator.Validate(new RuleSubmissionRequest(nickname, text, ruleId, ruleSubmissionStyle));
			if (readOnlyList.Count > 0)
			{
				SetStatus("校验未通过：" + string.Join("；", readOnlyList), error: true);
				return;
			}
			SubmissionRequest request = new SubmissionRequest(nickname, text, new ContentTrigger(ContentObjectKind.Event, ContentInstant.Entered, "*"), Array.Empty<ContentPrecondition>(), SelectedColor(), SelectedTopPinned(), SubmissionKind.Rule, ruleId, ruleSubmissionStyle, _selectedRainbow, ReadContinuationTexts(), SelectedSequenceSpeed(), ReadNote());
			SubmitRequest(request);
		}

		private void SubmitUgc()
		{
			LineEdit? nicknameInput = _nicknameInput;
			string nickname = (((nicknameInput != null) ? nicknameInput.Text : null) ?? "").Trim();
			LineEdit? textInput = _textInput;
			string text = (((textInput != null) ? textInput.Text : null) ?? "").Trim();
			ContentTrigger trigger = new ContentTrigger(Id: ResolveUgcTriggerId(), Kind: _selectedKind, Timing: _selectedInstant);
			IReadOnlyList<ContentPrecondition> preconditions = ReadPreconditions();
			SubmissionRequest request = new SubmissionRequest(nickname, text, trigger, preconditions, SelectedColor(), SelectedTopPinned(), SubmissionKind.Ugc, "", RuleSubmissionStyle.Narration, _selectedRainbow, ReadContinuationTexts(), SelectedSequenceSpeed(), ReadNote());
			SubmitRequest(request);
		}

		private void SubmitRequest(SubmissionRequest request)
		{
			IReadOnlyList<string> readOnlyList = SubmissionValidator.Validate(request);
			if (readOnlyList.Count > 0)
			{
				SetStatus("校验未通过：" + string.Join("；", readOnlyList), error: true);
				return;
			}
			if (_submissionBusy)
			{
				SetStatus("上一项投稿操作尚未完成，请稍候。", error: true);
				return;
			}
			_submissionBusy = true;
			SetSubmissionButtonsDisabled(disabled: true);
			long editingId = _editingId;
			SetStatus((editingId > 0) ? "提交改动中…" : "提交中…", error: false);
			if (editingId <= 0)
			{
				SubmitNewRequestAsync(request, _networkLifetime.Token);
			}
			else
			{
				SubmitEditRequestAsync(editingId, request, _networkLifetime.Token);
			}
		}

		private async Task SubmitNewRequestAsync(SubmissionRequest request, CancellationToken token)
		{
			SubmissionRequest request2 = request;
			CloudApiContract.SubmitResult result = await EnsureClient().SubmitAsync(request2, token).ConfigureAwait(continueOnCapturedContext: false);
			PostToMainThread(delegate
			{
				FinishSubmissionOperation();
				if (result.Id > 0)
				{
					Store.Record(result.Id, result.Token, request2, SubmissionStatus.Pending, SubmissionRequestType.Submit, 0L);
					SavePersistence();
					RenderMineRecords();
					SetStatus("投稿成功，等待作者审核。", error: false);
					RefreshMineRecords();
				}
				else
				{
					string message = result.Error switch
					{
						"cooldown" => result.Message ?? "投稿过于频繁，请稍后再试。", 
						"rate_limited" => result.Message ?? "本小时投稿已达上限，请稍后再试。", 
						"network" => "无法连接服务器，请检查网络。", 
						_ => result.Message ?? "投稿失败，请稍后重试。", 
					};
					SetStatus(message, error: true);
				}
			});
		}

		private async Task SubmitEditRequestAsync(long editingId, SubmissionRequest request, CancellationToken token)
		{
			bool success = await EnsureClient().RequestEditAsync(editingId, request, token).ConfigureAwait(continueOnCapturedContext: false);
			PostToMainThread(delegate
			{
				FinishSubmissionOperation();
				if (!success)
				{
					SetStatus("无法连接服务器，请检查网络。", error: true);
				}
				else
				{
					SetStatus("改动申请已提交，等待作者审核。", error: false);
					ExitEditMode();
					SavePersistence();
					RefreshMineRecords();
				}
			});
		}

		private void FinishSubmissionOperation()
		{
			_submissionBusy = false;
			SetSubmissionButtonsDisabled(disabled: false);
		}

