		private string ResolveDisplayName(ContentObjectKind kind, string id)
		{
			string id2 = id;
			if (id2 == "*")
			{
				return "任意";
			}
			switch (kind)
			{
			case ContentObjectKind.Act:
				return "第 " + id2 + " 幕";
			case ContentObjectKind.Turn:
				return "第 " + id2 + " 回合";
			default:
			{
				ContentObjectCatalog contentObjectCatalog = LoadCatalog();
				if (kind == ContentObjectKind.Event)
				{
					var (eventId, optionKey) = SubmissionUiModel.SplitEventOptionTriggerId(id2);
					if (optionKey != "*")
					{
						string text = contentObjectCatalog.OfKind(ContentObjectKind.Event).FirstOrDefault((ContentObjectEntry o) => o.Id == eventId).DisplayName ?? eventId;
						string text2 = contentObjectCatalog.OptionsOf(eventId).FirstOrDefault((EventOptionEntry o) => o.OptionKey == optionKey).DisplayName ?? optionKey;
						return text + " · " + text2;
					}
				}
				return contentObjectCatalog.OfKind(kind).FirstOrDefault((ContentObjectEntry o) => o.Id == id2).DisplayName ?? id2;
			}
			}
		}

