		private void ClosePanel()
		{
			if (_overlay != null)
			{
				ExitEditMode();
				ConfirmationDialog? noticeAcknowledgeConfirm = _noticeAcknowledgeConfirm;
				if (noticeAcknowledgeConfirm != null)
				{
					((Window)noticeAcknowledgeConfirm).Hide();
