				Window? noticeWindow = _noticeWindow;
				if (noticeWindow != null)
				{
					noticeWindow.Hide();
				}
				((CanvasItem)_overlay).Visible = false;
				_overlay.ReleaseFocus();
				((Node)this).GetViewport().GuiReleaseFocus();
			}
		}

