		private void BeginEdit(SubmissionRecord record)
		{
			_editingId = record.Id;
			_nicknameInput.Text = record.Request.Nickname;
			if (_noteInput != null)
			{
				_noteInput.Text = record.Request.Note ?? "";
			}
			RestoreStyleSelections(record.Request);
			if (record.Request.Kind == SubmissionKind.Rule)
			{
				SwitchToTab(SubmissionKind.Rule, exitEdit: false);
				_textInput.Text = record.Request.Text;
				SelectRule(record.Request.RuleId, record.Request.RuleStyle);
			}
			else
			{
				SwitchToTab(SubmissionKind.Ugc, exitEdit: false);
				_textInput.Text = record.Request.Text;
				FillUgcForm(record.Request);
			}
			ApplyEditModeLabel();
			SetStatus($"正在改动投稿 #{record.Id}，修改后点「确认改动并提交」。", error: false);
		}

