		private void FillUgcForm(SubmissionRequest request)
		{
			_selectedKind = request.Trigger.Kind;
			_selectedInstant = request.Trigger.Timing;
			string selectedId;
			string selectedOptionKey;
			if (_selectedKind == ContentObjectKind.Event && _selectedInstant == ContentInstant.OptionSelected)
			{
				(selectedId, selectedOptionKey) = SubmissionUiModel.SplitEventOptionTriggerId(request.Trigger.Id);
			}
			else
			{
				string id = request.Trigger.Id;
				selectedOptionKey = "*";
				selectedId = id;
			}
			SyncKindSelect();
			OnObjectKindChanged();
			if (_objectSelect != null)
			{
				PopulateObjectSelect(selectedId);
			}
			VBoxContainer? preconditionList = _preconditionList;
			foreach (Node item in ((preconditionList != null) ? ((Node)preconditionList).GetChildren(false) : null) ?? new Array<Node>())
			{
				((Node)_preconditionList).RemoveChild(item);
				item.QueueFree();
			}
			foreach (ContentPrecondition precondition in request.Preconditions)
			{
				AddPreconditionRowWithValues(precondition);
			}
			RestoreStyleSelections(request);
			RefreshEventOptionRow(selectedOptionKey);
			UpdateSummary();
		}

