namespace DanmakuSpire.DanmakuSpireCode.Commands
{
	public sealed class DanmakuSettingsCmd : AbstractConsoleCmd
	{
		public override string CmdName => "danmaku_settings";

		public override string Args => "[open|close]";

		public override string Description => "打开或关闭弹幕尖塔自有设置面板。";

		public override bool IsNetworked => false;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			//IL_0044: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_0061: Unknown result type (might be due to invalid IL or missing references)
			string text = args.FirstOrDefault()?.ToLowerInvariant() ?? "open";
			if (!(text == "open"))
			{
				if (text == "close")
				{
					DanmakuSettingsHost.Close();
					return new CmdResult(true, "已关闭弹幕尖塔设置面板");
				}
				return new CmdResult(false, "用法：danmaku_settings [open|close]");
			}
			DanmakuSettingsHost.Open();
			return new CmdResult(true, "已请求打开弹幕尖塔设置面板");
		}
	}
	public sealed class DanmakuAuditCmd : AbstractConsoleCmd
	{
		public override string CmdName => "danmaku_audit";

		public override string Args => "[read|reset|mark|status|harmony]";

		public override string Description => "读取弹幕尖塔事实/规则增量审计、管理读取游标或检查 Harmony。";

		public override bool IsNetworked => false;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0064: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a7: Unknown result type (might be due to invalid IL or missing references)
			//IL_0071: Unknown result type (might be due to invalid IL or missing references)
			//IL_0076: Unknown result type (might be due to invalid IL or missing references)
			//IL_0083: Unknown result type (might be due to invalid IL or missing references)
			//IL_0088: Unknown result type (might be due to invalid IL or missing references)
			//IL_008b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0090: Unknown result type (might be due to invalid IL or missing references)
			//IL_0093: Unknown result type (might be due to invalid IL or missing references)
			//IL_0098: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a1: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a6: Unknown result type (might be due to invalid IL or missing references)
			return (CmdResult)((args.FirstOrDefault()?.ToLowerInvariant() ?? "status") switch
			{
				"read" => Read(), 
				"reset" => Cursor(RuntimeAuditCursor.Reset(), "游标已重置；下次将重读内存中仍保留的记录"), 
				"mark" => Cursor(RuntimeAuditCursor.MarkCurrent(), "游标已移动到当前末尾"), 
				"status" => Status(), 
				"harmony" => HarmonyStatus(), 
				_ => new CmdResult(false, "用法：danmaku_audit [read|reset|mark|status|harmony]"), 
			});
		}

		private static CmdResult Read()
		{
			//IL_0090: Unknown result type (might be due to invalid IL or missing references)
			DanmakuRuntimeAuditSnapshot danmakuRuntimeAuditSnapshot = RuntimeAuditCursor.ReadAndAdvance();
			string text = JsonSerializer.Serialize(danmakuRuntimeAuditSnapshot, TelemetryJson.Compact);
			string value = WriteLatest("mcp-audit-latest.json", JsonSerializer.Serialize(danmakuRuntimeAuditSnapshot, TelemetryJson.Indented));
			MainFile.Log($"[MCP-Audit] facts={danmakuRuntimeAuditSnapshot.FactAudit.Count}, rules={danmakuRuntimeAuditSnapshot.RuleAudit.Count}, file={value}");
			return new CmdResult(true, text);
		}

		private static CmdResult Status()
		{
			//IL_006a: Unknown result type (might be due to invalid IL or missing references)
			RuntimeAuditCursorSnapshot position = RuntimeAuditCursor.Position;
			return new CmdResult(true, JsonSerializer.Serialize(new
			{
				cursor = position,
				activeTrace = (RuntimeTraceRecorder.Instance?.CurrentTracePath ?? ""),
				harmonyFailures = MainFile.HarmonyPatchStatus.Count((HarmonyPatchInstallResult item) => !item.Success),
				harmonyReport = MainFile.HarmonyCompatibilityReportPath,
				fixtureCases = RealGameTestCatalog.All.Count
			}, TelemetryJson.Compact));
		}

		private static CmdResult HarmonyStatus()
		{
			//IL_004a: Unknown result type (might be due to invalid IL or missing references)
			HarmonyCompatibilityReport harmonyCompatibilityReport = HarmonyCompatibilityReporter.Create(typeof(RunManager).Assembly.GetName().Version?.ToString() ?? "unknown", MainFile.HarmonyPatchStatus);
			return new CmdResult(harmonyCompatibilityReport.Compatible, JsonSerializer.Serialize(harmonyCompatibilityReport, TelemetryJson.Compact));
		}

		private static CmdResult Cursor(RuntimeAuditCursorSnapshot cursor, string message)
		{
			//IL_004c: Unknown result type (might be due to invalid IL or missing references)
			return new CmdResult(true, $"{message}：rule={cursor.RuleSequence}, fact={cursor.FactSequence}");
		}

		private static string WriteLatest(string fileName, string content)
		{
			string text = ProjectSettings.GlobalizePath("user://DanmakuSpire/coverage");
			Directory.CreateDirectory(text);
			string text2 = Path.Combine(text, fileName);
			File.WriteAllText(text2, content, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
			return text2;
		}
	}
	public sealed class DanmakuDiagnosticsCmd : AbstractConsoleCmd
	{
		public override string CmdName => "danmaku_diagnostics";

		public override string Args => "[snapshot|copy|path|export <path>]";

		public override string Description => "输出/复制弹幕尖塔诊断信息，或导出日志目录。";

		public override bool IsNetworked => false;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			//IL_004b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0068: Unknown result type (might be due to invalid IL or missing references)
			//IL_007a: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b5: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a9: Unknown result type (might be due to invalid IL or missing references)
			//IL_009d: Unknown result type (might be due to invalid IL or missing references)
			switch (args.FirstOrDefault()?.ToLowerInvariant() ?? "snapshot")
			{
			case "path":
				return new CmdResult(true, DanmakuDiagnostics.LogsRoot);
			case "copy":
			{
				string text2 = DanmakuDiagnostics.CaptureSnapshot();
				bool num = DanmakuDiagnostics.TryCopyToClipboard(text2);
				return new CmdResult(num, num ? "诊断信息已复制到剪贴板。" : text2);
			}
			case "export":
			{
				if (args.Length < 2)
				{
					return new CmdResult(false, "用法：danmaku_diagnostics export <目标目录>");
				}
				string text = DanmakuDiagnostics.ExportLogsTo(args[1]);
				if (!string.IsNullOrEmpty(text))
				{
					return new CmdResult(true, "日志已导出到：" + text);
				}
				return new CmdResult(false, "导出失败，详见日志。");
			}
			default:
				return new CmdResult(true, DanmakuDiagnostics.CaptureSnapshot());
			}
		}
	}
	public sealed class DanmakuFixtureCmd : AbstractConsoleCmd
	{
		private static readonly object Gate = new object();

		private static string _activeCaseId = "";

		private static string _activeTracePath = "";

		public override string CmdName => "danmaku_fixture";

		public override string Args => "[list|status|<RG-ID> <start|pass|fail|abort> [note]]";

		public override string Description => "列出或标记弹幕尖塔的固定实机夹具。";

		public override bool IsNetworked => false;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			//IL_0037: Unknown result type (might be due to invalid IL or missing references)
			//IL_0093: Unknown result type (might be due to invalid IL or missing references)
			//IL_0081: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b8: Unknown result type (might be due to invalid IL or missing references)
			//IL_023a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0310: Unknown result type (might be due to invalid IL or missing references)
			//IL_0315: Unknown result type (might be due to invalid IL or missing references)
			//IL_02e5: Unknown result type (might be due to invalid IL or missing references)
			//IL_02ea: Unknown result type (might be due to invalid IL or missing references)
			//IL_03c4: Unknown result type (might be due to invalid IL or missing references)
			//IL_034b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0350: Unknown result type (might be due to invalid IL or missing references)
			//IL_03af: Unknown result type (might be due to invalid IL or missing references)
			//IL_03b4: Unknown result type (might be due to invalid IL or missing references)
			if (args.Length == 0 || args[0].Equals("status", StringComparison.OrdinalIgnoreCase))
			{
				return new CmdResult(true, string.IsNullOrEmpty(_activeCaseId) ? "当前没有活动夹具" : ("活动夹具：" + _activeCaseId));
			}
			if (args[0].Equals("list", StringComparison.OrdinalIgnoreCase))
			{
				return new CmdResult(true, string.Join(" ", RealGameTestCatalog.All.Select((RealGameTestCase item) => item.CaseId)));
			}
			if (args.Length < 2)
			{
				return new CmdResult(false, "用法：danmaku_fixture <RG-ID> <start|pass|fail|abort> [note]");
			}
			string text = args[0].ToUpperInvariant();
			if (!RealGameTestCatalog.TryGet(text, out RealGameTestCase testCase))
			{
				return new CmdResult(false, "未知实机用例：" + text);
			}
			RealGameFixtureState? realGameFixtureState;
			switch (args[1].ToLowerInvariant())
			{
			case "start":
			case "started":
				realGameFixtureState = RealGameFixtureState.Started;
				break;
			case "pass":
			case "passed":
				realGameFixtureState = RealGameFixtureState.Passed;
				break;
			case "fail":
			case "failed":
				realGameFixtureState = RealGameFixtureState.Failed;
				break;
			case "abort":
			case "aborted":
				realGameFixtureState = RealGameFixtureState.Aborted;
				break;
			default:
				realGameFixtureState = null;
				break;
			}
			RealGameFixtureState? realGameFixtureState2 = realGameFixtureState;
			if (!realGameFixtureState2.HasValue)
			{
				return new CmdResult(false, "状态必须为 start、pass、fail 或 abort");
			}
			RealGameFixtureState value = realGameFixtureState2.Value;
			string note = ((args.Length > 2) ? string.Join(" ", args.Skip(2)) : "");
			lock (Gate)
			{
				string text2 = RuntimeTraceRecorder.Instance?.CurrentTracePath ?? "";
				if (!string.IsNullOrEmpty(_activeCaseId) && !string.Equals(_activeTracePath, text2, StringComparison.Ordinal))
				{
					_activeCaseId = "";
					_activeTracePath = "";
				}
				if (value == RealGameFixtureState.Started)
				{
					if (!string.IsNullOrEmpty(_activeCaseId))
					{
						return new CmdResult(false, "请先结束活动夹具 " + _activeCaseId);
					}
				}
				else if (!string.Equals(_activeCaseId, text, StringComparison.Ordinal))
				{
					return new CmdResult(false, text + " 不是当前活动夹具；当前为 " + _activeCaseId);
				}
				RealGameFixtureMarker marker = new RealGameFixtureMarker(text, testCase.RuleId, value, note);
				RuntimeTraceRecorder? instance = RuntimeTraceRecorder.Instance;
				if (instance == null || !instance.RecordFixture(marker))
				{
					return new CmdResult(false, "当前没有活动 Run 轨迹；请进入爬塔后再标记夹具");
				}
				_activeCaseId = ((value == RealGameFixtureState.Started) ? text : "");
				_activeTracePath = ((value == RealGameFixtureState.Started) ? text2 : "");
				return new CmdResult(true, $"{text} {value} 已写入实机轨迹");
			}
		}
	}
}
